window.__D("text/zohar/c011",{"p":[[9520011457,"<p>רִבִּי חִזְקִיָּה פָּתַח וְאָמַר, (בראשית ט״ו:י״ב) וַיְהִי הַשֶּׁמֶשׁ לָבֹא וְתַרְדֵּמָה נָפְלָה עַל אַבְרָם וְגו', הַאי קְרָא אוּקְמוּהָ. אֲבָל דָּא יוֹמָא דְּדִינָא קַשְׁיָא, דְּאַפְקֵי לֵיהּ לְבַּר נָשׁ מֵהַאי עַלְמָא. דְּתַנְיָא, (ההוא יומא) זִמְנָא דְמָטָא דְּבַר נָשׁ נָפִיק מֵהַאי עַלְמָא, הַהוּא (יומא) זִמְנָא יוֹמָא דְּדִינָא רַבָּא, דְּאִתְחַשַּׁךְ שִׁמְשָׁא מִן סִיהֲרָא, כְּמָה דִכְתִיב, (קהלת י״ב:ב׳) עַד אֲשֶׁר לא תֶחְשַׁךְ הַשֶּׁמֶשׁ, דָּא נִשְׁמָתָא קַדִּישָׁא, דְּאִתְמְנָעַת מִבַּר נָשׁ, תְּלָתִין יוֹמִין, עַד לָא יִפּוּק מֵעַלְמָא (והא חזי), וְחָמָא דְצוּלְמָא דְּאִתְמְנָעַת מִנֵּיהּ וְלָא אִתְחֲזֵי.</p>\n<p>מַאי טַעְמָא אִתְמְנָעַת מִנֵּיהּ. בְּגִין דְּנִשְׁמְתָא קַדִּישָׁא סָלְקַת, וְאִתְעֲבָרַת מִנֵּיהּ, וְלָא אִתְחֲזֵי. דְּלָא תֵימָא, דְּכַד מִית בַּר נָשׁ וְאִתְחַלָּשׁ, הַאי נִשְׁמָתָא אִתְעֲבָרַת מִנֵּיהּ, אֶלָּא כַּד אִיהוּ בְּחַיָּיו, בְּתוּקְפֵּיהּ, אִתְעֲבָרַת מִנֵּיהּ (ואתחלש) הַאי נִשְׁמְתָא, וְלָא נָהֲרָא לְרוּחָא, וְרוּחָא לָא נָהִיר לְנַפְשָׁא, כְּדֵין צוּלְמָא אִתְעֲבָרַת מִנֵּיהּ, וְלָא נָהִיר לֵיהּ. (אלא) מֵהַהוּא יוֹמָא, כֹּלָּא מַכְרְזֵי עֲלֵיהּ, וְאֲפִילּוּ צִפֳּרֵי שְׁמַיָא. מַאי טַעְמָא. בְּגִין דְּנִשְׁמָתָא הָא סָלְקָא מִנֵּיהּ, וְרוּחָא לָא נָהִיר לְנַפְשָׁא, כְּדֵין נַפְשָׁא אִתְחַלָּשַׁת, וּמֵיכְלָא וְכָל תִּיאוּבְתָּא דְגוּפָא, סָלְקָא מִנֵּיהּ וְאִתְעֲבַר.</p>\n<p>וְאָמַר רִבִּי יְהוּדָה, וְאֲפִילּוּ כָּל זִמְנָא דְּנָפִיל אִינִישׁ בְּבֵי מַרְעֵיהּ, וְלָא יָכִיל לְצַלָּאָה, נִשְׁמָתָא אִתְעֲבָרַת וְסָלְקָא מִנֵּיהּ, וּכְדֵין לָא נָהִיר רוּחָא לְנַפְשָׁא, עַד דְּדַיְינִין דִּינִיהּ דְּבַר נָשׁ. וְאִי דָּיְינִין לֵיהּ לְבַר נָשׁ לְטַב, כְּדֵין נִשְׁמָתָא אִתְהַדְּרַת לְאַתְרָהּ, וּנְהִירָא לְכֹלָּא. הָא בְּזִמְנָא דְּקָיְימָא מִלָּה בְּדִינָא. וּבְזִמְנָא דְּלָא קָיְימָא מִלָּה בְּדִינָא, תְּלָתִין יוֹמִין אַקְדִּימַת נִשְׁמָתָא לְכֹלָּא, וְצוּלְמָא אִתְעֲבַר מִנֵּיהּ.</p>\n<p>תָּאנָא, בְּזִמְנָא דְּדָיְינִין לֵיהּ לְבַר נָשׁ לְעֵילָא, סָלְקִין לְנִשְׁמָתֵיהּ לְבֵי דִינָא, וְדָיְינִין עַל מֵימְרָהָא, וְהִיא אַסְהִידַת בְּכֹלָּא, וְאַסְהִידַת בְּכָל רַעֲיוֹנִי דְבַר נָשׁ, וּבְעוֹבָדִין לָא אַסְהִידַת, דְּהָא כֻּלְּהוּ בְּסִפְרָא כְתִיבִין. וְכֻלְּהוּ דָּיְינִין לֵיהּ לְבַּר נָשׁ, בְּהַהִיא שַׁעְתָּא דְּדָיְינִין לֵיהּ לְבַּר נָשׁ לְעֵילָא, כְּדֵין דֹּחֲקָא דְגוּפָא אִשְׁתַּכַּח, יַתִּיר מִשְּׁאָר זִמְנַיָיא.</p>\n<p>אִי דָיְינִין לֵיהּ לְטַב, כְּדֵין אַרְפִּין מִנֵּיהּ. וְזֵיעָא אִתְבַּקַּע עַל גּוּפָא, וְנִשְׁמָתָא אֲהַדְּרַת לְבָתַר, וְנָהֲרָא לְכֹלָּא. וְלָא סָלִיק בַּר נָשׁ מִבֵּי מַרְעֵיהּ לְעָלְמִין, עַד דְּדָיְינִין דִּינֵיהּ לְעֵילָא. וְאִי תֵימָא, הָא כַּמָּה חַיָּיבֵי עַלְמָא, כַּמָּה רַשִּׁיעֵי עַלְמָא, קָיְימִין בְּקִיּוּמַיְיהוּ. אֶלָּא, קוּדְשָׁא בְּרִיךְ הוּא אַשְׁגַּח בְּדִינֵיהּ דְּבַּר נָשׁ, אַף עַל גַּב דְּהַשְׁתָּא לָא זָכֵי, וְהוּא חָמֵי דְּהָא לְבָתַר זָכֵי, דָּאִין לֵיהּ לְטַב. אוֹ לְזִמְנִין דְּאוֹלִיד בַּר, דְּיֶהֱוֵי זַכָּאָה בְּעַלְמָא, וְעַל דָּא קוּדְשָׁא בְּרִיךְ הוּא דָּאִין לֵיהּ לְטַב.</p>\n<p>וְכָל עוֹבָדוֹי וְדִינוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא לְטַב, וּבְכֹלָּא אַשְׁגַּח. כְּמָה דִכְתִיב, (יחזקאל ל״ג:י״א) חַי אָנִי נְאֻם ה' וְגו' אִם אֶחְפּוֹץ בְּמוֹת הָרָשָׁע כִּי אִם בְּשׁוּב רָשָׁע מִדַּרְכּוֹ. וּבְגִין דָּא, כָּל אִינוּן חַיָּיבֵי עַלְמָא, דְּקָיְימִין בְּקִיּוּמַיְיהוּ, קוּדְשָׁא בְּרִיךְ הוּא דָּאִין לוֹן לְטַב.</p>\n<p>וּלְזִמְנִין, דְּאִינוּן מַרְעִין אִשְׁתַּלִּימוּ זִמְנַיְיהוּ, מִלְּמִשְׁרֵי תַּמָּן. כְּמָא דְאַתְּ אָמֵר, (דברים כ״ח:נ״ט) וָחֳלָאִים רָעִים וְנֶאֱמָנִים, דְּעֲבָדוּ מְהֵימְנוּתָא. דְּכַד שָׁרִיאָן עֲלֵיהּ דְּבַר <Nonei></i>נָשׁ, מִסְתַּלְּקֵי מִנֵּיהּ לְבָתַר דְּאַשְׁלִימוּ זִמְנַיְיהוּ, בֵּין לְצַדִּיקַיָיא, בֵּין לְחַיָּיבַיָא, וְכֹלָּא אִתְעֲבַד בְּדִינָא כִּדְקָאֲמָרָן:</p>\n<p>וַיַּרְא יִשְׂרָאֵל אֶת בְּנֵי יוֹסֵף וַיֹּאמֶר מִי אֵלֶּה, אָמַר רִבִּי יִצְחָק, הַאי קְרָא קַשְׁיָא, דִּכְתִיב וַיַּרְא יִשְׂרָאֵל, וּכְתִיב וְעֵינֵי יִשְׂרָאֵל כָּבְדוּ מִזּוֹקֶן לֹא יוּכַל לִרְאוֹת, אִי לֹא יוּכַל לִרְאוֹת, מַהוּ וַיַּרְא יִשְׂרָאֵל. אֶלָּא דְּחָמָא בְּרוּחַ קוּדְשָׁא, אִינוּן בְּנֵי יוֹסֵף, דְּאִינוּן יָרָבְעָם וַחֲבֵירָיו. דְּיָרָבְעָם עֲבַד תְּרֵין עֶגְלֵי זָהָב, וְאָמַר (מלכים א יב) אֵלֶּה אֱלֹהֶיךָ יִשְׂרָאֵל. וּבְגִין כָּךְ, מִי אֵלֶּה, מַאן הוּא דְּזַמִּין לְמֵימַר אֵלֶּה אֱלֹהֶיךָ לְטַעֲוָון אָחֳרָן, וּבְגִין כָּךְ וַיַּרְא יִשְׂרָאֵל אֶת בְּנֵי יוֹסֵף.</p>\n<p>מִכָּאן, דְּצַדִּיקַיָיא חָמָאן עוֹבָדָא לְמֵרָחוֹק, וְקוּדְשָׁא בְּרִיךְ הוּא מְעַטֵּר לוֹן בְּעִטְרָא דִילֵיהּ, מַה קוּדְשָׁא בְּרִיךְ הוּא חָמֵי לְמֵרָחוֹק, כְּמָה דִכְתִיב, (בראשית א׳:ל״א) וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה וְהִנֵּה טוֹב מְאֹד, דְּקוּדְשָׁא בְּרִיךְ הוּא חָמָא כָּל עוֹבָדִין, עַד לָא יַעֲבֵד לוֹן, וְכֻלְּהוּ אַעֲבָרוּ קַמֵּיהּ.</p>\n<p>כְּגַוְונָא דָא, כָּל דָּרִין דְּעַלְמָא, מִסְּיָיפֵי עַלְמָא, עַד סְיָיפֵי עַלְמָא, כֻּלְּהוּ אִתְעַתָּדוּ וְקָיְימוּ קַמֵּיהּ עַד לָא יֵיתוּן לְעַלְמָא. הֲדָא הוּא דִכְתִיב, (ישעיהו מ״א:ד׳) קוֹרֵא הַדּוֹרוֹת מֵרֹאשׁ, עַד לָא אִתְבְּרֵי עַלְמָא. בְּגִין דְּכָל נִשְׁמָתִין דְּנָחֲתִין לְעַלְמָא, עַד לָא יֵיחֲתוּן, כֻּלְּהוּ קָיְימֵי קַמֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, בְּדִיוּקְנָא דְּקָיְימֵי בְּהַאי עַלְמָא, וְאִקְרוּן בִּשְׁמָהָן, דִּכְתִיב, (ישעיהו מ׳:כ״ו) לְכֻלָּם בְּשֵׁם יִקְרָא.</p>\n<p>אוּף הָכִי צַדִּיקַיָּיא, קוּדְשָׁא בְּרִיךְ הוּא אַחְמֵי לוֹן כָּל דָּרִין דְּעַלְמָא, עַד לָא יֵיתוּן וְיִשְׁתַּכְּחוּן בְּעַלְמָא. מְנָא לָן מֵאָדָם (דא אדם) דְּהֲוָה קַדְמָאָה. דְּקוּדְשָׁא בְּרִיךְ הוּא אַחְמֵי לֵיהּ כָּל אִינוּן דָּרִין עַד לָא יֵיתוּן, כְּדִכְתִיב, (בראשית ה׳:א׳) זֶה סֵפֶר תּוֹלְדוֹת (אדם). דְּתָנִינָן, אַחְמֵי לֵיהּ, כָּל אִינוּן דָּרִין דְּזַמִּינִין לְמֵיתֵי לְעַלְמָא. וְכֵן לְמשֶׁה, דִּכְתִיב, (דברים לה) וַיַּרְאֵהוּ ה' אֶת כָּל הָאָרֶץ, דְּקוּדְשָׁא בְּרִיךְ הוּא אַחְמֵי לֵיהּ כָּל דָּרִין דְּעַלְמָא, וְכָל אִינוּן מַנְהִיגֵי עַלְמָא, וְכָל שְׁאָר נְבִיאֵי, עַד לָא יֵיתוּן לְעַלְמָא.</p>\n<p>אוּף הָכָא, וַיַּרְא יִשְׂרָאֵל אֶת בְּנֵי יוֹסֵף, חָמָא לְמֵרָחוֹק, וְאִזְדַּעְזַע, וְאָמַר מִי אֵלֶּה. וְהַאי קְרָא אַשְׁלִים לִתְרֵין סִטְרִין, לְהַאי סִטְרָא, וּלְהַאי סִטְרָא. וְעַל דָּא אָתִיב יוֹסֵף וְאָמַר, בָּנַי הֵם אֲשֶׁר נָתַן לִי אֱלֹהִים בָּזֶה. וּמְנָא לָן דְּקוּדְשָׁא בְּרִיךְ הוּא אַחְמֵי לֵיהּ בְּרוּחָא דְקוּדְשָׁא. דִּכְתִיב וְהִנִּה הֶרְאָה אֹתִי אֱלֹהִים גַּם אֶת זַרְעֶךָ. גַּם, לְאַסְגָּאָה אִינוּן דְּנָפְקִין מִנֵּיהּ כִּדְקָאֲמָרָן:</p>"],[9520011458,"<p>וַיְבָרֶךָ אֶת יוֹסֵף וַיֹּאמַר הָאֱלֹהִים אֲשֶׁר וְגו', בְּהַאי קְרָא אִית לְאִסְתַּכָּלָא בֵּיהּ, וַיְבָרֶךְ אֶת יוֹסֵף, דְּלָא אַשְׁכְּחָן הָכָא בְּרָכָה דִּבְרִיךְ לֵיהּ לְיוֹסֵף אֶלָּא לִבְנוֹי. אִי לִבְנוֹי, וַיְבָרַכֵם מִבָּעֵי לֵיהּ, מַהוּ וַיְבָרֶךְ אֶת יוֹסֵף, וְלָא אַשְׁכְּחָן הָכָא דְּאִתְבְּרִיךְ יוֹסֵף.</p>\n<p>אָמַר רִבִּי יוֹסֵי, אֶת דַּיְיקָא, כְּתִיב אֶת יוֹסֵף, בִּרְכְתָא דִּבְנוֹי הֲוָה, וְכַד אִתְבָּרְכָאן בְּנוֹי, אִיהוּ מִתְבָּרֵךְ. דְּבִרְכְתָא דִּבְנוֹי דְּבַר נָשׁ בִּרְכָתֵיהּ אִיהִי.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, וַיְבָרֶךְ אֶת יוֹסֵף, אֶת דַּיְיקָא, דְּבָרִיךְ לְאָת קַיָּימָא, רָזָא (נ\"א דברית בגין דכיון דאמר בני הם אשר נתן לי אלהים בזה, כדין בריך לההוא אתר רזא) דִבְרִית דְּנָטַר יוֹסֵף, וּבְגִין כָּךְ אִקְרֵי צַדִּיק, אֶת דְּיוֹסֵף, רָזָא דִּבְרִית דְּקָיְימָא בַּהֲדֵיהּ דְּיוֹסֵף:</p>\n<p>הָאֱלהִים אֲשֶׁר הִתְהַלְּכוּ אֲבוֹתַי לְפָנָיו. הָאֱלהִים, דָּא רָזָא דִבְרִית קַדִּישָׁא, קְיָימָא קַדִּישָׁא. אֲבוֹתַי לְפָנָיו, דַּיְיקָא לְפָנָיו, דְּאִינוּן קַדְמָאֵי עִלָּאֵי, מִקַּמֵּי רָזָא דְנָא, אַבְרָהָם וְיִצְחָק, דְּהָא מִנְּהוֹן אִתְּזָן וְיָנְקָא הַהוּא (נ\"א מההוא) אֲתַר.</p>\n<p>הָאֱלהִים הָרוֹעֶה אוֹתִי, מַאי טַעְמָא זִמְנָא אָחֳרָא הָאֱלֹהִים. אֶלָּא רָזָא עִלָּאָה אִיהוּ, וְהָכָא בָּרִיךְ לְהַהוּא אֲתַר, בְּרָזָא דְּאֱלהִים חַיִּים, מְקוֹרָא דְחַיֵּי, דְּמִנֵּיהּ נָפְקִין בִּרְכָאן. וּבְגִין דָּא אַדְכַּר גַּרְמֵיהּ בְּהַאי אֲתַר, וְאָמַר, הָאֱלהִים הָרוֹעֶה אוֹתִי, בְּגִין דְּכָל בִּרְכָאן דְּנָגְדֵי מִמְּקוֹרָא דְחַיֵּי, יַעֲקֹב נָטִיל לוֹן. וְכֵיוָן דְּנָטִיל לוֹן אִיהוּ, הַאי אֲתַר נָטַל בִּרְכָאן, וְכֹלָּא אִיהוּ תַּלְיָיא (נ\"א בדכורא) בְּדִבּוּרָא. וְעַל דָּא וַיְבָרֶךְ אֶת יוֹסֵף כְּתִיב.</p>\n<p>בְּגִין כָּךְ, בְּכָל אֲתַר דְּבִרְכָאן אִצְטְרִיכוּ לְבָרְכָא, בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא לְאִתְבָּרְכָא בְּקַדְמִיתָא, וּלְבָתַר אִתְבָּרְכוּ אָחֳרָנִין, וְאִי קוּדְשָׁא בְּרִיךְ הוּא לָא אִתְבָּרִיךְ בְּקַדְמִיתָא, אִינוּן בִּרְכָאן לָא <Nonei></i>מִתְקָיְימִין.</p>\n<p>וְאִי תֵימָא, הָא יַעֲקֹב דְּבָרְכֵיהּ אֲבוּהָ, וְלָא בָּרְכֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא בְּקַדְמִיתָא. תָּא חֲזֵי, בְּשַׁעְתָּא דְּבָרִיךְ יִצְחָק לְיַעֲקֹב, לָא בָּרְכֵיהּ, עַד דְּבָרִיךְ לְקוּדְשָׁא בְּרִיךְ הוּא בְּקַדְמִיתָא. כֵּיוָן דְּבָרִיךְ לְקוּדְשָׁא בְּרִיךְ הוּא בְּקַדְמִיתָא, בָּרְכֵיהּ לְיַעֲקֹב. מְנָא לָן, דִּכְתִיב (בראשית כ״ו:י״ב) וַיֹּאמֶר רְאֵה רֵיחַ בְּנִי כְּרֵיחַ שָׂדֶה אֲשֶׁר בֵּרַכוֹ ה'. הָכָא קִיֵּים בְּרָכָה לְקוּדְשָׁא בְּרִיךְ הוּא. דִּכְתִיב, אֲשֶׁר בֵּרַכוֹ ה', אִתְבָּרֵךְ בְּקִיּוּמָא דְּבִרְכָאן, וּלְבָתַר כְּתִיב בַּתְרִיהּ, וְיִתֶּן לְךָ וְגו'. כֵּיוָן דְּהַהוּא שָׂדֶה אִתְקְיַּים בְּקַיְימָא דְּבִרְכָאן, (ס\"א בברכוי, מיד ברכיה, ויתן לך האלהים, דההוא שדה רזא) דְּנָפְקֵי מִינֵיהּ בִּרְכָאן, לְבָתַר דְּאִיהוּ אִתְקְיַּים בְּבִרְכוֹי. כְּגַוְונָא דָא בָּרִיךְ יַעֲקֹב בְּקַדְמִיתָא לְקוּדְשָׁא בְּרִיךְ הוּא, וּלְבָתַר בָּרִיךְ לִבְנוֹי. תָּא חֲזֵי, בְּצַפְרָא בָּעֵי בַּר נָשׁ לְאַקְדָּמָא בִּרְכָאן לְקוּדְשָׁא בְּרִיךְ הוּא, וּלְבָתַר לִשְׁאָר בְּנֵי עַלְמָא, וְהָא אוֹקִימְנָא דִּכְתִיב בַּבֹּקֶר יֹאכַל עַד וְגו'.</p>\n<p>וְתָּא חֲזֵי, כַּד בָּעָא יַעֲקֹב לְבָרְכָא לְאִינוּן בְּנֵי יוֹסֵף, חָמָא בְּרוּחַ קוּדְשָׁא דְּזַמִין לְנָפְקָא מֵאֶפְרַיִם יָרָבְעָם בֶּן נְבָט. פָּתַח וְאָמַר, מִי אֵלֶּה. מַשְׁמַע (ס\"א מאי שנא) דְּאָמַר בַּעֲבוֹדָה דָא דְסִטְרָא דְּעֲבוֹדָה זָרָה (שמות לכ) אֵלֶּה אֱלֹהֶיךָ יִשְׂרָאֵל. אֶלָּא רָזָא אִיהוּ, כָּל אִינוּן סִטְרִין דְּהַהוּא חִוְיָא בִּישָׁא, וּמִסִּטְרָא דְּהַהוּא רוּחַ מְסָאֲבָא הַהוּא חִוְיָא. (שמות רל\"ו ע\"ב) וְאִית מַאן דְּרָכִיב עֲלֵיהּ, וְכַד מִזְדַּוְוגָן, אִקְרוּן אֵלֶּה. וְאִינוּן מִזְדַּמְּנִין בְּעַלְמָא, בְּכָל אִינוּן סִטְרִין דִּלְּהוֹן.</p>\n<p>וְרוּחַ דְּקוּדְשָׁא אִקְרֵי זֹאת, דְּאִיהוּ רָזָא דִּבְרִית, רְשִׁימָא קַדִּישָׁא דְּאִשְׁתַּכַּח תָּדִיר בְּבַּר נָשׁ, וְכֵן (שמות ט״ו:ב׳) זֶה אֵלִי וְאַנְוִהוּ, (ישעיה כה) זֶה ה'. (ס\"א הוא יי) אֲבָל אִלֵּין, אִקְרוּן אֵלֶּ\"ה, וְעַל דָּא כְּתִיב, אֵלֶּה אֱלהֶיךָ יִשְׂרָאֵל.</p>\n<p>וּבְגִין כָּךְ כְּתִיב, (ישעיהו מ״ט:ט״ו) גַּם אֵלֶּה תִּשָּׁכַחְנָה, וְאָנֹכִי רָזָא דְזֹאת, לא אֶשְׁכָּחֵךְ. וּכְתִיב, (איכה א׳:ט״ז) עַל אֵלֶּה אֲנִי בּוֹכִיָה, דְּהַהוּא חוֹבָא גָּרְמָא לוֹן לְמִבְכֵּי כַּמָּה בְּכִיָּין. דָּבָר אַחֵר עַל אֵלֶּה אֲנִי, מַאי טַעְמָא. בְּגִין דְּאִתְיְיהִיב רְשׁוּ לְאֲתַר דָּא לְשַׁלְּטָאָה עַל יִשְׂרָאֵל, וּלְחָרָבָא בֵּי מַקְדְּשָׁא, וּבְגִין דְּאִתְיְיהִיב לוֹן רְשׁוּ לְשַׁלְּטָאָה, (ס\"א כתיב, (איכה א׳:ט״ז) על אלה אני בוכיה, רזא דמלה דא סטרא דמסאבא דאתייהיב לון רשו לשלטאה) אֲנִי בּוֹכִיָה, דָּא רוּחַ קוּדְשָׁא דְּאִקְרֵי אֲנִי.</p>\n<p>וְאִי תֵימָא, הָא כְּתִיב, (דברים כ״ח:ס״ט) אֵלֶּה דִּבְרֵי הַבְּרִית. הָכִי הוּא וַדַּאי, דְּכָל אִלֵּין לָא מִתְקַיְימֵי, אֶלָּא מִגּוֹ אֵלֶּה, דְּתַמָּן כָּל לְוָוטִין שָׁרְיָין, כְּמָה דְאוֹקִימְנָא דְּאִיהוּ אָרוּר. וּבְגִין דָּא אַקְדִּים וְאָמַר אֵלֶּה, דְּקָיְימָא לְמַאן דְּעֲבַר דִּבְרֵי הַבְּרִית.</p>\n<p>(ויקרא כ״ז:ל״ד) אֵלֶּה הַמִּצְוֹת אֲשֶׁר צִוָּה ה', בְּגִין דְּכָל פִּקּוּדָא דְאוֹרַיְיתָא לְאִתְדַּכָּאָה בַּר נָשׁ, וְלָא יִסְטֵי מֵאוֹרְחָא דָא, וְיִסְתַּמַּר מִתַּמָּן, וְיִתְפְּרַשׁ מִנַּיְיהוּ. וְאִי תֵימָא (בראשית ו׳:ט׳) אֵלֶּה תּוֹלְדוֹת נֹחַ. הָכִי הוּא וַדַּאי, דְּהָא נָפַק חָם, דְּאִיהוּ אֲבִי כְנַעַן, וּכְתִיב, (בראשית מט) אָרוּר כְּנַעַן וְאִיהוּ רָזָא דָא דְאֵלֶּה.</p>\n<p>וְעַל דָּא (ס\"א כל הני התוכא סוספיתא דדהבא, ועל דא כתיב מי אלה, ישראל כד עבדון עגלא) כְּתִיב וַיֹּאמְרוּ אֵלֶה אֱלהֶיךָ יִשְׂרָאֵל, וְכָל הַנֵּי הִתּוּכָא סוֹסְפִיתָא דְּדַהֲבָא. אַהֲרֹן קָרִיב דַּהֲבָא, דְּאִיהוּ סִטְרָא דִילֵיהּ, דְּכָלִיל אִיהוּ בְּתוּקְפָא דְאֶשָׁא, וְכֹלָּא חַד, וְסִטְרָא דָא דַּהֲבָא וְאֶשָּׁא. (ד\"א ל\"ג לאתתקפא) רוּחַ מְסָאֲבָא, דְּאִשְׁתַּכַּח תָּדִיר בְּמַדְבְּרָא, אַשְׁכַּח אֲתַר בְּהַהוּא זִמְנָא, לְאַתְקָפָא בֵּיהּ.</p>\n<p>וּמַה דְּהֲווּ יִשְׂרָאֵל דָּכְיָין מֵהַהוּא זוּהֲמָא קַדְמָאָה דְּאַטִיל בְּעַלְמָא, דְּגָרִים מוֹתָא לְעַלְמָא, כַּד קָמוּ עַל טוּרָא דְסִינַי, לְבָתַר אַהֲדָרוּ, וְגָרִים לוֹ כְּמִלְּקַדְּמִין, לְסָאֲבָא לוֹן, וּלְאִתְתַּקְפָא עֲלַיְיהוּ. וְגָרִים לוֹן מוֹתָא, וּלְכָל עַלְמָא, לְדָרֵיהוֹן בַּתְרַיְיהוּ. הֲדָא הוּא דִכְתִיב, (תהילים פ״ב:ו׳) אֲנִי אָמַרְתִּי אֱלהִים אַתֶּם וְגו' אָכֵן כְּאָדָם וְגו'.</p>\n<p>וְעַל דָּא כַּד חָמָא יַעֲקֹב לְיָרָבְעָם בֶּן נְבָט דְּעֲבַד כּוֹכָבִים וּמַזָּלוֹת, וְאָמַר אֵלֶּה אֱלהֶיךָ, אִזְדַּעְזַע, וְאָמַר מִי אֵלֶּה. כַּד בָּעָא לְבָתַר לְבָרְכָא לוֹן, בָּרִיךְ לֵיהּ (ס\"א לשכינתא בקדמיתא, ולבתר) בָּרִיךְ (לון) לִבְנוֹי. כֵּיוָן דְּבָרִיךְ לְקוּדְשָׁא בְּרִיךְ הוּא בְּקַדְמִיתָא, לְבָתַר מֵהַהוּא אֲתַר דְּבָרִיךְ בְּקַדְמִיתָא, בָּרִיךְ לוֹן. הֲדָא הוּא דִכְתִיב הַמַּלְאָךְ הַגּוֹאֵל אוֹתִי מִכָּל רָע וְגו'.</p>"],[9520011459,"<p>רִבִּי יְהוּדָה פָּתַח וְאָמַר, (ישעיהו ל״ח:ב׳) וַיַּסֵּב חִזְקִיָּהוּ פָּנָיו אֶל הַקִּיר וַיִּתְפַּלֵּל אֶל ה'. הָא אוּקְמוּהָ, דְּלָא לִצְלֵי בַּר נָשׁ אֶלָּא סָמוּךְ לְכוֹתְלָא, וְלָא יְהֵא מִלָּה חָצִיץ בֵּינֵיהּ לְבֵין כּוֹתְלָא. דִּכְתִיב וַיַּסֵּב חִזְקִיָּהוּ פָּנָיו אֶל הַקִּיר. מַאי שְׁנָא בְּכֻלְּהוּ דְּצַלֵּי צְלוֹתָא, דְּלָא כְּתִיב בְּהוּ וַיַּסֵּב פָּנָיו אֶל הַקִּיר, דְּהָא דַי לֵיהּ דְּיֵימָא וְיִתְפַּלֵּל אֶל ה', דְּהָא מַאן דְּמַצְלֵי צְלוֹתָא, אִיהוּ כִּוִּון דַּעְתֵּיהּ כְּדְקָא יְאוּת, דְּהָא כְּתִיב בְּמשֶׁה, (במדבר י״א:ב׳) וַיִּתְפַּלֵּל משֶׁה אֶל ה'. (שמות י״א:ט׳) וַיִּצְעַק משֶׁה אֶל ה' וְלָא כְּתִיב <Nonei></i>וַיַּסֵּב פָּנָיו. הָכָא בְּחִזְקִיָּהוּ, מַאי טַעְמָא וַיַּסֵּב חִזְקִיָּהוּ פָּנָיו אֶל הַקִּיר, וּלְבָתַר וַיִּתְפַּלֵּל.</p>\n<p>אֶלָּא רָזָא דְמִלָּה אִיהוּ, דְּתָנִינָן, חִזְקִיָּה בְּהַהוּא זִמְנָא לָא הֲוָה נָסִיב, וְלָא הֲוָה לֵיהּ אִנְתּוּ, וְלָא אוֹלִיד בְּנִין, מַה כְּתִיב, (ישעיהו ל״ח:א׳) וַיָּבֹא אֵלָיו וְגו' כִּי מֵת אַתָּה וְלֹא תִחְיֶה, וְתָנִינָן כִּי מֵת אַתָּה בָּעוֹלָם הַזֶּה, וְלָא תִחְיֶה בָּעוֹלָם הַבָּא. מַאי טַעְמָא, בְּגִין דְּלָא אוֹלִיד בְּנִין.</p>\n<p>דְּכָל מַאן דְּלָא אִשְׁתַּדַּל לְאוֹלָדָא בְּנִין בְּהַאי עַלְמָא, לָא מִתְקַיֵּים בְּעַלְמָא דְאָתֵי, וְלָא יְהֵא לֵיהּ חוּלָקָא בְּהַהוּא עַלְמָא. וְאִתְתָּרְכַת נִשְׁמָתֵיהּ בְּעַלְמָא (דאתי), וְלָא אַשְׁכָּחַת נַיְיחָא בְּאֲתַר דְּעַלְמָא. וְדָא הוּא עוֹנָשָׁא דִּכְתִיב בְּאוֹרַיְיתָא, (ויקרא כ׳:כ׳) עֲרִירִים יָמוּתוּ, וּמְתַרְגְּמִינָן בְּלָא וְלָד. בְּגִין דְּמַאן דְּאִיהוּ בְּלָא וְלַד, כַּד אָזִיל בְּהַהוּא עַלְמָא, מִית הוּא תַּמָּן. מִית בְּעַלְמָא דֵין, וּבְעַלְמָא דְאָתֵי. וְעַל דָּא כְּתִיב כִּי מֵת אַתָּה וְלֹא תִחְיֶה.</p>\n<p>וְלֹא עוֹד, אֶלָּא דִּשְׁכִינְתָּא לָא שַׁרְיָא עֲלוֹי כְּלָל, כְּדֵין כְּתִיב וַיַּסֵּב חִזְקִיָּהוּ פָּנָיו אֶל הַקִּיר. אוֹלִיפְנָא דְּשַׁוֵּי רַעֲיוֹנוֹי, וְכַוֵּון אַנְפּוֹהִי לְמֵיסַב אִתְּתָא, בְּגִין דְּתִשְׁרֵי עֲלוֹי שְׁכִינְתָּא, רָזָא דְקִיר.</p>\n<p>וּבְגִין כָּךְ כְּתִיב לְבָתַר, וַיִּתְפַּלֵּל אֶל ה', מִכָּאן אוֹלִיפְנָא, דְּמַאן דְּאִית בֵּיהּ חוֹבָא, וּבָעֵי לְמִבְעֵי רַחֲמֵי עֲלוֹי, יְכַוֵּין אַנְפּוֹי וְרַעֲיוֹנוֹי, לְאַתְקָנָא גַּרְמֵיהּ מֵהַהוּא חוֹבָא, וּלְבָתַר יִבְעֵי צְלוֹתָא. כְּמָא דְאַתְּ אָמֵר, (איכה ג׳:מ׳) נַחְפְּשָׂה דְרָכֵינוּ וְנַחְקוֹרָה בְּקַדְמִיתָא, וּלְבָתַר וְנָשׁוּבָה. אוּף הָכָא, כֵּיוָן דְּיָדַע חִזְקִיָּהוּ חוֹבֵיהּ, מַה כְּתִיב וַיַּסֵּב חִזְקִיָּהוּ פָּנָיו אֶל הַקִּיר, שַׁוֵּי אַנְפּוֹי לְאַתְקָנָא לְגַבֵּי שְׁכִינְתָּא, דְּהָא לְגַבֵּי אֲתַר דָּא חָב.</p>\n<p>בְּגִין דִּשְׁכִינְתָּא כָּל נוּקְבֵי דְעַלְמָא קַיְימִין בְּסִתְרָהָא. מַאן דְּאִית לֵיהּ נוּקְבָא, שַׁרְיָא אִיהִי לְגַבֵּיהּ, וּמַאן דְּלֵית לֵיהּ, לָא שַׁרְיָא לְגַבֵּיהּ. וְעַל דָּא אַתְקִין גַּרְמֵיהּ לְגַבָּהּ לְאַתְקָנָא, וְשַׁוֵּי עֲלֵיהּ לְאִתְנַסְּבָא, וּלְבָתַר וְיִתְפַּלֵּל אֶל יְיָ.</p>\n<p>קִיר, דָּא הוּא אֲדוֹן כָּל הָאָרֶץ, וְדָא שְׁכִינְתָּא, כְּמָא דְאַתְּ אָמֵר, (יהושע ג׳:י״א) הִנֵּה אֲרוֹן הַבְּרִית אֲדוֹן כָּל הָאָרֶץ. קִיר, כְּמָא דְאַתְּ אָמֵר, (ישעיהו כ״ב:ה׳) מְקַרְקַר קִיר וְשׁוֹעַ. קִרְקוּרָא וּנְהִימָא דְקִיר, דְּאִיהוּ אָדוֹן, כַּד אִתְחָרִיב בֵּי מַקְדְּשָׁא, כְּמָא דְאַתְּ אָמֵר, (ירמיהו ל״א:ט״ו) רָחֵל מְבַכָּה עַל בָּנֶיהָ, וְהָא אוֹקִימְנָא. וּבְגִין כָּךְ וַיַּסֵּב חִזְקִיָּהוּ פָּנָיו אֶל הַקִּיר.</p>\n<p>תָּא חֲזֵי, בִּצְלוֹתָא מַה כְּתִיב, (ישעיהו ל״ח:ג׳) אָנָא יְיָ זְכָר נָא אֶת אֲשֶׁר הִתְהַלַּכְתִּי לְפָנֶיךָ, רָמַז הָכָא, דְּנָטַר בְּרִית קַדִּישָׁא, וְלָא סָאִיב לֵיהּ, וְנָטַר לֵיהּ כְּדְקָא יְאוּת. כְּתִיב הָכָא הִתְהַלַּכְתִּי לְפָנֶיךָ, וּכְתִיב הָתָם (בראשית י״ז:א׳-ב׳) הִתְהַלֵּךְ לְפָנַי וְהְיֶה תָמִים וְאֶתְּנָה בְרִיתִי בֵּינִי וּבֵינֶיךָ, דְּנָטַר בְּרִית קַדִּישָׁא כְּדְקָא יְאוּת. בֶּאֱמֶת וּבְלֵב שָׁלֵם, דְּאִתְכַּוֵּון בְּכָל אִינוּן רָזֵי מְהֵימְנוּתָא דִּכְלִילָן בֶּאֱמֶת.</p>\n<p>וְהַטּוֹב בְּעֵינֶיךָ עָשִׂיתִי, דְּסָמַךְ גְּאוּלָה לִתְפִלָּה, וְהָא אוֹקִימְנָא. וְהָא אוּקְמוּהָ חַבְרַיָיא, דְּאִתְכַּוֵּון לְיַחֲדָא יִחוּדָא כְּדְקָא יְאוּת. וּבְגִין כָּךְ, וַיֵּבְךִ חִזְקִיָּהוּ בְּכִי גָדוֹל, דְּלֵית תַּרְעָא דְּקָיְימָא קַמֵּי דִּמְעִין. גְּאוּלָה, דָּא הוּא מַלְאָךְ הַגּוֹאֵל, דְּדָא אִיהוּ דְאִשְׁתַּכַּח בְּכָל פֵּרוֹקָא דְעַלְמָא, וְהָא אוֹקִימְנָא.</p>"],[9520011460,"<p>הַמַּלְאָךָ הַגּוֹאֵל אוֹתִי מִכָּל רָע. רִבִּי אֶלְעָזָר אָמַר, כֵּיוָן דְּבָרִיךְ יַעֲקֹב וְאִתְכַּוֵּון מִתַּתָּא לְעֵילָא, כְּדֵין אַמְשִׁיךְ מֵעֵילָא לְתַתָּא, דִּכְתִיב הָאֱלֹהִים הָרוֹעֶה אוֹתִי, כֵּיוָן דְּאִיהוּ נָטִיל, יָהִיב בִּרְכָאן לְהַאי אֲתַר, כֵּיוָן דְּאַמְטֵי בִּרְכָאן לְהַאי אֲתַר, כְּדֵין פָּתַח וְאָמַר הַמַּלְאָךְ הַגּוֹאֵל וְגו'.</p>\n<p>פָּתַח וְאָמַר, (מלכים א ח׳:ז׳) כִּי הַכְּרוּבִים פּוֹרְשֵׂי כְּנָפַיִם אֶל מְקוֹם הָאָרוֹן וְגו'. תָּא חֲזֵי, כְּרוּבִים בְּאָת וּבְנִיסָא הֲווּ קָיְימֵי, תְּלַת זִמְנִין בְּיוֹמָא הֲווּ פָּרְשֵׂי גַדְפֵיהוֹן, וְסָכְכֵי עַל אֲרוֹנָא לְתַתָּא, דִּכְתִיב פּוֹרְשֵׂי כְנָפַיִם, פְּרוּשֵׂי לָא כְּתִיב, אֶלָּא פּוֹרְשֵׂי.</p>\n<p>וְתָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא עָבִיד לְתַתָּא כְּגַוְונָא דִלְעֵילָא, כְּרוּבִים, דִּיוּקְנָא דִלְהוֹן כְּחֵיזוּ רַבְיָין, וְקָיְימִין תְּחוֹת הַאי אֲתַר, מִימִינָא וּמִשְׂמָאלָא, וְאִלֵּין אִתְבָּרְכָן בְּקַדְמִיתָא מֵהַנְהוּ בִּרְכָאן דְּנָגְדָן מֵעֵילָא, וּמֵהָכָא נַגְדֵי בִּרְכָאן לְתַתָּא.</p>\n<p>וְעַל דָּא כְּתִיב, הַמַּלְאָךְ הַגּוֹאֵל אוֹתִי מִכָּל רָע. אוֹתִי, דְּנָטִיל בִּרְכָאן מִגְּוָונִין דִּלְעֵילָא, וְכֵיוָן דְּאִיהוּ נָטִיל, יְבָרֵךְ אֶת הַנְּעָרִים, דָּא רָזָא דִכְרוּבִים, דְּמִנַּיְיהוּ נָגְדֵי <Nonei></i>בִּרְכָאן מֵעִילָאֵי לְתַתָּאֵי (ותתאי):</p>\n<p>הַמַּלְאָךָ הַגּוֹאֵל אוֹתִי מִכָּל רָע יְבָרֵךְ אֶת הַנְּעָרִים וְגו'. רִבִּי חִיָּיא פָּתַח וְאָמַר, (משלי י״ט:י״ד) בַּיִת וָהוֹן נַחֲלַת אָבוֹת, וְכִי נַחֲלַת אָבוֹת אִינְהוּ, וְהָא קוּדְשָׁא בְּרִיךְ הוּא יָהִיב כֹּלָּא לְבַּר נָשׁ. אֶלָּא, דְּכֵיוָן דְּאַחְסִין בֵּיתָא לְבַר נָשׁ וּמָמוֹנָא, לְזִמְנִין דְּיַחֲסִין כֹּלָּא לִבְרֵיהּ, וִיהֵא אַחְסָנָא דְאָבוֹת. אֲבָל וּמֵיְיָ אִשָּׁה מַשְׂכָּלֶת, בְּגִין דְּאִתְּתָא, כַּד אַחְסִין לָהּ בַּר נָשׁ, מֵעִם קוּדְשָׁא בְּרִיךְ הוּא אַחְסִין לָהּ, דְּהָא לָא יַחְסִין לָהּ קוּדְשָׁא בְּרִיךְ הוּא לְבַּר נָשׁ, אֶלָּא כַּד מַכְרִיזִין עֲלֵיהּ בִּרְקִיעָא.</p>\n<p>דְּקוּדְשָׁא בְּרִיךְ הוּא מְזַוֵּוג זִווּגִין, עַד לָא יֵיתוּן לְעַלְמָא. וְכַד זָכוּ בְּנֵי נָשָׁא לְפוּם עוֹבָדֵיהוֹן, הָכִי יַהֲבֵי לוֹן אִתְּתָא, וְכֹלָּא אִתְגַּלְּיָין קַמֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, וּלְפוּם עוֹבָדִין דְּזַכָּאִין, הָכִי מְזַוִּוג זִוּוּגִין.</p>\n<p>וּלְזִמְנִין דְּקָא סְלִיקוּ בִּקְלִיטִין, וְאַסְטֵי הַהוּא בַּר נָשׁ אָרְחֵיהּ, סָלִיק זִוּוּגֵיהּ לְאָחֳרָא, עַד דְּיִכְשַׁר עוֹבָדוֹי, וְכַד יִכְשַׁר עוֹבָדוֹי, אוֹ דְּמָטֵי זִמְנֵיהּ, אִתְדָּחֵי גְּבַר מִקַּמֵּי גְבַר, וְאָתֵי הַאי וְנָטִיל דִּילֵיהּ. וְדָא קָשֵׁי קַמִּי קוּדְשָׁא בְּרִיךְ הוּא מִכֹּלָּא לְדַחְיָא בַּר נָשׁ מִקַּמֵּי גַבְרָא אָחֳרָא, וּבְגִין כָּךְ קוּדְשָׁא בְּרִיךְ הוּא אִיהוּ יָהִיב אִתְּתָא לְבַּר נָשׁ, וּמִנֵּיהּ אַתְיָין זִוּוּגִין. וְעַל דָּא וּמֵיְיָ אִשָּׁה מַשְׂכָּלֶת.</p>\n<p>בְּגִין כָּךְ, קוּדְשָׁא בְּרִיךְ הוּא יָהִיב כֹּלָּא לְבַר נָשׁ. וְאִי תֵימָא אִשָּׁה מַשְׂכָּלֶת וְלָא אָחֳרָא. תָּא חֲזֵי, אַף עַל גַּב דְּקוּדְשָׁא בְּרִיךְ הוּא אַזְמִין טָבָאן לְבַּר נָשׁ לְמֵיהַב לֵיהּ, וְהוּא אַסְטֵי אָרְחוֹי מֵעִם קוּדְשָׁא בְּרִיךְ הוּא לְגַבֵּי סִטְרָא אָחֳרָא, מֵהַהוּא סִטְרָא אָחֳרָא דְּאִתְדָּבַּק בֵּיהּ, יֵיתֵי לֵיהּ מַאן דְּיֵיתֵי, בְּכָל (נ\"א כל) קִטְרוּגִין, וְכָל בִּישִׁין, וְלָא אַתְיָין לֵיהּ מֵעִם קוּדְשָׁא בְּרִיךְ הוּא, אֶלָּא מֵהַהוּא סִטְרָא בִּישָׁא דְּאִתְדָּבַּק בֵּיהּ, בְּאִינוּן עוֹבָדִין דְּעָבַד.</p>\n<p>וְעַל דָּא, אִתְּתָא דְּלָאו אִיהִי מַשְׂכֶּלֶת, קָרָא עַל דָּא שְׁלמֹה, (קהלת ז׳:כ״ו) וּמוֹצֵא אֲנִי מַר מִמָּוֶת אֶת הָאִשָּׁה. בְּגִין דְּחוֹבוֹי דְּבַּר נָשׁ, הוּא מָשִׁיךְ עֲלֵיהּ, בְּאִינוּן עוֹבָדִין דְּעָבַד. וְעַל דָּא כַּד קוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בֵּיהּ בְּבַר נָשׁ, בְּגִין עוֹבָדוֹי דְּכָשְׁרָן, אִיהוּ אַזְמִין לֵיהּ אִנְתּוּ דְּאִיהִי מַשְׂכֶּלֶת, וּפָרִיק לֵיהּ בְּפוּרְקָן, מִגּוֹ סִטְרָא אָחֳרָא.</p>\n<p>וְעַל דָּא אָמַר יַעֲקֹב, הַמַּלְאָךְ הַגּוֹאֵל אוֹתִי מִכָּל רָע. מַאי מִכָּל רָע, דְּלָא אִזְדַּמְּנַת לִי אִתְּתָא, דְּאִיהִי מִגּוֹ סִטְרָא אָחֳרָא, וְלָא אִעָרַע פְּסוּל בְּזַרְעִי (ס\"א בערסי), דְּכֻלְּהוּ צַדִּיקֵי וּשְׁלֵימֵי בִּשְׁלִימוּ, בְּגִין דְּאִתְפְּרַק מִכָּל רָע, וְיַעֲקֹב לָא אִתְדָּבַּק בְּהַהוּא סִטְרָא אָחֳרָא כְּלָל.</p>\n<p>וְעַל דָּא, הַמַּלְאָךְ הַגּוֹאֵל אוֹתִי מִכָּל רָע יְבָרֵךְ אֶת הַנְּעָרִים. מַאי טַעְמָא אִתְחֲזוּ לְאִתְבָּרְכָא, בְּגִין דְּנָטִיר יוֹסֵף אָת קַיָּימָא קַדִּישָׁא, וְעַל דָּא אָמַר יוֹסֵף בָּנַי הֵם אֲשֶׁר נָתַן לִי אֱלֹהִים בָּזֶה, אַחְמֵי לֵיהּ רָזָא דִבְרִית דְּנָטַר לֵיהּ. וּבְגִין דְּנָטַר לֵיהּ, אִתְחֲזוּ לְאִתְבָּרְכָא וְאִתְחֲזֵי אִיהוּ לְבִרְכָאן סַגִּיאִין. בְּגִין דָּא לְכֻלְּהוּ יָהַב בִּרְכָא חַד, וּלְיוֹסֵף בִּרְכָאן סַגִּיאִין, מַשְׁמַע דִּכְתִיב בִּרְכוֹת אָבִיךָ גָּבְרוּ עַל בִּרְכוֹת הוֹרַי וְגו', בִּרְכוֹת שָׁדַיִם וָרָחַם תִּהְיֶיןָ לְרֹאשׁ יוֹסֵף.</p>\n<p>רִבִּי יְהוּדָה פָּתַח וְאָמַר, (ר\"ח ע\"ב) (תהילים קכ״ג:א׳) אֵלֶיךָ נָשָׂאתִי אֶת עֵינַי הַיּוֹשְׁבִי בַּשָּׁמָיִם, הַאי קְרָא אוּקְמוּהָ, אֲבָל תָּא חֲזֵי, צְלוֹתָא דְּבַּר נָשׁ דְּאִתְכַּוֵּון בָּהּ, אִיהוּ לְעֵילָא לְעוּמְקָא עִלָּאָה, דְּמִתַּמָּן נָגְדֵי כָּל בִּרְכָאן וְכָל חֵירוּ, וּמִתַּמָּן נָפְקֵי לְקָיְימָא כֹּלָּא.</p>\n<p>וְעַל דָּא יַתִּיר יו\"ד, בְּגִין דְּלָא פָּסִיק יוּ\"ד, מֵאֲתַר דָּא לְעָלְמִין. וּבְגִין דָּא כְּתִיב, הַיּוֹשְׁבִי בַּשָּׁמָיִם, אָחִיד לְעֵילָא, בְּרָזָא דְּחָכְמְתָא עִלָּאָה, וְאָחִיד לְתַתָּא, דְּיָתִיב עַל כָּרְסְיָא דְּאֲבָהָן, יָתִיב עַל כָּרְסְיָא דְּאִקְרֵי שָׁמָיִם, וּבְגִין כָּךְ הַיּוֹשְׁבִי בַּשָּׁמָיִם כְּתִיב.</p>\n<p>וּמֵהָכָא, כַּד בִּרְכָאן נָגְדֵי מֵעֵילָא מֵעוּמְקָא דָא, כֻּלְּהוּ נָטִיל לוֹן הַאי אֲתַר דְּאִקְרֵי שָׁמַיִם, וּמֵהַאי נָגְדֵי לְתַתָּא, עַד דְּמָטוּ לְצַדִּיקַיָּיא קְיָימָא דְעַלְמָא, וּמֵהָכָא מִתְבָּרְכִין כָּל אִינוּן חַיָּילִין, וְכָל אִינוּן מַשִּׁרְיָין לִזְנַיְיהוּ, וְהָא אוּקְמוּהָ.</p>\n<p>תָּא חֲזֵי, בְּשִׁבְעִין וּתְרֵין נְהוֹרִין, אִסְתַּלַּק עֲטָרָא דְּכָל מַשִּׁרְיָין, עִגּוּלָא דְעַלְמָא, בְּשִׁבְעִין דּוּכְתֵּי, חַד עִגּוּלָא לְכֻלְּהוּ (לעיל נ\"ג ע\"ב) בְּגוֹ הַהוּא עִגּוּלָא נְקוּדָה חָדָא דְּקָיְימָא בְּאֶמְצָעִיתָא, מֵהַאי נְקוּדָה, אִתְּזָנַת כָּל הַהוּא עִגּוּלָא, בֵּית קֹדֶשׁ הַקֳּדָשִׁים, אִיהוּ אֲתַר <Nonei></i>לְהַהוּא רוּחָא דְּכָל רוּחִין (ס\"א הכא רזא דכל רזין) אִתְטַמַּר בְּגַוֵּיהּ. הַאי טְמִירוּ אִיהוּ בְּגוֹ חֵילָהָא, טְמִירָא אִיהוּ בְּגוֹ לְגוֹ, כַּד סָלְקָא דָא, כֹּלָּא סָלְקִין אֲבַתְרָהּ. הֲדָא הוּא דִכְתִיב, (שיר השירים א׳:ד׳) מָשְׁכֵנִי אַחֲרֶיךָ נָרוּצָה.</p>"],[9520011461,"<p>רִבִּי חִזְקִיָּה וְרִבִּי יוֹסֵי וְרִבִּי יְהוּדָה הֲווּ אָזְלֵי בְּאוֹרְחָא, אָמַר רִבִּי יוֹסֵי, כָּל חַד וְחַד מִינָן לֵימָא מִלֵּי דְאוֹרַיְיתָא. פָּתַח רִבִּי יְהוּדָה וְאָמַר, (תהילים ע״ט:ח׳) אַל תִּזְכָּר לָנוּ עֲוֹנוֹת רִאשׁוֹנִים מַהֵר יְקַדְמוּנוּ וְגו'. תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא, בִּרְחִימוּתָא דְיִשְׂרָאֵל, רָחִים לוֹן, דְּאִינוּן עַדְבֵיהּ וְאַחְסַנְתֵּיהּ, לָא מִסְתַּכַּל אָחֳרָא בְּדִינַיְיהוּ, בַּר אִיהוּ בִּלְחוֹדֵיהּ. וְכֵיוָן דְּאִיהוּ מִסְתַּכֵּל בְּדִינַיְיהוּ, אִתְמָלֵי עֲלַיְיהוּ רַחֲמִין, בְּגִין דְּאִיהוּ כְּאָב דְּרָחִים עַל בָּנִים, כְּמָא דְאַתְּ אָמֵר, (תהילים ק״ג:י״ג) כְּרַחֵם אָב עַל בָּנִים רִחַם ה' וְגו'. וְכֵיוָן דְּאִשְׁתַּכַּח לוֹן חוֹבִין, מַעֲבָר לוֹן רִאשׁוֹן רִאשׁוֹן, עַד דְּאַעֲבַר לוֹן לְכֻלְּהוּ מִקַּמֵּיהּ. וְכֵיוָן דְּאַעֲבַר לוֹן מִקַּמֵּיהּ, לָא אִשְׁתָּאַר עֲלַיְיהוּ חוֹבִין לְמֵיהַב שָׁלְטָנוּ לְסִטְרָא אָחֳרָא דְּדִינָא עֲלַיְיהוּ.</p>\n<p>אָתֵי לְמֵיחַב קַמֵּיהּ כְּדְבְּקַדְמִיתָא, אִינוּן חוֹבִין קַדְמָאֵי דְּאַעֲבַר מִקַּמֵּיהּ חָשִׁיב עֲלַיְיהוּ, וְעַל דָּא כְּתִיב אַל תִּזְכָּר לָנוּ עֲוֹנוֹת רִאשׁוֹנִים מַהֵר יְקַדְמוּנוּ רַחֲמֶיךָ וְגו'. דְּאִי רַחֲמֶיךָ לֹא יַקְדִּימוּ עֲלַיְיהוּ דְיִשְׂרָאֵל, לָא יָכְלִין לְקָיְימָא בְּעַלְמָא. בְּגִין דְּכַמָּה אִינוּן מָארֵי דְּדִינָא קַשְׁיָא, מָארֵי תְּרִיסֵין, וְכַמָּה דִלְטוֹרִין דְּקָיְימֵי עֲלַיְיהוּ דְיִשְׂרָאֵל לְעֵילָא, וְאִלְמָלֵא דְּאַקְדִּים קוּדְשָׁא בְּרִיךְ הוּא רַחֲמִים עֲלַייהוּ דְיִשְׂרָאֵל, עַד לָא יַשְׁגַּח בְּדִינֵיהוֹן, לָא יָכְלִין לְקָיְימָא בְּעַלְמָא. וְעַל דָּא, מַהֵר יְקַדְמוּנוּ רַחֲמֶיךָ כִּי דַלוֹנוּ מְאֹד. דַּלּוּתָא דְעוֹבָדִין טָבִין, דַּלּוּתָא דְּעוֹבָדִין דְּכָשְׁרָן. (קמי קודשא בריך הוא).</p>\n<p>תָּא חֲזֵי, אִלְמָלֵי יְסַגְּלוּן יִשְׂרָאֵל עוֹבָדִין דְּכָשְׁרָן קַמֵּי קוּדְשָׁא בְרִיךְ הוּא, לָא הֲווּ קָאִימוּ עֲלֵיהּ עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת בְּעַלְמָא, אֲבָל יִשְׂרָאֵל אִינוּן גָּרְמִין לִשְׁאָר עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת לְזָקְפָא רֵישַׁיְיהוּ בְּעַלְמָא. דְּאִלְמָלֵי יִשְׂרָאֵל לָא יְהוֹן חָטָאן קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא שְׁאָר עַמִין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת אִתְכַּפְיָין קַמַּיְיהוּ.</p>\n<p>וְתָא חֲזֵי, אִלְמָלֵא דְּאַמְשִׁיכוּ יִשְׂרָאֵל בְּעוֹבָדִין בִּישִׁין לִסְטַר אָחֳרָא בְּאַרְעָא קַדִּישָׁא, הָא אִתְּמָר, דְּלָא שָׁלְטוּ שְׁאָר עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת בְּאַרְעָא קַדִּישָׁא, וְלָא אִתְגָּלוּ מֵעַל אַרְעָא. וְעַל דָּא כְּתִיב, כִּי דַלּוֹנוּ מְאֹד. דְּלֵית לָן עוֹבָדִין דְּכָשְׁרָן כְּדְקָא חָזֵי. וּבְגִין כָּךְ כִּי דַלּוֹנוּ מְאֹד מַהֵר יְקַדְמוּנוּ רַחֲמֶיךָ.</p>"],[9520011462,"<p>רִבִּי יוֹסֵי פָּתַח וְאָמַר, (תהילים ב׳:י״א) עִבְדוּ אֶת ה' בְּיִרְאָה וְגִילוּ בִּרְעָדָה, וּכְתִיב, (תהילים ק׳:ב׳) עִבְדוּ אֶת ה' בְּשִׂמְחָה בֹּאוּ לְפָנָיו בִּרְנָנָה. תָּא חֲזֵי, כָּל בַּר נָשׁ דְּאָתֵי לְמִפְלַח לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, בְּצַפְרָא וּבְפַנְיָא בָּעֵי לְמִפְלַח לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>בְּצַפְרָא כַּד סָלִיק נְהוֹרָא, וְאִתְעָרוּתָא דִסְטַר יְמִינָא אִתְעַר בְּעַלְמָא, כְּדֵין בָּעֵי בַּר נָשׁ לְאִתְקַשְּׁרָא בִּימִינָא דְקוּדְשָׁא בְּרִיךְ הוּא, וּלְמִפְלַח קַמֵּיהּ בְּפוּלְחָנָא דִצְלוֹתָא. בְּגִין דִּצְלוֹתָא אַחְסִין תּוּקְפָא לְעֵילָא, וְאַמְשִׁיךְ בִּרְכָאן מֵעוּמְקָא עִלָּאָה לְכֻלְּהוּ עַלְמִין, וּמִתַּמָּן אַמְשִׁיךְ בִּרְכָאן לְתַתָּאֵי. וְאִשְׁתַּכְּחוּ עִלָּאִין וְתַתָּאִין מִתְבָּרְכָאן, בְּהַהוּא פּוּלְחָנָא דִצְלוֹתָא.</p>\n<p>פּוּלְחָנָא דִצְלוֹתָא, דְּקָא בָּעֵי בַּר נָשׁ לְמִפְלַח קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, (שמות כ\"ט ע\"א) בְּשִׂמְחָה וּבִרְנָנָה לְאַכְלָלָא לִכְנֶסֶת יִשְׂרָאֵל בֵּינַיְיהוּ, וּלְבָתַר לְיַיחֲדָא יִחוּדָא כְּדְקָא חָזֵי. דִּכְתִיב, (תהילים ק׳:ג׳) דְּעוּ כִּי ה' הוּא אֱלֹהִים, דָּא רָזָא דְּיִחוּדָא בְּרָזָא דְפוּלְחָנָא.</p>\n<p>וְעִם כָּל דָּא, בָּעֵי בַּר נָשׁ לְמִפְלַח קַמֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא בְּחֶדְוָה, וּלְאַחֲזָאָה חֶדְוָה בְּפוּלְחָנֵיהּ, וְאִלֵּין תְּרֵין שִׂמְחָה וּרְנָנָה, לָקֳבֵל תְּרֵין אִלֵּין, תְּרֵין צְלוֹתִין, תְּרֵין קוּרְבָּנִין לְיוֹמָא לָקֳבֵל תְּרֵין אִלֵּין, דְּאִינוּן שִׂמְחָה וּרְנָנָה. שִׂמְחָה בְּצַפְרָא, וּרְנָנָה בְּרַמְשָׁא. וְעַל דָּא, (במדבר כ״ח:ד׳) אֶת הַכֶּבֶשׂ אֶחָד תַּעֲשֶׂה בַּבֹּקֶר וְאֵת הַכֶּבֶשׂ הַשֵּׁנִי תַּעֲשֶׂה בֵּין הָעַרְבָּיִם.</p>\n<p>וְעַל דָּא, צְלוֹתָא דְעַרְבִית רְשׁוּת אִיהִי, בְּגִין דְּהַהִיא שַׁעְתָּא מְחַלֵּק טַרְפָּא לְכָל חֵילָהָא, וְ לָאו שַׁעְתָּא לְאַדְכָּרָא (נ\"א לאתברכא) אֶלָּא לְמֵיהַב מְזוֹנָא. בִּימָמָא הִיא מִתְבָּרֶכֶת מִתְּרֵין סִטְרִין אִלֵּין, בְּצַפְרָא וּבְרַמְשָׁא מִגּוֹ שִׂמְחָה וּרְנָנָה, וּבְלֵילְיָא פָּלִיג בִּרְכָאן לְכֹלָּא כְּדְקָא חָזֵי, הֲדָא הוּא דִכְתִיב, (משלי ל״א:ט״ו) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְגו'.</p>"],[9520011463,"<p>פָּתַח רִבִּי חִזְקִיָּה וְאָמַר, (תהילים קמ״א:ב׳) תִּכּוֹן תְּפִלָּתִי קְטֹרֶת לְפָנֶיךָ מַשְׂאַת כַּפַּי מִנְחַת עָרֶב. אַמַּאי מִנְחַת עָרֶב וְלָא צְלוֹתָא <Nonei></i>דְצַפְרָא, דְּלָא כְּתִיב תִּכּוֹן תְּפִלָּתִי בַּבֹּקֶר. אֶלָּא הָכִי אִתְּמָר, תִּכּוֹן תְּפִלָּתִי קְטֹרֶת לְפָנְיךָ, קְטֹרֶת לָא אַתְיָא אֶלָּא עַל חֶדְוָה, הֲדָא הוּא דִכְתִיב, (משלי כ״ז:ט׳) שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב. וְעַל דָּא כַּהֲנָא כַּד אַדְלִיק בּוֹצִינִין, הֲוָה מַקְרִיב קְטֹרֶת, כְּמָא דְאַתְּ אָמֵר, (שמות ל׳:ז׳-ח׳) בְּהֵטִיבוֹ אֶת הַנִּרוֹת יַקְטִירֶנָּה וּבְהַעֲלוֹת אַהֲרֹן אֶת הַנִּרוֹת בֵּין הָעַרְבַּיִם יַקְטִירֶנָּה. בְּצַפְרָא, עַל חֶדְוָה, דְּשַׁעְתָּא גָרִים. בְּרַמְשָׁא, לְמֶחדֵי סְטַר שְׂמָאלָא, וְהָכִי אִתְחֲזֵי. וּלְעָלַם לָא אָתֵי אֶלָּא עַל חֶדְוָה.</p>\n<p>וְתָא חֲזֵי קְטֹרֶת מְקַשֵּׁר קִשְׁרִין, וְאָחִיד לְעֵילָא וְתַתָּא, וְדָא אַעֲבַר מוֹתָא וְקִטְרוּגָא וְרוּגְזָא, דְּלָא יָכִיל לְשַׁלְטָאָה בְּעַלְמָא. כְּמָה דִכְתִיב, (במדבר י״ז:י״א) וַיֹּאמֶר משֶׁה אֶל אַהֲרֹן קַח אֶת הַמַּחְתָּה וְתֵן עָלֶיהָ אֵשׁ מֵעַל הַמִּזְבֵּחַ וְשִׂים קְטֹרֶת וְהוֹלֵךְ מְהֵרָה וְגו'. לְבָתַר דָּא כְּתִיב, וַיָּרָץ (אהרן) וְגו', וַיְכַפֵּר עַל הָעָם, וּכְתִיב, וַיַּעֲמֹד בֵּין הַמֵּתִים וּבֵין הַחַיִּים וַתֵּעָצַר הַמַּגֵּפָה. בְּגִין דְּלָא יָכְלִין כָּל סִטְרִין בִּישִׁין וְכָל מְקַטְרְגִין לְמֵיקַם קַמֵּי קְטֹרֶת. וְעַל דָּא אִיהוּ רָזָא (ס\"א חדוה) דְכֹלָּא וְקִשּׁוּרָא דְכֹלָּא.</p>\n<p>וּבְשַׁעְתָּא דְמִנְחָה, דְּדִינָא שַׁרְיָא בְּעַלְמָא, אִתְכַּוֵּון דָּוִד בְּהַהוּא צְלוֹתָא. דִּכְתִיב, תִּכּוֹן תְּפִלָּתִי קְטֹרֶת לְפָנֶיךָ וְגו'. וְהַאי צְלוֹתָא דְסָלִיק, יַעֲבֵר רוּגְזָא דְּדִינָא קַשְׁיָא, דְּשַׁלִּיט הַשְׁתָּא בְּהַאי זִמְנָא, בְּהַהוּא קְטֹרֶת. דְּדָחֵי וְאַעֲבַר קַמֵּיהּ כָּל רוּגְזָא, (דסליק השתא בהאי שעתא בההוא קטרת דאעדי כל רוגזא) וְכָל קִטְרוּגָא דְעַלְמָא, (ס\"א ל\"ג היינו דכתיב) (ס\"א מאי טעמא בגין דאיהי) מִנְחַת עָרֶב, דְּדִינָא תַּלְיָא בְּעַלְמָא.</p>\n<p>תָּא חֲזֵי, כַּד אִתְחָרַב בֵּי מַקְדְּשָׁא, בְּשַׁעְתָּא דְאִתּוֹקַד, זְמַן מִנְחָה הֲוָה. וְעַל דָּא כְּתִיב, (ירמיהו ו׳:ד׳) אוֹי לָנוּ כִּי פָנָה הַיּוֹם כִּי יִנָּטוּ צִלְלֵי עָרֶב. מַאן צִלְלֵי עָרֶב. אִינוּן מְקַטְרְגִין דְּעַלְמָא, וְרוּגְזֵי דְּדִינִין, דִּזְמִינִין בְּהַהִיא שַׁעְתָּא. וְעַל דָּא תָּנִינָן, דְּבָעֵי (שמות ל\"ו ע\"ב) בַּר נָשׁ לְכַוְּונָא דַעְתֵּיהּ, בִּצְלוֹתָא דְמִנְחָה. בְּכֻלְּהוּ צְלוֹתָא בָּעֵי בַּר נָשׁ לְכַוְּונָא דַעְתֵּיהּ, וּבְהַאי צְלוֹתָא יַתִּיר מִכֻּלְּהוּ, בְּגִין דְּדִינָא שַׁרְיָא בְּעַלְמָא. וְעַל דָּא זְמַן צְלוֹתָא דְמִנְחָה, יִצְחָק תַּקִּין לֵיהּ, וְהָא אוּקְמוּהָ.</p>"],[9520011464,"<p>עַד דְּהֲווּ אָזְלֵי, אָעֳלוּ בְּחַד טוּרָא. אָמַר רִבִּי יוֹסֵי, הַאי טוּרָא דַחֲלָא, נִהַךְ וְלָא נִתְעַכֵּב הָכָא, בְּגִין דְּטוּרָא דְּחִילָא הוּא. אָמַר רִבִּי יְהוּדָה, אִי הֲוָה חַד, הֲוָה אֲמִינָא הָכִי. דְּהָא תָּנִינָן, דְּמַאן דְּאָזִיל יְחִידָאי בְּאוֹרְחָא, אִתְחַיַּיב בְּנַפְשֵׁיהּ. אֲבָל תְּלָתָא לָא. וְכָל חַד וְחַד מִינָן, אִתְחֲזֵי דְלָא תַעֲדֵי מִינָן שְׁכִינְתָּא.</p>\n<p>אָמַר רִבִּי יוֹסֵי, הָא תָּנִינָן דְּלָא יִסְמוֹךְ בַּר נָשׁ עַל נִסָּא. מְנָלָן, מִשְׁמוּאֵל. דִּכְתִיב, (שמואל א ט״ז:ב׳) אֵיךְ אֵלֵךְ וְשָׁמַע שָׁאוּל וַהֲרָגָנִי, וְהָא אִתְחֲזֵי שְׁמוּאֵל יַתִּיר מִינָן. אָמַר לֵיהּ, אֲפִילּוּ הָכִי, אִיהוּ הֲוָה חַד, וְהֶזֵּיקָא אִשְׁתַּכַּח לְעֵינָא. אֲבָל אֲנַן תְּלָתָא, וְהֶזֵּיקָא לָא אִשְׁתַּכַּח לְעֵינָא. דְּאִי מִשּׁוּם מַזִּיקִין. הָא תָּנִינָן, דְּלִתְלָתָא לָא מִתְחֲזֵי וְלָא מַזְקֵי. וְאִי מִשּׁוּם לִסְטִים, לָא מִשְׁתַּכְּחֵי הָכָא, דְּהָא רָחִיק מֵיִישׁוּבָא הַאי טוּרָא, וּבְנֵי נָשָׁא לָא מִשְׁתַּכְּחֵי הָכָא. בְּרַם דְּחִילוּ הוּא, דְּחֵיוָון בָּרָא דְּמִשְׁתַּכְּחִין הָכָא.</p>\n<p>פָּתַח וְאָמַר. הַמַּלְאָךְ הַגּוֹאֵל אוֹתִי מִכָּל רָע, הַאי קְרָא אִית לְאִסְתַּכָּלָא בֵּיהּ, (ס\"א ל\"ג דהא כתיב) הַגּוֹאֵל, אֲשֶׁר גָּאַל מִבָּעֵי לֵיהּ, מַאי הַגּוֹאֵל. בְּגִין דְּהוּא מִשְׁתַּכַּח תָּדִיר לְגַבֵּי בְּנֵי נָשָׁא, וְלָא אַעֲדֵי מִבַּר נָשׁ זַכָּאָה לְעָלְמִין. תָּא חֲזֵי, הַמַּלְאָךְ הַגּוֹאֵל אוֹתִי דָּא שְׁכִינְתָּא, דְּאָזִיל עִמֵּיהּ דְּבַּר נָשׁ תָּדִיר, וְלָא אַעֲדֵי מִנֵּיהּ, כַּד בַּר נָשׁ נָטִיר פִּקּוּדֵי אוֹרַיְיתָא. וְעַל דָּא יִזְדַּהֵר בַּר נָשׁ, דְּלָא יִפּוּק יְחִידָאי בְּאוֹרְחָא. מַאי יְחִידָאי, דְּיִזְדַּהֵר בַּר נָשׁ לְמִטַּר פִּקּוּדֵי דְאוֹרַיְיתָא, בְּגִין דְּלָא תַעֲדֵי מִנֵּיהּ שְׁכִינְתָּא, וְיִצְטָרֵךְ לְמֵיזַל יְחִידָאי, בְּלָא זִוּוּגָא דִשְׁכִינְתָּא.</p>\n<p>תָּא חֲזֵי, כַּד נָפִיק בַּר נָשׁ לְאוֹרְחָא, יְסַדַּר צְלוֹתָא קַמֵי מָארֵיהּ, בְּגִין לְאַמְשָׁכָא עֲלֵיהּ שְׁכִינְתָּא, וּלְבָתַר יִפּוּק לְאוֹרְחָא, וְיִשְׁכַּח זִוּוּגָא דִשְׁכִינְתָּא, לְמִפְרַק לֵיהּ בְּאוֹרְחָא, וּלְשֵׁזָבָא לֵיהּ בְּכָל מַה דְּאִצְטְרִיךְ.</p>\n<p>מַה כְּתִיב בְּיַעֲקֹב, (בראשית כ״ח:כ׳) אִם יִהְיֶה אֱלֹהִים עִמָּדִי, דָּא זִווּגָא דִשְׁכִינְתָּא. וּשְׁמָרַנִי בַּדֶּרֶךְ הַזֶּה, לְמִפְרַק לִי מִכֹּלָּא, וְיַעֲקֹב יְחִידָאי הֲוָה <Nonei></i>בְּהַהוּא זִמְנָא, וּשְׁכִינְתָּא אָזְלַת קַמֵּיהּ. כָּל שֶׁכֵּן חַבְרַיָיא דְּאִית בֵּינַיְיהוּ מִלִּין דְּאוֹרַיְיתָא, עַל אַחַת כַּמָּה וְכַמָּה. (אמר רבי יוסי, ודאי כך הוא, אדהכי מאיך שמשא לערבא.)</p>\n<p>אָמַר רִבִּי יוֹסֵי, מַאי נַעֲבִיד, אִי נִתְעַכֵּב הָכָא, הָא יוֹמָא מָאִיךְ לְמֵיעַל. אִי נְהַךְ לְעֵילָא, טוּרָא רַב אִיהוּ, וּדְחִילוּ דְּחֵיוָון חַקְלָא דָּחִילְנָא. אָמַר רִבִּי יְהוּדָה, תְּוַוהְנָא עֲלָךְ רִבִּי יוֹסֵי. אָמַר לֵיהּ הָא תָּנִינָן דְּלָא יִסְמוֹךְ בַּר נָשׁ עַל נִיסָא, דְּקוּדְשָׁא בְּרִיךְ הוּא לָא יַרְחִישׁ נִיסָא בְּכָל שַׁעְתָּא. אָמַר לֵיהּ, הָנֵי מִילֵי יְחִידָאי, אֲבָל אֲנַחְנָא תְּלָתָא, וּמִלֵּי אוֹרַיְיתָא בֵּינָנָא, וּשְׁכִינְתָּא עִמָּנָא, לָא דָחִילְנָא.</p>"],[9520011465,"<p>עַד דְּהֲווּ אָזְלֵי, חָמוּ לְעֵילָא בְּטוּרָא, טִנָּרָא חַד, וְחַד מְעַרְתָּא בְּגַוָּוהּ. אָמַר רִבִּי יְהוּדָה, נִיהַךְ וְנֵיסַק לְהַהוּא טִינָרָא, דְּאֲנָא חָמֵי חָדָא מְעַרְתָּא תַּמָּן. סְלִיקוּ לְתַמָּן, וְחָמוּ הַהִיא מְעַרְתָּא. אָמַר רִבִּי יוֹסֵי, דָּחִילְנָא, דִּילְמָא הַהִיא מְעַרְתָּא אֲתַר דִּלְחֵיוָון אִיהוּ, וְלָא יִפְגְּעוּ לוֹן הָכָא.</p>\n<p>אָמַר רִבִּי יְהוּדָה לְרִבִּי חִזְקִיָּה, הָא חָמֵינָא דְּרִבִּי יוֹסֵי דָחִיל אִיהוּ, אִי תֵימָא בְּגִין דְּאִיהוּ חַטָּאָה. דְּכָל מַאן דְּדָחִיל, חַטָּאָה אִיהוּ. דִּכְתִיב, (ישעיהו ל״ג:י״ד) פָּחֲדוּ בְצִיּוֹן חַטָּאִים, הָא לָאו אִיהוּ חַטָּאָה, (והא) וּכְתִיב, (משלי כ״ח:א׳) וְצַדִּיקִים כִּכְפִיר יִבְטָח. אָמַר רִבִּי יוֹסֵי, בְּגִין דְּנִזְקָא שְׁכִיחַ.</p>\n<p>אָמַר לֵיהּ, אִי נִזְקָא שְׁכִיחַ, הָכִי הוּא. אֲבָל הָכָא לָא אִשְׁתַּכַּח נִזְקָא. וּלְבָתַר דְּאֲנַן נִיעוֹל לִמְעַרְתָּא, לָא לֵיעוּל נִזְקָא לְצַעֲרָא לָן. עָאלוּ לִמְעַרְתָּא, אָמַר רִבִּי יְהוּדָה, נִפְלוֹג לֵילְיָא לִתְלַת מִשְׁמָרוֹת דְּהֲוֵי לֵילְיָא, כָּל חַד וְחַד מִנָּן, לֵיקוּם עַל קִיּוּמֵיהּ, בְּהַנֵּי תְּלַת סִטְרֵי לֵילְיָא וְלָא נִדְמוּךְ.</p>\n<p>פָּתַח רִבִּי יְהוּדָה וְאָמַר, (תהילים פ״ט:א׳) מַשְׂכִּיל לְאֵיתָן הָאֶזְרָחִי, הַאי תּוּשְׁבַּחְתָּא, אַבְרָהָם אָבִינוּ אֲמָרָהּ, בְּשַׁעְתָּא דְּאִשְׁתַּדַּל בְּפוּלְחָנָא דְקוּדְשָׁא בְּרִיךְ הוּא, וְעָבִיד חֶסֶד עִם בְּנֵי עַלְמָא, דְּיִשְׁתְּמוֹדְעוּן כֹּלָּא לְקוּדְשָׁא בְּרִיךְ הוּא, דְּקוּדְשָׁא בְּרִיךְ הוּא שַׁלִּיט עַל אַרְעָא וְאִקְרֵי אֵיתָן. בְּגִין דְּאַתְקִיף בִּתְקִיפוּ בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>חַסְדֵּי ה' עוֹלָם אָשִׁירָה, וְכִי מִסִּטְרָא דַּחֲסִידִים אַתְיָין לְזַמְּרָא, אֶלָּא הָכָא אִתְכְּלִיל סִטְרָא דִשְׂמָאלָא בִּימִינָא, וְעַל דָּא קוּדְשָׁא בְּרִיךְ הוּא נַסֵּי לְאַבְרָהָם, וּבָחֵין לֵיהּ. וְהָא אִתְּמָר דְּיִצְחָק בַּר תְּלָתִין וּשְׁבַע שְׁנִין הֲוָה בְּהַהוּא זִמְנָא. מַאי נִסָּה אֶת אַבְרָהָם, נִסָּה אֶת יִצְחָק מִבָּעֵי לֵיהּ. אֶלָּא נִסָּה אֶת אַבְרָהָם, דְּיִשְׁתַּכַּח בְּדִינָא, וּלְאִתְכְּלָלָא בְּדִינָא, דְּיִשְׁתַּכַּח שְׁלִים כְּדְקָא יְאוּת. וְעַל דָּא חַסְדֵּי ה' עוֹלָם אָשִׁירָה.</p>\n<p>דָּבָר אַחֵר חַסְדֵּי ה' עוֹלָם אָשִׁירָה, אִינוּן חֲסָדִים דְּקוּדְשָׁא בְּרִיךְ הוּא עָבִיד עִם עַלְמָא. (תהילים פ״ט:ב׳) לְדוֹר וָדוֹר אוֹדִיעַ אֱמוּנָתְךָ בְּפִי, טִיבוּ וּקְשׁוֹט דְּעָבִיד עִם כֹּלָּא. לְדוֹר וָדוֹר אוֹדִיעַ אֱמוּנָתְךָ, דָּא מְהֵימְנוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא דְּאוֹדַע אַבְרָהָם בְּעַלְמָא, וְאַדְכַּר לֵיהּ בְּפוּמָא דְּכָל בִּרְיָין. וְעַל דָּא אוֹדִיעַ אֱמוּנָתְךָ בְּפִי.</p>\n<p>וְקוּדְשָׁא בְּרִיךְ הוּא אוֹדַע לֵיהּ לְאַבְרָהָם רָזָא דִמְהֵימְנוּתָא, וְכַד יָדַע רָזָא דִמְהֵימְנוּתָא, יָדַע דְּאִיהוּ עִיקָרָא וְקִיוּמָא דְעַלְמָא, דִּבְגִינֵיהּ אִתְבְּרֵי עַלְמָא, וְאִתְקְיַּים. הֲדָא הוּא דִכְתִיב, (תהילים פ״ט:ג׳) כִּי אָמַרְתִּי עוֹלָם חֶסֶד יִבָּנֶה וְגו'. דְכַד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא, חָמָא דְלָא יָכִיל לְמֵיקַם, עַד דְּאוֹשִׁיט יְמִינָא עֲלֵיהּ וְאִתְקְיַּים. וְאִי לָאו דְּאוֹשִׁיט יְמִינָא עֲלֵיהּ, לָא אִתְקְיַּים. בְּגִין דְּעַלְמָא דָּא בְּדִינָא אִתְבְּרִי, וְהָא אוֹקִימְנָא.</p>\n<p>וְאִתְּמָר בְּרֵאשִׁית, וְרָזָא כְּלָלָא חָדָא, תְּרֵין גְּוָונִין הָכָא, בְּרֵאשִׁית, אַף עַל גַּב דְּאֲמָרָן שֵׁירוּתָא מִתַּתָּא לְעֵילָא, רֵאשִׁית הָכִי נָמֵי מֵעֵילָא לְתַתָּא, וְקָאַמְרִינָן ב' רֵאשִׁית, כִּדְקָאַמְרִינָן בֵּית קֹדֶשׁ הַקֳּדָשִׁים, דְּהַאי אִתְיְיהִיבַת לְהַהוּא רֵאשִׁית, וּמִלָּה כְּלִילָא אִיהִי כְּחֲדָא.</p>\n<p>וּבְהַאי בי\"ת אִתְבְּרֵי עַלְמָא דָא, וְלָא אִתְקְיַּים אֶלָּא בִּימִינָא. וְהָא אוּקְמוּהָ. בְּהִבָּרְאָם, בְּאַבְרָהָם כְּתִיב. וּבְגִין כָּךְ, אָמַרְתִּי עוֹלָם חֶסֶד יִבָּנֶה. וּבִנְיָנָא קַדְמָאָה דְעַלְמָא (ההוא עולם), הַהוּא נְהוֹרָא דְיוֹמָא קַדְמָאָה, הֲוָה בֵּיהּ לְקַיְימָא. וּלְבָתַר בְּיוֹמָא תִּנְיָינָא, בִּשְׂמָאלָא. וּבְהַנְהוּ אַתְקִין שָׁמַיִם. וּכְתִיב, שָׁמַיִם תָּכִין אֱמוּנָתְךָ בָּהֶם.</p>\n<p>דָּבָר אַחֵר, שָׁמַיִם תָּכִין אֱמוּנָתְךָ בָּהֶם, שָׁמַיִם בְּאִינוּן חֲסָדִים אִתַּקְנוּ, וְרָזָא דֶּאֱמוּנָה אַתְקָנַת בְּהוּ, דְּלֵית תִּקּוּנָהָא אֶלָּא מִגּוֹ שָׁמַיִם. (תהילים פ״ט:ד׳) כָּרַתִּי בְּרִית לִבְחִירִי, דָּא הוּא רָזָא דִמְהֵימְנוּתָא.</p>\n<p>דָּבָר אַחֵר, דָּא אִיהוּ <Nonei></i>צַדִּיק דְּמִינֵיהּ נָפְקִין בִּרְכָאן לְכֻלְּהוּ תַּתָּאֵי, וְכָל (אינון) חֵיוָון קַדִּישָׁן, כֻּלְּהוּ אִתְבָּרְכָאן, מִן הַהוּא נְגִידוּ דְּנָגִיד לְתַתָּאי, וּבְגִין כָּךְ כְּתִיב, כָּרַתִּי בְּרִית לִבְחִירִי.</p>\n<p>(תהילים פ״ט:ד׳) נִשְׁבַּעְתִּי לְדָוִד עַבְדִי, דָא רָזָא דִמְהֵימְנוּתָא, דְּאִיהוּ קָיְימָא תָּדִיר בְּצַדִּיק דָּא. קִיּוּמָא דְעַלְמָא, דְּלָא יִתְבַּדְּרוּן לְעָלְמִין, בַּר בְּזִמְנָא דְּגָלוּתָא, דִּנְגִידוּ דְּבִרְכָאן אִתְמְנָעוּ. וְרָזָא דִמְהֵימְנוּתָא לָא אִשְׁתַּלִּים, וְכָל חֶדְוָון אִתְמְנָעוּ. וְכַד עָיִיל לֵילְיָא, מֵהַהוּא זִמְנָא, חֶדְוָון לָא עָאלוּ קַמֵּי מַלְכָּא.</p>\n<p>וְאַף עַל גַּב דְּחֶדְוָון לָא אִתְעָרוּ, אֲבָל לְבַר קָיְימֵי וּמְזַמְּרֵי שִׁירָתָא. וְכַד אִתְפְּלִיג לֵילְיָא, וְאִתְעָרוּתָא סָלְקָא מִתַּתָּא לְעֵילָא, כְּדֵין קוּדְשָׁא בְּרִיךְ הוּא אַתְעַר כָּל חֵילֵי שְׁמַיָא לִבְכִיָה, וּבָעַט בִּרְקִיעָא, וְאִזְדַּעְזְעָן עִלָּאֵי וְתַתָּאֵי.</p>\n<p>וְלֵית נַיְיחָא קַמֵּיהּ, בַּר בְּזִמְנָא דְּמִתְעָרֵי לְתַתָּא בְּאוֹרַיְיתָא. כְּדֵין, קוּדְשָׁא בְּרִיךְ הוּא וְכָל אִינוּן נִשְׁמָתִין דְּצַדִּיקַיָא (דעמיה), כֻּלְּהוּ צַיְיתִין וְחָדְיָין לְהַהוּא קָלָא וּכְדֵין נַיְיחָא. (ס\"א קמיה ואתי נייחא לכלהו נשמתין דצדיקיא עמיה) (קמיה אשתכח). בְּגִין דְּמִיּוֹמָא דְּאִתְחָרִיב מַקְדְּשָׁא לְתַתָּא, אוֹמֵי קוּדְשָׁא בְּרִיךְ הוּא, דְּלָא יֵיעוּל בְּגוֹ יְרוּשְׁלֵם דִּלְעֵילָא, עַד דְּיַעֲלוּן יִשְׂרָאֵל לִיְרוּשָׁלַם דִּלְתַתָּא. דִּכְתִיב, (הושע י״א:ט׳) בְּקִרְבְּךָ קָדוֹשׁ וְלא אָבוֹא בְּעִיר, וְהָא אוּקְמוּהָ חַבְרַיָיא.</p>\n<p>וְכָל אִינוּן מְזַמְּרֵי, קָיְימֵי לְבַר, וְאָמְרֵי שִׁירָתָא, בִּתְלַת פַּלְגֵי לֵילְיָא וְכֻלְּהוּ מְשַׁבְּחָן בְּתוּשְׁבָּחְתַן יְדִיעָאן, וְכֻלְּהוּ חֵילֵי שְׁמַיָא, כֻּלְּהוּ מִתְעָרֵי בְּלֵילְיָא, וְיִשְׂרָאֵל בִּימָמָא. וּקְדוּשָׁה לָא מְקַדְּשֵׁי לְעֵילָא, עַד דִּמְקַדְּשֵׁי יִשְׂרָאֵל לְתַתָּא, וּכְדֵין כָּל חֵילֵי שְׁמַיָא מְקַדְּשֵׁי שְׁמָא קַדִּישָׁא כְּחֲדָא. וְעַל דָּא יִשְׂרָאֵל קַדִּישִׁין, מִתְקַדְּשִׁין מֵעִלָּאֵי וְתַתָּאֵי (ס\"א בגין דקדושא דשמא דקודשא בריך הוא לא סליק אלא מעילא ומתתא) כְּחֲדָא. הֲדָא הוּא דִכְתִיב, (ויקרא י״ט:ב׳) קְדוֹשִׁים תִּהְיוּ כִּי קָדוֹשׁ אֲנִי ה' אֱלהֵיכֶם.</p>\n<p>פָּתַח רִבִּי יוֹסֵי וְאָמַר, (איוב ל״ח:ו׳) עַל מָה אֲדָנֶיהָ הָטְבָּעוּ, הַאי קְרָא קוּדְשָׁא בְּרִיךְ הוּא אָמַר לֵיהּ, בְּגִין דְּכַד בָּרָא עַלְמָא, לָא בָרָא לֵיהּ אֶלָּא עַל סָמְכִין, דְּאִינוּן ז' סָמְכִין דְּעַלְמָא. כְּמָא דְאַתְּ אָמֵר, (משלי ט׳:א׳) חָצְבָה עַמּוּדֶיהָ שִׁבְעָה, וְאִינוּן סָמְכִין לָא אִתְיְידַע עַל מָה קָיְימִין.</p>\n<p>בְּגִין דְּאִיהוּ רָזָא עֲמִיקָא סְתִימָא דְכָל סְתִימָן. וְעַלְמָא לָא אִתְבְּרֵי, עַד דְּנָטַל אַבְנָא חָדָא, וְאִיהוּ אַבְנָא דְּאִתְקְרֵי אֶבֶן שְׁתִיָּה, וְנָטַל לָהּ קוּדְשָׁא בְּרִיךְ הוּא, וְזָרַק לָהּ לְגוֹ תְהוֹמָא, וְאִתְנְעִיץ מֵעֵילָא לְתַתָּא, וּמִנֵּיהּ אִשְׁתִּיל עַלְמָא. וְאִיהִי נְקוּדָה אֶמְצָעִיתָא דְעַלְמָא, וּבְהַאי נְקוּדָה קָיְימָא קֹדֶשׁ הַקֳּדָשִׁים. הֲדָא הוּא דִכְתִיב, (איוב ל״ח:ו׳) אוֹ מִי יָרָה אֶבֶן פִּנָּתָהּ. כְּמָא דְאַתְּ אָמֵר, (ישעיהו כ״ח:ט״ז) אֶבֶן בֹּחַן פִּנַת יִקְרַת. וּכְתִיב, (תהילים קי״ח:כ״ב) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָה.</p>\n<p>תָּא חֲזֵי, הַאי אֶבֶן אִתְכָּרֵי מֵאֶשָּׁא וּמֵרוּחָא וּמִמַּיָא, וְאִתְגְּלִיד מִכֻּלְּהוּ, וְאִתְעֲבִיד אַבְנָא חָדָא, וְקָיְימָא עַל תְּהוֹמֵי, וּלְזִמְנִין נָבְעִין מִנֵּיהּ מַיָא, וְאִתְמַלְיָין תְּהוֹמֵי. וְהַאי אַבְנָא קָיְימָא לְאָת בְּאֶמְצָעִיתָא דְעַלְמָא, וְהַאי אִיהוּ אֶבֶן דְּקִיֵּים וְאַשְׁתִּיל יַעֲקֹב, שְׁתִילוּ וְקִיּוּמָא דְעַלְמָא. הֲדָא הוּא דִכְתִיב, (בראשית ל״א:מ״ה) וַיִּקַּח יַעֲקֹב אָבֶן וַיְרִימֶהָ מַצֵּבָה.</p>\n<p>וְהָאֶבֶן הַזֹּאת אֲשֶׁר שַׂמְתִּי מַצֵּבָה וְגו', (בראשית כח כב) וְכִי הַאי אֶבֶן שַׁוֵּי לֵיהּ יַעֲקֹב. וְהָא הַאי אֶבֶן אִתְבְּרֵי בְּקַדְמִיתָא, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא. אֶלָּא דְּשַׁוֵּי לָהּ (נ\"א וכי השתא שוי ליה יעקב. והא עד לא אתברי עלמא הוות, אלא דיעקב שוי לה) קִיּוּמָא דִלְעֵילָא וְתַתָּא, וְעַל דָּא אֲשֶׁר שַׂמְתִּי מַצֵּבָה כְּתִיב. מַאי אֲשֶׁר שַׂמְתִּי, דִּכְתִיב, יִהְיֶה בֵּית אֱלֹהִים, דְּשַׁוֵּי מְדוֹרָא דִלְעֵילָא הָכָא.</p>\n<p>תָּא חֲזֵי, הַאי אֶבֶן אִית עֲלָהּ שִׁבְעָה עֵינַיִם. כְּמָא דְאַתְּ אָמֵר, (זכריה ג׳:ט׳) עַל אֶבֶן אַחַת שִׁבְעָה עֵינַיִם, עַל מָה אִתְקְרִיאַת שְׁתִיָיה. חַד דְּמִנָּהּ אִשְׁתִּיל עַלְמָא. וְחַד, שְׁתִיָיה. שָׁת יָה, דְּשַׁוֵּי קוּדְשָׁא בְּרִיךְ הוּא לָהּ, לְאִתְבָּרְכָא מִנָּהּ עַלְמָא, בְּגִין דְּעַלְמָא מִנָּהּ מִתְבָּרְכָא.</p>\n<p>וְתָּא חֲזֵי, בְּשַׁעְתָּא דְּעָאל שִׁמְשָׁא, הַנֵּי כְּרוּבִים דְּקָיְימִין בְּהַאי דוּכְתָּא, וְהֲווּ יָתְבֵי בְּאָת, הֲווּ אַקְשָׁן גַּדְפַיְיהוּ לְעֵיל, וּפָרְשֵׂי לוֹן, וְאִשְׁתְּמַע קוֹל נִגּוּנָא דְּגַדְפַיְיהוּ לְעֵילָא, וּכְדֵין שָׁרָאן לְנַגְנָא אִינוּן מַלְאָכִין, דְּאָמְרֵי שִׁירָתָא בְּשֵׁירוּתָא דְלֵילְיָא, בְּגִין דִּיסַלַּק יְקָרֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, מִתַּתָּא לְעֵילָא. וּמַאי שִׁירָתָא הֲווּ אָמְרוּ, הַהוּא נִגּוּנָא דְּגַדְפַיְיהוּ דִּכְרוּבִים, (תהילים קל״ד:ב׳) הִנֵּה בָּרְכוּ אֶת ה' כָּל עַבְדֵּי ה' וְגו', שְׂאוּ יְדֵיכֶם קֹדֶשׁ וְגו', וּכְדֵין (אינון) אִיהוּ שִׁירָתָא לְאִינוּן מַלְאֲכֵי עִלָּאֵי לְזַמָּרָא.</p>\n<p>בְּמִשְׁמַרְתָּא תִּנְיָינָא, הַנֵּי כְּרוּבִים <Nonei></i>אַקְשֵׁי גַדְפַיְיהוּ לְעֵילָא, וְאִשְׁתְּמַע קוֹל נִגּוּנָא דִּלְהוֹן, וּכְדֵין שָׁרָאן לְנַגְנָא אִינוּן מַלְאָכִין דְקָיְימִין בְּמִשְׁמַרְתָּא תִּנְיָינָא. וּמַאי שִׁירָתָא הֲווּ אָמְרֵי בְּהַאי שַׁעְתָּא, נִגּוּנָא דְּגַדְּפַיְיהוּ דִכְרוּבִים, (תהילים קכ״ה:א׳) הַבּוֹטְחִים בַּה' כְּהַר צִיּוֹן לא יִמּוֹט וְגו'. וּכְדֵין (ההוא) אִיהוּ (שירתא) שֵׁירוּתָא לְאִינוּן דְּקָיְימֵי בְּהַאי מִשְׁמָרָה תִּנְיָינָא לְנַגְנָא.</p>\n<p>בְּמִשְׁמָרָה תְּלִיתָאָה, הַנֵּי כְּרוּבִים אַקְשׁוּ גַדְפַיְיהוּ וְאָמְרֵי שִׁירָתָא, וּמַאי הִיא. (תהילים קי״ג:א׳-ב׳) הַלְלוּיָה הַלְּלוּ עַבְדֵּי ה' וְגו', יְהִי שֵׁם ה' מְבוֹרָךְ וְגו', מִמִּזְרַח שֶׁמֶשׁ וְגו'. כְּדֵין אִינוּן מַלְאָכִין דְּקָיְימֵי בְּמִשְׁמָרָה תְּלִיתָאָה, כֻּלְּהוּ אָמְרֵי שִׁירָתָא.</p>\n<p>וְכֻלְּהוּ כּוֹכָבֵי וּמַזָּלֵי דְּבִרְקִיעָא פָּתְחֵי שִׁירָתָא. כְּמָה דִכְתִיב, (איוב ל״ח:ז׳) בְּרָן יַחַד כּוֹכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים. וּכְתִיב, (תהילים קמ״ח:ג׳) הַלְּלוּהוּ כָּל כּוֹכְבֵי אוֹר, דְּהָא אִינוּן כֹּכְבֵי דִנְהוֹרָא, מְנַגְנָן עַל נְהוֹרָא. (ס\"א דממנן על שירתא).</p>\n<p>כַּד אָתֵי צַפְרָא, וּכְדֵין נָטְלֵי שִׁירָתָא אֲבַּתְרַיְיהוּ דְיִשְׂרָאֵל (ס\"א ישראל) לְתַתָּא, וְסָלְקָא יְקָרֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, מִתַּתָּא וּמִלְּעֵילָא. יִשְׂרָאֵל לְתַתָּא בִּימָמָא, וּמַלְאֲכֵי עִלָּאֵי לְעֵילָא בְּלֵילְיָא, וּכְדֵין אִשְׁתְּלִים שְׁמָא קַדִּישָׁא בְּכָל סִטְרִין.</p>\n<p>וְהַאי אֶבֶן דְּקָאֲמַר, כֻּלְּהוּ מַלְאֲכֵי עִלָּאֵי, וְיִשְׂרָאֵל לְתַתָּא, כֻּלְּהוּ אִתְקָפוּ בְּהַאי אֶבֶן, וְאִיהִי סָלְקָא לְעֵילָא, לְאִתְעַטְּרָא גּוֹ אֲבָהָן בִּימָמָא. וּבְלֵילְיָא, קוּדְשָׁא בְּרִיךְ הוּא אָתֵי לְאִשְׁתַּעְשְׁעָא עִם צַדִּיקַיָא בְּגִנְתָא דְעֵדֶן.</p>\n<p>זַכָּאִין אִינוּן כָּל דְּקָיְימֵי בְּקִיּוּמַיְיהוּ, וּמִשְׁתַּדְּלִין בְּאוֹרַיְיתָא בְּלֵילְיָא. בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא וְכָל אִינוּן צַדִּיקַיָיא דִּבְגִנְתָא דְעֵדֶן, שָׁמְעוּ קָלַיְיהוּ דִּבְנֵי נָשָׁא, אִינוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא. כְּמָה דִכְתִיב, (שיר השירים ח׳:י״ג) הַיּוֹשֶׁבֶת בַּגַּנִּים וְגו'.</p>\n<p>תָּא חֲזֵי, הַאי אֶבֶן, אִיהוּ אֶבֶן טָבָא. וְדָא הוּא רָזָא דִכְתִיב, (שמות כ״ח:י״ז) וּמִלֵּאתָ בוֹ מִלּוּאַת אֶבֶן אַרְבָּעָה טוּרֵי אֶבֶן. וְאִלֵּין אִינוּן סִדְרִין (דאשלמותא) דְּאֶבֶן טָבָא, אַשְׁלָמוּתָא דְאֶבֶן יְקָרָה. בְּגִין דְּאִית (אשלמותא) אֶבֶן אָחֳרָא. דִּכְתִיב, (יחזקאל ל״ו:כ״ו) וַהֲסִירוֹתִי אֶת לֵב הָאֶבֶן וְגו'. וּכְתִיב, (יחזקאל ל״ו:כ״ז) וְאֶת רוּחִי אֶתֵּן בְּקִרְבְּכֶם. וְהַאי אִיהוּ (ישעיהו כ״ח:ט״ז) אֶבֶן בֹּחַן פִּנַּת יִקְרַת וְאוּקְמוּהָ.</p>\n<p>וְעַל רָזָא דָּא כְּתִיב, (שמות לא) לוּחוֹת הָאֶבֶן, דְּאִינוּן לוּחוֹת אִתְגְּזָרוּ מֵהָכָא, וְעַל דָּא אִקְרוּן עַל שְׁמֵיהּ דְּהַאי אֶבֶן. וְהַאי הוּא רָזָא דִכְתִיב, (בראשית מ״ט:כ״ד) מִשָּׁם רוֹעֶה אֶבֶן יִשְׂרָאֵל (ס\"א הא ודאי אבן ישראל אקה) כְּמָה דְאִתְּמָר.</p>\n<p>פָּתַח רִבִּי חִזְקִיָּה וְאָמַר, (שמות כ״ח:כ״א) וְהָאֲבָנִים תִּהְיֶיןָ עַל שְׁמוֹת בְּנִי יִשְׂרָאֵל שְׁתֵּים עֶשְׂרֵה, אִלֵּין אַבְנֵי יְקָרִין עִלָּאִין, דְּאִתְקָרוּן אַבְנִי הַמָּקוֹם, כְּמָא דְאַתְּ אָמֵר, (בראשית כ״ח:י״א) וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם. וְהָא אוּקְמוּהָ. (שמות ל״ט:י״ד ועי\"ש) וְהָאֲבָנִים עַל שְׁמוֹת בְּנֵי יִשְׂרָאֵל, כְּמָה דְּאִית (י\"ב אבנים) י\"ב שְׁבָטִים לְתַתָּא, הָכִי נָמֵי לְעֵילָא תְּרֵיסַר שִׁבְטִין, וְאִינוּן תְּרִיסַר אֲבָנִין יַקִּירִין, וּכְתִיב, (תהילים קכ״ב:ד׳) שֶׁשָּׁם עָלוּ שְׁבָטִים שִׁבְטֵי יָהּ (דא רזא) עֵדוּת לְיִשְׂרָאֵל, דָּא יִשְׂרָאֵל, רָזָא דִלְעֵילָא. וְכֻלְּהוּ לְהוֹדוֹת לְשֵׁם ה', וְעַל דָּא וְהָאֲבָנִים תִּהְיֶיןָ עַל שְׁמוֹת בְּנֵי יִשְׂרָאֵל.</p>\n<p>וּכְמָה דְאִית י\"ב שָׁעֵי בִּימָמָא, הָכִי אִית י\"ב שָׁעֵי בְּלֵילְיָא, בְּיוֹמָא לְעֵילָא, בְּלֵילְיָא לְתַתָּא, כֹּלָּא דָא לָקֳבֵל דָּא, הַנֵּי י\"ב שָׁעֵי דִּבְלֵילְיָא מִתְפַּלְּגֵי לִתְלַת פְּלָגָאן, וְכַמָּה מְמַנֵּי תְּרִיסִין קָיְימֵי תְּחוֹתַיְיהוּ, דַּרְגִּין עַל דַּרְגִּין, כֻּלְּהוּ מְמַנָּן בְּלֵילְיָא, וְנָטְלֵי טַרְפָּא בְּקַדְמַיתָא.</p>\n<p>וּכְדֵין כַּד אִתְפְּלִיג לֵילְיָא, קָיְימִין תְּרֵין (סתרין) סִדְרִין מִסִּטְרָא דָא, וּתְרֵין סִדְּרִין מִסִּטְרָא אָחֳרָא, (ס\"א ודא) וְרוּחָא עִלָּאָה נָפַק (ס\"א נשיב) בֵּינַיְיהוּ, וּכְדֵין כָּל אִינוּן אִלָּנִין דִּבְגִנְתָּא דְעֵדֶן, כֻּלְּהוּ פָּתְחֵי שִׁירָתָא, וְקוּדְשָׁא בְּרִיךְ הוּא עָאל בְּגִנְתָא דְעֵדֶן. הֲדָא הוּא דִכְתִיב, (דברי הימים א י״ז:ט״ז) אָז יְרַנְּנוּ עֲצֵי הַיַּעַר מִלִּפְנֵי יְיָ, כִּי בָא לִשְׁפּוֹט אֶת הָאָרֶץ. כְּמָה דִכְתִיב, (ישעיהו י״א:ד׳) וְשָׁפַט בְּצֶדֶק דַּלִּים. בְּגִין דְּמִשְׁפָּט עָאל בֵּינַיְיהוּ וְאִתְמַלְיָיא מִנָּהּ (ס\"א מניה) גַּן עֵדֶן.</p>\n<p>וְרוּחָא דְצָפוֹן אִתְעַר בְּעַלְמָא, וְחֶדְוָה אִשְׁתַּכַּח וְנָשִׁיב הַהוּא רוּחָא בְּאִינוּן בּוּסְמִין, וְסָלְקִין רֵיחִין לְעֵילָא, וּמִתְעַטְּרִין (ס\"א ומתערין) צַדִּיקַיָא בְּעִטְרַיְיהוּ, וּמִתְהַנָּן מִגּוֹ זִיוָא דְּאַסְפַּקְלַרְיָאה דְּנָהֲרָא.</p>\n<p>זַכָּאִין אִינוּן צַדִּיקַיָא, דְּזָכָאן לְהַהוּא נְהוֹרָא עִלָּאָה, וְהַהוּא נְהוֹרָא דְּאַסְפַּקְלַרְיָאה דְּנָהֲרָא, נָהִיר לְכָל סִטְרִין, וְכָל חַד וְחַד מֵאִלֵּין צַדִּיקַיָא, נָטִיל לְחוּלָקֵיהּ כְּדְקָא חָזֵי לֵיהּ, וְהֲוָה נָטִיל (ס\"א והכי נהיר) כָּל חַד וְחַד כְּפוּם עוֹבָדוֹי דְּעָבַד בְּהַאי עַלְמָא, (מאינון) אִית מִנְּהוֹן דְּמִתְכַּסְפֵי, מֵהַהוּא נְהִירוּ דְּנָטִיל חַבְרֵיהּ <Nonei></i>יַתִּיר וְנָהִיר, וְהָא אוּקְמוּהָ.</p>\n<p>חוּלָקֵיהּ דְּלֵילְיָא, מִכַּד שָׁארֵי לֵילְיָא לְמֵיעַל. כַּמָּה גַרְדִּינֵי נִמּוּסִין מִתְעָרִין, וְשָׁטָאן בְּעַלְמָא, וּפָתְחִין (קע\"ב ע\"ב) סְתִימִין, וּלְבָתַר כַּמָּה זִינִין לִזְנַיְיהוּ, כְּמָה דְאוֹקִימְנָא. וּכְדֵין כַּד אִתְפְּלִיג לֵילְיָא, סִטְרָא דְצָפוֹן נָחִית (נהיר נהירו) מֵעֵילָא לְתַתָּא, וְאָחִיד בֵּיהּ בְּלֵילְיָא, עַד תְּרֵין חוּלָקִין דְּלֵילְיָא.</p>\n<p>וּלְבָתַר סִטְרָא דְּדָרוֹם אִתְעַר, עַד דְּאָתֵי צַפְרָא. וְכַד אָתֵי צַפְרָא, כְּדֵין דָּרוֹם וְצָפוֹן אֲחִידוּ בֵּיהּ, וּכְדֵין אָתָאן יִשְׂרָאֵל לְתַתָּא, סָלְקִין לָהּ בִּצְלוֹתְהוֹן וּבָעוּתְהוֹן לְעֵילָא, עַד דְּסָלְקָא וְאִתְגְּנִיזַת בֵּינַיְיהוּ. וְנָטְלָא בִּרְכָאן מֵרֵישָׁא (דמלכא) דְּכָל רֵישִׁין.</p>\n<p>וְאִתְבָּרְכָא מֵהַהוּא טַלָּא דְּאִתְמַשְּׁכָא מִלְּעֵילָא. וּמֵהַהוּא טַלָּא פָּרִישׁ לְכַמָּה סִטְרִין, וְכַמָּה רַבְוָון אִתְּזָנוּ מִנֵּיהּ מֵהַהוּא טַלָּא, וּמִנֵּיהּ עֲתִידִין לַאֲחָיָיא מֵיתַיָיא. הֲדָא הוּא דִכְתִיב, (ישעיהו כ״ו:י״ט) הָקִיצוּ וְרַנְּנוּ שׁוֹכְנֵי עָפָר כִּי טַל אוֹרוֹת טַלֶךָ. טַלָּא מֵאִינוּן נְהוֹרִין עִלָּאִין דְּנָהֲרִין לְעֵילָא.</p>"],[9520011466,"<p>עַד דְּהֲווּ יָתְבֵי אִתְפְּלִיג לֵילְיָא, אָמַר לֵיהּ רִבִּי יְהוּדָה לְרִבִּי יוֹסֵי, הַשְׁתָּא רוּחָא דְצָפוֹן אִתְעַר, וְלֵילְיָא אִתְפְּלַג, וְהַשְׁתָּא עִדָּנָא דְּקוּדְשָׁא בְּרִיךְ הוּא תָּאִיב לְקָלְהוֹן דְּצַדִּיקַיָא בְּהַאי עַלְמָא, אִינוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא. הַשְׁתָּא קוּדְשָׁא בְּרִיךְ הוּא צַיֵּית (לקול מלייהו) לָן בְּהַאי אֲתַר, לָא נִפְסוֹק מִלֵּי דְאוֹרַיְיתָא.</p>\n<p>פָּתַח וְאָמַר, הַמַּלְאָךָ הַגּוֹאֵל אוֹתִי מִכָּל רָע, הָא אִתְּמָר וְאוּקְמוּהָ. אֲבָל תָּא חֲזֵי, כְּתִיב, (שמות כ״ג:כ׳) הִנִּה אָנֹכִי שׁוֹלֵחַ מַלְאָךְ וְגו', דָּא הוּא מַלְאָךְ דְּאִיהוּ פָּרוֹקָא דְעַלְמָא, נְטִירוּ דִּבְנֵי נָשָׁא, וְהַאי אִיהוּ דְּאַזְמִין בִּרְכָאן לְכָל עַלְמָא, בְּגִין דְּאִיהוּ נָטִיל לוֹן בְּקַדְמִיתָא, ולְבָתַר אִיהוּ אַזְמִין לוֹן בְּעַלְמָא. וּבְגִין דָּא כְּתִיב, הִנֵּה אָנֹכִי שׁוֹלֵחַ מַלְאָךְ לְפָנֶיךָ. (שמות ל״ג:ב׳) וְשָׁלַחְתִּי לְפָנֶיךָ מַלְאָךְ.</p>\n<p>וְהַאי אִיהוּ מַלְאָךְ דִּלְזִמְנִין דָּכָר וּלְזִמְנִין נוּקְבָא, וְהָכִי אִיהוּ. דְּבְּזִמְנָא דְּאִיהוּ אַזְמִין בִּרְכָאן לְעַלְמָא (לעילא), כְּדֵין אִיהוּ דָּכָר, וְאִקְרֵי דָּכָר. כִּדְכוּרָא דְּאַזְמִין בִּרְכָאן (לתתא) לְנוּקְבָא, הָכִי אִיהוּ אַזְמִין בִּרְכָאן לְעַלְמָא. וּבְזִמְנָא דְּקָיְימָא בְּדִינָא עַל עַלְמָא, כְּדֵין אִקְרֵי נוּקְבָא. כְּנוּקְבָא דְּאִיהִי עוּבָּרָא, הָכִי אִיהוּ אִתְמְלֵי מִן דִּינָא, וּכְדֵין אִקְרֵי נוּקְבָא. וְעַל דָּא לְזִמְנִין אִקְרֵי דְכוּרָא, וּלְזִמְנִין אִקְרֵי נוּקְבָא, וְכֹלָּא רָזָא חָדָא.</p>"],[9520011467,"<p>כְּגַוְונָא דָא כְּתִיב, (בראשית ג׳:כ״ד) וְאֶת לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת, מַלְאָכִין אִית שְׁלוּחַן בְּעַלְמָא, דְּמִתְהַפְּכִין לְכַמָּה גְוָונִין, לְזִמְנִין נוּקְבֵי, לְזִמְנִין דְּכוּרֵי, לְזִמְנִין דִּינָא, לְזִמְנִין רַחֲמֵי, וְכֹלָּא בְּחַד גַּוְונָא. כְּגַוְונָא דָּא הַאי מַלְאָךְ, בִּגְוָונִין סַגִּיאִין אִיהוּ, וְכָל גְּוָונִין דְּעַלְמָא, כֻּלְּהוּ אִיתָנְהוּ בְּהַאי אֲתַר. וְרָזָא דָא, (יחזקאל א׳:כ״ח) כְּמַרְאֵה הַקֶּשֶׁת אֲשֶׁר יִהְיֶה בֶעָנָן בְּיוֹם הַגֶּשֶׁם כֵּן מַרְאֵה הַנֹּגַּהּ סָבִיב הוּא מַרְאֵה דְּמוּת כְּבוֹד ה'. וּכְמָה דְּאִית בֵּיהּ כָּל אִינוּן גְּוָונִין, הָכִי נָמֵי אַנְהִיג לְכָל עָלְמָא:</p>\n<p><Noneb>תוספתא</b> רְחִימֵי עִלָּאֵי, מָארֵי דְסֻכְלְתָּנוּ אִסְתַּכָּלוּ, הוּרְמָנִי יְדִיעָן בְּקוּלְפֵּי דְּסִיכְתָּא, קְרִיבוּ לְמִנְדַע, מַאן מִנְּכוֹן מָארֵי דְעַיְינִין בְּסֻכְלְתָּנוּ, וְיָדַע בְּשַׁעְתָּא דְּסָלִיק בִּרְעוּתָּא דְרָזָא דְרָזִין, לְאֲפָּקָא תְּלַתּ גְּוָונִין כְּחֲדָא כְּלִילָן, ואִינוּן, חִוַּור וְסוּמָק ויָרוֹק, תְּלַתּ גּווָֹנִין כְּחֲדָא אִשְׁתְּלִיבָאן דָּא עִם דָּא, מִזְדַּווגָן (ס\"א מזדלגן) דָּא עִם דָּא, מַגְרוֹפַּיָא תַּתָּאָה אִצְטַבַּע, ונָפְּקָא מִגּוֹ גּווָֹנִין אִלֵּין.</p>\n<p>וְכָל גּווָֹנִין אִלֵּין, אִתְּחֲזוּן בְּהַאי. חֵיזוּ אִיהוּ לְאִסְתַּכָּלָא, כְּעֵינָא דִּבְדוֹלְחָא אִתְּחֲזֵי בְּשַׁעְתָּא. כְּגַוְונָא דְּבָטַשׁ בְּגַוָּוהּ, הָכִי אִתְּחֲזִיִ לְבַר. אִלֵּין תְּלַתּ גּווָֹנִין סַחֲרָן לְהַאי, וְגווָֹנָא אָזְלָא סָלְקָא וְנָחֲתָּא קִסְטוֹרִין דְּקִטְרָא קְבִיעֵי בְּגוָֹון (ס\"א בגווה).</p>\n<p>גּווָֹנִין סָחֲרִין (ס\"א גוונין) כְּלִילָן כְּחֲדָא, סָלְקִין לָהּ לְעֵילָא בִּימָמָא, וְנָחֲתָּא בְּלֵילְיָא. שְׁרַגָא דְּדָלִיק אִתְּחֲזִיִ בְּלֵילְיָא, בִּימָמָא אִסְתַּתָּרַתּ נְהוֹרָא, טְמִירָא בְּמָאתָּן וְאַרְבָּעִין וּתְּמַנְיָא עָלְמִין, כֻּלְּהוּ אָזְלִין לְגַוָּוהּ (ס\"א בגינה) מִלְּעֵילָא לְתַּתָּא, גּוֹ תְּלַתּ מְאָה וְשִׁתִּין וְחָמֵשׁ שַׁיְיפִּין גְּנִיזָא ואִתְּכַּסְיָא לְתַּתָּא.</p>\n<p>מַאן דִּמְפַּשְׁפֵּשׁ <Nonei></i>לְאַשְׁכָּחָא לָהּ, יִתְּבַר גַּדְפִּין קְלִיפִּין טְמִירִין, וְיִפְּתַּח תַּרְעִין. מַאן דְזָכֵי לְמֶיחֱמֵי, יֶחֱמֵי גּוֹ יְדִיעָה וְסֻכְלְתָּנוּ, כְּמַאן דְּחָמֵי בָּתַּר כּוֹתְּלָא. בַּר מִן משֶׁה נְבִיאָה מְהֵימְנָא עִלָּאָה, דְּהֲוָה חָמֵי לֵיהּ עֵינָא בְּעֵינָא, לְעֵילָא בְּאֲתַּר דְּלָא אִתְּיְידַע.</p>\n<p>מַאן דְּלָא זָכֵי, דָּחוּ לֵיהּ לְבַר, כַּמָּה חֲבִילֵי טְהִירִין אִזְדַּמְּנוּ לְגַבֵּיהּ, אִזְדַּמְּנָן נָפְּקֵי עֲלֵיהּ, ואֲפִּיקוּ לֵיהּ דְּלָא יִסְתַּכַּל בְּעִנּוּגָא דְמַלְכָּא. וַוי לוֹן לְאִינוּן חַיָּיבִין דְּעַלְמָא, דְּלָא זָכָאן לְאִסְתַּכָּלָא, כְּמָא דְאַתְּ אָמֵר, (במדבר ד׳:כ׳) וְלֹא יָבֹאוּ לִרְאוֹתּ כְּבַלַּע אתּ הַקֹּדֶשׁ וְגו'.</p>\n<p>אָמַר רִבִּי יְהוּדָה, מִסְתַּכֵּל הֲוֵינָא, וְהָא מִגּוֹ זְהִירִין אִלֵּין, מִסְתַּכְּלָן נִשְׁמַתְּהוֹן דְּצַדִּיקַיָא, כַּד אִתְּדַּבָּקוּ בְּהַאי אֲתַּר, מִגּוֹ זְהִירִין אִלֵּין מִסְתַּכְּלִין נִשְׁמַתְּהוֹן דְּצַדִּיקַיָא. אִינוּן גּווָֹנִין, סָלְקִין וְאִתְּכְּלִילָן כְּחֲדָא. זַכָּאָה אִיהוּ מַאן דְּיָדַע לְאַכְלָלָא וּלְיַחֲדָא כֻּלְּהוּ כְּחֲדָא, לְאַתְּקָנָא כֹּלָּא בְּאֲתַּר דְּאִצְטְרִיךָ לְעֵילָא לְעֵילָא, וּכְדֵין אִתְּנְטִיר בַּר נָשׁ בְּהַאי עַלְמָא, וּבְעַלְמָא דְאָתֵּי. (ע\"כ תוספתא):</p>"],[9520011468,"<p>פָּתַח רִבִּי יוֹסֵי וְאָמַר, (תהילים צ״ט:ד׳) וְעֹז מֶלֶךְ מִשְׁפָּט אָהֵב אַתָּה כּוֹנַנְתָּ מֵישָׁרִים וְגו'. וְעֹז מֶלֶךְ מִשְׁפַּט אָהֵב, דָּא קוּדְשָׁא בְּרִיךְ הוּא. וְעֹז מֶלֶךְ, תּוּקְפָא דְּאַתְקִיף קוּדְשָׁא בְּרִיךְ הוּא, לָאו אִיהוּ אֶלָּא בְּמִשְׁפָּט, דְּהָא בְּמִשְׁפָּט אִתְקְיַּים אַרְעָא. כְּמָא דְאַתְּ אָמֵר, (משלי כ״ט:ד׳) מֶלֶךְ בְּמִשְׁפָּט יַעֲמִיד אָרֶץ.</p>\n<p>וּבְגִין כָּךְ, וְעֹז מֶלֶךְ מִשְׁפָּט אָהֵב, וְלָא (אתקף) אִתְתַּקָּנַת כְּנֶסֶת יִשְׂרָאֵל אֶלָא בְּמִשְׁפָּט, בְּגִין דְּמִתַּמָּן אִתְּזָנַת, וְכָל בִּרְכָאן דְּנָטְלָא, מִתַּמָּן נָטְלָא. וּבְגִין כָּךְ וְעֹז מֶלֶךְ מִשְׁפָּט אָהֵב, כָּל תְּאִיבוּ, וְכָל רְחִימוּ דִילָהּ לָקֳבֵיל מִשְׁפָּט. אַתָּה כּוֹנַנְתָּ מֵשָׁרִים, רָזָא (קצ\"ב ע\"א בסתרי תורה) דִתְרֵין כְּרוּבִים לְתַתָּא, דְּאִינוּן תִּקּוּנָא וְיִישׁוּבָא דְעַלְמָא, וְהָא אִתְּמָר.</p>"],[9520011469,"<p>רִבִּי (יצחק) חִזְקִיָּה פָּתַח וְאָמַר, (תהילים קל״ה:א׳) הַלְּלוּ יָהּ הַלְּלוּ עַבְדֵּי ה' הַלְּלוּ אֶת שֵׁם ה', הַאי קְרָא אִית לְאִסְתַּכָּלָא בֵּיהּ, כֵּיוָן דְּאָמַר הַלְּלוּיָה, אַמַּאי הַלְּלוּ עַבְדֵּי ה', וּלְבָתַר הַלְּלוּ אֶת שֵׁם ה'. אֶלָּא הָכִי תָּנִינָן, מַאן דִּמְשַׁבַּח (לחדא) לְאַחֲרָא, אִצְטְרִיךְ לְשַׁבָּחָא לֵיהּ כְּפוּם יְקָרֵיהּ, וּכְפוּם יְקָרֵיהּ הָכִי אִצְטְרִיךְ שִׁבְחֵיהּ, וְתָנִינָן מַאן דִּמְשַׁבַּח לְאַחֲרָא, בְּשִׁבְחָא דְּלֵית בֵּיהּ, הוּא גָלֵי (גלותא וסבב) גְנוּתֵיהּ, וְצָבֵי לְגַלָּאָה לֵיהּ. וְעַל דָּא, מַאן דְּעָבִיד הֶסְפֵּדָא עַל בַּר נָשׁ, אִצְטְרִיךְ כְּפוּם יְקָרֵיהּ, וְלָא יַתִּיר. דְּמִגּוֹ שִׁבְחֵיהּ אָתֵי לִגְנוּתֵיהּ, וּבְכֹלָּא שְׁבָחָא אִצְטְרִיךְ כְּפוּם יְקָרֵיהּ.</p>\n<p>תָּא חֲזֵי, הַלְלוּיָהּ, הָכָא אִית שְׁבָחָא עִלָּאָה דְּמָארֵי דְכֹלָּא. אֲתַר דְּלָא שָׁלְטָא בֵּיהּ עֵינָא לְמִנְדַע וּלְאִסְתַּכָּלָא (ס\"א אתר), דְּאִיהוּ טְמִירָא דְכָל טְמִירִין. וּמַאן אִיהוּ, י\"ה. שְׁמָא עִלָּאָה עַל כֹּלָּא.</p>\n<p>וּבְגִין כָּךְ הַלְּלוּיָהּ, שְׁבָחָא וּשְׁמָא כְּחֲדָא, כְּלִילָן כְּחֲדָא. וְהָכָא סָתִים מִלָּה דְּאָמַר הַלְּלוּיָהּ, וְלָא אָמַר מַאן הַלְּלוּיָהּ, לְמַאן אָמְרוּ הַלְּלוּ, אֶלָּא כְּמָה דְּי\"ה סָתִים, הָכִי שְׁבָחָא דְּשַׁבּוּחֵי סָתִים אִינוּן, דִּמְשַׁבְּחֵי לָא יְדַעְנָא מַאן אִינוּן, וְהָכִי אִצְטְרִיךְ לְמֶהֱוֵי כֹּלָּא סָתִים, בְּרָזָא עִלָּאָה. וּלְבָתַר דְּסָתִים בְּרָזָא עִלָּאָה, גַּלֵּי וְאָמַר, הַלְּלוּ עַבְדֵּי ה' הַלְּלוּ אֶת שֵׁם ה'. בְּגִין דְּדָא אִיהוּ אֲתַר דְּלָא סָתִים כְּהַהוּא עִלָּאָה טְמִירָא דְּכָל טְמִירִין. דָּא הוּא אֲתַר דְּאִקְרֵי שֵׁם, כְּמָא דְאַתְּ אָמֵר, (שמואל ב ו׳:ב׳) אֲשֶׁר נִקְרָא שָׁם שֵׁם ה'.</p>\n<p>קַדְמָאָה סָתִים דְּלָא (ס\"א דא) גַלְיָא, (תניינא) סָתִים וְגַלְיָא, וּבְגִין דְּקַיְימָא בְּאִתְגַּלְּיָיא, אָמַר אִינוּן דְּקָא מְשַׁבְּחֵי לְהַהוּא אֲתַר, מַאן אִינוּן. וְקָאֲמַר דְּאִינוּן עַבְדֵּי ה', דְּאִתְחַזּוּן לְשַׁבָּחָא לְאֲתַר דָּא.</p>\n<p>יְהִי שֵׁם ה' מְבוֹרָךְ, מַאי שְׁנָא דְּקָאֲמַר יְהִי. אֶלָּא יְהִי, רָזָא דְּאַמְשָׁכוּתָא מֵהַהוּא אֲתַר עִלָּאָה, דְּאִיהוּ סָתִים דְּקָאֲמָרָן, דְּאִיהוּ י\"ה, עַד רָזָא דִבְרִית, דְּאִיהוּ יו\"ד תַּתָּאָה, כְּגַוְונָא דְּיוּ\"ד עִלָּאָה, שֵׁירוּתָא כְּסוֹפָא.</p>\n<p>וּבְגִין כָּךְ יְהִי, רָזָא דְּאַמְשְׁכוּתָא מִטְּמִירָא דְכָל טְמִירִין, עַד דַּרְגָּא תַּתָּאָה. וּבְמִלָּה דָא אִתְקְיַּים כָּל עוֹבָדָא דִּבְרֵאשִׁית. כְּמָא דְאַתְּ אָמֵר, (י\"ו ע\"ב) יְהִ\"י רָקִיעַ, יְהִ\"י מְאוֹרוֹת, יְהִ\"י אוֹר. בְּכָל אִינוּן עוֹבָדִין דִּלְעֵילָא כְּתִיב יְהִי.</p>\n<p>בְּכָל אִינוּן עוֹבָדִין דִּלְתַתָּא, לָא כְּתִיב יְהִ\"י. בְּגִין דְּרָזָא דָא דְּאִיהוּ (ס\"א אמשכותא) מֵרָזָא עִלָּאָה, סְתִימִין דְּכָל סְתִימִין, לָא אִתְקְיַּים אֶלָּא בְּמִלִּין עִלָּאֵי דִּלְעֵילָא, וְלָא אִתְּמָר בְּאִינוּן <Nonei></i>מִלִּין תַּתָּאִין דִּלְתַתָּא.</p>\n<p>וּבְדָא מִתְבָּרַךְ שְׁמָא קַדִּישָׁא בְּכֹלָּא, וְעַל דָּא כְּתִיב יְהִי שֵׁם יְיָ מְבוֹרָךְ וְגו', מִמִּזְרַח שֶׁמֶשׁ עַד מְבוֹאוֹ, דָּא אֲתַר עִלָּאָה, דְּקָא נָהִיר מִנֵּיהּ שִׁמְשָׁא, וְנָהִיר לְכֹלָּא. וְדָא הוּא אֲתַר דְרֵישָׁא עִלָּאָה סְתִימָאָה.</p>\n<p>וְעַד מְבוֹאוֹ, דָּא הוּא אֲתַר קִשְׁרָא, דְּאִתְקַּשַּׁר בֵּיהּ מְהֵימְנוּתָא כְּדְקָא חָזֵי, וּמִתַּמָּן נָפְקָן בִּרְכָאן לְכֹלָּא, וְעַלְמָא מֵהָכָא אִתְּזָן, כְּמָה דְאִתְּמָר. וּבְגִין כָּךְ קָיְימָא הַאי אֲתַר לְאִתְּזָנָא מֵעֵילָא, וּלְאִתְבָּרְכָא מִתַּמָּן. וְכֹלָּא קָיְימָא בְּאִתְעֲרוּתָא דִּלְתַתָּא, דְּמִתְעָרֵי אִינוּן עַבְדֵּי יְיָ, כַּד מְבָרְכֵי שְׁמָא קַדִּישָׁא, כִּדְקָאֲמָרָן. ובְגִין כָּךְ דְּאִיהוּ בְּאִתְגַּלְּיָיא, כְּתִיב הַלְּלוּ עַבְדֵּי יְיָ הַלְּלוּ אֶת שֵׁם יְיָ.</p>\n<p>אַדְהָכִי הֲוָה נָהִיר צַפְרָא, נָפְקוּ מִן מְעַרְתָּא, וּבְהַהוּא לֵילְיָא לָא דְמִיכוּ. אָזְלוּ בְּאָרְחָא, כַּד נָפְקוּ מֵאִינוּן טוּרִין, יָתְבוּ וְצַלּוּ צְלוֹתָא. מָטוּ לְחַד כְּפַר, וְיָתְבוּ תַּמָּן כָּל הַהוּא יוֹמָא, בְּהַהוּא לֵילְיָא נָמוּ, עַד דְּהֲוָה פַּלְגוּת לֵילְיָא, קָמוּ לְאִתְעַסְּקָא בְּאוֹרַיְיתָא.</p>"],[9520011470,"<p>פָּתַח רִבִּי יְהוּדָה וְאָמַר וַיְבָרֲכֵם בַּיּוֹם הַהוּא לֵאמוֹר בְּךָ יְבָרֵךְ יִשְׂרָאֵל וְגו', וַיְבָרַכֵם בַּיּוֹם הַהוּא, מַאי בַּיּוֹם הַהוּא, דְּהָא סַגֵּי דְּקָאֲמַר וַיְבָרֲכֵם. וְתוּ, כָּל לֵאמֹר כְּתִיב חָסֵר, וְהָכָא לֵאמֹר בְּוי\"ו כְּתִיב, (כללא כתיב לאמר, אלא בוי\"ו לאמור כתיב הכא) מַאי שְׁנָא.</p>\n<p>אֶלָא רָזָא אִיהוּ, וַיְבָרַכֵם בַּיּוֹם הַהוּא, מַאי בַּיּוֹם הַהוּא, רָזָא דְּדַרְגָּא דְּאִתְמַנָּא עַל בִּרְכָאן לְעֵילָא. יוֹם הַהוּא, יוֹם מֵהַהוּא אֲתַר עִלָּאָה, דְּאִקְרֵי הוּא. וְהַאי יוֹם הַהוּא, דְּלֵית פִּירוּדָא בֵּין יוֹם וּבֵין הוּא, וּבְכָל אֲתַר הַיּוֹם הַהוּא, דָּא (הוא) תְּרֵין דַּרְגִּין (עלאין), דַּרְגָּא עִלָּאָה וְתַתָּאָה דְּאִינוּן כְּחֲדָא.</p>\n<p>וּבְגִין כָּךְ, כַּד בָּעָא יַעֲקֹב לְבָרְכָא לִבְנוֹי דְיוֹסֵף, בָּרִיךְ לוֹן בְּיִחוּדָא דִלְעֵילָא וְתַתָּא כֻּלְּהוּ כְּחֲדָא, (ס\"א לאמור בוא\"ו דאתכליל וא\"ו בינייהו, על דא ייחד לון ביחודא דלעילא כלהו כחדא) בְּגִין דְּיִתְקַיַּים בִּרְכַתְהוֹן, וּלְבָתַר כָּלִיל כֹּלָּא כְּחֲדָא. וְאָמַר, בְּךָ יְבָרֵךְ יִשְׂרָאֵל (לאמר). מַאי בְּךָ. וַדַּאי דָּא רָזָא דְיִחוּדָא, בְּקַדְמִיתָא מִתַּתָּא לְעֵילָא (ס\"א יום ההוא מתתא לעילא), וּלְבָתַר נָחִית לְאֶמְצָעִיתָא וּלְתַתָּא. לֵאמוֹר בְּוא\"ו הָא אֶמְצָעִיתָא. וּלְבָתַר נָחִית לְתַתָּא בְּךָ. וְהָכִי הוּא יָאוֹת כְּדְקָא חָזֵי, מִתַּתָּא לְעֵילָא וּמֵעֵילָא לְתַתָּא.</p>\n<p>בְּךָ יְבָרֵךְ יִשְׂרָאֵל, מַאי יִשְׂרָאֵל, יִשְׂרָאֵל סָבָא. יְבוֹרָךְ יִשְׂרָאֵל לָא כְּתִיב, אֶלָּא יְבָרֵךְ, דְּהָא יִשְׂרָאֵל נָטִיל בִּרְכָאן מִלְּעֵילָא, וּלְבָתַר אִיהוּ מְבָרֵךְ לְכֹלָּא, בְּהַאי דַרְגָּא תַּתָּאָה דַיְיקָא, דְּקָאֲמַר בְּךָ יְבָרֵךְ יִשְׂרָאֵל לֵאמֹר.</p>\n<p>יְשִׂימְךָ אֱלֹהִים כְּאֶפְרַיִם וְכִמְנַשֶּׁה, אַקְדִּים לֵיהּ לְאֶפְרַיִם בְּקַדְמִיתָא, בְּגִין דְּאֶפְרַיִם עַל שְׁמָא (דיוסף) דְיִשְׂרָאֵל אִקְרֵי. מְנָא לָן. מֵהָא, דְּכַד שִׁבְטָא דְאֶפְרַיִם נָפַק, עַד לָא אִשְׁתְּלִים זִמְנָא דְּשִׁעְבּוּדָא דְמִצְרַיִם, דָּחֲקוּ שַׁעְתָּא וְנָפְקוּ מִן גָּלוּתָא, קָמוּ עֲלֵיהוֹן שַׂנְאֵיהוֹן וּקְטָלוּ לוֹן. וּכְתִיב, (יחזקאל לו) בֶּן אָדָם הָעֲצָמוֹת הָאֵלֶּה כָּל בֵּית יִשְׂרָאֵל הֵמָּה. מַשְׁמַע דִּכְתִיב, (יחזקאל לו) כָּל בֵּית יִשְׂרָאֵל הֵמָּה, וְעַל דָּא אַקְדִּים לְאֶפְרַיִם קֳדָם מְנַשֶּׁה. בְּגִין כָּךְ אֶפְרַיִם מָטוּלֵיהּ לִסְטַר מַעֲרָב, וּמַטְלָנוֹי הֲוָה.</p>\n<p>תָּא חֲזֵי, בִּרְכְתָא דְּבָרִיךְ לִבְנֵי יוֹסֵף, אַמַּאי אַקְדִּים לוֹן בִּרְכָאן, עַד לָא יְבָרֵךְ לִבְנוֹי. אֶלָּא מִכָּאן, דַּחֲבִיבוּתָא דִּבְנֵי בְּנוֹי, חָבִיב עֲלֵיהּ דְּבַּר נָשׁ יַתִּיר מִבְּנוֹי. וּבְגִין כָּךְ, אַקְדִּים חֲבִיבוּתָא דִּבְנֵי בְּנוֹי קוֹדֶם לִבְנוֹי, לְבָרְכָא לוֹן בְּקַדְמִיתָא.</p>\n<p>וַיְבָרַכֵם בַּיּוֹם הַהוּא לֵאמֹר, רִבִּי יוֹסֵי פָּתַח וְאָמַר, (תהילים קט״ו:י״ב) יְיָ זְכָרָנוּ יְבָרֵךְ יְבָרֵךְ אֶת בֵּית יִשְׂרָאֵל וְגו'. יְיָ זְכָרָנוּ יְבָרֵךְ, אִלֵּין גּוּבְרִין. יְבָרֵךְ אֶת בֵּית יִשְׂרָאֵל, אִלֵּין נָשִׁין. בְּגִין דִּדְכוּרִין בָּעְיָין לְאִתְבָּרְכָא בְּקַדְמִיתָא, וּלְבָתַר נָשִׁין, וְנָשִׁין לָא מִתְבָּרְכָן אֶלָא מִבִּרְכַתְהוֹן דִּדְכוּרִין, דְּכַד דְּכוּרִין מִתְבָּרְכָן כְּדֵין נָשִׁין מִתְבָּרְכָן. וְאִי תֵימָא מֵהָא, דִּכְתִיב, (ויקרא ט״ז:ו׳) וְכִפֶּר בַּעֲדוֹ וּבְעַד בֵּיתוֹ, דְּבָעֵי לְכַפָּרָא עֲלֵיהּ בְּקַדְמִיתָא, וּלְבָתַר עַל בֵּיתֵיהּ, בְּגִין דְּמִתְבָּרְכָא מִנֵּיהּ.</p>\n<p>תָּא חֲזֵי, דְּנָשִׁין לָא מִתְבָּרְכָן אֶלָּא מִגּוּבְרִין, כַּד אִתְבָּרְכָן אִינוּן בְּקַדְמִיתָא, וּמֵהַאי בִּרְכָתָא מִתְבָּרְכָן. אֶלָּא בְּמַאי אוֹקִימְנָא יְבָרֵךְ אֶת בֵּית יִשְׂרָאֵל. אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא יָהַב תּוֹסֶפֶת בִּרְכָאן לִדְכוּרָא דְּנָסִיב, בְּגִין דְּמִתְבָּרְכָא מִינֵיהּ אִתְּתָא. וְכֵן בְּכָל אֲתַר <Nonei></i>יָהִיב קוּדְשָׁא בְּרִיךְ הוּא תּוֹסֶפֶת בִּרְכָאן לִדְכוּרָא דְנָסִיב, בְּגִין דְּמִתְבָּרְכָא (מניה אתתא וכן בכל אתר יהיב קודשא בריך הוא תוספת ברכאן לדכורא דנסיב, בגין דתתברך מניה נוקבא) מֵהַהוּא תּוֹסֶפֶת דְּבִרְכָאן. כֵּיוָן דְּאִנְסִיב בַּר נָשׁ יָהִיב לֵיהּ תְּרֵין חוּלָקִין, חַד לֵיהּ וְחַד לְנוּקְבֵיהּ, וְאִיהוּ נָטִיל כֹּלָּא, חוּלָקֵיהּ וְחוּלַק נוּקְבֵיהּ.</p>\n<p>תָּא חֲזֵי, וַיְבָרַכֵם בַּיּוֹם הַהוּא, (ס\"א לאמור בריך ברכאן לון ולכל דיפקון מנייהו) לְבָתַר לֵאמוֹר בְּוא\"ו, הָכָא אִתְרְמִיזָא בְּרָא בּוּכְרָא, (שמות ד) בְּנִי בְּכוֹרִי יִשְׂרָאֵל, וּכְתִיב, (ירמיהו ל״א:ט׳) וְאֶפְרַיִם בְּכוֹרִי הוּא, וְעַל דָּא תּוֹסֶפֶת וא\"ו.</p>"],[9520011471,"<p>רִבִּי חִזְקִיָּה פָּתַח, (תהילים קל״ט:ט״ז) גָּלְמִי רָאוּ עֵינֶיךָ וְעַל סִפְרְךָ כֻּלָּם יִכָּתֵבוּ וְגו', הַאי קְרָא אוּקְמוּהָ בְּכַמָּה אֲתַר. אֲבָל תָּא חֲזֵי, כָּל אִינוּן נִשְׁמָתִין דְּהֲווּ מִיּוֹמָא דְאִתְבְּרֵי עַלְמָא, כֻּלְּהוּ קָיְימֵי קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא עַד לָא נָחֲתוּ לְעַלְמָא, בְּהַהוּא דִּיוּקְנָא מַמָּשׁ דְּאִתְחֲזוּן לְבָתַר בְּעַלְמָא. וְהַהוּא חֵיזוּ דְגוּפָא דְּבַר נָשׁ דְּקָאִים בְּהַאי עַלְמָא, הָכִי קָאִים לְעֵילָא.</p>\n<p>וּבְשַׁעְתָּא דְנִשְׁמָתָא דָא זְמִינָא לַאֲחָתָא בְּעַלְמָא, הַהִיא נִשְׁמָתָא בְּהַהִיא דִיוּקְנָא מַמָּשׁ דְּקָיְימָא בְּהַאי עַלְמָא, הָכִי קָאִים (לעילא) קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְאוֹמֵי לָהּ קוּדְשָׁא בְּרִיךְ הוּא דְּיִטּוֹר פִּקּוּדֵי אוֹרַיְיתָא, וְלָא יַעֲבָר עַל קְיָימִין.</p>\n<p>וּמְנָא לָן דְּקָיְימִין קַמֵּיהּ, דִּכְתִיב, (מלכים א י״ז:א׳) חַי יְיָ אֲשֶׁר עָמַדְתִּי לְפָנָיו. עָמַדְתִּי וַדַּאי, וְהָא אוּקְמוּהָ. וּבְגִין כָּךְ גָּלְמִי רָאוּ עֵינֶיךָ, עַד לָא יִתְחֲזֵי (צולמא) בְּעַלְמָא. וְעַל סִפְרְךָ כֻּלָּם יִכָּתֵבוּ, דְּהָא כָּל נִשְׁמָתִין, בְּהַהוּא דִּיוּקְנָא דִּלְהוֹן, כֻּלְּהוּ בְּסִפְרָא כְּתִיבִין. יָמִים יֻצָּרוּ, הָא אוּקְמוּהָ יֻצָרוּ וַדַּאי, וְלֹא אֶחָד בָּהֶם, בְּהַאי עַלְמָא לְמֵיקַם בְּקִיּוּמָא דְמָארֵיהוֹן, כְּדְקָא חָזֵי.</p>"],[9520011472,"<p>תָּא חֲזֵי, יוֹמִין דְּבַּר נָשׁ, כַּד זָכֵי בְּהַאי עַלְמָא בְּעוֹבָדִין טָבָאן, יוֹמִין דִּילֵיהּ אִתְבָּרְכָאן לְעֵילָא, מֵהַהוּא אֲתַר דְּאִיהוּ מִדַּת יוֹמוֹי. פָּתַח וְאָמַר, (תהילים ל״ט:ה׳) הוֹדִיעֵנִי יְיָ קִצִּי וּמִדַּת יָמַי מַה הִיא וְגו', הַאי קְרָא אוּקְמוּהָ. אֲבָל תָּא חֲזֵי, קִצִּי, דָּא קֵץ הַיָּמִין, דְּאִיהוּ מִתְקַשַּׁר בֵּיהּ בְּדָוִ ד. וּמִדַּת יָמַי מַה הִיא, דָּא אִיהוּ דְּאִתְמַנֵּי (נ\"א דאית ממנא) מַמָּשׁ עַל יוֹמוֹי.</p>\n<p>אָמַר רִבִּי יְהוּדָה, הָא שָׁמַעְנָא מֵרִבִּי שִׁמְעוֹן, דְּהַאי קְרָא אִתְּמָר, עַל אִינוּן יוֹמִין דְּאִתְגְּזָרוּ עֲלוֹי מֵאָדָם קַדְמָאָה, דְּאִינוּן ע'. דְּהָא אִתְּמָר, דְּחַיִּין כְּלַל לָא הֲווּ לֵיהּ, אֶלָּא דְּיָהִיב לֵיהּ אָדָם מֵאִינוּן יוֹמִין דִּילֵיהּ, שִׁבְעִין שְׁנִין.</p>\n<p>וְרָזָא דָא, וִילוֹן לָא מְשַׁמֵשׁ כְּלוּם, וְסִיהֲרָא לָא נָהֲרַת מִגַּרְמָהּ כְּלַל, וְשִׁבְעִין שְׁנִין נָהֲרִין לָהּ בְּכָל סִטְרָהָא, וְאִינוּן חַיֵּי דָוִד סְתָם. וְעַל דָּא בָּעָא דָּוִד לְקוּדְשָׁא בְּרִיךְ הוּא, לְמִנְדַע רָזָא דָּא, עַל מָה לֵית לָהּ חַיִּין לְסִיהֲרָא מִגַּרְמָהּ, וּלְמִנְדַע עִקָּרָא דִילָהּ.</p>\n<p>וּמִדַּת יָמַי מַה הִיא, דָּא הוּא דַרְגָּא (ס\"א דעלמא) עִלָּאָה סְתִימָא, דְּאִיהוּ קָיְימָא עַל כָּל אִינוּן יוֹמִין, דְּאִינוּן חַיִּין דִילָהּ, אֲתַר דְּנָהִיר לְכֹלָּא. אֵדְעָה מֶה חָדֵל אָנִי. אָמַר דָּוִד, אִנְדַע עַל מַה חָדֵל אֲנָא נְהוֹרָא מִגַּרְמִי, וְאִתְמְנַע מִנִּי, כִּשְׁאָר כָּל אִינוּן נְהוֹרָאִין עִלָּאִין דְּאִית לוֹן חַיִּין לְכֻלְּהוּ, וְאֲנָא עַל מַה אֲנָא חָדֵל, וְעַל מַה אִתְמְנַע מִנִּי. וְדָא הוּא דְבָעָא דָוִד לְמִנְדַע, וְלָא אִתְיְיהִיב לֵיהּ רְשׁוּתָא לְמִנְדַע.</p>"],[9520011473,"<p>תָּא חֲזֵי, כָּל בִּרְכָאן עִלָּאִין, כֻּלְּהוּ אִתְמְסָרוּ לְהַאי דַרְגָּא, לְבָרְכָא לְכֹלָּא. וְאַף עַל גַּב דְּלֵית לָהּ נְהוֹרָא מִגַּרְמָהּ, כָּל בִּרְכָאן, וְכָל חֵידוּ, וְכָל טִיבוּ, כֻּלְּהוּ קָיְימִין בָּהּ, וּמִנָּהּ (קיימי) נָפְקֵי, וְעַל דָא אִתְקְרִיאַת כּוֹס שֶׁל בְּרָכָה. וְאִקְרֵי בְּרָכָה מַמָּשׁ, כְּמָה דִכְתִיב, (משלי י׳:כ״ב) בִּרְכַּת ה' הִיא תַּעֲשִׁיר, וְעַל דָּא כְּתִיב, (דברים ל״ג:כ״ג) וּמָלֵא בִּרְכַּת ה' יָם וְדָרוֹם יְרָשָׁה.</p>\n<p>וּבְגִין כָּךְ אִית לָהּ בְּכֻלְּהוּ שִׁיּוּר, וּמִכֻּלְּהוּ אִתְמַלְיָיא, וּמִכֻּלְּהוּ אִית בָּהּ, וְאִתְבָּרְכָא מִכָּל <Nonei></i>אִינוּן בִּרְכָאן עִלָּאִין, וְאִתְמְסָרוּ לָהּ בִּרְכָאן לְבָרְכָא, מְנָלָן. דְּאָמַר רִבִּי יִצְחָק, יַעֲקֹב בָּרִיךְ לִבְנוֹי דְיוֹסֵף, מֵאֲתַר דָּא דְכָל בִּרְכָאן אִתְמְסָרוּ בִּידֵיהּ לְבָרְכָא, כְּמָא דְאַתְּ אָמֵר, (בראשית יב) וְהְיֵה בְּרָכָה. מִכָּאן וּלְהַלְאָה בִּרְכָאן אִתְמְסָרוּ בְּיָדֶךָ.</p>\n<p>תָּא חֲזֵי, כְּגַוְונָא דָא אֲנַן מְבָרְכָן וּמְשַׁבְּחִין לִשְׁמָא דָא, וְעַל דָּא הַלֵּילָא, דְּאִינוּן יוֹמִין דְּקָאַמְרֵי הַלֵּילָא. דְּאָמַר רִבִּי חִיָּיא בְּהַלֵּילָא צְרִיכִין ג' דַּרְגִּין, חֲסִידִים, צַדִּיקִים, וְיִשְׂרְאֵלִים. (ס\"א בגין דיסתלק יקרא דקודשא בריך הוא על כלא באלין דרגין) חֲסִידִים, מִסִּטְרָא דִּימִינָא, צַדִּיקִים מִסִּטְרָא דִשְׂמָאלָא, וְיִשְׂרָאֵל מִכָּל אִינוּן סִטְרִין, בְּגִין (דישרים) דְּיִשְׂרָאֵל כְּלִילָן מִכֻּלְּהוּ, וְעַל דָּא אִסְתַּלַּק תּוּשְׁבַּחְתָּא דְּקוּדְשָׁא בְּרִיךְ הוּא מִכֹּלָּא, וְכֵן בְּכָל אֲתַר דְּיִשְׂרָאֵל מְשַׁבְּחָן לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא מִתַּתָּא, אִסְתַּלַּק יְקָרֵיהּ בְּכֹלָּא:</p>"],[9520011474,"<p><Nonei></i><Noneb>תּוֹסֶפְתָּא</b> קל גלגלא מתגלגלא מתתא לעילא, רתיכהא טורקהא אזלין ומתגלגלי. קל נעימותא סלקא ונחתא, אזלא ושטיא בעלמא. קל שופרא נגיד בעומקי דדרגי אסחר דרגא (ס\"א גלגלא) סחרנהא.</p>\n<p>יתבין תרין מגרופין, מימינא ומשמאלא, בתרין גוונין משתאבין דא בדא, דא חוור ודא סומק, ותרווייהו סחרין גלגלא לעילא, אסחר לימינא חוורא סלקא, ואסחר לשמאלא סומקא נחתא. <Nonei></i>וגַלְגַּלָּא אַסְחַר תָּדִיר וְלָא שָׁכִיךָ.</p>\n<p>תְּרֵין (קס\"ב ע\"ב) צִּפֳּרִין סָלְקִין, דְּקָא מְצַּפְּצְּפָּן, חַד לִסְטַר דָּרוֹם, וחַד לִסְטַר צָּפּוֹן. פָּרְחִין בַּאֲוִירָא צִּפְּצּוּפָּא, וְקָל נְעִימוּ דְּגַלְגַּלָּא מִתְּחַבְּרָן כְּחֲדָא, כְּדֵין (תהילים צ״ב:א׳) מִזְמוֹר שִׁיר לְיוֹם הַשַׁבָּתּ. וְכָל בִּרְכָאן נָגְדִין בִּלְחִישׁוּ בְּדָא נְעִימוּ (מקול), מִגּוֹ רְחִימוּ דְּקוֹל שׁוֹפָּרָא.</p>\n<p>לְקַבְּלָא אִינוּן בִּרְכָאן, נָחֲתִּין מִלְּעֵילָא לְתַּתָּא, ואִתְּגְּנִיזוּ כְּחֲדָא בְּגוֹ (שמות ס\"ג ע\"ב) עוּמְקָא דְבֵירָא, נְבִיעוּ דְבֵירָא דְלָא פָּסְקָא בִּלְחִישׁוּ, עַד דְּאִתְּמַלְיָיא הַהוּא גַּלְגַּלָּא סַחֲרָא.</p>\n<p>אִינוּן תְּרֵין מַגְרוֹפִּין סָחֲרָן, חַד דִּימִינָא, קָרֵא בְחָיִל ואָמַר, זְהִירוּ דְּזָהֲרִין דְּסָלְקָא ונָחֲתָּא, תְּרֵי אַלְפֵּי עָלְמִי\"ן אִזְדָּהֲרוּ. עַלְמָא דְאֶמְצָּעִיתָּא בְּגַוַּויְיהוּ, אִזְדָּהַר בְּזוֹהֲרָא דְּמָארָךָ. כָּל אִינוּן מָארֵי דְּעַיְינִין, אִסְתַּכָּלוּ וּפִּקְחוּ עֵינֵיכוֹן, ותִּזְכּוּן לְהַאי נְהִירוּ, לְהַאי עִדּוּנָא, אִלֵּין אִינוּן בִּרְכָאן דְּנָגְדֵי מִלְּעֵילָא, מַאן דְּזָכֵי, גַּלְגַּלָּא סָלְקָא אַסְחַר לִימִינָא, ואַנְגִיד ואַמְשִׁיךָ לְהַהוּא דְּזָכֵי, ואִתְּעַדַּן מֵאִלֵּין בִּרְכָאן עִלָּאִין דְּזָהֲרָן, זַכָּאִין אִינוּן דְּזָכָאן בְּהוּ.</p>\n<p>וְכַד לָא זָכֵי, גַּלְגַּלָּא אַסְחַר, והַהוּא מַגְרוֹפָּא דְּלִסְטַר שְׂמָאלָא, אַסְחַר ונָחַתּ לְתַּתָּא, ואַמְשִׁיךָ דִּינָא עַל הַאי דלא זָכֵי, וקָלָא נָפְּקַתּ, ווי לְאִינוּן חַיָּיבִין דְּלָא זָכוּ. מֵהַהוּא סִטְרָא, נָפִּיק אֶשָׁא דְשַׁלְהוֹבָא דְּדָלִיק, דְּשָׁארֵי עַל רֵישֵׁיהוֹן דְּחַיָּיבַיָא. זַכָּאִין אִינוּן, כּל אִינוּן דַּאֲזְלוּ בְּאוֹרַח קְשׁוֹט בְּהַאי עַלְמָא, לְמִזְכֵּי לְהַהוּא נְהוֹרָא עִלָּאָה, בִּרְכָאן דְּצַּחְצְּחָן, כְּמָה דְאַתְּ אָמֵר, (ישעיהו נ״ח:י״א) והִשְׂבִּיעַ בְּצַּחְצָּחוֹתּ נַפְּשֶׁךָ (עד כאן תוספתא):</p>"],[9520011475,"<p>וַיִּקְרָא יַעֲקֹב אֶל בָּנָיו וַיֹּאמֶר הֵאָסְפוּ וְגו', רִבִּי אַבָּא פָּתַח וְאָמַר, (תהילים ק״ב:י״ח) פָּנָה אֶל תְּפִלַּת הָעַרְעָר וְלֹא בָּזָה אֶת תְּפִלָּתָם. הַאי קְרָא אוּקְמוּהָ, וְאַקְשׁוּ בֵּיהּ חַבְרַיָיא. (אלא תו אית ביה סטר קורדיטא) פָּנָה, הִקְשִׁיב מִבָּעֵי לֵיהּ, אוֹ שָׁמַע, מַאי פָּנָה.</p>\n<p>אֶלָּא כָּל צְלוֹתִין דְּעַלְמָא צְלוֹתִין. וּצְלוֹתָא דְיָחִיד, לָא עָאל קַמֵּי מַלְכָּא קַדִּישָׁא, אֶלָּא בְּחֵילָא תַּקִּיפָא. דְּעַד לָא עָאֳלַת הַהִיא צְלוֹתָא לְאִתְעַטְּרָא בְּדוּכְתָּהּ, אַשְׁגַּח בָּהּ קוּדְשָׁא בְּרִיךְ הוּא, וְאִסְתְּכֵי בָּהּ, וְאִסְתְּכֵי בְּחוֹבוֹי וּבִזְכוּתֵיהּ דְּהַהוּא בַּר נָשׁ, מַה דְּלָא עָבִיד כֵּן בִּצְלוֹתָא דְסַגִּיאִין. דִּצְלוֹתָא דְּסַגִּיאִין כַּמָּה אִינוּן צְלוֹתִין דְּלָא (מבני) מִן זַכָּאִין אִינוּן, וְעָאלִין כֻּלְּהוּ קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְלָא אַשְׁגַּח בְּחוֹבַיְיהוּ.</p>\n<p>בְגִין כָּךְ, פָּנָה אֶל תְּפִלַּת הָעַרְעָר, מְהַפֵּךְ (בזכותיה) וְאִסְתְּכֵי בָהּ, וְאִסְתְּכֵי בָּהּ בְּמָּה רְעוּתָא אִתְעֲבִיד, וּמַאן הַהוּא בַּר נָשׁ דְּצַלֵּי צְלוֹתָא דָא, וּמַאן אִינוּן עוֹבָדוֹי. בְגִין כָּךְ, לִיבָּעֵי לֵיהּ לְבַּר נָשׁ, דִּלְצַלֵּי צְלוֹתָא בְּצִבּוּרָא. מַאי טַעְמָא, בְּגִין דְּלָא בָזָה אֶת תְּפִלָּתָם, אַף עַל גַּב דְּלָאו כֻּלְּהוּ בְּכַוָּונָה וּרְעוּתָא דְּלִבָּא.</p>\n<p>דָּבָר אַחֵר פָּנָה אֶל תְּפִלַּת הָעַרְעָר, דָּא יְחִידָאי דְּאִתְכְּלִיל בְּסַגִּיאִין. וּמַאן הוּא יְחִידָאי דְּאִתְכְּלִיל בְּסַגִּיאִין, הֱוֵי אֵימָא דָא יַעֲקֹב, דְּאִיהוּ כָּלִיל בִּתְרֵין סִטְרִין, וּקְרָא לִבְנוֹי, וְצַלֵּי צְלוֹתֵיהּ עֲלַיְיהוּ. מַאן צְלוֹתָא דְּיִתְקַבְּלוּן בִּשְׁלִימוּ לְעֵילָא, צְלוֹתָא דְלָא יִשְׁתֵּצוּן בְּגָלוּתָא.</p>\n<p>בְּהַאי שַׁעְתָּא דְּיַעֲקֹב קָרָא לוֹן, אִסְתַּלַּק מִנֵּיהּ שְׁכִינְתָּא, וְהָא אוּקְמוּהָ. וְתָּא חֲזֵי, בְּשַׁעְתָּא דְּיַעֲקֹב הֲוָה קָארֵי לִבְנוֹי, אִזְדַּמְּנוּ אַבְרָהָם וְיִצְחָק תַּמָּן, וּשְׁכִינְתָּא עַל גַּבַּיְיהוּ. וּשְׁכִינְתָּא הֲוָה חָדֵי בֵּיהּ בְּיַעֲקֹב, לְאִתְחַבְּרָא בַּאֲבָהָן, <Nonei></i>לְאִתְקַשְּׁרָא עִם נַפְשַׁיְיהוּ כְּחַד, לְמֶהוֵי רְתִיכָא.</p>\n<p>בְּשַׁעְתָּא דְּפָתַח יַעֲקֹב, וְאָמַר הֵאָסְפוּ וְאַגִּידָה לָכֶם אֵת אֲשֶׁר יִקְרָא אֶתְכֶם בְּאַחֲרִית הַיָּמִים. בְּאַחֲרִית, דָּא שְׁכִינְתָּא, כִּבְיָכוֹל יָהַב עֲצִיבוּ בֵּיהּ, וְאִסְתַּלַּק. וּלְבָתַר אַהֲדָרוּ לָהּ בְּנוֹי, בְּיִחוּדֵי דְמִילַיְיהוּ, וּפָתְחוּ וְאָמְרוּ, (דברים ו) שְׁמַע יִשְׂרָאֵל וְגו'. בְּהַהִיא שַׁעְתָּא קָאִים לָהּ יַעֲקֹב, וְאָמַר בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד, וְאִתְיַישְׁבַת שְׁכִינְתָּא בְּדוּכְתָּהּ. וַיִּקְרָא יַעֲקֹב, מַאי קְרִיאָה הָכָא. אֶלָּא קְרִיאָה, לְקַיְימָא דוּכְתַּיְיהוּ, לְקַיְימָא לוֹן לְעֵילָא וְתַתָּא.</p>\n<p>תָּא חֲזֵי, בְּכָל אֲתַר קְרִיאָה בְּהַאי גַוְונָא, דִּכְתִיב, (במדבר י״ג:ט״ז) וַיִּקְרָא משֶׁה לְהוֹשֵׁעַ בִּן נוּן יְהוֹשֻׁעַ, לְקַיְימָא דּוּכְתֵּיהּ, בְּאֲתַר דְּאִצְטְרִיךְ, וּלְקָשְׁרָא לֵיהּ. וְכֵן (בראשית כ״ה:כ״ו) וַיִּקְרָא שְׁמוֹ יַעֲקֹב. וּכְתִיב, (בראשית ל״ג:כ׳) וַיִּקְרָא לוֹ אֵל אֱלֹהֵי יִשְׂרָאֵל, קוּדְשָׁא בְּרִיךְ הוּא קִיֵּים לֵיהּ לְאֲתַר דָּא בִּשְׁמָא דָא. קְרִיאָה לְקִיּוּמָא קָא אַתְיָא.</p>\n<p>אִי תֵימָא (יונה ג׳:ח׳) וְיִקְרְאוּ אֶל אֱלהִים, (יונה ב׳:ג׳) קָרָאתִי מִצָּרָה לִי אֶל ה', הָכִי הוּא וַדַּאי, לְקָשְׁרָא וּלְקָיְימָא קִיּוּמָא לְעֵילָא. וּמַאן אִיהוּ, סִדּוּרָא דְשִׁבְחָא דְמָארֵיהּ. וְכָל אִינוּן מִלִּין דְּבָעָאן קַמֵּי מָארֵיהּ, קִיּוּמָא יָהִיב לֵיהּ לְמָארֵיהּ, דְּאַחֲזֵי דְּבֵיהּ תַּלְיָא כֹּלָּא, וְלָא בְּאֲתַר אָחֳרָא, הָא כֹּלָּא קַיַּים קִיּוּמָא. כְּהַאי גַּוְונָא וַיִּקְרָא יַעֲקֹב אֶל בָּנָיו, קִיֵּים לוֹן בְּקִיּוּמָא שְׁלִים. כְּגַוְונָא דָא וַיִּקְרָא אֶל משֶׁה, אִתְקְיַּים בְּקִיּוּמֵיהּ.</p>\n<p>אָמַר רִבִּי יִצְחָק, א' דְוַיִּקְרָא, אַמַּאי הִיא זְעֵירָא. אָמַר לֵיהּ, אִתְקְיַּים משֶׁה בִּשְׁלִימוּ, וְלָא בְּכֹלָּא, דְּהָא אִסְתַּלַּק מֵאִתְּתֵיהּ. בְּסִפְרֵי קַדְמָאֵי אָמְרֵי לְשִׁבְחָא, וְאֲנַן הָכִי תָּנִינָן, מַאי דְאִסְתַּלַּק לְעֵילָא, יִתְקַשַּׁר לְעֵילָא וּלְתַתָּא, וּכְדֵין, אִיהוּ שְׁלִים. תוּ, אָלֶ\"ף זְעֵירָא מֵאֲתַר זְעֵירָא הֲוָה, זְעֵירָא דְּאִיהוּ רַב בְּאִתְחַבְּרוּתֵיהּ לְעֵילָא. (נ\"א לעילא ותתא וכדין שלים).</p>\n<p>וַיֹּאמֶר, מַאי וַיֹּאמֶר. הָא אוּקְמוּהָ, (כמא דאת אמר, ויאמר בלבו) (ישעיהו מ״ט:כ״א) וְאָמַרְתָּ בִלְבָבֶךָ, אֲמִירָה בַּחֲשַׁאי. הֵאָסְפוּ, אִסְפוּ מִבָּעֵי לֵיהּ, כְּמָא דְאַתְּ אָמֵר, (תהילים נ׳:ה׳) אִסְפוּ לִי חֲסִידָי. אֶלָּא (ס\"א קיים לון) קִים לָן הֵאָסְפוּ מֵאֲתַר דִּלְּעֵילָא הוּא. הֵאָסְפוּ בְּקִשּׁוּרָא שְׁלִים בְּיִחוּדָא חַד. וְאַגִּידָה לָכֶם, מַאי וְאַגִּידָה, רָזָא דְחָכְמְתָא אִיהוּ.</p>\n<p>רִבִּי יוֹסֵי שָׁאִיל לְרִבִּי שִׁמְעוֹן, אָמַר לֵיהּ, וְאַגִּידָה, אוֹ וְיַגֵּד, אוֹ וְיַגִּידוּ, וְכֵן כֻּלְּהוּ, דְּתָנִינָן דְּרָזָא דְחָכְמָתָא אִיהִי, אַמַּאי בְּמִלָּה דָא (בכלהו) אִיהוּ רָזָא דְחָכְמְתָא. אָמַר לֵיהּ, בְּגִין דְּאִיהוּ מִלָּה דְאַתְיָא בְּגִימֶ\"ל דָלֶ\"ת בְּלָא פִּירוּדָא, וְהַאי אִיהוּ רָזָא דְחָכְמָתָא. מִלָּה דְאַתְיָא בִּשְׁלִימוּ בְּרָזָא דְאַתְוָון, הָכִי הוּא, כַּד אִינוּן בְּחָכְמְתָא. אֲבָל דָלֶ\"ת בְּלָא גִימֶ\"ל, לָאו הוּא שְׁלִימוּ, וְכֵן גִימֶ\"ל בְּלָא דָלֶ\"ת. דְּהָא דָא בְּדָא אִתְקַשְּׁרוּ בְּלָא פִּירוּדָא, וּמַאן דְּאַפְרִישׁ לוֹן, גָּרִים לְגַרְמֵיהּ מוֹתָא, וְרָזָא דָא חוֹבָא דְּאָדָם.</p>\n<p>בְגִין כָּךְ, הוּא מִלָּה דְרָזָא דְחָכְמְתָא, וְאַף עַל גַּב דְּאִית יו\"ד לְזִמְנִין בֵּין גִימֶ\"ל לְדָלֶ\"ת, לָאו הֲוֵי פִּירוּדָא, וְכֹלָּא קִשּׁוּרָא חָדָא, וְעַל דָּא מִלָּה דָא, הָכִי הוּא וַדַּאי. וְאַגִּידָה לָכֶם, רָזָא דְחָכְמְתָא, בָּעָא לְגַלָּאָה סוֹפָא דְכָל עוֹבָדֵיהוֹן דְּיִשְׂרָאֵל.</p>\n<p>וְאִי תֵימָא, דְּלָא גָלֵי מַאי דְבָעָא לְגַלָּאָה, אִי הָכִי, אַמַּאי כְּתִיב בְּאוֹרַיְיתָא מִלָּה דְיַעֲקֹב שְׁלֵימָא, וְאִתְפְּגִים לְבָתַר, וְלָא אִשְׁתְּלִים מִלָּה. אֶלָּא וַדַּאי אִשְׁתְּלִים, כָּל מַה דְּאִצְטְרִיךְ לְגַלָּאָה גַּלֵּי וְסָתִים, אָמַר מִלָּה וְגַלֵּי לְבַר וְסָתִים לְגוֹ. וּמִלָּה דְאוֹרַיְיתָא לָא אִתְפְּגִים לְעָלְמִין.</p>\n<p>וְכֹלָּא הוּא סָתִים בֵּיהּ בְּאוֹרַיְיתָא, בְּגִין דְּאוֹרַיְיתָא הוּא שְׁלִימוּ דְּכֹלָּא, שְׁלִימוּ דִּלְעֵילָא וְתַתָּא, וְלָא אִית מִלָּה אוֹ אָת בְּאוֹרַיְיתָא פְּגִימוּ. וְיַעֲקֹב כָּל מַה דְּאִצְטְרִיךְ לֵיהּ לְמֵימַר אָמַר, אֲבָל גַּלֵּי וְסָתִים, וְלָא פָּגִים מִכָּל מַה דְּבָעָא אֲפִילּוּ אוֹת אַחַת.</p>\n<p>רִבִּי יְהוּדָה וְרִבִּי יוֹסֵי הֲווּ יַתְבֵי יוֹמָא חַד אֲפִתְחָא דְלוֹד. אָמַר רִבִּי יוֹסֵי לְרִבִּי יְהוּדָה, הָא דְחָמִינָן דְּיַעֲקֹב בָּרִיךְ לִבְנוֹי, חָמִינָן מִמַּה דִּכְתִיב, וַיְבָרֶךְ אוֹתָם, אֲבָל אָן בִּרְכָתָא דִלְהוֹן. אָמַר לֵיהּ, כֹּלָּא בִּרְכָאן אִינוּן דְּבָרִיךְ לְהוּ. כְּגוֹן, יְהוּדָה אַתָּה יוֹדוּךָ אַחֶיךָ. דָּן יָדִין עַמּוֹ. מֵאָשֵׁר שְׁמֵנָה לַחְמוֹ. וְכֵן כֻּלְּהוּ.</p>\n<p>אֲבָל מַה דְּבָעֵי לְגַלֵּי לוֹן לָא גַּלֵּי, דְּבָעָא לְגַלָּאָה לְהוּ אֶת הַקֵּץ. וְהָא אוּקְמוּהָ, דְּאִית קֵץ לִימִינָא, וְאִית קֵץ לִשְׂמָאלָא, וּבָעָא לְגַלָּאָה לוֹן אֶת הַקֵּץ, בְּגִין לְאִסְתַּמְּרָא <Nonei></i>וּלְאִתְדַּכְּאָה מֵעָרְלָה. ומַאן דְּגַלֵּי לוֹן אִתְיְדַע וְאִתְגַּלֵּי, עַד דְּעָאלוּ לְאַרְעָא קַדִּישָׁא. אֲבָל מִלִּין אָחֳרָנִין לָאו אִינוּן בְּאִתְגַּלְּיָיא, וּסְתִימִין אִינוּן בְּאוֹרַיְיתָא, בְּהַאי פָּרְשָׁתָא דְיַעֲקֹב, וּבְאִינוּן בִּרְכָאן.</p>"],[9520011476,"<p>פָּתַח וְאָמַר. רְאוּבֵן בְּכֹרִי אַתָּה כֹּחִי וְרֵאשִׁית אוֹנִי. מַאי קָא חָמָא יַעֲקֹב לְמִפְתַּח בִּרְאוּבֵן, לִיפְתַּח בִּיהוּדָה, דְּאִיהוּ קַדְמָאָה לְכָל מַשִּׁרְיָין, וְאִיהוּ מַלְכָּא, וְחָמִינָן דְּלָא בָּרְכֵיהּ וְסָלִיק בִּרְכָאן מִנֵּיהּ, עַד דְּאָתָא משֶׁה וְצַלֵּי צְלוֹתָא עֲלֵיהּ. כְּמָה דְאַתְּ אָמֵר, (דברים ל״ג:ו׳) יְחִי רְאוּבֵן וְאַל יָמוֹת.</p>\n<p>אֲבָל וַדַּאי בָּרְכֵיהּ, וְסָלְקָא הַהוּא בִּרְכְתָא לְאַתְרֵיהּ. לְבַר נָשׁ דְּהֲוָה לֵיהּ בַּר, כַּד מָטָא זִמְנֵיהּ לְאִסְתַּלְּקָא מֵעַלְמָא, אֲתָא מַלְכָּא עֲלֵיהּ, אָמַר, הָא כָּל מָמוֹנָא דִילִי, לֶיהוֵי בִּידָא דְמַלְכָּא נָטִיר לִבְרָאי. כַּד חָמֵי מַלְכָּא דִּבְרִי אִתְחֲזֵי, יָהִיב לֵיהּ. כָּךְ יַעֲקֹב אָמַר. רְאוּבֵן בְּכֹרִי אַתָּה, רְחִימָא דְּמֵעַיי אַנְתְּ, אֲבָל בִּרְכָאן דִּילָךְ יִסְתַּלְּקוּן בִּידָא דְּמַלְכָּא קַדִּישָׁא, עַד דְּיֶחמֵי בָךְ, בְּגִין דְּאֲזַלְתְּ לָקֳבֵל אַפָּךְ וְגו', כְּתַרְגּוּמוֹ:</p>\n<p>רְאוּבֵן בְּכוֹרִי אַתָּה וְגו'. רִבִּי אֶלְעָזָר פָּתַח וְאָמַר, (יחזקאל ל״ז:ט׳) וַיֹּאמֶר אֵלַי הִנָּבֵא אֶל הָרוּחַ וְגו'. כַּמָּה אֲטִימִין אִינוּן בְּנֵי נָשָׁא, דְּלָא יָדְעִין וְלָא מַשְׁגִּיחִין בִּיקָרָא דְמַלְכָּא, דְּהָא אוֹרַיְיתָא אַכְרִיז עֲלַיְיהוּ בְּכָל יוֹמָא, וְלֵית מַאן דְּצַיִּית אוּדְנֵיהּ לְקֳבְלֵיהּ. הַאי קְרָא קַשְׁיָא, כֵּיוָן דִּכְתִיב הִנָּבֵא אֶל הָרוּחַ, אַמַּאי זִמְנָא אָחֳרָא הִנָּבֵא בֶּן אָדָם וְאָמַרְתָּ אֶל הָרוּחַ.</p>\n<p>אֶלָּא מִכָּאן אוֹלִיפְנָא רָזָא דְחָכְמְתָא, תְּרֵין קָיְימִין הָכָא, חַד לְאִתְעָרָא מִתַּתָּא לְעֵילָא. דְּאִי לָא מִתְעָרִין לְתַתָּא, לָא מִתְעָרִין לְעֵילָא, וּבְאִתְעֲרוּתָא דִלְתַתָּא אִתְעַר לְעֵילָא. הִנָּבֵא אֶל הָרוּחַ מִתַּתָּא לְעֵילָא. הִנָּבֵא בֶּן אָדָם וְאָמַרְתָּ אֶל הָרוּחַ, מֵעֵילָא לְתַתָּא.</p>\n<p>דְּהָא אֲפִילּוּ לְעֵילָא, בְּאִתְעֲרוּתָא דִלְתַתָּא, נָקִיט הַהוּא עִלָּאָה מֵעִלָּאָה מִנֵּיהּ. כְּגוֹן הַאי קְרָא, (יחזקאל ל״ז:ט׳) כֹּה אָמַר ה' מֵאַרְבַּע רוּחוֹת בֹּאִי הָרוּחַ, מֵאַרְבַּע רוּחוֹת, דָּא דָרוֹם וּמִזְרָח וְצָפוֹן וּמַעֲרָב, וְרוּחַ אַתְיָא מִמַּעֲרָב, בְּאִתְחַבְּרוּתָא דְאִלֵּין אָחֳרָנִין. כְּמָא דְאַתְּ אָמֵר, (במדבר כ״א:י״ח) כָּרוּהָ נְדִיבֵי הָעָם וְגו'.</p>\n<p>וּמֵהָכָא נָפְקִין רוּחִין וְנִשְׁמָתִין לִבְנֵי עַלְמָא לְאִצְטַיְירָא בְּהוּ. וּפַחֵי, כְּמָא דְאַתְּ אָמֵר, (בראשית ב׳:ז׳) וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים. תָּא חֲזֵי, נָקִיט מֵהַאי גִיסָא, וְיָהִיב בְּגִיסָא אָחֳרָא, וְעַל דָּא (קהלת א׳:ז׳) כָּל הַנְּחָלִים הוֹלְכִים אֶל הַיָּם וְהַיָּם אֵינְנּוּ מָלֵא. אַמַּאי אֵינֶנּוּ מָלֵא, בְּגִין דְּנָקִיט וְיָהִיב, אָעִיל וְאַפִּיק.</p>\n<p>רִבִּי אֶלְעָזָר שָׁאִיל שְׁאֵלְתָּא לְרִבִּי שִׁמְעוֹן. אָמַר, הוֹאִיל וְקוּדְשָׁא בְּרִיךְ הוּא גָלֵי קַמֵּיהּ דִּבְנֵי נָשָׁא יְמוּתוּן, אַמַּאי נָחִית נִשְׁמָתִין לְעַלְמָא, וְאַמַּאי אִצְטְרִיךְ לֵיהּ. אָמַר לֵיהּ, שְׁאֵילְתָּא דָא קַמַּיְיהוּ דְרַבָּנָן שְׁאִילוּ כַמָּה וְכַמָּה, וְאוּקְמוּהָ. אֲבָל קוּדְשָׁא בְּרִיךְ הוּא יָהִיב נִשְׁמָתִין דְּנָחֲתִין לְהַאי עַלְמָא, לְאִשְׁתְּמוֹדְעָא יְקָרֵיהּ, וְנָקִיט לוֹן לְבָתַר, אִי הָכִי אַמַּאי נָחֲתוּ.</p>\n<p>אֶלָּא, רָזָא דָא, הָכִי הוּא. פָּתַח וְאָמַר, (משלי ה׳:ט״ו) שְׁתֵה מַיִם מִבּוֹרֶךָ וְנוֹזְלִים מִתּוֹךְ בְּאֵרֶךָ, הָא (ס' ע\"א) אוֹקִימְנָא. בּוֹר, אֲתַר דְּלָא נְבִיעַ מִגַּרְמֵיהּ, וְאֵימָתַי נָבְעִין הַנֵּי מַיָא, בְּשַׁעְתָּא דְּאִשְׁתְּלִים נִשְׁמָתָא בְּהַאי עַלְמָא, כַּד סָלְקָא לְהַהוּא אֲתַר דְּאִתְקַשַּׁר בֵּיהּ, כְּדֵין הוּא שְׁלִים, מִכָּל סִטְרִין מִתַּתָּא וּמֵעֵילָא. (ס\"א ומכל סטרין).</p>\n<p>וְכַד נִשְׁמָתָא סָלְקָא, כְּדֵין אִתְעַר תִּיאוּבְתָּא דְנוּקְבָא לְגַבֵּי דְּכוּרָא, וּכְדֵין נָבְעִין מַיָא מִתַּתָּא לְעֵילָא. וּבוֹר, אִתְעֲבִיד בְּאֵר, מַיִין נְבִיעָאן. וּכְדֵין אִתְחַבְּרוּתָא וְיִחוּדָא (נ\"א ויסודא) וְתִיאוּבְתָּא וְרַעֲוָא אִשְׁתַּכַּח. (להא) דְּהָא בְּנִשְׁמָתָא דְּצַדִּיקָא אִשְׁתְּלִים הַהוּא אֲתַר, וְאִתְעַר חֲבִיבוּתָא וּרְעוּתָא לְעֵילָא, וְאִתְחַבַּר כְּחַד.</p>\n<p>רְאוּבֵן בְּכֹרִי אַתָּה, הָכִי הוּא וַדַּאי, טִפָּה קַדְמָאָה דְיַעֲקֹב הֲוָה, וּרְעוּתֵיהּ בְּאֲתַר אָחֳרָא הֲוָה כְּמָה דְאִתְּמָר. תָּא חֲזֵי, רְאוּבֵן וְכֻלְּהוּ שִׁבְטִין תְּרֵיסַר, כֻּלְּהוּ אִתְאַחֲדָן בִּשְׁכִינְתָּא, וְכַד חָמָא יַעֲקֹב לִשְׁכִינְתָּא עַל גַּבֵּיהּ, קָרָא לִבְנוֹי תְּרֵיסַר לְאִתְחַבְּרָא בָּהּ.</p>\n<p>וְתָא חֲזֵי, עַרְסָא שְׁלֵימָתָא לָא אִשְׁתַּכַּח מִן יוֹמָא דְאִתְבְּרֵי עַלְמָא, כְּהַהִיא שַׁעְתָּא דְבָעָא <Nonei></i>יַעֲקֹב לְאִסְתַּלְּקָא מֵעַלְמָא, אַבְרָהָם מִימִינֵיהּ, יִצְחָק מִשְׂמָאלֵיהּ, יַעֲקֹב הֲוָה שָׁכִיב בֵּינַיְיהוּ, שְׁכִינְתָּא קַמֵּיהּ. כֵּיוָן דְּחָמָא יַעֲקֹב כָךְ, קָרָא לִבְנוֹי, וְאָחִיד לוֹן סַחֲרָנֵיהּ דִּשְׁכִינְתָּא, וְסִדֵּר לוֹן בְּסִדּוּרָא שְׁלִים.</p>\n<p>מְנָא לָן דְּסִדֵּר לוֹן סַחֲרָנֵיהּ דִּשְׁכִינְתָּא, דִּכְתִיב הֵאָסְפוּ, וּכְדֵין אִשְׁתַּכַּח תַּמָּן שְׁלִימוּ דְּכֹלָּא, וְכַמָּה רְתִיכִין עִלָּאִין סַחֲרָנַיְיהוּ. פָּתְחֵי וְאָמְרֵי, (דברי הימים א כ״ט:י״א) לְךָ ה' הַגְּדוּלָּה וְהַגְּבוּרָה וְגו', כְּדֵין אִתְכְּנִישׁ שִׁמְּשָׁא לְגַבֵּיהּ דְסִיהֲרָא, וְאִתְקְרִיב מִזְרָח בְּמַעֲרָב. הֲדָא הוּא דִכְתִיב וַיֶּאֱסוֹף רַגְלָיו אֶל הַמִּטָּה, וְאִתְנְהִיר סִיהֲרָא, וְאִשְׁתַּכַּח בִּשְׁלִימוּ. וּכְדֵין וַדַּאי תָּנִינָן, יַעֲקֹב אָבִינוּ לָא מִית. כֵּיוָן דְּחָמָא יַעֲקֹב (ס\"א סדורא) סִטְרָא שְׁלִים, מַה דְּלָא אִשְׁתַּכַּח הָכִי לְבַר נָשׁ אָחֳרָא, חָדֵי, וְשַׁבַּח לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, וּפָתַח וּבָרִיךְ לִבְנוֹי, כָּל חַד וְחַד כְּדְקָא יְאוּת לֵיהּ.</p>"],[9520011477,"<p>רִבִּי יוֹסֵי וְרִבִּי יֵיסָא הֲווּ אָזְלֵי בְּאָרְחָא. אָמַר רִבִּי יִיִסָא הָא וַדַּאי תָּנִינָן, כָּל בְּנוֹי דְיַעֲקֹב אִתַּקָּנוּ בְּסִדּוּרָא שְׁלִים, וְאִתְבָּרְכוּ כָּל חַד וְחַד כְּדְקָא יְאוּת לֵיהּ, מַאי קָא נֵימָא בְּהַאי קְרָא, דִּכְתִיב, מֵאָשֵׁר שְׁמֵנָה לַחְמוֹ וְגו'. אָמַר לֵיהּ, לָא יְדַעְנָא, בְּגִין דְּלָא שָׁמַעְנָא בֵּיהּ מִבּוּצִינָא קַדִּישָׁא, אֶלָּא אַנְתְּ וְאֲנָא נֵיזִיל לְגַבֵּי בּוּצִינָא קַדִּישָׁא. אָזְלֵי, כַּד מָטוּ לְגַבֵּי דְּרִבִּי שִׁמְעוֹן, אָמְרוּ מִלָּה וְשָׁאִילוּ שְׁאִילְתָּא. אָמַר לוֹן, וַדַּאי רָזָא דְחָכְמְתָא הוּא.</p>\n<p>פָּתַח וְאָמַר, (שופטים ה׳:י״ז) אָשֵׁר יָשַׁב לְחוֹף יַמִּים וְעַל מִפְרָצָיו יִשְׁכּוֹן, אַמַּאי יָתִיב תַּמָּן. אֶלָּא מַאן דְּיָתִיב בְּשִׂפְתָא דְיַמָּא, אִשְׁתַּמֵּשׁ בְּתַפְנוּקֵי עַלְמָא. (והכא אשר דא פתחא עלאה דצדיק (ס\"א דצדק) כד אתברכא לארקא ברכאן בעלמא. ס\"א והכא סמך להאי קרא, מאשר, שמנה לפתחא עלאה דמתמן אתרקו ברכאן לעלמא) וְהַאי פִּתְחָא אִשְׁתְּמוֹדַע תָּדִיר בִּרְכָאן דְּעַלְמָא וְאִקְרֵי אָשֵׁר, וְדָא הוּא עַמּוּדָא מֵאִינוּן דְּקָאִים עַלְמָא עֲלַיְיהוּ.</p>\n<p>וְהַהוּא אֲתַר דְּאִקְרֵי לֶחֶם עוֹנִי, מֵהַהוּא אֲתַר אַתְקִין (ההוא). הֲדָא הוּא דִכְתִיב מֵאָשֵׁר שְׁמֵנָה לַחְמוֹ, מַה דְּהֲוָה לַחְמָא דְמִסְכֵּנָא, אִתְהַדַּר לֶחֶם (עוני) פַּנַּג (שמנה). בְּגִין דְּאֲרִיק וְאַרְמֵי בֵּיהּ בִּרְכָאן וְתַפְנוּקִין, וְסוֹפָא דִקְרָא אוֹכַח, וְהוּא יִתֵּן מַעֲדַנֵּי מֶלֶךְ. מַאן מֶלֶךְ, דָּא כְּנֶסֶת יִשְׂרָאֵל, דְּמִנָּהּ אִתְּזָן בְּתַפְנוּקֵי עַלְמָא. וְדָא יָהִיב לְהַאי מֶלֶךְ כָּל בִּרְכָאן, כָּל חֵידוּ וְכָל טִיבוּ. הוּא יָהִיב וּמִנָּה נַפְקֵי. אָמְרוּ, אִי לָא אֲתֵינָא לְעַלְמָא, אֶלָּא לְמִנְדַע דָּא, טַב לָן.</p>"],[9520011478,"<p>רְאוּבֵן בּוּכְרָא דְיַעֲקֹב הֲוָה, אָמַר רִבִּי חִיָּיא, לֵיהּ הֲוָה אִתְחֲזֵי כֹּלָּא, וְאִתְעֲבַר מִינָהּ כֹּלָּא, וְאִתְיְהִיב מַלְכוּ לִיהוּדָה, בְּכֵירוּתָא לְיוֹסֵף, כְּהוּנָּתָא לְלֵוִי. הֲדָא הוּא דִכְתִיב, פַּחַז כַּמַּיִם אַל תּוֹתַר, לָא תִשְׁתָּאַר בְּהוּ. וּמַה דְּאָמַר כֹּחִי וְרֵאשִׁית אוֹנִי, הָכָא בָּרְכֵיהּ וּפַקְדֵּיהּ לְקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>לִרְחִימָא דְמַלְכָּא, (דבעא מן מלכא למעבד ביה טיבו) (נ\"א דהוה ליה ברא והוה בעי דמלכא יעביד ליה טיבו) יוֹמָא חַד אַעֲבַר בְּרֵיהּ בְּשׁוּקָא, אָמַר לְמַלְכָּא, דָּא הוּא בְּרִי, וַדַּאי רְחִימָא דְנַפְשָׁאי. שָׁמַע מַלְכָּא, וְיָדַע דְּהָא שָׁאִיל עַל בְּרֵיהּ. כָּךְ יַעֲקֹב אָמַר, רְאוּבֵן בְּכוֹרִי אַתָּה כֹּחִי וְגו', הָכָא פַקְדֵּיהּ לְמַלְכָּא.</p>\n<p>פַּחַז כַּמַּיִם אַל תּוֹתַר, הָכָא אָמַר מַה דְּאִעֲרַע לֵיהּ, דְּלָא אִשְׁתָּאַר (ליה) בְּאַרְעָא, וְשָׁדֵי לֵיהּ לְבַר מֵאַרְעָא. לָקֳבֵל דָּא, חַד מְמַנָּא (תחומא) מִסִּטְרָא דְּמִשְׁכְּנָא לְעֵילָא, דִּי מְמַנָּא תְּחוֹת יָדָא דְמִיכָאֵל, וְאָמְרֵי לָהּ תְּחוֹת יְדָא דְגַבְרִ\"יאֵל. וּמִיכָאֵל הוּא רֵישָׁא בְּכָל אֲתַר מִסִּטְרָא דְחֶסֶ\"ד, וְגַבְרִיאֵל מִסִּטְרָא דִשְׂמָאלָא דִגְבוּרָ\"ה. (הושע י״ב:א׳) וִיהוּדָה עֹד רָד עִם אֵל, סְטַר גְּבוּרָה, בֵּי דִינָא אִקְרֵי, וְסָמִיךְ לֵיהּ רְאוּבֵן, אַף עַל גַּב דְּמַלְכוּ הֲוָה דִיהוּדָה, רְאוּבֵן סָמוּךְ לְקֳבְלֵיהּ הֲוָה.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, זְמִינִין אִינוּן בְּנֵי רְאוּבֵן, לַאֲגָחָא תְּרֵין קְרָבִין בְּגוֹ אַרְעָא. תָּא חֲזֵי, כְּתִיב כֹּחִי, בְּגָלוּתָא דְמִצְרַיִם. וְרֵאשִׁית אוֹנִי, דְּאִינוּן הֲווּ קַדְמָאִין לְגַבֵּי אֲחוּהוֹן לִקְרָבָא. יֶתֶר שְׂאֵת, לְגָלוּתָא דְאַשּׁוּר, דְּמִתַּמָּן גָלוּ בְּנֵי גָד וּבְנֵי רְאוּבֵן קַדְמָאי מִכֻּלְּהוּ, וְסָבְלֵי כַּמָּה בִּישִׁין, וְכַמָּה עִנּוּיִין סָבְלוּ, וְלָא תָבוּ עַד כְּעָן.</p>\n<p>וְיֶתֶר עָז, לְזִמְנָא דְמַלְכָּא מְשִׁיחָא יִתְעַר בְּעַלְמָא, אִינוּן יִפְקוּן וְיִגְחוּן קְרָבִין בְּעַלְמָא, וִינַצְחוּן, וְיִתַּקְפוּן עַל עַמְמַיָא. וּבְנֵי עַלְמָא יִדְחֲלוּן מִנַּיְיהוּ וְיִרְתְּתוּן קַמַּיְיהוּ, <Nonei></i>וְיַחְשִׁיבוּ לְאִתְגַּבְּרָא בְּמַלְכוּתָא, וְלָא יִשְׁתָּאֲרוּן בֵּיהּ. הֲדָא הוּא דִכְתִיב פַּחַז כַּמַּיִם אַל תּוֹתַר, מַאי טַעְמָא לָא יִשְׁתָּאֲרוּן בֵּיהּ, וְאֲפִילּוּ בְּסִטְרָא חַד דְּעַלְמָא, בְּגִין כִּי עָלִיתָ מִשְׁכְּבֵי אָבִיךָ. דִּזְמִינִין לְאֲעָלָא וּלְאַגָּחָא קְרָבִין בְּגוֹ אַרְעָא קַדִּישָׁא, מִשְׁכְּבֵי אָבִיךָ דַּיְיקָא, זוֹ יְרוּשָׁלֵם.</p>\n<p>תָּא חֲזֵי, בְּאַרְבַּע סִטְרֵי עַלְמָא, אִתְבַּדְּרוּ בְּנֵי רְאוּבֵן בְּגָלוּתָא, לְקִבְלֵיהוֹן דְּכָל יִשְׂרָאֵל, דְּאִתְגָּלוּ בְּגָלוּתָא אַרְבַּע זִמְנִין בְּאַרְבַּע סִטְרֵי עַלְמָא. הֲדָא הוּא דִכְתִיב, כֹּחִי חַד, וְרֵאשִׁית אוֹנִי תְּרֵי, יֶתֶר שְׂאֵת תְּלַת, וְיֶתֶר עָז אַרְבָּעָה. כְּגַוְונָא דָא זְמִינִין אִינוּן לַאֲגָחָא קְרָבָא בְּאַרְבַּע סִטְרֵי עַלְמָא, וּלְמִשְׁלַט בְּקִרְבַּיְיהוּ עַל כֹּלָּא, וִינַצְחוּן עֲמָמִין סַגִּיאִין, וְיִשְׁלְטוּן עֲלַיְיהוּ:</p>\n<p>פַּחַז כַּמַּיִם אַל תּוֹתַר כִּי עָלִיתָ מִשְׁכְּבֵי אָבִיךָ, הָכָא אִתְרְמִיז עַל הִרְהוּרָא קַדְמָאָה דְּהֲוָה לֵיהּ לְיַעֲקֹב. בְּהַאי טִפָּה קַדְמָאָה בְּרָחֵל, דְּאִלְמָלֵא הִרְהוּרָא דְהַהִיא טִפָּה הֲוָה בְּאַתְרָהּ, אִשְׁתָּאַר רְאוּבֵן בְּכֹלָּא. אֲבָל פַּחַז כַּמַּיִם אַל תּוֹתַר כִּי עָלִיתָ מִשְׁכְּבֵי אָבִיךָ, עָלִיתָ, בְּהִרְהוּרָא אָחֳרָא, אָז חִלַּלְתָּ וְגו'.</p>\n<p>דָּבָר אַחֵר, פַּחַז כַּמַּיִם אַל תּוֹתַר, דְּהָא כַּד יִגְחוּן קְרָבָא בְּנִי רְאוּבֵן בְּעַלְמָא, וִינַצְחוּן עֲמָמִין סַגִּיאִין, לָא יִשְׁתָּאֲרוּן בְּמַלְכוּתָא, מַאי טַעְמָא, כִּי עָלִיתָ מִשְׁכְּבֵי, דִּזְמִינִין לַאֲגָחָא קְרָבָא בְּאַרְעָא קַדִּישָׁא דַיְיקָא, דִּכְתִיב כִּי עָלִיתָ מִשְׁכְּבֵי אָבִיךָ (ס\"א דא ירושלים. משכבי), מִשְׁכַּב מִבָּעֵי לֵיהּ. אֶלָּא, אָבִיךָ דָּא יִשְׂרָאֵל סָבָא, מִשְׁכְּבֵי אָבִיךָ וְלָא מִשְׁכַּב, בְּגִין דְּהָא בִּתְרֵי זִמְנֵי אִתְבְּנֵי יְרוּשָׁלַ ם, וּתְלִיתָאָה לְזִמְנָא דְמַלְכָּא מְשִׁיחָא. וְעַל דָּא מִשְׁכְּבֵי אָבִיךָ. וְהָכָא אִתְגַּלְּיָיא בְּרָכָה, וּמַאי דְּהֲוָה בְּהַהוּא זִמְנָא, וּמַאי דְּהֲוָה כַּד עָאלוּ יִשְׂרָאֵל לְאַרְעָא, וּמַה דִּיְהֵא בְּזִמְנָא דְמַלְכָּא מְשִׁיחָא בְּעוֹבָדָא דִרְאוּבֵן:</p>"],[9520011479,"<p>שִׁמְעוֹן וְלֵוִי אַחִים, אָמַר רִבִּי יִצְחָק, הָכָא אָחִיד לוֹן בְּסִטְרָא שְׂמָאלָא דִּשְׁכִינְתָּא. דְּחָמָא עוֹבָדִין דְּדִינָא קַשְׁיָא, דְּלָא יָכִיל עַלְמָא לְמִסְבַּל. אָמַר רִבִּי יוֹסֵי, בִּרְכְתָא דִּלְהוֹן אָן הִיא. אָמַר רִבִּי יִצְחָק, שִׁמְעוֹן לָא אִתְחֲזֵי לְהַאי, דְּחָמָא לֵיהּ כַּמָּה עוֹבָדִין בִּישִׁין. וְלֵוִי דְּאָתֵי מִסִּטְרָא דְּדִינָא קַשְׁיָא, וּבִרְכְתָא לָא תַלְיָא בֵּיהּ. וְאֲפִילּוּ כַּד אֲתָא משֶׁה, לָא תָּלֵי בִּרְכָתֵיהּ בֵּיהּ. דִּכְתִיב, (דברים ל״ג:י״א) בָּרֵךְ ה' חֵילוֹ וּפוֹעַל יָדָיו תִּרְצֶה, בְּקוּדְשָׁא בְּרִיךְ הוּא תַּלְיָיא.</p>\n<p>תָּא חֲזֵי, כְּתִיב, (תהילים ק״ד:כ״ה) זֶה הַיָּם גָּדוֹל וּרְחַב יָדַיִם שָׁם רְמֶשׂ וְאֵין מִסְפָּר חַיּוֹת קְטַנּוֹת עִם גְּדוֹלוֹת. זֶה הַיָּם גָּדוֹל, דָּא שְׁכִינְתָּא דְּקָיְימָא עֲלֵיהּ דְּיַעֲקֹב כַּד בָּעָא לְאִסְתַּלְּקָא מֵעַלְמָא. וּרְחַב יָדַיִם, דְּהָא כָּל עַלְמָא אִמְלֵי וְאִשְׁתְּלִים וְאִתְצַמְצֵם תַּמָּן. שָׁם רֶמֶשׂ וְאֵין מִסְפָּר, דְּכַמָּה מַלְאֲכֵי עִלָּאֵי וְקַדִּישָׁאֵי אִשְׁתַּכְּחוּ תַּמָּן. חַיּוֹת קְטַנּוֹת עִם גְּדוֹלוֹת, אִלֵּין אִינוּן י\"ב שְׁבָטִין, בְּנוֹי דְּיַעֲקֹב, דְּאִשְׁתַּכָּחוּ בְּהוֹן בִּשְׁלִימוּ. חַד אַיָּלָה, וְחַד זְאֵב, וְחַד אֲרִי, וְחַד טָלֶה. אָמַר רִבִּי יִצְחָק, אַרְיֵה חַד, וְטָלֶה חַד, חַד זְאֵב, וְחַד גְּדִי, וְכֵן כֻּלְּהוּ, לְאִשְׁתַּכְּחָא חַיּוֹת קְטַנּוֹת עִם גְּדוֹלוֹת.</p>\n<p>רִבִּי יְהוּדָה אָמַר, כֻּלְּהוּ שַׁפִּיר. אֲבָל יְהוּדָה אַרְיֵה, שִׁמְעוֹן שׁוֹר, וְהָא אוּקְמוּהָ חַבְרַיָיא דְּהֲווּ מַשְׁגִּיחִין דָא לָקֳבֵל דָּא, דָּא מִימִינָא, וְדָא מִשְׂמָאלָא. לְתוֹרָא דְּעוֹבָדוֹי בִּישִׁין, אָמְרוּ נְצַיֵּיר אִקּוּנִין דְּאַרְיֵה בְּקוֹפְטֵיהּ, וְיִסְתַּכֵּל בְּדָא וְיִדְחַל מִנֵּיהּ, כָּךְ שִׁמְעוֹן שׁוֹר, יְהוּדָה אַרְיֵה.</p>\n<p>שִׁמְעוֹן לָא זָכָה לְבִרְכָאן, אֶלָּא טָפַל לֵיהּ משֶׁה בִּיהוּדָה. כְּתִיב הָכָא (דברים ל״ג:ז׳) שְׁמַע ה' קוֹל יְהוּדָה, וּכְתִיב הָתָם (בראשית כ״ט:ל״ג) כִּי שָׁמַע ה' כִּי שְׂנוּאָה אָנֹכִי. אָמַר רִבִּי יְהוּדָה, שִׁמְעוֹן וְלֵוִי, אֲבוּהוֹן סָלִיק לוֹן לְמשֶׁה. אָמַר לֵיהּ רִבִּי יוֹסֵי, מַאי טַעְמָא אֲבוּהוֹן סָלִיק לוֹן לְמשֶׁה. אָמַר לֵיהּ, אַף אֲנַן נַסְלִיק לֵיהּ לְבוּצִינָא קַדִּישָׁא עִלָּאָה.</p>\n<p>אָתוּ שָׁאֲלוּ לֵיהּ לְרִבִּי שִׁמְעוֹן. אָמַר, כַּמָּה חֲבִיבִין מִלִּין. אַטְפַח בִּידוֹי וּבָכָה, אָמַר מַאן יְגַלֵּי לָךְ מְהֵימְנָא קַדִּישָׁא, אִסְתַּלַּקְתְּ בְּחַיָּיךְ עַל בְּנֵי נָשָׁא, אִסְתַּלַּקְתְּ בְּמוֹתָךְ, וְאַסְתִּים דְּיוּקְנָךְ. מַפְּתְּחָן דְמָארַךְ אִתְמַסְרוּ בִּידָךְ תָּדִיר.</p>\n<p>תָּא חֲזֵי, יַעֲקֹב הֲוָה לֵיהּ אַרְבַּע נָשִׁין, וְאוֹלִיד בְּנִין מִכֻּלְּהוּ, <Nonei></i>וְאִסְתַּלִּיק (נ\"א ואשתלים) בִּנְשׁוֹי. כַּד בָּעָא יַעֲקֹב לְאִסְתַּלָּקָא, שְׁכִינְתָּא קָיְימֵי עֲלוֹי, בָּעָא לִבְרוּכֵי לְאִלֵּין, וְלָא יָכִיל, מִקַּמֵּי שְׁכִינְתָּא דְּדָחִיל. אָמַר, הֵיךְ אַעֲבִיד, דְּהָא תַּרְוַויְיהוּ מִסִּטְרָא דְּדִינָא קַשְׁיָא קָא אַתְיָין. אִי אַתְקִיף בִּשְׁכִינְתָּא לָא יָכִילְנָא, דְּהָא אַרְבַּע נָשִׁין הֲווּ לִי, וְאִשְׁתַּלִּימְנָא בְּהוֹן. אֶלָּא אֲסַלֵּק לוֹן לְמָארֵי דְבֵיתָא, דְּהָא (ביה) בֵּיתָא בִּרְעוּתֵיהּ קָיְימָא, וּמַה דְּבָעֵי יַעֲבִיד.</p>\n<p>כָּךָ יַעֲקֹב אָמַר, חוּלָקִין דִּנְשִׁין וּבְנִין הָא נָסְבִית בְּהַאי עַלְמָא, וְאִשְׁתַּלַּמְּנָא, הֵיךְ אַתְקִיף בְּמַטְרוֹנִיתָא יַתִּיר, אֶלָּא אֲסַלֵּק מִלִּין לְמָארֵי מַטְרוֹנִיתָא, וְהוּא יַעֲבִיד מַה דְּבָעֵי, וְלָא יִדְחַל.</p>\n<p>תָּא חֲזֵי, מַה כְּתִיב, (דברים ל״ג:א׳) וְזֹאת הַבְּרָכָה אֲשֶׁר בֵּרַךְ משֶׁה אִישׁ הָאֱלהִים, מָארֵיהּ דְּבֵיתָא, מָארֵיהּ דְּמַטְרוֹנִיתָא. כְּמָה דִכְתִיב, (במדבר ל׳:י״ד) אִישָׁהּ יְקִימֶנּוּ וְאִישָׁהּ יְפֵרֶנּוּ. דְּהָא (במדבר ז׳:א׳) כַּלֹּת משֶׁה כְּתִיב. וְעַל דָּא, משֶׁה בָּרִיךְ מַאן דְּבָעָא וְלָא דָחִיל, כִּדְאוֹקִימְנָא. וּבְגִין כָּךְ אָמַר יַעֲקֹב, הָא חָמֵינָן דְּבָנַי אִלֵּין בְּסִטְרָא דְּדִינָא קַשְׁיָא, (ליתיה) יֵיתֵי מָארִיהּ דְּבֵיתָא וִיבָרֵךְ לוֹן.</p>\n<p>משֶׁה וַדַּאי אִישׁ הָאֱלהִים הָיָה, וּרְעוּתֵיהּ עָבִיד בְּבֵיתֵיהּ, כְּמָא דְאַתְּ אָמֵר אִישָׁהּ יְקִימֶנּוּ. הֲדָא הוּא דִכְתִיב, (במדבר י׳:ל״ה) וַיֹּאמֶר משֶׁה קוּמָה ה'. וְאִישָׁהּ יְפֵרֶנּוּ. הֲדָא הוּא דִכְתִיב, (במדבר י׳:ל״ו) וּבְנֻחֹה יֹאמַר שׁוּבָה ה'. וַדַּאי רְעוּתֵיהּ עָבַד מָארֵיהּ דְּבֵיתָא וְלֵית דְּיִמְחֵי בִידֵּיהּ. כְּבַר נָשׁ דְּגָזַר עַל אִנְתְּתֵיהּ, וְעָבְדָא רְעוּתֵיהּ. וְעַל דָּא יַעֲקֹב אַף עַל גַּב דְּהֲוָה אָחִיד בְּאִילָנָא דְחַיֵּי, לָא הֲוָה מָארֵי דְבֵיתָא, אֶלָּא לְתַתָּא, משֶׁה הוּא לְעֵילָא, בְּגִין כָּךְ סָלִיק לוֹן לְמָארֵיהּ דְּבֵיתָא:</p>\n<p>בְּסוֹדָם אַל תָּבֹא נַפְשִׁי וְגו', רִבִּי אַבָּא פָּתַח וְאָמַר, (תהילים כ״ה:י״ד) סוֹד יְיָ לִירֵאָיו וְגו'. סוֹד יְיָ לִירֵאָיו, רָזָא עִלָּאָה דְאוֹרַיְיתָא, לָא יָהִיב קוּדְשָׁא בְּרִיךְ הוּא אֶלָּא לְאִינוּן דַּחֲלֲי חַטָּאָה. וּמַאן דְּאִינוּן דַּחֲלֵי חַטָּאָה, אִתְגְּלִי לוֹן רָזָא עִלָּאָה דְאוֹרַיְיתָא. וּמַאן אִיהוּ רָזָא עִלָּאָה דְאוֹרַיְיתָא, הֱוֵי אֵימָא דָּא אָת קַיָּימָא קַדִּישָׁא, דְּאִקְרֵי סוֹד יְיָ בְּרִית קֹדֶשׁ.</p>\n<p>שִׁמְעוֹן וְלֵוִי, אַטְרְחוּ גַרְמַיְיהוּ עַל הַאי סוֹד, בְּאַנְשֵׁי שְׁכֶם, דְּיִגְזְרוּן גַּרְמַיְיהוּ וִיקַבְּלוֹי עֲלוֹן הַאי סוֹד. וּקְרָא אַסְהִיד, בְּמִרְמָה. תוּ בְּעוֹבָדָא דְּזִמְרִי בֶּן סָלוּא, דְּפָסַל הַאי סוֹד. וְיַעֲקֹב אָמַר בְּסוֹדָם אַל תָּבֹא נַפְשִׁי. מַאי נַפְשִׁי. דָּא נַפְשָׁא דְּעָאֳלַת וְאִתְאַחֲדַת בִּבְרִית עִלָּאָה לְעֵילָא, וְאִקְרֵי נֶפֶשׁ צְרוֹרָא דְחַיֵּי.</p>\n<p>בִּקְהָלָם אַל תֵּחַד כְּבוֹדִי. הָא אוּקְמוּהָ, כְּמָא דְאַתְּ אָמֵר, (במדבר ט״ז:י״ט) וַיַּקְהֵל עֲלֵיהֶם קֹרַח. אַל תֵּחַד כְּבוֹדִי, דָּא כְּבוֹד יִשְׂרָאֵל סְתָם. וְעַל דָּא לָא בָּרִיךְ לוֹן אֲבוּהוֹן, בְּגִין דְּסָלִיק לוֹן לְמשֶׁה. רִבִּי חִיָּיא אָמַר, מֵהַנֵּי קְרָאֵי (חסר) (ובגיני כך) (ס\"א משמע) דְּלָא אִתְאֲחִיד דָּא בְּדָא, וְאִצְטְרִיךְ הָכִי. וְעַל דָּא אִית בֵּיהּ כֹּלָּא, וְלֵית לָךְ דָּרָא בְּעַלְמָא, דְּלָא נָחֲתָא דִּינָא דִּלְּהוֹן לְקַטְרְגָא בְּעַלְמָא וְאַסְגִּיאוּ מְהַדְּרֵי עַל פְּתָחַיְיהוּ דִבְנֵי נָשָׁא, הֵא לָךְ כֹּלָּא. (ס\"א הא לקבל הא):</p>"],[9520011480,"<p>יְהוּדָה אַתָּה יוֹדוּךָ אַחֶיךָ יָדְךָ בְּעֹרֶף אוֹיְבֶיךָ וְגו'. רִבִּי יוֹסֵי פָּתַח, (תהילים ק״ד:י״ט) עָשָׂה יָרֵחַ לְמוֹעֲדִים וְגו'. עָשָׂה יָרֵחַ בְּגִין לְקַדְּשָׁא בֵּיהּ רֵישׁ יַרְחִין, וְרֵישׁ שַׁתִּין. וּלְעָלְמִין סִיהֲרָא לָא נָהִיר אֶלָּא מִשִּׁמְשָׁא, וְכַד שִׁמְשָׁא שַׁלִּיט, סִיהֲרָא לָא שָׁלְטָא. כַּד אִתְכְּנִישׁ שִׁמְשָׁא, כְּדֵין סִיהֲרָא שָׁלְטָא, וְלֵית חוּשְׁבַּן לְסִיהֲרָא אֶלָּא כַּד אִתְכְּנִישׁ שִׁמְשָׁא.</p>\n<p>וְתַרְוַויְיהוּ עֲבַד קוּדְשָׁא בְּרִיךְ הוּא לְאַנְהָרָא. הֲדָא הוּא דִכְתִיב, (בראשית א׳:י״ז) וַיִּתֵּן אֹתָם אֱלהִים בִּרְקִיעַ הַשָּׁמָיִם לְהָאִיר עַל הָאָרֶץ וְגו'. וְהָיוּ לְאוֹתוֹת, אִלֵּין שַׁבָּתוֹת, דִּכְתִיב, (שמות ל״א:י״ג) כִּי אוֹת הִיא. וּלְמוֹעֲדִים, אִינוּן יוֹמִין טָבִין. וּלְיָמִים, אִלֵּין רֵישֵׁי יַרְחִין. וּלְשָׁנִים, אִלֵּין רִישֵׁי שְׁנִין. דְּלֶהווֹן אוּמּוֹת הָעוֹלָם עָבְדִין חֻשְׁבַּן לְשִׁמְשָׁא, וְיִשְׂרָאֵל לְסִיהֲרָא.</p>\n<p>וְאָזְלָא הָא, כִּי הָא דְּאָמַר רִבִּי אֶלְעָזָר, כְּתִיב, (ישעיהו ט׳:ב׳) הִרְבִּיתָ הַגּוֹי לוֹ הִגְדַּלְתָּ הַשִּׂמְחָה. הִרְבִּיתָ הַגּוֹי, אִלֵּין יִשְׂרָאֵל, דִּכְתִיב בְּהוּ (דברים ד׳:ז׳) כִּי מִי גּוֹי גָדוֹל. וּכְתִיב, (דברי הימים א י״ז:כ״א) גּוֹי אֶחָד בָּאָרֶץ. לוֹ, בְּגִינֵיהּ. הִגְדַּלְתָּ הַשִּׂמְחָה (ממש), דָּא סִיהֲרָא, דְּאִתְרְבִיאַת בִּנְהוֹרָא בְּגִינֵיהוֹן דְּיִשְׂרָאֵל. אוּמּוֹת הָעוֹלָם לְשִׁמְשָׁא, וְיִשְׂרָאֵל לְסִיהֲרָא, הֵי מִנַּיְיהוּ עָדִיף. וַדַּאי סִיהֲרָא <Nonei></i>לְעֵילָא, וְשִׁמְשָׁא דְּאוּמּוֹת הָעוֹלָם, תְּחוֹת הַאי סִיהֲרָא הוּא, וְהַהוּא שִׁמְשָׁא מֵהַאי (ס\"א סטרא) סִיהֲרָא נָהִיר. חָמֵי מַה בֵּין יִשְׂרָאֵל, לְהוּ. יִשְׂרָאֵל אֲחִידוּ בְּסִיהֲרָא, וְאִשְׁתַּלְּשְׁלוּ בְּשִׁמְשָׁא עִלָּאָה, וְאִתְאַחֲדוּ בְּאֲתַר (ביה) (ס\"א דנהיר לשמשא) דִּנְהִירָא מְשַׁמְּשָׁא עִלָּאָה, וּמִתְדַּבְּקָן בֵּיהּ, דִּכְתִיב, (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ אֱלהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם.</p>"],[9520011481,"<p>יְהוּדָה אַתָּה וְגו'. רִבִּי שִׁמְעוֹן אָמַר, מַלְכוּ לִיהוּדָה אִתְקְיַּים, וְהַיְינוּ דְּאַמְרִינָן, מַאי דִכְתִיב, (בראשית כ״ט:ל״ה) הַפַּעַם אוֹדֶה אֶת ה', בְּגִין דְּאִיהוּ רְבִיעָאָה, אוֹדֶה אֶת ה', בְּגִין דְּאִיהוּ רַגְלָא רְבִיעָאָה לְכָרְסְיָא. יה\"ו, דָּא רְשִׁימָא דִשְׁמָא עִלָּאָה, וּבְמָּה אִשְׁתְּלִים, בְּה\"א (ס\"א בדל\"ת), וְהַיְינוּ ה\"א בַּתְרָאָה דִּשְׁמָא קַדִּישָׁא. שְׁמָא קַדִּישָׁא שְׁלִים בְּאַתְווֹי, וְקֶשֶׁר דְּאָחִיד לוֹן, עַל דָּא יוֹדוּךָ אַחֶיךָ, דְּמַלְכוּ לָךְ אִתְחַזְיָא לְאִתְקָיְימָא וַדַאי. (הושע י״ב:א׳) וִיהוּדָה עֹד רָד עִם אֵל וְעִם קְדוֹשִׁים נְאֱמָן, מַאן קְדוֹשִׁים, אִלֵּין קְדוֹשִׁים עֶלְיוֹנִין, דְּכֻלְּהוּ אוֹדָן לְגַבֵּיהּ, וְשַׁוְיוּהָ נֶאֱמָן, בְּגִין כָּךְ הוּא קַדְמָאָה בְּכוֹלָא, הוּא מַלְכָּא עַל כֹּלָּא.</p>\n<p>רִבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (תהילים מ״ה:י״ד) כָּל כְּבוּדָהּ בַּת מֶלֶךְ פְּנִימָה. כָּל כְּבוּדָהּ, דָּא כְּנֶסֶת יִשְׂרָאֵל, כְּבוּדָהּ, בְּגִין דְּאִיהוּ כָּבוֹד, דָּא עַל דָּא, דָּא דָּכָר, וְדָא נוּקְבָא (ס\"א דא נוקבא), וְאִתְקְרֵי כְּבוּדָהּ. בַּת מֶלֶךְ, הַיְינוּ בַּת שֶׁבַע, בַּת קוֹל דְּאִיהוּ קוֹל גָּדוֹל, וְהַאי מֶלֶךְ עִלָּאָה הוּא. פְּנִימָה, בְּגִין דְּאִית מֶלֶךְ דְּלָאו אִיהוּ לְגוֹ כַּוָּותֵיהּ, וְהַאי כְּבוּדָהּ בַּת מֶלֶךְ.</p>\n<p>מִמִּשְׁבְּצוֹת זָהָב לְבוּשָׁהּ, בְּגִין דְּאִתְלַבְּשַׁת וְאִתְאַחֲדַת בִּגְבוּרָתָא עִלָּאָה, וְהַאי, אוּף נָמֵי מֶלֶךְ אִקְרֵי, וּבְגִינָהּ קָיְימָא אַרְעָא. אֵימָתַי, בְּשַׁעְתָּא דְּאִתְאַחֲדַת בְּמִשְׁפָּט. כְּמָא דְאַתְּ אָמֵר, (משלי כ״ט:ד׳) מֶלֶךְ בַּמִּשְׁפָּט יַעֲמִיד אָרֶץ. וְדָא קָרֵינָן מַלְכוּ דִשְׁמַיָא, וִיהוּדָה אִתְאֲחִיד בָּהּ, וְיָרִית מַלְכוּתָא דִבְאַרְעָא.</p>\n<p>רִבִּי (אבא) יְהוּדָה וְרִבִּי יִצְחָק הֲווּ קָאָזְלֵי בְּאָרְחָא. אָמַר רִבִּי יִצְחָק, נִפְתַּח בְּמִלֵּי דְאוֹרַיְיתָא וְנִיזִיל. פָּתַח רִבִּי יִצְחָק וְאָמַר, (בראשית ג׳:כ״ד) וַיְגָרֶשׁ אֶת הָאָדָם וַיַּשְׁכֵּן מִקֶּדֶם לְגַּן עֵדֶן וְגו'. הַאי קְרָא אוּקְמוּהָ חַבְרַיָיא. אֲבָל וַיְגָרֶשׁ, כְּבַּר נָשׁ דְּגָרִישׁ לְאִנְתְּתֵיהּ, אֶת הָאָדָם דַּיְיקָא.</p>\n<p>תָּא חֲזֵי, רָזָא דְמִלָּה, אָדָם בְּמָּה דְחָטָא אִתְּפַס, וְגָרִים מוֹתָא לֵיהּ וּלְכָל עַלְמָא, וְגָרִים לְהַהוּא אִילָנָא דְּחָטָא בֵּיהּ תֵּירוּכִין, לְאִתָּרְכָא בֵּיהּ, וּלְאִתְתָּרְכָא בִּבְנוֹי לְעָלְמִין. הֲדָא הוּא דִכְתִיב, וַיְגָרֶשׁ אֶת הָאָדָם, אֶת דַּיְיקָא, כְּמָה דִּכְתִיב, (ישעיה ז) וָאֶרְאֶה אֶת ה'. אוּף הָכִי אֶת הָאָדָם.</p>\n<p>וַיַּשְׁכֵּן מִקֶּדֶם לְגַּן עֵדֶן וְגו', הַאי לְתַתָּא. וּכְמָה דִכְרוּבִים לְעֵילָא, אִית כְּרוּבִים לְתַתָּא, וְהַאי אִילָנָא אַשְׁרֵי עֲלַיְיהוּ. וְאֶת לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת, אִינוּן טָפְסֵי דְּשַׁלְּהוֹבֵי דְּאֶשָּׁא, מֵהַהוּא חַרְבָּא דְמִתְלַהֲטָא. הַמִּתְהַפֶּכֶת, דָּא הַאי חַרְבָּא, דְּיָנְקָא בִּתְרֵין סִטְרִין, וְאִתְהַפְּכָא מִסִּטְרָא דָא לְסִטְרָא אָחֳרָא. דָּבָר אַחֵר הַמִּתְהַפֶּכֶת, דָּא לַהַט אִינוּן טָפְסֵי דְּשַׁלְּהוֹבָא (ס\"א דמלכותא) דְּקָאֲמָרָן, דְּמִתְהַפְּכָן לְזִמְנִין גּוּבְרִין וּלְזִמְנִין נָשִׁין, וּמִתְהַפְּכָן מִדּוּכְתַּיְיהוּ לְכֹלָּא. וְכָל דָּא, לִשְׁמוֹר אֶת דֶּרֶךְ עֵץ הַחַיִּים. מַאן דֶּרֶךְ, כְּמָא דְאַתְּ אָמֵר, (ישעיהו מ״ג:ט״ז) הַנּוֹתֵן בַּיָּם דָּרֶךְ.</p>\n<p>אָמַר רִבִּי יְהוּדָה שַׁפִּיר, וְהָכִי הוּא וַדַּאי, דְּגָרִים אָדָם לְהַהוּא אִילָנָא דְּחָטָא בֵּיהּ לְאִתָּרְכָא, וְאֲפִילּוּ שְׁאָר בְּנֵי עַלְמָא נָמֵי, כְּמָא דְאַתְּ אָמֵר, (ישעיה ב) וּבְפִשְׁעֵיכֶם שֻׁלְּחָה אִמְּכֶם, אֲבָל שַׁפִּיר קָאֲמַרְתְּ, דְּהָא מִדּוּכְתֵּיהּ מַשְׁמַע, דִּכְתִיב וַיְגָרֶשׁ אֶת הָאָדָם, בְּגִין דְּדָא שְׁלִימוּ דְּאָדָם הוּא.</p>\n<p>וּמֵהַהוּא יוֹמָא אִתְפְּגִים סִיהֲרָא, עַד דְּאָתָא נֹחַ וְעָאל בְּתִּיוּבְתָּא (נ\"א בתיבותא). אָתוּ חַיָּיבַיָא וְאִתְפְּגִים. עַד דְּאָתָא אַבְרָהָם (ואתקיימו), וְקָיְימָא בִּשְׁלִימוּ דְיַעֲקֹב וּבְנוֹי. וְאָתָא יְהוּדָה וְאָחִיד בֵּיהּ, וְאִתְקַף בְּמַלְכוּתָא, וְאַחְסִין לֵיהּ אַחְסָנַת עָלְמִין, הוּא וְכָל בְּנוֹי בַּתְרוֹי, הֲדָא הוּא דִכְתִיב, יְהוּדָה אַתָּה יוֹדוּךָ אַחֶיךָ. (ס\"א בגין דדיליה מלכותא עלייהו, כמא דאת אמרז, (דברי הימים א ה׳:ב׳) כי יהודה גבר באחיו, יודוך אחיך) וַדַּאי בְּשַׁעְתָּא דְּקָיְימוּ יִשְׂרָאֵל עַל יַמָּא, דְּכֻלְּהוּ אוֹדוּ לֵיהּ, וְנָחֲתוּ אֲבַתְרֵיהּ בְּיַמָּא.</p>\n<p>יָדְךָ בְּעֹרֶף אוֹיְבֶיךָ, כְּמָא דְאַתְּ אָמֵר, (שופטים א׳:ב׳) יְהוּדָה יַעֲלֶה (בתחילה). יִשְׁתַּחֲוּ לְךָ בְּנֵי אָבִיךָ, כְּלָלָא דְּכָל אִינוּן שְׁאָר שִׁבְטִין, בְּגִין דָּא בְּנִי אָבִיךָ, וְלָא בְּנֵי אִמֶּךָ. בְּנֵי אָבִיךָ, הָא כֻּלְּהוּ שְׁאָר שִׁבְטִין, דְּאַף עַל גַּב (בספרים ישנים דאינון אתפליגו) דְּאִתְפְּלִיג לִתְרֵין מַלְכְּוָון, כַּד הֲווּ סָלְקִין לִיְרוּשָׁלַ ם, הֲווּ סְגִידִין וְכָרְעָן לְמַלְכָּא דְּבִיְרוּשָׁלַ ם, בְּגִין דְּמַלְכוּתָא דִּיְרוּשָׁלַ ם, <Nonei></i>מִמַּלְכוּתָא קַדִּישָׁא (שלטא) מִנֵּיהּ הֲוָה.</p>\n<p>יִשְׁתַּחֲווּ לְךָ, וְלָא כְּתִיב וְיִשְׁתַּחֲווּ, דְּאִי כְּתִיב וְיִשְׁתַּחֲווּ, לְאוֹסָפָא לִשְׁאָר עַמִּין. וְיִשְׁתַּחֲווּ לָא כְּתִיב, אֶלָּא בְּזִמְנָא דְּיֵיתֵי מַלְכָּא מְשִׁיחָא, דִּכְתִיב, (ישעיהו מ״ט:ז׳) שָׂרִים וְיִשְׁתַּחֲווּ, הַשְׁתָּא דְּאָמַר יִשְׁתַּחֲווּ, לְאַחֲזָאָה דְּיִשְׂרָאֵל כֻּלְּהוּ בִּלְחוֹדַיְיהוּ, כֻּלְּהוּ יִפְלְחוּן לְרֵישָׁא דְגוֹלָה, לְרֹאשׁ דְּבָבֶל, וְלָא שְׁאָר עַמִּין:</p>\n<p>גּוּר אַרְיֵה יְהוּדָה, בְּקַדְמִיתָא גּוּר, וּלְבָתַר אַרְיֵה, וְרָזָא דְמִלָּה בְּקַדְמִיתָא נַעַר, וּלְבָתַר אִישׁ, (שמות ט״ו:ג׳) יְיָ אִישׁ מִלְחָמָה. מִטֶּרֶף בְּנִי עָלִיתָ, מַאי מִטֶּרֶף. לְאַכְלָלָא מַלְאַךְ הַמָּוְת, דְּאִיהוּ קָיְימָא עַל טֶרֶף, לְשֵׁיצָאָה בְּנֵי עַלְמָא, וְלָא מְשֵׁזִּיב. כְּמָא דְאַתְּ אָמֵר, (מיכה ה׳:ז׳) וְטָרַף וְאֵין מַצִּיל. (ומהו) וּמֵהַהוּא טֶרֶף אִסְתַּלְּקַת שְׁכִינְתָּא.</p>\n<p>כָּרַע, בְּגָלוּתָא דְבָבֶל. רָבַץ, בְּגָלוּתָא דֶאֱדוֹם. כְּאַרְיֵה, דְּאִיהוּ תַּקִּיפָא. וּכְלָבִיא, דְּאִיהוּ תַּקִּיפָא יַתִּיר. כָּךְ יִשְׂרָאֵל תַּקִּיפִין אִינוּן. דִּבְנֵי עַלְמָא עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת מְפַתִּין וְדָחֲקִין לוֹן, וְאִינוּן קָיְימֵי בְּדָתֵיהוֹן וּבְנִימוּסֵיהוֹן כְּאַרְיֵה וּכְלָבִיא.</p>\n<p>כָּךְ שְׁכִינְתָּא, דְּאַף עַל גַּב דִּכְתִיב, (עמוס ה׳:ב׳) נָפְלָה לֹא תוֹסִיף קוּם בְּתוּלַת יִשְׂרָאֵל, הִיא תַּקִּיפָא כְּאַרְיֵה וּכְלָבִיא בְּהַאי נְפִילָה. מַה אַרְיֵה וְלָבִיא לָא נָפְלִין, אֶלָּא בְּגִין לְמִטְרַף טַרְפָּא וּלְשַׁלְּטָאָה, דְּהָא מֵרָחִיק אָרַח טַרְפֵּיהּ, וּמִשַׁעְתָּא דְּאָרַח נָפַל, וְלָא קָם עַד דְּדָלִיג עַל טַרְפֵּיהּ וְאָכִיל לָהּ. כָּךְ שְׁכִינְתָּא לָא נָפְלָה אֶלָּא כְּאַרְיֵה וּכְלָבִיא, בְּגִין לְנַקְמָא מֵעַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, וּלְדַלְּגָא עֲלַיְיהוּ. כְּמָא דְאַתְּ אָמֵר, (ישעיה סג) צוֹעֶה בְּרוֹב כֹּחוֹ.</p>\n<p>מִי יְקִימֶנּוּ, הוּא לָא יָקוּם לְנַקְמָא מִנַּיְיהוּ נוּקְמָא זְעֵירָא, אֶלָּא מִי יְקִימֶנּוּ. מִי, כְּמָא דְאַתְּ אָמֵר, (מיכה ב) מִי יִרְפָּא לָךְ, וְהוּא אִיהוּ עַלְמָא עִלָּאָה, דְּבֵיהּ שָׁלְטָנוּתָא לְאִתַּקְפָא לְכֹלָּא. וּכְתִיב, (איוב ל״ח:כ״ט) מִבֶּטֶן מִי יָצָא הַקֶּרַח וְאוּקְמוּהָ:</p>\n<p>לֹא יָסוּר שֵׁבֶט מִיהוּדָה וְגו', אוּקְמוּהָ חַבְרַיָא, אֲבָל עַד כִּי יָבֹא שִׁילֹ\"ה בְּה\"א, בְּגִין דְּשְׁאַר בְּו', לְאַחֲזָאָה הָכָא רָזָא (הכא) דִשְׁמָא קַדִּישָׁא י\"ה, בְּאֲתַר אָחֳרָא שִׁילוֹ בְּלָא ה', בְּאֲתַר אָחֳרָא שִׁלֹּה בְּלָא י', וְהָכָא שִׁיל\"ה בְּיו\"ד ה\"א, רָזָא דִשְׁמָא קַדִּישָׁא עִלָּאָה, דִּשְׁכִינְתָּא תָּקוּם בִּשְׁמָא (ס\"א דא) דְּי\"ה וְאִיהוּ רָזָא דְּי' (ס\"א מ\"י), כִּדְקָאַמְרִינָן.</p>"],[9520011482,"<p>אֹסְרִי לַגֶּפֶן עִירֹה וְלַשּׂרֵקָה בְּנִי אֲתֹנוֹ וְגו'. רִבִּי חִיָּיא פָּתַח, (תהילים קכ״א:ז׳) ה' יִשְׁמָרְךָ מִכָּל רָע יִשְׁמוֹר אֶת נַפְשֶׁךָ, כֵּיוָן דְּאָמַר ה' יִשְׁמָרְךָ מִכָּל רָע, אַמַּאי יִשְׁמוֹר אֶת נַפְשֶׁךָ. אֶלָּא ה' יִשְׁמָרְךָ מִכָּל רָע, בְּהַאי עַלְמָא. יִשְׁמוֹר אֶת נַפְשְׁךָ בְּהַהוּא עַלְמָא.</p>\n<p>שְׁמִירָה דְּהַאי עַלְמָא הוּא, לְמֶהוֵי נָטִיר בַּר נָשׁ מִכַּמָּה זִינִין בִּישִׁין מְקַטְרְגִין, דְּאָזְלִין לְקַטְרְגָא בְּנִי נָשָׁא בְּעַלְמָא, וּלְאִתְדַּבְּקָא בְּהוּ. בְּהַהוּא עַלְמָא מַאי הוּא, כְּמָה דְאֲמָרָן. כַּד נָפִיק בַּר נָשׁ מֵהַאי עַלְמָא, אִי אִיהוּ זָכֵי, נִשְׁמָתָא דִילֵיהּ סָלְקָא וְאִתְעַטְּרַת בְּאַתְרֵיהּ. וְאִי לָא, כַּמָּה חֲבִילִין טְרִיקִין אִזְדַּמְּנָן, לְאִנְגְּדָא לֵיהּ לַגֵּיהִנֹּם, וּלְאִמְסְרָא לֵיהּ בִּידָא דְּדוּמָה, דְּאִתְמַסְּרָא לִמְמַנָּא עַל גֵּיהִנֹּם, וּתְלֵיסַר אֶלֶף רִבּוֹא מְמַנָּן עִמֵּיהּ, וְכֻלְּהוּ אִזְדַּמְּנָן עַל נַפְשַׁיְיהוּ דְחַיָּיבַיָא.</p>\n<p>תָּא חֲזֵי, שִׁבְעָה מָדוֹרִין אִית בֵּיה בַּגֵּיהִנָּם, וְשִׁבְעָה פִּתְחִין. וְנִשְׁמָתָא דְחַיָּיבַיָא עָאלַת, וְכַמָּה טְרִיקִין, טְהִירִין, נְטוּרֵי תַּרְעֵי, וְעֲלַיְיהוּ חַד מְמַנָּא בְּכָל תַּרְעָא וְתַרְעָא, וְנִשְׁמַתְהוֹן דְּחַיָּיבַיָא אִתְמַסְרוּן לְאִינוּן מְמַנָּן, עַל יְדָא דְּדוּמָה. כֵּיוָן דְּאִתְמַסְּרָן בִּידַיְיהוּ, סָתְמִין תַּרְעִין דְּאֶשָּׁא דִּמְלַהֲטָא.</p>\n<p>דְּהָא תַּרְעִין בָּתַר תַּרְעִין הֲווּ, תַּרְעִין כֻּלְּהוּ פְּתִיחִין וּסְתִימִין, אִינוּן דִּלְבַר פְּתִיחִין, דִּלְגוֹ סְתִימִין. וּבְכָל שַׁבָּת וְשַׁבָּת כֻּלְּהוּ פְּתִיחִין, וְנָפְקִין חַיָּיבַיָא עַד אִינוּן פִּתְחִין דִּלְבַר, וּפָגְעִין נִשְׁמָתִין אָחֳרָנִין, דְּמִתְעַכְּבִין בְּפִתְחִין דִּלְבַר. כַּד נָפַק שַׁבַּתָּא, כְּרוֹזָא קָאי בְּכָל פִּתְחָא וּפִתְחָא, וְאָמַר (תהילים ט׳:י״ח) יָשׁוּבוּ רְשָׁעִים לִשְׁאוֹלָה וְגו'. תָּא חֲזֵי, נִשְׁמָתִין דְּצַדִּיקַיָיא, קוּדְשָׁא בְּרִיךְ הוּא נָטִיר לוֹן, דְּלָא יִתְמַסְּרוּן בִּידָא דְּדוּמָה, דְּהוּא מְמַנָּא, הֲדָא הוּא דִכְתִיב, יִשְׁמָר צֵאתְךָ וּבֹאֶךָ וּכְתִיב יִשְׁמוֹר אֶת נַפְשֶׁךָ.</p>\n<p><Nonei></i>אֹסְרִי לַגֶּפֶן עִירֹה. מַאי גֶפֶן, דָּא כְּנֶסֶת יִשְׂרָאֵל, כְּמָא דְאַתְּ אָמֵר, (תהילים פ׳:ט׳) גֶּפֶן מִמִּצְרַיִם תַּסִּיעַ. וּכְתִיב, (תהילים קכ״ח:ג׳) אֶשְׁתְּךָ כְּגֶפֶן פּוֹרִיָּה, אֶשְׁתְּךָ, כְּהַאי גֶפֶן קַדִּישָׁא. אָמַר רִבִּי יוֹסֵי, הַאי גֶפֶן דִּמְבָרְכִינָן בֵּיהּ בּוֹרֵא פְּרִי הַגָּפֶן. בּוֹרֵא, הַיְינוּ דִכְתִיב, עֵץ עוֹשֶׂה פְּרִי. פְּרִי הַגֶּפֶן, דָּא עֵץ פְּרִי. עוֹשֶׂה פְּרִי, דְּכַר, עֵץ פְּרִי דָּא נוּקְבָא. בְּגִינֵי כָּךְ, בּוֹרֵא פְּרִי הַגֶּפֶן דָּא דְּכַר וְנוּקְבָא כְּחֲדָא. (ס\"א נשמתיהון דצדיקייא אינון פרי הגפן כדאמר בורא פרי הגפן).</p>\n<p>אֹסְרִי לַגֶּפֶן עִירֹה, דָּא מַלְכָּא מְשִׁיחָא, דְּזַמִּין לְשַׁלְּטָאָה עַל כָּל חֵילֵי עֲמָמַיָא, חֵילִין דִּי מְמַנָּן עַל עַמִּין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, וְאִינוּן תּוּקְפָא דִלְהוֹן לְאִתְתַּקְּפָא, וְזַמִּין מַלְכָּא מְשִׁיחָא לְאִתְגַּבְּרָא עֲלַיְיהוּ.</p>\n<p>בְּגִין דְּהַאי גֶפֶן, שַׁלִּיט עַל כָּל אִלֵּין כִּתְרִין תַּתָּאִין, דְּשָׁלְטֵי בְּהוּ עֲמָמַיָא עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, הַאי נָצַח לְעֵילָא. יִשְׂרָאֵל, דְּאִינוּן שׂרֵקָה, יְשֵׁיצוּן וִינַצְחוּן חֵילִין אָחֳרָנִין לְתַתָּא, וְעַל כֻּלְּהוּ יִתְגַּבֵּר מַלְכָּא מְשִׁיחָא. הֲדָא הוּא דִכְתִיב, (זכריה ט׳:ט׳) עָנִי וְרוֹכֵב עַל חֲמוֹר וְעַל עַיִר. עַיִר וַחֲמוֹר תְּרֵין כִּתְרִין אִינוּן, דְּשָׁלְטֵי בְּהוּ עֲמָמַיָא עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, וְאִינוּן מִסְטַר שְׂמָאלָא סִטְרָא דְחוֹל.</p>\n<p>וּמַה דְּאָמַר עָנִי, וְכִי מַלְכָּא מְשִׁיחָא עָנִי אִקְרֵי. אֶלָּא הָכִי אָמַר רִבִּי שִׁמְעוֹן, בְּגִין דְּלֵית לֵיהּ מִדִּילֵיהּ וְקָרִינָן לֵיהּ מֶלֶךְ הַמָּשִׁיחַ. דָּא הוּא סִיהֲרָא קַדִּישָׁא לְעֵילָא, דְּלֵית לָהּ נְהוֹרָא אֶלָּא מִשִּׁמְשָׁא.</p>\n<p>מַלְכָּא מְשִׁיחָא דָא, יִשְׁלוֹט בְּשָׁלְטָנֵיהּ, יִתְיַיחֵד בְּדוּכְתֵּיהּ, וּכְדֵין (זכריה ט׳:ט׳) הִנֵּה מַלְכֵּךְ יָבֹא לָךְ, סְתָם. אִי לְתַתָּא עָנִי הוּא, דְּהָא בְּסִטְרָא דְסִיהֲרָא הוּא. אִי לְעֵילָא עָנִי, אַסְפַּקְלַרְיָא דְּלָא נָהֲרָא. לֶחֶם עֹנִי. וְעִם כָּל דָּא, רוֹכֵב עַל חֲמוֹר וְעַל עַיִר, תּוּקְפָא דְּעַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, לְאִכַּפְיָיא תְּחוֹתֵיהּ, וְיִתְתַּקַּף קוּדְשָׁא בְּרִיךְ הוּא בְּדוּכְתֵּיהּ.</p>\n<p>כִּבֵּס בַּיַּיִן לְבוּשׁוֹ, כְּמָא דְאַתְּ אָמֵר, (ישעיהו ס״ג:א׳) מִי זֶה בָּא מֵאֱדוֹם חֲמוּץ בְּגָדִים מִבָּצְרָה, וּכְתִיב פּוּרָה דָרַכְתִּי לְבַדִּי וְגו'. כִּבֵּס בַּיַּיִן דָּא סְטַר גְּבוּרָה, דִּינָא קַשְׁיָא, לְמֶהוֵי עַל עֲמָמַיָא עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, וּבְדַם עֲנָבִים סוּתֹה, דָּא אִילָנָא לְתַתָּא, בֵּי דִינָא דְאִקְרֵי עֲנָבִים, וְיֵינָא אִתְמָסַר (ס\"א אסתמר) בְּדַם עֲנָבִים, בְּגִין לְאִתְלַבְּשָׁא בְּתַרְוַוְיְיהוּ, לְתַבְרָא תְּחוֹתֵיהּ כָּל שְׁאָר עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת וּמַלְכִין דְּעַלְמָא.</p>\n<p>רִבִּי יוֹסֵי פָּתַח וְאָמַר. אֹסְרִי לַגֶּפֶן עִירֹה. וּכְתִיב, (בראשית מ׳:י׳) וּבַגֶּפֶן שְׁלשָׁה שָׂרִיגִים וְהִיא כְּפוֹרַחַת עָלְתָה נִצָּהּ. תָּא חֲזֵי, כַּמָּה אֲטִימִין אִינוּן בְּנִי נָשָׁא, דְּלָא יָדְעִין וְלָא מַשְׁגִּיחִין בִּיקָרָא דְּמָארֵיהוֹן, וְלָא מִסְתַּכְּלֵי בְּמִלֵּי דְאוֹרַיְיתָא, וְלָא יָדְעֵי אָרְחַיְיהוּ בְּמָּה יִתָּפְסוּן. דִּכְתִיב, (משלי ד׳:י״ט) דֶּרֶךְ רְשָׁעִים כַּאֲפֵלָה לא יָדְעוּ בַּמֶּה יִכָּשֵׁלוּ.</p>\n<p>בְּזִמְנָא קַדְמָאָה הֲוַת נְבוּאָה שַׁרְיָא עֲלַיְיהוּ דִבְנֵי נָשָׁא, וְהֲווּ יָדְעִין וּמִסְתַּכְּלֵי לְמִנְדַע בִּיקָרָא עִלָּאָה. כֵּיוָן דְּפָסְקָא נְבוּאָה מִנַּיְיהוּ, הֲווּ מִשְׁתַּמְּשֵׁי בְּבַת קוֹל. הַשְׁתָּא פָּסְקָא נְבוּאָה וּפָסְקָא בַּת קוֹל, וְלָא מִשְׁתַּמְּשֵׁי בְּנֵי נָשָׁא אֶלָּא בְּחֶלְמָא.</p>\n<p>וְחֶלְמָא דַּרְגָּא תַּתָּאָה הוּא לְבַר, דְּהָא תָּנִינָן חֶלְמָא אֶחָד מִשִּׁשִּׁים לִנְבוּאָה. מַאי טַעְמָא, בְּגִין דְּאַתְיָיא מִדַּרְגָּא שְׁתִיתָאָה לְתַתָּא, וְהָא אִתְּמָר. תָּא חֲזֵי, חֶלְמָא לְכֹלָּא אִתְחֲזֵי, בְּגִין דְּחֶלְמָא מִסְטַר שְׂמָאלָא אַתְיָיא, וְנָחִית בְּכַמָּה דַרְגִּין, וְאִתְחֲזֵי (קצ\"ב ע\"ב) חֶלְמָא, אֲפִילּוּ לְחַיָּיבַיָא. וְאֲפִילּוּ לְעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת.</p>\n<p>בְּגִין דְּזִמְנִין נָקְטִין חֶלְמָא וְשָׁמְעִין הַנֵּי זִינֵי בִּישִׁין, וּמוֹדְעִין לִבְנֵי נָשָׁא, מִנַּיְיהוּ דְּחַיְיכָן (בהו) בִּבְנִי נָשָׁא, וּמוֹדִיעִין לוֹן מִלִּין כְּדִיבִין. וּלְזִמְנִין מִלִּין דִּקְשׁוֹט דְּשָׁמְעִין. וּלְזִמְנִין דְּאִינוּן שְׁלוּחִין לְחַיָּיבַיָא, וּמוֹדָעֵי לוֹן מִלִּין עִלָּאִין.</p>\n<p>הַאי רָשָׁע מַאי כְּתִיב בֵּיהּ, חָמָא חֶלְמָא דִּקְשׁוֹט, דִּכְתִיב וּבַגֶּפֶן שְׁלשָׁה שָׂרִיגִים. (קצ\"ב ע\"א) מַאי גֶפֶן. דָּא כְּנֶסֶת יִשְׂרָאֵל, דִּכְתִיב, (תהילים פ׳:ט״ו) הַבֵּט מִשָּׁמַיִם וּרְאֵה וּפְקוֹד גֶּפֶן זֹאת. מִשָּׁמַיִם, דְּהָא מֵאֲתַר דָּא אִתְרַמֵּי, כְּמָא דְאַתְּ אָמֵר, (איכה ב׳:א׳) הִשְׁלִיךְ מִשָּׁמַיִם אָרֶץ. וּפְקוֹד גֶּפֶן זֹאת, גֶּפֶן דְּהִיא זֹאת, וַדַּאי.</p>\n<p>שְׁלשָׁה שָׂרִיגִים, כְּמָא דְאַתְּ אָמֵר, (בראשית כ״ט:ב׳) שְׁלשָׁה עֶדְרֵי צֹאן רוֹבְצִים עָלֶיהָ. וְהִיא כְּפוֹרַחַת, דִּכְתִיב, (מלכים א ה׳:י׳) וַתֵּרֶב חָכְמַת שְׁלמֹה, דְּאִתְנְהִיר סִיהֲרָא. עָלְתָה נִצָּהּ, דָּא יְרוּשָׁלַ ם דִּלְתַתָּא. דָּבָר אַחֵר, עָלְתָה נִצָּהּ, לְעֵילָא, הַהוּא דַרְגָּא דְּקָיְימָא עֲלָה וְיַנִּיק לָהּ, כְּמָא דְאַתְּ אָמֵר <Nonei></i>(בראשית א׳:י״א) אֲשֶׁר זַרְעוֹ בוֹ עַל הָאָרֶץ. הִבְשִׁילוּ אַשְׁכְּלוֹתֶיהָ עֲנָבִים, לְנַטְרָא בְּהוּ יַיִן דְּמִנְטְרָא.</p>\n<p>חָמֵי כַּמָּה חָמָא הַהוּא רָשָׁע. מַה כְּתִיב, (בראשית מ׳:י״א) וְכוֹס פַּרְעֹה בְּיָדִי וָאֶקַח אֶת הָעֲנָבִים וָאֶשְׂחַט אוֹתָם. הָכָא חָמָא הַהוּא כּוֹס תַּרְעֵלָה, יַנִּיקָא דְבֵי דִינָא, דְּנָפִיק מֵאִינוּן עֲנָבִים דְּאִתְיְיהִיב לְפַרְעֹה וְשָׁתֵי לֵיהּ, כְּמָה דְהֲוָה בְּגִינֵיהוֹן דְּיִשְׂרָאֵל. כֵּיוָן דְּשָׁמַע יוֹסֵף דָּא, חָדֵי, וְיָדַע מִלָּה דִקְשׁוֹט בְּהַאי חֶלְמָא. בְּגִינִי כָּךְ פָּשַׁר לֵיהּ חֶלְמָא לְטַב, עַל דְּבַשַּׂר לְיוֹסֵף בְּהַאי.</p>\n<p>תָּא חֲזֵי, אֹסְרִי לַגֶּפֶן עִירֹה, דְּאִתְכַּפְיָין תְּחוֹת הַאי גֶפֶן כָּל אִינוּן חֵילִין תַּקִּיפִין דְּעַמִּין עוֹבְדֵי עֲבוֹדָה זָרָה, כִּדְאֲמָרָן, בְּגִין הַאי גֶפֶן, אִתְקַשַּׁר וְאִתְכַּפְיָיא הַהוּא חֵילָא דִלְהוֹן. וְאִתְּמָר.</p>\n<p>רִבִּי שִׁמְעוֹן אָמַר, אִית גֶּפֶן, וְאִית גֶּפֶן. אִית גֶּפֶן קַדִּישָׁא עִלָּאָה, וְאִית גֶּפֶן דְּאִקְרֵי, (דברים לכ) גֶּפֶן סְדוֹם, וְאִית (ירמיהו ב׳:כ״א) גֶּפֶן נָכְרִיָה בַּת אֵל נֵכָר. בְּגִין כָּךְ כְּתִיב גֶּפֶן זֹאת, הַהִיא דְאִקְרֵי כֻּלֹה זֶרַע אֱמֶת. שׂוֹרֵק אֵלּוּ יִשְׂרָאֵל, דְּנָפְקֵי מֵהַאי גֶפֶן. כַּד חָבוּ יִשְׂרָאֵל, וְשָׁבְקוּ לְהַאי גֶפֶן, מַה כְּתִיב, כִּי מִגֶּפֶן סְדוֹם גַּפְנָם וְגו'. וּבְגִין כָּךְ אִית גֶּפֶן וְאִית גֶּפֶן.</p>\n<p>רִבִּי יְהוּדָה וְרִבִּי יִצְחָק הֲווּ אָזְלֵי בְּאָרְחָא. אָמַר רִבִּי יְהוּדָה לְרִבִּי יִצְחָק, נֵיזִיל בְּהַאי חֲקַל, דְּהוּא אֹרַח מֵישַׁר יַתִּיר. אֲזְלוּ. עַד דְּהֲווּ אָזְלֵי, אָמַר רִבִּי יְהוּדָה, כְּתִיב, (משלי ל״א:כ״א) לא תִירָא לְבֵיתָהּ מִשָּׁלֶג כִּי כָל בֵּיתָהּ לָבוּשׁ שָׁנִים. הַאי קְרָא, רִבִּי חִזְקִיָּה חַבְרָנָא אוֹקִים בֵּיהּ. דְּאָמַר, דִּינָא דְּחַיָּיבֵי דְּגֵיהִנֹּם תְּרֵיסַר יַרְחִין, פַּלְגָא מִנַיְיהוּ בְּחַמָּה וּפַלְגָא מִנַּיְיהוּ בְּתַלְגָא.</p>\n<p>בְּשַׁעְתָּא דְעָאלִין לְנוּרָא, אִינוּן אָמְרֵי דָא הוּא וַדַּאי גֵּיהִנֹּם, עָאלִין לְתַלְגָא, אָמְרֵי דָּא חֲרִיפָא דְסִיטָא (דסיתוא) דְקוּדְשָׁא בְּרִיךְ הוּא. שָׁרָאן וְאָמְרִין וַה, וּלְבָתַר אָמְרִין וַוי. וְדָוִד אָמַר (תהילים מ׳:ג׳) וַיַּעֲלֵנִי מִבּוֹר שָׁאוֹן מִטִּיט הַיָּוֵן וַיָּקֶם וְגו'. מֵאֲתַר (נ\"ט ע\"א) דְּאָמְרֵי וַה, וּלְבָתַר וַוי.</p>\n<p>וְהֵיכָן מִשְׁתַּלְּמֵי נַפְשַׁיְיהוּ, בַּשֶּׁלֶג. כְּמָא דְאַתְּ אָמֵר, (תהילים ס״ח:ט״ו) בְּפָרֵשׂ שַׁדַּי מְלָכִים בָּהּ תַּשְׁלֵג בְּצַלְמוֹן. יָכוֹל אַף יִשְרָאֵל כֵּן, תַּלְמוּד לוֹמַר לֹא תִירָא לְבֵיתָהּ מִשָּׁלֶג. מַאי טַעְמָא. בְּגִין דְּכָל בֵּיתָהּ לָבוּשׁ שָׁנִים. אַל תִּקְרֵי שָׁנִים אֶלָּא שְׁנַיִם. כְּגוֹן מִילָה וּפְרִיעָה, צִיצִית וּתְפִילִין, מְזוּזָה וְנֵר חֲנוּכָּה כו'.</p>\n<p>תָּא חֲזֵי, לֹא תִירָא לְבֵיתָהּ מִשָּׁלֶג, דָּא כְּנֶסֶת יִשְׂרָאֵל, דְּאִיהִי כָּל בֵּיתָהּ לָבוּשׁ שָׁנִים, כְּמָה דְּאֲמָרָן. דִּכְתִיב, חֲמוּץ בְּגָדִים וְגו', לְבוּשָׁא דְּדִינָא קַשְׁיָא, לְאִתְפָּרְעָא מֵעַמִּין עוֹבְדֵי עֲבוֹדָה זָרָה. וְזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְמִלְבַּשׁ לְבוּשָׁא סוּמְקָא, וְחַרְבָּא סוּמְקָא, וּלְאִתְפָּרְעָא מִן סוּמְקָא. לְבוּשָׁא סוּמְקָא, דִּכְתִיב, (ישעיהו ס״ג:א׳) חֲמוּץ בְּגָדִים, וּכְתִיב, (ישעיהו ס״ג:א׳) מַדּוּעַ אָדוֹם לִלְבוּשֶׁךָ. סְיָיפָא סוּמְקָא, דִּכְתִיב, (ישעיה לה) חֶרֶב לַה' מָלְאָה דָם. וּלְאִתְפָּרְעָא מִן סוּמְקָא, דִּכְתִיב, (ישעיה לה) כִּי זֶבַח לַה' בְּבָצְרָה וְגו'. תוּ, כִּי כָל בֵּיתָהּ לָבוּשׁ שָׁנִים דְּהָא מִסִּטְרָא דְּדִינָא קַשְׁיָא קָא אַתְיָיא.</p>\n<p>אָמַר רִבִּי יִצְחָק, וַדַּאי הָכִי הוּא, אֶלָּא כָּל בֵּיתָהּ לָבוּשׁ שָׁנִים, מַאי שָׁנִים, אִלֵּין שָׁנִים קַדְמוֹנִיּוֹת, בְּגִין דְּאִיהִי אִתְכְּלִילַת מִכֻּלְּהוּ, וְיָנְקָא מִכָּל סִטְרִין, כְּדִכְתִיב, (קהלת א׳:ז׳) כָּל הַנְּחָלִים הוֹלְכִים אֶל הַיָּם.</p>\n<p>עַד דְּהֲווּ אָזְלֵי, פָּגְעוּ בֵּיהּ בְּהַהוּא יְנוּקָא, דְּהֲוָה אָזִיל לְקַפּוֹטְקִיָא בְּקַסְטִירָא דְחַמְרָא, וְחַד סָבָא רָכִיב. אָמַר הַהוּא סָבָא לְהַהוּא יְנוּקָא, בְּרִי, אֵימָא לִי קְרָאִיךְ. אָמַר לֵיהּ, קְרָאי לָאו חַד הוּא, אֶלָּא חוּת לְתַתָּא, אוֹ אֶרְכַּב לְקַמָּךְ וְאֵימָא לָךְ. אָמַר לֵיהּ, לָא בָּעִינָא. אֲנָא סָבָא וְאַנְתְּ רַבְיָא, דְּאַתְקַל גַּרְמִי בַּהֲדָךְ. אָמַר לֵיהּ, אִי הָכִי אַמַּאי שְׁאַלְתְּ קְרָאי. אָמַר לֵיהּ, בְּגִין דְּנֵיזִיל בְּאוֹרְחָא. אָמַר, תִּיפַּח רוּחֵיהּ דְּהַהוּא סָבָא, דְּהוּא רָכִיב וְלָא יָדַע מִלָּה, וְאָמַר דְּלָא יִתְקַל בַּהֲדִי. אִתְפְּרַשׁ מֵהַהוּא סָבָא, וַאֲזִיל לֵיהּ בְּאוֹרְחָא.</p>\n<p>כַּד מָטוּ רִבִּי יְהוּדָה וְרִבִּי יִצְחָק, קָרִיב לְגַבַּיְיהוּ. שְׁאִילוּ לֵיהּ, וְסָח לוֹן עוֹבָדָא, אָמַר לֵיהּ רִבִּי יְהוּדָה, שַׁפִּיר קָא עֲבַדְתְּ. זִיל בַּהֲדָן, וְנֵיתִיב הָכָא, וְנִשְׁמַע מִלָּה מִפּוּמָךְ. אָמַר לוֹן, לָאֵי (ס\"א רבא) אֲנָא, דְּלָא <Nonei></i>אָכִילְנָא יוֹמָא דֵין. אֲפִיקוּ נַהֲמָא, וִיהִיבוּ לֵיהּ. אִתְרְחִישׁ לוֹן נִיסָּא, וְאַשְׁכָּחוּ חַד נְבִיעָא דְמַיָא דַּקִּיק תְּחוֹת אִילָנָא, שָׁתֵי מִנַּיְיהוּ, וְאִינוּן שָׁתוּ וִיתִיבוּ.</p>\n<p>פָּתַח הַהוּא יְנוּקָא וְאָמַר, (תהילים ל״ז:א׳) לְדָוִד אַל תִּתְחַר בַּמְרֵעִים אַל תְּקַנֵּא בְּעוֹשֵׂי עַוְלָה. לְדָוִד, אִי שִׁירָתָא, לָא קָאֲמַר. אִי תְּפִלָּה, לָא קָאֲמַר. אֶלָּא בְּכָל אֲתַר לְדָוִד סְתָם, רוּח הַקֹּדֶשׁ אֲמָרוֹ.</p>"],[9520011483,"<p>אַל תִּתְחַר בַּמְרֵעִים. מַאי אַל תִּתְחַר בַּמְרֵעִים, אַל תִּתְחַבֵּר מִבָּעֵי לֵיהּ. אֶלָּא אַל תַּעֲבִיד תַּחֲרוּת בַּמְרֵעִים, בְּגִין דְּלָא יָדַעְתְּ יְסוֹדָא דְגַרְמָךְ, וְלָא תֵיכוּל לֵיהּ, דִּילְמָא אִיהוּ אִילָנָא דְּלָא אִתְעַקַּר לְעָלְמִין, וְתִדְחֵי קַמֵּיהּ.</p>\n<p>וְאַל תְּקַנֵּא בְּעוֹשֵׂי עַוְלָה, דְּלָא תַשְׁגַּח בְּעוֹבָדֵיהוֹן, וְלָא תֵיתֵי לְקַנְאָה עֲלַיְיהוּ, דְּכָל מַאן דְחָמֵי עוֹבָדֵיהוֹן, וְלָא קַנֵּי לְקוּדְשָׁא בְּרִיךְ הוּא, אַעֲבַר עַל תְּלַת לָאוִין. דִּכְתִיב, (שמות כ׳:ד׳) לֹא יִהְיֶה לְךָ אֱלֹהִים אֲחֵרִים עַל פָּנָי. לא תַעֲשֶׂה לְךָ פֶסֶל וְכָל תְּמוּנָה. לֹא תִשְׁתַּחֲוֶה לָהֶם וְלֹא תָעָבְדֵם כִּי אָנֹכִי ה' אֱלהֶיךָ אֵל קַנָּא.</p>"],[9520011484,"<p>בְגִין כָּךְ, בָּעֵי לֵיהּ לְבַּר נָשׁ לְאִתְפָּרְשָׁא מִנַּיְיהוּ, וּלְמִסְטֵי אוֹרְחֵיהּ מִנַּיְיהוּ, עַל דָּא אִתְפְּרָשְׁנָא וְסָטִינָא אָרְחָאי. מִכָּאן וּלְהָלְאָה דְּאַשְׁכַּחְנָא לְכוּ, אֵימָא הַנֵּי קְרָאֵי קַמֵּיכוֹן. פָּתַח וְאָמַר, וַיִּקְרָא אֶל משֶׁה, הָכָא אָלֶ\"ף זְעֵירָא. אַמַּאי, בְּגִין דְּהַאי קְרִיאָה לָא הֲוָה בִּשְׁלִימוּ. מַאי טַעְמָא, דְּהָא לָא הֲוָה אֶלָּא בְּמִשְׁכְּנָא, וּבְאַרְעָא אָחֳרָא. בְּגִין דִּשְׁלִימוּ לָא אִשְׁתַּכַּח אֶלָּא בְּאַרְעָא קַדִּישָׁא.</p>\n<p>תוּ, הָכָא שְׁכִינְתָּא, (ס\"א ל\"ג התם וגריס נוקבא) הָתָם שְׁלִימוּ דִּדְכַר וְנוּקְבָא, (דברי הימים א א׳:א׳) אָדָם שֵׁת אֱנוֹשׁ. אָדָם, שְׁלִימוּ דְּכַר וְנוּקְבָא, הָכָא נוּקְבָא. תוּ סֵיפָא דִקְרָא, וַיְדַבֵּר ה' אֵלָיו מֵאֹהֶל מוֹעֵד לֵאמֹר, בְּגִין כָּךְ אָלֶ\"ף זְעֵירָא.</p>\n<p>תוּ אָלֶ\"ף זְעֵירָא, מְתַל לְמַלְכָּא, דְּהֲוָה יָתִיב בְּכָרְסְיֵהּ, וְכִתְרָא דְמַלְכוּתָא עֲלֵיהּ, אִקְרֵי מֶלֶךְ עִלָּאָה. כַּד נָחִית וְאֲזַל לְבֵי עַבְדֵיהּ, מֶלֶךְ זוּטָא אִקְרֵי. כָּךְ קוּדְשָׁא בְּרִיךְ הוּא, כָּל זִמְנָא דְּאִיהוּ לְעֵילָא עַל כֹּלָּא, מֶלֶךְ עִלָּאָה אִקְרֵי. כֵּיוָן דְּנָחִית מָדוֹרֵיהּ לְתַתָּא, מֶלֶךְ אִיהוּ, אֲבָל לָאו עִלָּאָה כְּקַדְמִיתָא, בְּגִין כָּךְ אָלֶ\"ף זְעֵירָא.</p>\n<p>וַיִּקְרָא, הָכִי תָּנִינָן, זַמִּין לֵיהּ לְהֵיכָלֵיהּ. מֵאֹהֶל מוֹעֵד. מַאן אֹהֶל מוֹעֵד. אֹהֶל דְּבֵיהּ תַּלְיָין מוֹעֵד וְחַגָּא וְשַׁבַּתָּא לְמִמְנֵי, כְּמָא דְאַתְּ אָמֵר, (בראשית א׳:י״ד) וְהָיוּ לְאוֹתוֹת וּלְמוֹעֲדִים, בֵּיהּ שַׁרְיָא חוּשְׁבְּנָא לְמִמְנֵי. וּמַאן אִיהוּ, סִיהֲרָא, כְּמָא דְאַתְּ אָמֵר, (ישעיהו ל״ג:כ׳) אֹהֶל בַּל יִצְעָן בַּל יִסַּע יְתֵדוֹתָיו לָנֶצַח.</p>\n<p>לֵאמֹר, מַאי לֵאמֹר. בְּגִין לְגַלָּאָה, (אבל כלא חד ושפיר הוא, בגין דשלימו ושפירו הוא אתר לגלאה) מַה דְּהֲוָה סָתִים לְגוֹ. וּבְכָל אֲתַר לֵאמֹר, כְּמָא דְאַתְּ אָמֵר, וַיְדַבֵּר ה' אֶל משֶׁה לֵאמֹר, דְּאִתְיְיהִיב רְשׁוּ לְגַלָּאָה. אֲבָל כֹּלָּא חַד הוּא, וְשַׁפִּיר הוּא, בְּגִין דְּהָא אִתְמַנֵּי לְסִיהֲרָא הַהִיא מִלָּה, מֵאֲתַר דְּמשֶׁה קָיְימָא.</p>\n<p>וַיְדַבֵּר, לְעֵילָא. אֶל משֶׁה, בְּאֶמְצָעִיתָא. לֵאמֹר, בַּתְרַיְיתָא. אֲתַר, דְּאִית רְשׁוּ לְגַלָּאָה. תוּ, וַיִּקְרָא אֶל משֶׁה מַה כְּתִיב לְעֵילָא, (שמות ל״ט:ל״ג) וַיָּבִיאוּ אֶת הַמִּשְׁכָּן אֶל משֶׁה וְגו'. אַמַּאי אֶל משֶׁה. הָכִי אָמְרוּ, בְּגִין דְּמשֶׁה חָמָא לֵיהּ בְּטוּרָא, וְקוּדְשָׁא בְּרִיךְ הוּא אַחְמֵי לֵיהּ בְּחֵיזוּ דְעֵינָא, כְּמָא דְאַתְּ אָמֵר, (שמות כ״ז:ח׳) כַּאֲשֶׁר הֶרְאָה אוֹתְךָ בָּהָר, וּכְתִיב, (במדבר ח׳:ד׳) כַּמַּרְאֶה אֲשֶׁר הֶרְאָה ה' אֶת משֶׁה וְגו'. וּכְתִיב (שמות כח) וּרְאֵה וַעֲשֵׂה בְּתַבְנִיתָם אֲשֶׁר אַתָּה מָרְאֶה בָּהָר, הַשְׁתָּא אַיְיתִיאוּ לֵיהּ, בְּגִין דְּיֶחֱמֵי, אי אִיהוּ כְּהַהוּא מִשְׁכְּנָא דְּחָמָא.</p>\n<p>אֲבָל אַמַּאי וַיָּבִיאוּ אֶת הַמִּשְׁכָּן אֶל משֶׁה. אֶלָּא, לְמַלְכָּא דְּבָעָא לְמִבְנִי פַּלְטְרִין לְמַטְרוֹנִיתָא, פַּקִּיד לְאוּמָנִין הֵיכָלָא דָּא בְּדוּךְ פְּלַן, וְהֵיכָלָא דָּא בְּדוּךְ פְּלַן, הָכָא אֲתַר לְעַרְסָא, וְהָכָא אֲתַר לְנַיְיחָא. כֵּיוָן דַּעֲבִידוּ לוֹן אוּמָנִין, אַחְמִיּוּ לְמַלְכָּא. כָּךְ וַיָּבִיאוּ אֶת הַמִּשְׁכָּן אֶל משֶׁה, מָארֵי דְבֵיתָא, אִישׁ הָאֱלהִים, כֵּיוָן דְּאִשְׁתַּכְלַל הֵיכָלָא, מַטְרוֹנִיתָא זְמִינַת לְמַלְכָּא לְהֵיכָלָא, זְמִינַת לְבַעֲלָהּ עִמָּהּ, בְּגִין כָּךְ וַיִּקְרָא אֶל משֶׁה.</p>\n<p>וּבְגִין דְּמשֶׁה מָארֵי דְבֵיתָא אִיהוּ, מַה כְּתִיב, (שמות ל״ג:ז׳) וּמשֶׁה יִקַּח אֶת הָאֹהֶל וְנָטָה לוֹ מִחוּץ לַמַּחֲנֶה, משֶׁה דְּאִיהוּ מָארֵי דְבֵיתָא, <Nonei></i>עָבִיד הָכִי, מַה דְּלֵית רְשׁוּ לְבַר נָשׁ אָחֳרָא לְמֶעְבַּד הָכִי.</p>\n<p>וַיְדַבֵּר ה' אֵלָיו, דַּרְגָּא אָחֳרָא עִלָּאָה, וּכְדֵין בְּשַׁעְתָּא דְּאִזְדַּמַּן משֶׁה לְמֵיעַל, כְּדֵין פָּתַח וְאָמַר, (ויקרא א׳:ב׳) אָדָם כִּי יַקְרִיב מִכֶּם. מַאי אָדָם הָכָא. אֶלָּא כַּד אִתְחַבְּרוּ שִׁמְשָׁא וְסִיהֲרָא כְּחֲדָא, פָּתַח וְאָמַר אָדָם. כְּדִכְתִיב, (חבקוק ג׳:י״א) שֶׁמֶּשׁ יָרֵחַ עָמַד זְבוּלָהּ, עָמַד, וְלא עָמְדוּ.</p>\n<p>כִּי יַקְרִיב מִכֶּם, הָכָא אִתְרְמִיז, מַאן דְּיַעֲבִיד פּוּלְחָנָא דְקָרְבְּנָא שְׁלִים, דְּיִשְׁתַּכַּח דְּכַר וְנוּקְבָא. מַשְׁמַע דִּכְתִיב מִכֶּם, דְיִשְׁתַּכַּח בְּחֵיזוּ דִלְכוֹן. קָרְבָּן לַה' דְּאַקְרִיב כֹּלָּא, לְאִתְאַחֲדָא כְּחֲדָא, לְעֵילָא וְתַתָּא.</p>\n<p>מִן הַבְּהֵמָה, לְאַחֲזָאָה אָדָם וּבְהֵמָה, כֹּלָּא כְּחֲדָא. מִן הַבָּקָר וּמִן הַצֹּאן, אִלֵּין רְתִיכִין, דְּאִינוּן דַכְיָין. דְּכֵיוָן דְּאָמַר מִן הַבְּהֵמָה, יָכוֹל מִכֹּלָּא, בֵּין דַּכְיָין בֵּין מְסָאֲבָן. הֲדַר וְאָמַר, מִן הַבָּקָר וּמִן הַצֹּאן.</p>\n<p>תַּקְרִיבוּ אֶת קָרְבַּנְכֶם. קָרְבָּנִי מִבָּעֵי לֵיהּ, מַאי קָרְבַּנְכֶם. אֶלָּא בְּקַדְמִיתָא קָרְבָּן לַה', וְהַשְׁתָּא קָרְבַּנְכֶם. קָרְבָּן לַה' אָדָם. קָרְבַּנְכֶם מִן הַבְּהֵמָה מִן הַבָּקָר וּמִן הַצֹּאן, לְאַחֲזָאָה יִחוּדָא מִתַּתָּא לְעֵילָא, וּמֵעֵילָא לְתַתָּא. מִתַּתָּא לְעֵילָא, הַיְינוּ קָרְבָּן לַה'. מֵעֵילָא לְתַתָּא, הַיְינוּ קָרְבַּנְכֶם.</p>\n<p>לְמַלְכָּא, דְּאִיהוּ יָתִיב בְּטוּרְסְקָא עִלָּאָה, לְעֵילָא לְעֵילָא, וְכָרְסְיָא אִתְתַּקַּן עַל הַהוּא טוּרְסְקָא, וּמַלְכָּא עִלָּאָה עַל כֹּלָּא. בַּר נָשׁ דְּקָרִיב דּוֹרוֹנָא לְמַלְכָּא, בָּעָא לְסַלְקָא מִדַּרְגָא לְדַרְגָא, עַד דְּסָלִיק מִתַּתָּא לְעֵילָא לְאֲתַר דְּמַלְכָּא יָתִיב, עִלָּאָה עַל כֹּלָּא. וּכְדֵין יָדְעִין דְּהָא סָלְקִין דּוֹרוֹנָא לְמַלְכָּא, וְהַהוּא דוֹרוֹנָא דְמַלְכָּא אִיהוּ. נָחִית דּוֹרוֹנָא מֵעֵילָא לְתַתָּא, הָא יָדְעִין דְּהַהוּא דוֹרוֹנָא דְמַלְכָּא נָחִית מֵעֵילָא, לִרְחִימָא דְמַלְכָּא דְּאִיהוּ לְתַתָּא.</p>\n<p>כָּךָ בְּקַדְמִיתָא, אָדָם סָלִיק בְּדַרְגּוֹי מִתַּתָּא לְעֵילָא, וּכְדֵין קָרְבָּן לַה'. מִן הַבְּהֵמָה מִן הַבָּקָר, נָחִית בְּדַרְגוֹי מֵעֵילָא לְתַתָּא, וּכְדֵין קָרְבַּנְכֶם. בְּגִינֵי כָּךְ כְּתִיב, (שיר השירים ה׳:א׳) אָכַלְתִּי יַעֲרִי עִם דִּבְשִׁי שָׁתִיתִי יִיִנִי עִם חֲלָבִי. הַיְינוּ אָדָם וְקָרְבָּן לַה'. אִכְלוּ רֵעִים, הַיְינוּ מִן הַבְּהֵמָה מִן הַבָּקָר וּמִן הַצֹּאן, וּכְדֵין תַּקְרִיבוּ אֶת קָרְבַּנְכֶם.</p>\n<p>אָתוּ רִבִּי יִצְחָק וְרִבִּי יְהוּדָה וּנְשָׁקוּהוּ עַל רֵישֵׁיהּ. אָמְרוּ, בְּרִיךְ רַחֲמָנָא דְּזַכֵּינָא לְמִשְׁמַע דָא, וּבְרִיךְ רַחֲמָנָא, דְּלָא אִתְאֲבִידוּ מִלִּין אִלֵּין בְּהַהוּא סָבָא. קָמוּ וְאֲזְלוּ. עַד דְּהֲווּ אָזְלֵי, חָמוּ חַד גֶּפֶן נְטִיעַ בְּחַג גִּנָּא.</p>\n<p>פָּתַח הַהוּא יְנוּקָא וְאָמַר, אֹסְרִי לַגֶּפֶן עִירֹה וְלַשּׂוֹרֵקָה בְּנִי אֲתוֹנוֹ הַאי קְרָא רָזָא עִלָּאָה הוּא. אֹסְרִי, אָסַר מִבָּעֵי לֵיהּ. עִירֹה, עַיִר מִבָּעֵי לֵיהּ. אֶלָּא רָזָא הוּא, לְדַרְדְּקֵי דְּאִינוּן בְּבֵי רַב, לְאִסְתַּמְּרָא מֵהַהוּא גִּירָא דְּעַיִר, וּשְׁמָא קַדִּישָׁא אִתְכְּלִיל תַּמָּן י\"ה.</p>\n<p>וּכְמָה דְהָכָא אִתְרְמִיז שְׁמָא קַדִּישָׁא, הָכִי נָמֵי וְלַשּׂרֵקָה, שׂוֹרֵק מִבָּעֵי לֵיהּ. אִתְכְּלִיל תַּמָּן ו\"ה. בְּנִי בֶּן מִבָּעֵי לֵיהּ. שׂוֹרֵק, כְּדִכְתִיב, (ירמיהו ב׳:כ״א) וְאָנֹכִי נְטַעְתִּיךְ שׂוֹרֵק. בֵּן, כְּמָא דְאַתְּ אָמֵר, (זכריה ט) בֶּן אֲתוֹנוֹת. אַמַּאי שׂוֹרֵקָה, וְאַמַּאי בְּנִי.</p>\n<p>אֶלָּא, כְּמָה דְאִית שְׁמָא קַדִּישָׁא לְאִכַּפְיָא לְעַיִר, הָכִי נָמֵי, אִית שְׁמָא קַדִּישָׁא, לְאִכַּפְיָא חֵילָא אָחֳרָא, דְּאִיהִי חַמְרָא, דְּאִלְמָלֵא דִּשְׁמָא קַדִּישָׁא אִתְרְמִיז הָכָא, הֲווּ מְטַרְטְשֵׁי עַלְמָא, י\"ה בְּחֵילָא דָא, (ס\"א וי\"ה) ו\"ה בְּחֵילָא דָא, לְאִסְתַּמְּרָא עַלְמָא מִנַּיְיהוּ, וּלְאִסְתַּמְּרָא בַּר נָשׁ, דְּלָא יִשְׁלְטוּן בֵּיהּ בְּעַלְמָא.</p>\n<p>אֹסְרִי לַגֶּפֶן, מַאי גֶּפֶן. דָּא כְּנֶסֶת יִשְׂרָאֵל, אַמַּאי אִתְקְרִיאַת גֶּפֶן. אֶלָּא מַה גֶּפֶן, לָא מְקַבְּלָא עֲלָהּ נְטִיעָא אָחֳרָא, הָכִי נָמֵי כְּנֶסֶת יִשְׂרָאֵל, לָא מְקַבְּלָא עֲלָהּ אֶלָּא לְקוּדְשָׁא בְּרִיךְ הוּא. וּבְגִין כְּנֶסֶת יִשְׂרָאֵל, אִתְכַּפְיָין קַמָּהּ כָּל חֵילִין אָחֳרָנִין, וְלָא יָכְלִין לְאַבְאָשָׁא וּלְשַׁלְטָאָה בְּעַלְמָא. וְעַל דָּא אַטִּיל קְרָא שְׁמָא קַדִּישָׁא בֵּינַיְיהוּ, בְּהַאי גִיסָא וּבְהַאי גִיסָא. בְּנִי אֲתוֹנוֹ, דְּאִתְעַקַּר בְּגִין הַהוּא שׂוֹרֵק, כְּמָה דְאַתְּ אָמֵר, וְאָנֹכִי נְטַעְתִּיךְ שׂוֹרֵק וְגו'.</p>\n<p>כִּבֵּס בַּיַּיִן לְבוּשׁוֹ וְגו', כִּבֵּס, כּוֹבֵס מִבָּעֵי לֵיהּ. אֶלָּא כִּבֵּס, מִיּוֹמָא דְּאִתְבְּרֵי עַלְמָא, וּמַאן אִיהוּ, דָּא מַלְכָּא מְשִׁיחָא. בַּיַּיִן סְטַר שְׂמָאלָא. וּבְדַם עֲנָבִים סְטַר שְׂמָאלָא. לְתַתָּא. וְזַמִּין מַלְכָּא מְשִׁיחָא <Nonei></i>לְשַׁלְּטָאָה לְעֵילָא עַל כָּל חֵילִין אָחֳרָנִין דְּעַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, וּלְתַבְרָא תּוֹקְפֵיהוֹן מֵעֵילָא וּמִתַּתָּא.</p>\n<p>דָּבָר אַחֵר, כִּבֵּס בַּיַּיִן לְבוּשׁוֹ, כְּגַוְונָא דְהַאי חַמְרָא, אַחֲזֵי חֵידוּ, וְכוּלֵיהּ דִּינָא. (לעמין עובדי עבודת כוכבים ומזלות). הָכִי נָמֵי מַלְכָּא מְשִׁיחָא, יֶחזִיִ חֵדוּ לְיִשְׂרָאֵל, וְכוּלֵיהּ דִּינָא לְעַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. כְּתִיב, (בראשית א׳:ב׳) וְרוּחַ אֱלֹהִים מְרַחֶפֶת עַל פְּנֵי הַמָּיִם, דָּא רוּחָא דְמַלְכָּא מְשִׁיחָא, וּמִן יוֹמָא דְּאִתְבְּרֵי עַלְמָא, אַסְחֵי לְבוּשֵׁיהּ בְּחַמְרָא עִלָּאָה.</p>\n<p>חָמֵי מַה כְּתִיב בַּתְרֵיהּ, חַכְלִילִי עֵינַיִם מִיָּיִן וּלְבֶן שִׁנַּיִם מֵחָלָב, דָּא חַמְרָא עִלָּאָה, (ס\"א דמרוי דאורייתא) דְּאוֹרַיְיתָא דְּמַרְוֵי, מִנֵּיהּ שָׁתֵי. וּלְבֶן שִׁנַּיִם מֵחָלָב, דְּהָא אוֹרַיְיתָא יַיִן וְחָלָב, תּוֹרָה שֶׁבִּכְתָב, וְתוֹרָה שֶׁבְּעַל פֶּה.</p>\n<p>כְּתִיב, (תהילים ק״ד:ט״ו) וְיַיִן יְשַׂמַּח לְבַב אֱנוֹשׁ (ס\"א אמאי, בגין דמאתר דחדוה קאתי, ומאן הוא סופיה דקרא) לְהַצְהִיל פָּנִים מִשָּׁמֶן, וַדַּאי מֵאֲתַר דְּאִתְקְרֵי שָׁמֶן. תָּא חֲזֵי, שֵׁירָתָא דְחַמְרָא חֶדְוָה, הוּא אֲתַר דְּכָל חֵידוּ מִנֵּיהּ נַפְקָא. וְסוֹפֵיהּ דִּינָא. מַאי טַעְמָא, בְּגִין דְּסוֹפָא דִילֵיהּ, אֲתַר כְּנִישׁוּ דְּכֹלָּא, דִּינָא הוּא, וּבֵיהּ אִתְדָּן עַלְמָא. וְעַל דָּא שֵׁירוּתָא חֶדְוָה, וְסוֹפָא דִינָא. בְּגִינֵי כָּךְ, לְהַצְהִיל פָּנִים מִשָּׁמֶן. מֵאֲתַר דְּכָל חֶדְוָה מִנֵּיהּ נָפְקָא.</p>\n<p>וְלֶחֶם לְבַב אֱנוֹשׁ יִסְעָד, מַאן לֶחֶם. אֶלָּא לֶחֶם עַלְמָא סָעִיד (סמיך), וְאִי תֵימָא, דְּבֵיהּ תַלְיָיא סְעִידוּ דְעַלְמָא בִּלְחוֹדוֹי, לָאו הָכִי, דְּהָא לֵילְיָא בְּלָא יוֹמָא, לָא אִשְׁתַּכַּח, וְלָא בָּעֵי לְאַפְרָשָׁא לוֹן. וּמַאן דְּאַפְרִישׁ לוֹן, יִתְפָּרַשׁ מֵחַיִּין, וְהַיְינוּ דִכְתִיב, (דברים ח׳:ג׳) לְמַעַן הוֹדִיעֲךָ כִּי לא עַל הַלֶּחֶם לְבַדּוֹ יִחְיֶה הָאָדָם. בְּגִין דְּלָא בָּעֵי לְאִתְפָּרְשָׁא.</p>\n<p>וְאִי תֵימָא, דָּוִד הֵיךְ קָאֲמַר וְלֶחֶם לְבַב אֱנוֹשׁ יִסְעָד, הוֹאִיל וְלָא תַלְיָיא בֵּיהּ בִּלְחוֹדוֹי סְעִידוּ דְּעַלְמָא. אֶלָּא דַּיְיקָא דְמִלָּה, וְלֶחֶם, וא\"ו אִיתּוֹסַף, כְּמוֹ וַיְיָ, וְעַל דָּא, כֹּלָּא אִשְׁתַּכַּח כְּחֲדָא.</p>\n<p>תָּא חֲזֵי, מַאן דִּמְבָרֵךְ עַל מְזוֹנָא, לָא יְבָרֵךְ עַל פְּתוֹרָא רֵיקַנְיָא, וּבָעֵי נַהֲמָא לְאִשְׁתַּכְּחָא עַל פָּתוֹרָא, וְכַסָּא דְחַמְרָא בִּימִינָא. מַאי טַעְמָא, בְּגִין לְקָשְׁרָא שְׂמָאלָא בִּימִינָא, וְנַהֲמָא דְּיִתְבָּרַךְ מִנַּיְיהוּ, וּלְאִתְקַשְּׁרָא בְּהוּ, וּלְמֶהוֵי כֹּלָּא חַד קִשּׁוּרָא, לְבָרְכָא שְׁמָא קַדִּישָׁא כְּדְקָא יְאוּת. דְּהָא לֶחֶם אִתְקַשַּׁר בְּיַיִן, וְיַיִן בִּימִינָא, וּכְדֵין בִּרְכָאן שַׁרְיָין בְּעַלְמָא, וּפָתוֹרָא אִשְׁתְּלִים כְּדְקָא יְאוּת.</p>"],[9520011485,"<p>אָמַר רִבִּי יִצְחָק, אִלְמָלֵא לָא אִזְדַּמָּן לָן אוֹרְחָא דָא אֶלָּא לְמִשְׁמַע מִלִּין אִלֵּין, דַּי לָן. אָמַר רִבִּי יְהוּדָה, יָאוֹת הוּא לְהַאי יְנוּקָא דְּלָא יִנְדַע כָּל הַאי, וְאֲנָא מִסְתָּפִינָא עֲלֵיהּ. אִי יִתְקַיַּים בְּעַלְמָא בְּגִין הַאי. אָמַר רִבִּי יִצְחָק וְלָמָּה. אָמַר לֵיהּ, בְּגִין דְּהַאי רַבְיָא יָכִיל לְאִסְתַּכְּלָא בְּאַתְרָא דְּלֵית רְשׁוּ לְבַר נָשׁ לְאִסְתַּכְּלָא בֵּיהּ. וּמִסְתָּפִינָא עֲלוֹי, דְּעַד לָא יִמְטֵי לְפִרְקוֹי, יַשְׁגַּח וְיִסְתַּכַּל וְיַעַנְשׁוּן לֵיהּ.</p>\n<p>שָׁמַע הַהוּא יְנוּקָא. אָמַר, לָא מִסְתָּפִינָא מֵעוֹנָשָׁא לְעָלְמִין, דְּהָא בְּשַׁעְתָּא דְּאִסְתַּלִּיק אַבָּא מֵעַלְמָא, בָּרִיךְ לִי וְצַלֵּי עָלַי. וִידַעְנָא דִזְכוּתָא דְּאַבָּא יָגִין עָלַי. אָמְרוּ לֵיהּ, וּמַאן הוּא אֲבוּךְ. אָמַר, (נ\"א ליתא רב יהודה) בְּרֵיהּ דְּרַב הַמְנוּנָא סָבָא, נָטְלוּ לֵיהּ, וְאַרְכְּבוּהָ עַל כִּתְפַיְיהוּ תְּלַת מִילִין.</p>\n<p>קָרוּ עֲלֵיהּ, (שופטים י״ד:י״ד) מֵהָאוֹכֶל יָצָא מַאֲכָל וּמֵעַז יָצָא מָתוֹק וְגו'. אָמַר לוֹן הַהוּא יְנוּקָא, מִלָּה אֲתָא לִידַיְיכוּ, פָּרִישׁוּ לָהּ. אָמְרוּ לֵיהּ, קוּדְשָׁא בְּרִיךְ הוּא זַמִּין לָן אָרְחָא דְחַיֵּי, אֵימָא אַנְתְּ.</p>\n<p>פָּתַח וְאָמַר, מֵהָאוֹכֶל יָצָא מַאֲכָל וּמֵעַז יָצָא מָתוֹק. הַאי קְרָא, אַסְמַכְתָּא אִית לָן בֵּיהּ, מֵהָאוֹכֶל, דָּא צַדִּיק, דִּכְתִיב, (משלי י״ג:כ״ה) צַדִּיק אוֹכֵל לְשׂוֹבַע נַפְשׁוֹ. צַדִּיק אוֹכֵל וַדַּאי, וְנָטִיל כֹּלָּא, אַמַּאי, לְשׂוֹבַע נַפְשׁוֹ. לְמֵיהַב שָׂבְעָא, לְהַהוּא אֲתַר דְּאִקְרֵי נַפְשׁוֹ דְּדָוִד. יָצָא מַאֲכָל, דְּאִלְמָלֵא הַהוּא צַדִּיק, לָא יִפּוּק מְזוֹנָא לְעָלְמִין, וְלָא יָכִיל עַלְמָא לְקָיְימָא (ביה). וּמֵעַז יָצָא מָתוֹק, דָּא יִצְחָק, דְּבָרִיךְ לְיַעֲקֹב בְּטַל הַשָּׁמַיִם וּמִשְׁמַנֵּי הָאָרֶץ.</p>\n<p>תוּ, אַף עַל גַּב דְּכֹלָּא חַד, אִלְמָלֵא תּוּקְפָא דְּדִינָא קַשְׁיָא, לָא נָפְקָא דְבַשׁ. מַאן דְּבַשׁ. דָּא תּוֹרָה שֶׁבְּעַל פֶּה, דִּכְתִיב, (תהילים י״ט:י״א) וּמְתוּקִים מִדְּבַשׁ וְנֹפֶת צוּפִים. מֵעַז, דָּא תּוֹרָה שֶׁבִּכְתָב, דִּכְתִיב, (תהילים כ״ט:י״א) ה' עֹז לְעַמּוֹ יִתֵּן. יָצָא מָתוֹק, דָּא תּוֹרָה שֶׁבְּעַל פֶּה.</p>\n<p><Nonei></i>אֲזְלוּ כְּחֲדָא תְּלַת יוֹמִין, עַד דְּמָטוּ לְטוּרְסָא דְקִירָא דְּאִמֵּיהּ. כֵּיוָן דְּחָמַאת לוֹן אַתְקָנִית בֵּיתָא, וְיַתְבוּ תַּמָּן תְּלַת יוֹמִין אָחֳרָנִין. בֵּרְכוּהוּ, וְאֲזְלוּ, וְסִדְּרוּ מִלִּין קַמֵּיהּ דְּרַבִּי שִׁמְעוֹן. אָמַר, וַדַּאי יְרוּתַת אוֹרַיְיתָא אַחְסִין, וְאִלְמָלֵא זְכוּתָא דַאֲבָהָן יִתְעַנַּשׁ מִלְּעֵילָא, אֲבָל קוּדְשָׁא בְּרִיךְ הוּא לְאִינוּן דְּאָזְלִין בָּתַר אוֹרַיְיתָא, אַחְסִינוּ לָהּ אִינוּן וּבְנַיְיהוּ לְעָלְמִין. הֲדָא הוּא דִכְתִיב, (ישעיהו נ״ט:כ״א) וַאֲנִי זֹאת בְּרִיתִי אוֹתָם אָמַר ה' רוּחִי אֲשֶׁר עָלֶיךָ וגו'.</p>"],[9520011486,"<p>זְבוּלוּן לְחוֹף יַמִּים יִשְׁכּוֹן וְהוּא לְחוֹף אֳנִיּוֹת וְיַרְכָתוֹ וְגו'. רִבִּי אַבָּא פָּתַח, (תהילים מ״ה:ד׳) חֲגוֹר חַרְבְּךָ עַל יָרֵךְ גִּבּוֹר הוֹדְךָ וַהֲדָרֶךָ. וְכִי דָּא הוֹד וְהָדָר, לְמֵיזַן זַיְינָא, וּלְאִזְדַּרְזָא בְּהַאי. מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא, וְאַגַּח קְרָבָא בְּאוֹרַיְיתָא, וְזַרִיז גַּרְמֵיהּ בָּהּ, דָּא הוּא שְׁבָחָא (דמאריה), דָּא הוּא הוֹד וְהָדָר, וְאַתְּ אֲמַרְתְּ חֲגוֹר חַרְבְּךָ.</p>\n<p>אֶלָּא, וַדַאי עִקְּרָא דְמִלָּה, אָת קַיָּימָא קַדִּישָׁא. יָהַב קוּדְשָׁא בְּרִיךְ הוּא, וְרָשִׁים לֵיהּ בִּבְנִי נָשָׁא, בְּגִין דְּיִנְטְרוּן לֵיהּ, וְלָא יִפְגְּמוּן לֵיהּ בִּפְגִימוּ לְהַאי רְשִׁימָא דְמַלְכָּא. וּמַאן דְּפָגִים לֵיהּ, הָא קָאִים לְקֳבְלֵיהּ (ויקרא כ״ו:כ״ה) חֶרֶב נֹקֶמֶת נְקַם בְּרִית, לְנַקְמָא נוּקְמָא דִּבְרִית קַדִּישָׁא, דְּאִתְרְשִׁים בֵּיהּ, וְהוּא פָּגִים לֵיהּ.</p>\n<p>וּמַאן דְּבָעֵי לְנַטְרָא הַאי אֲתַר, יִזְדַּרֵז וִיתַקֵּן גַּרְמֵיהּ, וִישַׁוֵּי לְקֳבְלֵיהּ, בְּשַׁעְתָּא דְּיִצְרָא בִישָׁא יִתְקַף עֲלוֹי, לְהַאי חֶרֶב דְּקָיְימָא עַל יָרֵךְ, לְאִתְפָּרְעָא מִמַּאן דְּפָגִים הַאי אֲתַר. וּכְדֵין, חֲגוֹר חַרְבְּךָ עַל יָרֵךְ גִּבּוֹר, גִּבּוֹר אִיהוּ, גִּבּוֹר אִתְקְרֵי. וְעַל דָּא הוֹדְךָ וַהֲדָרֶךָ.</p>\n<p>דָּבָר אַחֵר, חֲגוֹר חַרְבְּךָ עַל יָרֵךְ גִּבּוֹר. מַאן דְּנָפִיק בְּאָרְחָא, יְתַקֵּן גַּרְמֵיהּ בִּצְלוֹתָא דְמָארֵיהּ, וְיִזְדַּרֵז בְּהַאי (מ\"ט ע\"ב) צֶדֶק, חֶרֶב עִלָּאָה, בִּצְלוֹתָא וּבָעוּתִין עַד לָא יִפּוּק לְאָרְחָא. כְּדִכְתִיב, (תהילים פ״ה:י״ד) צֶדֶק לְפָנָיו יְהַלֵּךְ וְיָשֵׂם לְדֶרֶךְ פְּעָמָיו. תָּא חֲזֵי, זְבוּלוּן נָפִיק תְּדִירָא לִשְׁבִילִין וְאָרְחִין, וְאַגַּח קְרָבִין, וְאִזְדַּרֵז בְּהַאי חֶרֶב עִלָּאָה, בִּצְלוֹתָא וּבָעוּתִין, עַד לָא נָפִיק בְּאָרְחָא, וּכְדֵין נָצַח עַמִּין, וְאִתְתַּקַּף עֲלַיְיהוּ. וְאִי תֵימָא יְהוּדָה, הָא אִתְתַּקַּן בְּהַאי, לְאַגָּחָא קְרָבִין, וְתִקּוּנִין, בְּהַאי חֶרְב, אַמַּאי זְבוּלוּן. אֶלָּא.</p>\n<p>תָּא חֲזֵי, הַנֵּי תְּרֵיסַר שִׁבְטִין, כֻּלְּהוּ תִּקּוּנָא דְמַטְרוֹנִיתָא הֲווּ. תְּרֵין תִּקּוּנִין דְּנוּקְבֵי אָמַר שְׁלֹמה בְּשִׁיר הַשִּׁירִים, חַד לְרַעֲיָא עִלָּאָה יוֹבֵלָא, וְחַד לְכַלָּה, שְׁנַת הַשְּׁמִיטָה. חַד תִּקּוּנָא לְעֵילָא, וְחַד תִּקּוּנָא לְתַתָּא. עוֹבָדָא דִבְרֵאשִׁית, הָכִי הוּא נָמֵי, בְּהַנֵּי תְּרֵי אַתְרֵי, חַד עוֹבָדָא לְעֵילָא, וְחַד עוֹבָדָא לְתַתָּא, וְעַל דָּא פְּתִיחָא דְאוֹרַיְיתָא בְּב'. עוֹבָדָא דִּלְתַתָּא, כְּגַוְונָא דִלְעֵילָא, דָּא עֲבַד עַלְמָא עִלָּאָה, וְדָא עֲבַד עַלְמָא תַּתָּאָה. כְּגַוְונָא דָא.</p>\n<p>תְּרֵין תִּקּוּנִין דְּנוּקְבֵי קָאֲמַר שְׁלֹמֹה, חַד לְעֵילָא, וְחַד לְתַתָּא. חַד לְעֵילָא, בְּתִקּוּנָא עִלָּאָה דִּשְׁמָא קַדִּישָׁא. חַד לְתַתָּא, בְּתִקּוּנָא תַּתָּאָה כְּגַוְונָא דִלְעֵילָא.</p>\n<p>תָּא חֲזֵי, זַכָּאָה חוּלָקֵיהּ דְּיַעֲקֹב קַדִּישָׁא, דְּזָכָה לְהַאי. וְהָא אִתְּמָר, מִיּוֹמָא דְאִתְבְּרֵי עַלְמָא, לָא אִשְׁתַּכַּח עַרְסָא שְׁלֵימָתָא כְּעַרְסֵיהּ דְּיַעֲקֹב. וּבְשַׁעְתָּא דְבָעָא לְאִסְתַּלָּקָא מֵעַלְמָא, כְּדֵין הֲוָה שְׁלִים, בְּכָל (רל\"א ע\"ב) סִטְרוֹי. אַבְרָהָם מִימִינֵיהּ, יִצְחָק מִשְׂמָאלֵיהּ, הוּא בְּאֶמְצָעִיתָא, שְׁכִינְתָּא קַמֵּיהּ. כֵּיוָן דְּחָמָא יַעֲקֹב הַאי, קָרָא לִבְנוֹי, וְאָמַר לוֹן הֵאָסְפוּ, בְּגִין דְּיִשְׁתַּכַּח תִּקּוּנָא דִלְעֵילָא וְתַתָּא.</p>\n<p>תָּא חֲזֵי, רָזָא דְמִלָּה, תְּרֵין תִּקּוּנִין אִשְׁתַּכָּחוּ תַּמָּן, חַד עִלָּאָה, וְחַד תַּתָּאָה, לְמֶהֱוֵי כֹּלָּא שְׁלִים כְּדְקָא יְאוּת. תִּקּוּנָא עִלָּאָה, תִּקּוּנָא סָתִים וְגַלְיָא, דְּהָא תִּקּוּנָא דְיוֹבֵלָא אִיהוּ, הַהוּא דְּאָמַר שְׁלֹמֹה בְּשִׁיר הַשִּׁירִים כִּדְקָאֲמָרָן, רֵישָׁא סָתִים הֲוָה דְּלָא אִתְגַּלְּיָיא הָכָא, וְלָא יָאוֹת לְאִתְגַּלְּיָיא. דְּרוֹעִין וְגוּפָא אִתְגַּלְּיָין, וְהָא יְדִיעִין. שׁוֹקִין סְתִימוּ וְלָא אִתְגַלְּיָין. מַאי טַעְמָא, בְּגִין דִּנְבוּאָה לָא שַׁרְיָא אֶלָּא בְּאַרְעָא קַדִּישָׁא. וְתִקּוּנָא דָא סָתִים וְגַלְיָיא.</p>\n<p>תִּקּוּנָא אָחֳרָא תַּתָּאָה, תִּקּוּנָא דְּכַלָּה דְּקָאֲמַר שְׁלֹמֹה בְּשִׁיר הַשִּׁירִים, הַאי תִּקּוּנָא דְּאִתְגַּלְּיָיא יַתִּיר, וְתִקּוּנָא דָא בִּתְרֵיסַר שִׁבְטִין <Nonei></i>דְּאִינוּן תְּחוֹתָהּ, וְתִקּוּנָא דְגוּפָא דִילָהּ.</p>"],[9520011487,"<p>פָּתַח רִבִּי אַבָּא וְאָמַר, (מלכים א ז׳:כ״ג) וַיַּעַשׂ אֶת הַיָּם מוּצָק וְגו'. וּכְתִיב עוֹמֵד עַל שְׁנֵי עָשָׂר בָּקָר שְׁלשָׁה פּוֹנִים צָפוֹנָה וּשְׁלשָׁה פּוֹנִים יָמָּה וּשְׁלשָׁה פּוֹנִים נֶגְבָּה וְגו' (רמ\"ו ע\"א) וְהַיָּם עֲלֵיהֶם מִלְּמַעְלָה וְגו'. וּכְתִיב וְאֶת הַבָּקָר שְׁנֵים עָשָׂר תַּחַת הַיָּם (וגו'). עוֹמֵד עַל שְׁנֵי עָשָׂר בָּקָר, הָכִי הוּא וַדַּאי, דְּדָא יָם מִתַּקְנָא בְּי\"ב בִּתְרֵין עָלְמִין, בִּתְרֵיסַר לְעֵילָא רְתִיכִין מְמַנָּן. לְעֵילָא בִּתְרֵיסַר, לְתַתָּא תְּרֵיסַר שִׁבְטִין. כֵּיוָן דְּחָמָא יַעֲקֹב תִּקּוּנָא עִלָּאָה, וְחָמָא שְׁכִינְתָּא קָאִים לְקֳבְלֵיהּ, בָּעָא לְאַשְׁלָמָא תִּקּוּנָהָא, קָרָא לִבְנוֹהִי תְּרֵיסַר, וְאָמַר לוֹן הֵאָסְפוּ. אַתְקִינוּ גַרְמַיְיכוּ לְאַשְׁלָמָא מְהֵימְנוּתָא.</p>\n<p>תָּא חֲזֵי, תְּרֵיסַר שִׁבְטִין, בְּד' דִּגְלִין, בְּד' סִטְרִין, שְׁלשָׁה פּוֹנִים צָפוֹנָה וּשְׁלשָׁה פּוֹנִים יָמָה וּשְׁלשָׁה פּוֹנִים נֶגְבָּה וּשְׁלשָׁה פּוֹנִים מִזְרָחָה וְהַיָּם עֲלֵיהֶם. וְהָכִי הוּא וַדַּאי, תְּלַת שִׁבְטִין לְכָל סְטַר לְד' רוּחֵי עַלְמָא, וּתְלַת שִׁבְטִין לִדְרוֹעָא דִּימִינָא, וּתְלַת שִׁבְטִין לִדְרוֹעָא דִשְׂמָאלָא, וּתְלַת שִׁבְטִין, לְיַרְכָא יְמִינָא, וּתְלַת שִׁבְטִין לְיַרְכָא שְׂמָאלָא, וְגוּפָא דִשְׁכִינְתָּא עֲלַיְיהוּ. הֲדָא הוּא דִכְתִיב, וְהַיָּם עֲלֵיהֶם.</p>\n<p>מַאי טַעְמָא תְּלַת שִׁבְטִין לִדְרוֹעָא, וּתְלַת שִׁבְטִין לְיַרְכָא, וְכֵן לְכֹלָּא. אֶלָּא רָזָא דְמִלָּה, תְּלַת קִשְׁרִין אִינוּן בִּדְרוֹעָא יְמִינָא, וּתְלַת בִּשְׂמָאלָא, וּתְלַת בְּיַרְכָא יְמִינָא, וּתְלַת קִשְׁרִין בְּיַרְכָא שְׂמָאלָא, אִשְׁתַּכָּחוּ תְּרֵיסַר קִשְׁרִין לְאַרְבַּע סִטְרִין, וְגוּפָא עֲלַיְיהוּ. אִשְׁתַּכָּחוּ תְּרֵיסַר עִם גּוּפָא כְּגַוְונָא דִלְעֵילָא. מְנָא לָן, דִּכְתִיב, כָּל אֵלֶּה שִׁבְטֵי יִשְׂרָאֵל שְׁנֵים עָשָׂר. וְזֹאת, בְּגִין דְּבָהּ אִשְׁתְּלִים חוּשְׁבְּנָא, כְּמָה דְאִתְּמָר וְהַיָּם עֲלֵיהֶם מִלְּמָעְלָה.</p>\n<p>(זכריה ד׳:י׳) שִׁבְעָה עֵינֵי ה', אִינוּן שִׁבְעָה עֵינֵי הָעֵדָה. שִׁבְעִין סַנְהֶדְּרִין. שַׂעֲרָהָא, כְּמָה דִכְתִיב, (במדבר כ) כָּל הַפְּקוּדִים לְמַחֲנֵה יְהוּדָה מְאַת אֶלֶף וְגו'. כָּל הַפְּקוּדִים לְמַחֲנִה רְאוּבֵן, וְכֵן לְכֻלְּהוּ.</p>\n<p>וְאִי תֵימָא, בְּמִצְרַיִם בִּסְלִיקוּ דְיַעֲקֹב מֵעַלְמָא, דְּאִשְׁתַּכַּח שְׁלִימוּ בְּהַהִיא שַׁעְתָּא, כּוּלֵּי הַאי אָן הוּא. וַדַּאי שִׁבְעִין נַפְשִׁין הֲווּ, וְכָל אִינוּן דְּאוֹלִידוּ בִּשְׁבַע עֶשְׂרֵה שְׁנִין, דְּלֵית לוֹן חוּשְׁבְּנָא. כְּמָה דִכְתִיב (שמות א׳:ז׳) וּבְנֵי יִשְׂרָאֵל פָּרוּ וַיִּשְׁרְצוּ וַיִּרְבּוּ וַיַּעַצְמוּ בִּמְאֹד מְאֹד. וּכְתִיב, (תהילים מ׳:י״ג) עָצְמוּ מִשַּׂעֲרוֹת רֹאשִׁי. זַכָּאָה חוּלָקֵיהּ דְּיַעֲקֹב שְׁלֵימָא, דְּהוּא אִשְׁתְּלִים לְעֵילָא וְתַתָּא.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, וַדַּאי הָכִי הוּא, אֲבָל בְּתִקּוּנָא עִלָּאָה דְּיוֹבֵלָא, הֵיךְ אִשְׁתַּכַּח כּוּלֵּי הַאי. אָמַר לֵיהּ, אַרְיָא, כֵּיוָן דְּסַדַּר רַגְלוֹי לְמֵיעָאל בְּכַרְמָא, מַאן אִיהוּ דְּעָיִיל בַּהֲדֵיהּ.</p>\n<p>פָּתַח רִבִּי אֶלְעָזָר וְאָמַר, (איוב כ״ג:י״ג) וְהוּא בְּאֶחָד וּמִי יְשִׁיבֶנּוּ וְנַפְשׁוֹ אִוְתָה וַיָּעַשׂ. הַאי תִּקּוּנָא עִלָּאָה, הוּא כֹּלָּא חַד, לָא הֲוֵי בֵּיהּ פִּירוּדָא כְּהַאי תַּתָּאָה, דְּהָא כְּתִיב, (בראשית ב׳:י׳) וּמִשָּׁם יִפָּרֶד וְהָיָה לְאַרְבָּעָה רָאשִׁים. וְאַף עַל גַּב דְּאִית בֵּיהּ פִּירוּדָא, כַּד יִסְתַּכְּלוּן מִלֵּי, כֹּלָּא סַלְקָא לְחַד.</p>\n<p>אֲבָל הַאי תִּקּוּנָא עִלָּאָה דְיוֹבֵלָא, קָיְימָא עַל תְּרֵיסַר, כְּהַאי תַּתָּאָה. וְאַף עַל גַּב דְּאִיהוּ חַד, הַאי חַד אַשְׁלִים לְכָל סְטַר, בְּהַאי סְטַר, וּבְהַאי סְטַר. אִינוּן שִׁית סִטְרִין עִלָּאִין תְּרִיסַר הֲווּ. דְּכָל חַד אוֹזִיף לְחַבְרֵיהּ, (קנ\"ח ע\"א) וְאִתְכְּלִיל מִנֵּיהּ, וְאִשְׁתַּכָּחוּ תְּרֵיסַר, וְגוּפָא, וְכֹלָּא קָיְימָא עַל תְּרֵיסַר. מַאן גּוּפָא, דָּא יַעֲקֹב, וְהָא אִתְּמָר, אֶלָּא רֵישָׁא וְגוּפָא בְּחַד קָיְימֵי.</p>\n<p>תוּ תְּרֵיסַר, תְּלַת קִשְׁרִין דִּדְרוֹעָא יְמִינָא חֶסֶ\"ד חֲסָדִים. תְּלַת קִשְׁרִין דִּדְרוֹעָא שְׂמָאלָא גְּבוּרָ\"ה גְּבוּרוֹת. תְּלַת קִשְׁרִין בְּיַרְכָא יְמִינָא, נְצַ\"ח נְצָחִים. תְּלַת קִשְׁרִין בְּיַרְכָא שְׂמָאלָא, הוֹ\"ד וְהוֹדוֹת. הָא תְּרֵיסַר. וְגוּפָא קָיְימָא עֲלַיְיהוּ הָא תְּלֵיסַר. תּוּ, בִּתְלֵיסַר מְכִילָן אוֹרַיְיתָא אִתְפְּרַשׁ, וְכֹלָּא חַד, מֵעֵילָא לְתַתָּא בְּיִחוּדָא, עַד הַהוּא אֲתַר דְּקָיְימָא עַל פִּירוּדָא.</p>\n<p>שִׁבְעָה עַיְנִין עִלָּאִין, אִלֵּין דִּכְתִיב, (זכריה ד׳:י׳) עֵינִי ה' הֵמָּה מְשׁוֹטְטִים דְּכוּרִין, דְּהָא אֲתַר דִּדְכוּרָא אִיהוּ. הָכָא (דברי הימים ב טז) עֵינֵי ה' מְשׁוֹטְטוֹת, בְּתִקּוּנֵי שְׁכִינְתָּא לְתַתָּא, אֲתַר דְּנוּקְבָא (זהר חדש ל\"ג קיימא). שִׁבְעָה עַיְנִין עִלָּאִין, לָקֳבֵיל הָא דִכְתִיב, (דברי הימים א כ״ט:י״א) לְךָ ה' <Nonei></i>הַגְּדוּלָּה וְהַגְּבוּרָה וְגו'. הַאי אֲתַר, אַשְׁלִים לְכָל סְטַר.</p>\n<p>תוּ שַׂעֲרָא, כְּמָה דִכְתִיב, (תהילים ק״ו:ב׳) מִי יְמַלֵּל גְּבוּרוֹת ה'. הֲדָא הוּא דִכְתִיב, (תהילים מ׳:י״ג) עָצְמוּ מִשַּׂעֲרוֹת רֹאשִׁי. וּכְתִיב, (איכה ג׳:כ״ב) חַסְדֵּי ה' כִּי לֹא תָמְנוּ וְגו'. וְתִקּוּנִין אִלֵּין אִסְתַּלָּקוּ (מאתר) לְאֲתַר אָחֳרָא. וְאַף עַל גַּב דְּהָכָא אִתְּמָר טְפֵי, וְאִסְתַּלִּיק בְּמַתְקְלָא עִלָּאָה וְתַתָּאָה, וּשְׁלֹמֹה מַלְכָּא אֲמָרָן, וְאִצְטָרִיכְנָא לְפָרְשָׁא לוֹן. זַכָּאָה חוּלְקֵהוֹן דְּצַדִּיקַיָא יַתִּיר, דְּיָדְעִין אָרְחָא דְקוּדְשָׁא בְּרִיךְ הוּא, וְהָכָא כֹּלָּא אִתְגַּלְּיָיא לְיָדְעֵי מִדִּין.</p>"],[9520011488,"<p>אָמַר רִבִּי יְהוּדָה, זְבוּלֻן וְיִשָּׂשכָר תְּנַאי עֲבָדוּ, חַד יָתִיב וְלָעֵי בְּאוֹרַיְיתָא, וְחַד נָפִיק וְעָבִיד פְּרַקְמַטְיָא, וְתָמִיךְ לְיִשָּׂשכָר, דִּכְתִיב, (משלי ג) וְתוֹמְכֶיהָ מְאוּשָּׁר. וְהֲוָה פָּרִישׁ בְּיַמֵּי לְמֶעְבַּד פְּרַקְמַטְיָא, וְחוּלָקֵיהּ הָכִי הֲוָה, דְּהָא יַמָּא הֲוָה אַחְסַנְתֵּיהּ.</p>\n<p>וּבְגִינִי כָּךְ קָרֵי לֵיהּ יָרֵךְ. דַּרְכֵּיהּ דְּיָרֵךְ לְנַפְקָא וּלְמֵיעַל, הֲדָא הוּא דִכְתִיב, (דברים ל״ג:י״ח) שְׂמַח זְבוּלוּן בְּצֵאתֶךָ וְיִשָּׂשכָר בְּאֹהֳלֶךָ. לְחוֹף יַמִּים יִשְׁכּוֹן, בְּאִינוּן פְּרִישֵׁי יַמִּים, לְמֶעְבַּד פְּרַקְמַטְיָא. לְחוֹף יַמִּים, אַף עַל גַּב דְּחַד יַמָּא הֲוָה לֵיהּ בְּאַחְסַנְתֵּיהּ, בִּתְרֵין יַמִּין שָׁרְיָיא.</p>\n<p>רִבִּי יוֹסֵי אָמַר, כָּל שְׁאָר יַמִּין הֲווּ מְהַדְּרָן קַרְפּוֹלִין בְּיַמָּא דִילֵיהּ. וְהוּא לְחוֹף אֳנִיּוֹת, אֲתַר דְּכָל אַרְבִין מִשְׁתַּכְּחִין לְמֶעְבַּד סְחוֹרָתָא. וְיַרְכָתוֹ, אָמַר רִבִּי חִזְקִיָּה יַרְכָתֵיהּ דִּילֵיהּ מָטֵי עַל סְפַר צִידוֹן, וּתְחוּמָא פָּרִישׁ לְהַהוּא אֲתַר, וּפְרַקְמַטְיָא דְּכָל מָארֵי סְחוֹרָתָא, סָחֲרִין וְתָיְיבִין בִּסְחוֹרָתַיְהוּ לְהַהוּא אֲתַר.</p>\n<p>רִבִּי אַחָא אָמַר, כְּתִיב, (ויקרא ב׳:י״ג) וְלא תַשְׁבִּית מֶלַח בְּרִית אֱלֹהֶיךָ מֵעַל מִנְחָתֶךָ עַל כָּל קָרְבָּנְךָ תַּקְרִיב מֶלַח, וְכִי אַמַּאי מֶלַח. אֶלָּא בְּגִין דְּאִיהוּ מְמָרֵק וּמְבַשֵּׂם מְרִירָא לְאַטְעָמָא, וְאִי לָאו הֲוֵי (בגין) מִלְחָא, לָא יָכִיל עַלְמָא לְמִסְבַּל מְרִירָא. הֲדָא הוּא דִכְתִיב, (ישעיהו כ״ו:ט׳) כִּי כַּאֲשֶׁר מִשְׁפָּטֶיךָ לָאָרֶץ צֶדֶק לָמְדוּ יוֹשְׁבֵי תֵבֵל. וּכְתִיב, (תהילים פ״ט:ט״ו) צֶדֶק וּמִשְׁפָּט מְכוֹן כִּסְאֲךָ.</p>\n<p>וּמֶלַח אִיהוּ בְּרִית דְּעַלְמָא קָיְימָא בֵּיה. דִּכְתִיב, (ירמיהו ל״ג:כ״ה) אִם לא בְרִיתִי יוֹמָם וְלַיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לא שָׂמְתִּי. בְּגִין כָּךְ, אִקְרֵי בְּרִית אֱלֹהֶיךָ, וְאִקְרֵי יַם הַמֶּלַח, וְיַמָּא אִקְרֵי עַל שְׁמֵיהּ.</p>\n<p>רִבִּי חִיָּיא אָמַר, כְּתִיב, (תהילים י״א:ז׳) כִּי צַדִּיק ה' צְדָקוֹת אָהֵב, דָּא מִלְחָא בְּיַמָּא (במיא). וּמַאן דְּפָּרִישׁ לוֹן, גָּרִים לְגַרְמֵיהּ מִיתָה. בְגִין כָּךְ כְּתִיב, לֹא תַשְׁבִּית מֶלַח, דְּהָא דָא בְּלָא דָא לָא אָזְלָא.</p>\n<p>אָמַר רִבִּי אַחָא, יַם חַד הוּא, וְאִקְרֵי (שמות מח) יַמִּים. אֶלָּא אֲתַר אִית בְּיַמָּא דְּאִיהוּ מַיִין צְלִילָן, וַאֲתַר דְּאִית בֵּיהּ מַיִין מְתִיקָן, וַאֲתַר דְּאִית בֵּיהּ מַיִין מְרִירָן, בְגִין כָּךְ יַמִּים קָרִינָן, וְעַל דָּא לְחוֹף יַמִּים. אָמַר רִבִּי אַבָּא, כָּל שִׁבְטָא וְשִׁבְטָא, וְכָל חַד וְחַד קִשְׁרָא חַד, מֵאִינוּן קִשְׁרִין דְּמִתְחַבְּרָן בְּגוּפָא.</p>\n<p>רִבִּי אַבָּא הֲוָה יָתִיב לֵילְיָא חַד וְקָם לְמִלְעֵי בְּאוֹרַיְיתָא. עַד דְּהֲוָה יָתִיב, אֲתָא רִבִּי יוֹסֵי, וּבָטַשׁ אֲפִתְחָא. אָמַר, סִיפְטָא בְּטוּפְסְרָא קַפְּטְלָאי שְׁכִיחֵי.</p>\n<p>יָתְבוּ וְלָעוּ בְּאוֹרַיְיתָא. אַדְהָכִי קָם בְּרֵיהּ דְּאוּשְׁפִּיזָא וְיָתִיב קַמַּיְיהוּ, אָמַר לוֹן מַאי דִכְתִיב, (יהושע ב׳:י״ב) וְהַחֲיִיתֶם אֶת אָבִי וְאֶת אִמִּי וְגו'. וּכְתִיב וּנְתַתֶּם לִי אוֹת אֱמֶת. מַאי קָא בָּעַאת מִנַּיְיהוּ. אָמַר רִבִּי אַבָּא יָאוֹת שָׁאַלְתְּ, אֲבָל אִי שָׁמַעְתְּ מִידִי אֵימָא בְּרִי. אָמַר, תוּ שְׁאֵלְתָּא, דְּהָא אִינוּן יַהֲבוּ לָהּ מַה דְּלָא בָעַאת מִנַּיְיהוּ, דִּכְתִיב, אֶת תִּקּ1ות חוּט הַשָּׁנִי הַזֶּה תִּקְשְׁרִי בַּחֲלוֹן וְגו'.</p>\n<p>אֶלָּא הָכִי אוֹלִיפְנָא, הִיא בָּעַאת סִימָנָא דְחַיֵּי, דִּכְתִיב וְהַחֲיִיתֶם אֶת אָבִי וְגו', וַאֲמָרָה, סִימָנָא דְחַיֵּי לָא שַׁרְיָיא, אֶלָא בְּאוֹת אֱמֶת, וּמַאי אִיהוּ (ויקרא ב ע\"א) אוֹת אֱמֶת, דָּא אָת ו', בְּגִין דְּבֵיהּ שַׁרְיָין חַיִּין. הָכִי אוֹלִיפְנָא, סִימָנָא דְמשֶׁה קָא בָּעַאת, וְאִינוּן אַמַּאי יַהֲבוּ לָהּ תִּקְוַת חוּט הַשָּׁנִי.</p>\n<p>אֶלָּא אִינוּן אָמְרֵי, משֶׁה הָא אִסְתַּלַּק מֵעַלְמָא, דְּהָא אִתְכְּנִישׁ שִׁמְשָׁא, וְהָא מָטָא זִמְנָא דְסִיהֲרָא לְמִשְׁלַט, סִימָנָא דְּסִיהֲרָא אִית לָן לְמֵיהַב לָךְ, וּמַאי אִיהוּ, תִּקּ1ות חוּט הַשָּׁנִי הַזֶּה. כְּמָא דְאַתְּ אָמֵר, (שיר השירים ד׳:ג׳) כְּחוּט הַשָּׁנִי שִׂפְתוֹתַיִךְ. סִימָנָא דִיהוֹשֻׁעַ יְהֵא גַבָּךְ, בְּגִין דְּשׁוּלְטָנוּתָא דְסִיהֲרָא הַשְׁתָּא. קָמוּ רִבִּי אַבָּא וְרִבִּי יוֹסֵי <Nonei></i>וּנְשָׁקוּהוּ. אָמְרוּ, וַדַּאי זַמִּין אַנְתְּ לְמֶהֱוֵי רֵישׁ מְתִיבְתָּא, אוֹ גַבְרָא רַבָּא בְּיִשְׂרָאֵל, וּמַנּוּ. רִבִּי בּוֹן.</p>\n<p>תוּ שָׁאִיל וְאָמַר, בְּנוֹי דְיַעֲקֹב כֻּלְּהוּ תְּרֵיסַר שִׁבְטִין, אִתְסַדְּרוּ לְתַתָּא כְּגַוְונָא דִלְעֵילָא, אַמַּאי אַקְדִּים בְּבִרְכָאן זְבוּלוּן לְיִשָּׂשכָר תָּדִיר, וְהָא יִשָּׂשכָר אִשְׁתַּדְּלוּתֵיהּ בְּאוֹרַיְיתָא, וְאוֹרַיְיתָא אַקְדִּים בְּכָל אֲתַר, אַמַּאי אַקְדִּים לֵיהּ זְבוּלוּן בְּבִרְכָאן. אֲבוֹי אַקְדִּים לֵיהּ, משֶׁה אַקְדִּים לֵיהּ.</p>\n<p>אֶלָּא זְבוּלוּן זָכָה עַל דְּאֲפִיק פִּתָּא מִפּוּמֵיהּ, וְיָהַב לְפוּמֵיהּ דְּיִשָּׂשכָר, בְּגִינֵי כָּךְ אַקְדִּים לֵיהּ בְּבִרְכָאן. מֵהָכָא אוֹלִיפְנָא, מַאן דְּסָעִיד לְמָרֵיהּ דְּאוֹרַיְיתָא, נָטִיל בִּרְכָאן מֵעֵילָא וְתַתָּא. וְלָא עוֹד אֶלָּא דְזָכֵי לִתְרֵי פָּתוֹרֵי, מַה דְּלָא זָכֵי בַּר נָשׁ אַחֲרָא. זָכֵי לְעוּתְרָא דְיִתְבָּרַךְ בְּהַאי עַלְמָא, וְזָכֵי לְמֶהֱוֵי לֵיהּ חוּלָקָא בְּעַלְמָא דְאָתֵי. הֲדָא הוּא דִכְתִיב, זְבוּלוּן לְחוֹף יַמִּים יִשְׁכּוֹן וְהוּא לְחוֹף אֳנִיּוֹת. כֵּיוָן דִּכְתִיב לְחוֹף יַמִּים, אַמַּאי וְהוּא לְחוֹף אֳנִיּוֹת. אֶלָּא, לְחוֹף יַמִּים, בְּעַלְמָא דֵין. לְחוֹף אֳנִיּוֹת, בְּעַלְמָא דְאָתֵי, כְּמָא דְאַתְּ אָמֵר, (תהילים ק״ד:כ״ו) שָׁם אֳנִיּוֹת יְהַלֵּכוּן וְגו', דְּתַמָּן הוּא נְגִידוּ דְעַלְמָא דְאָתֵי.</p>"],[9520011489,"<p>פָּתַח וְאָמַר, (שיר השירים ג׳:ה׳) הִשְׁבַּעְתִּי אֶתְכֶם בְּנוֹת יְרוּשָׁלַיִם אִם תִּמְצְאוּ אֶת דּוֹדִי מַה תַּגִּידוּ לוֹ שֶׁחוֹלַת אַהֲבָה אָנִי. וְכִי מַאן קָרִיב לְמַלְכָּא כִּכְנְסֶת יִשְׂרָאֵל, דְּאִיהִי אָמְרַת אִם תִּמְצְאוּ אֶת דּוֹדִי מַה תַּגִּידוּ לוֹ. אֶלָּא בְּנוֹת יְרוּשָׁלַיִם, אִלֵּין אִינוּן נִשְׁמַתְהוֹן דְּצַדִּיקַיָיא דְּאִינוּן קְרֵיבִין לְמַלְכָּא תָּדִיר, וּמוֹדְעִין לְמַלְכָּא בְּכָל יוֹמָא עִסְקוֹי דְמַטְרוֹנִיתָא.</p>\n<p>דְּהָכִי אוֹלִיפְנָא, בְּשַׁעְתָּא דְנִשְׁמָתָא נָחֲתַת לְעַלְמָא, כְּנֶסֶת יִשְׂרָאֵל עָאלַת עֲלָהּ בְּקִיּוּמָא דְאוֹמָאָה, דִּיחֲוֵי לְמַלְכָּא, וְיוֹדַע לֵיהּ רְחִימוּתָא דִילָהּ לְגַבֵּיהּ, בְּגִין לְאִתְפַּיְיסָא בַּהֲדֵיהּ.</p>\n<p>וּבְמָּה, בְּגִין דְּחִיּוּבָא עַל בַּר נָשׁ לְיַחֲדָא שְׁמָא קַדִּישָׁא בְּפוּמָא, בְּלִבָּא בְּנַפְשָׁא, וּלְאַקְּשְּׁרָא כֹּלָּא, כְּשַׁלְּהוֹבָא דְּאִתְקַשְּׁרָא בְּטִיפְסָא, וּבְהַהוּא יִחוּדָא דְּעָבִיד, גָּרִים לְאִתְפַּיְיסָא מַלְכָּא בְּמַטְרוֹנִיתָא, וְאוֹדַע לֵיהּ לְמַלְכָּא רְחִימוּתָא דִילָהּ לְגַבֵּיהּ.</p>\n<p>דָּבָר אַחֵר, בְּנוֹת יְרוּשָׁלַם, אִלֵּין תְּרֵיסַר שִׁבְטִין. דְּתָנִינָן, יְרוּשָׁלַ ם עַל תְּרֵיסַר טוּרִין קָיְימָא. וּמַאן דְּאָמַר עַל שִׁבְעָה, לָא קָאֲמַר לְאַשְׁלָמָא שְׁלִימוּ, וְאַף עַל גַּב דְּכֹלָּא חַד, דְּאִית שִׁבְעָה, וְאִית ד', וְאִית תְּרֵיסַר, וְכֹלָּא חַד.</p>\n<p>וַדַּאי עַל תְּרֵיסַר טוּרִין קָיְימָא, תְּלַת טוּרִין לְסִטְרָא דָא, וּתְלַת טוּרִין לְסִטְרָא דָא, וְכֵן לְאַרְבַּע זִוְויָין, וּכְדֵין אִתְקְרֵי חַיָּה. כְּמָא דְאַתְּ אָמֵר, (יחזקאל י׳:כ׳) הִיא הַחַיָּה אֲשֶׁר רָאִיתִי תַּחַת אֱלֹהֵי יִשְׂרָאֵל. וְאִלֵּין אִקְרוּן בְּנוֹת יְרוּשָׁלַיִם, בְּגִין דְּקָיְימָא עֲלַיְיהוּ. וְאִינוּן סָהֲדֵי סַהֲדוּתָא לְמַלְכָּא עַל כְּנֶסֶת יִשְׂרָאֵל. הֲדָא הוּא דִכְתִיב, (תהילים קכ״ב:ד׳) שִׁבְטֵי יָהּ עֵדוּת לְיִשְׂרָאֵל לְהוֹדוֹת לְשֵׁם יְיָ. אָמַר רִבִּי יְהוּדָה, זַכָּאָה חוּלְקֵהוֹן דְּיִשְׂרָאֵל, דְּיָדְעֵי אוֹרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, עֲלַיְיהוּ כְּתִיב, (דברים י״ד:ב׳) כִּי עַם קָדוֹשׁ אַתָּה לַיְיָ אֱלהֶיךָ וּבְךָ בָּחַר יְיָ וְגו':</p>"],[9520011490,"<p>יִשָּׂשכָר חֲמוֹר גָּרֶם רוֹבֵץ בֵּין הַמִּשְׁפְּתָיִם. אָמַר רִבִּי אֶלְעָזָר, וְכִי יִשָּׂשכָר חֲמוֹר אִקְרֵי. אִי בְּגִין דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא, נִקְרְיֵיהּ לֵיהּ סוּס אוֹ אַרְיֵהּ, אוֹ נָמֵר, אַמַּאי חֲמוֹר. אֶלָּא אָמְרוּ, בְּגִין דַּחֲמוֹר נָטִיל מָטוּלָא, וְלָא בָּעִיט בְּמָארֵיהּ כִּשְׁאָר בְּעִירֵי, וְלָא אִית בֵּיהּ גַּסּוּת הָרוּחַ, וְלָא חַיִּישׁ לְמִשְׁכַּב בְּאֲתַר מִתְתַּקַּן. אוּף הָכִי יִשָּׂשכָר, דְּאִשְׁתַּדְּלוּתֵיהּ בְּאוֹרַיְיתָא, נָטִיל מָטוּלָא דְאוֹרַיְיתָא, וְלָא בָּעִיט בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, וְלָא אִית בֵּיהּ גַּסּוּת הָרוּחַ, כַּחֲמוֹר דְּלָא חָיִישׁ לִיקָרָא דִילֵיהּ, אֶלָּא לִיקָרָא דְמָרֵיהּ (ס\"א דרביה). רוֹבֵץ בֵּין הַמִּשְׁפְּתָיִם, כִּדְאַמְרִינָן וְעַל הָאָרֶץ תִּישַׁן, וְחַיֵּי צַעַר תִּחְיֶה, וּבַתּוֹרָה אַתָּה עָמֵל.</p>\n<p>דָּבָר אַחֵר יִשָּׂשכָּר חֲמוֹר גָּרֶם רוֹבֵץ וְגו'. פָּתַח וְאָמַר, (תהילים כ״ז:א׳) לְדָוִד ה' אוֹרִי וְיִשְׁעִי מִמִּי אִירָא יְיָ מָעוֹז חַיַּי מִמִּי אֶפְחָד, כַּמָּה חֲבִיבִין אִינוּן מִלִּין דְּאוֹרַיְיתָא, כַּמָּה חֲבִיבִין אִינוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא. דְּכָל מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא, לָא דָחִיל מִפִּגְעֵי עַלְמָא, נָטִיר הוּא לְעֵילָא, נָטִיר הוּא לְתַתָּא. וְלָא עוֹד, אֶלָּא <Nonei></i>דְּכָפִית לְכָל פְּגִיעֵי דְעַלְמָא, וְאָחִית לוֹן לְעוּמְקֵי דִתְהוֹמָא רַבָּא.</p>\n<p>תָּא חֲזֵי, בְּשַׁעְתָּא דְּעָאל לֵילְיָא, (לעיל קע\"ב ע\"א) פָּתְחִין סְתִימִין, וְכַלְבֵּי וַחֲמָרֵי שַׁרְיָין וְשָׁטָאן בְּעַלְמָא, וְאִתְיְיהִיבַת רְשׁוּ לְחַבָּלָא, וְכָל בְּנֵי עַלְמָא נַיְימֵי בְּעַרְסַיְיהוּ, וְנִשְׁמַתְהוֹן דְּצַדִּיקַיָיא סָלְקִין לְאִתְעֲנָגָא לְעֵילָא. כַּד אִתְעַר רוּחַ צָפוֹן, וְאִתְפְּלִיג לֵילְיָא, אִתְעֲרוּתָא קַדִּישָׁא אִתְעַר בְּעַלְמָא, וְאִתְּמָר בְּכַמָּה דוּכְתֵּי.</p>\n<p>זַכָּאָה חוּלָקֵיהּ דְּהַהוּא בַּר נָשׁ, דְּאִיהוּ קָאִים בְּהַהִיא שַׁעְתָּא, וְאִשְׁתְּדָּל בְּאוֹרַיְיתָא. כֵּיוָן דְּאִיהוּ פָּתַח בְּאוֹרַיְיתָא, כָּל אִינוּן זִינִין בִּישִׁין, אָעִיל לוֹן בְּנוּקְבֵי דִתְהוֹמָא רַבָּה, וְכָפִית לֵיהּ לַחֲמוֹר, וְנָחִית לֵיהּ בְּטַפְסְרֵי דִּתְחוֹת עַפְרָא, דְּזוּהֲמֵי קִסְרָא.</p>\n<p>בְּגִינֵי כָּךְ, יִשָּׂשכָר, דְּאִשְׁתַּדְּלוּתֵיהּ בְּאוֹרַיְיתָא, כָּפֵית לֵיהּ לַחֲמוֹר, וְנָחִית לֵיהּ. מֵהַהוּא גְרַם הַמַּעֲלוֹת, דְּאִיהוּ סָלִיק לְנִזְקָא עַלְמָא, וְשַׁוֵּי מָדוֹרֵיהּ בֵּין הַמִּשְׁפְּתָיִם, בֵּין זוּהֲמֵי דְטַפְסְרִי דְעַפְרָא.</p>\n<p>תָּא חֲזֵי, מַה כְּתִיב. וַיַּרְא מְנוּחָה כִּי טוֹב וְאֶת הָאָרֶץ כִּי נָעֵמָה וַיֵּט שִׁכְמוֹ לִסְבּוֹל וַיְהִי לְמַס עוֹבֵד. וַיַּרְא מְנוּחָה כִּי טוֹב, דָּא תּוֹרָה שֶׁבִּכְתָב. וְאֶת הָאָרֶץ כִּי נָעֵמָה, דָּא תּוֹרָה שֶׁבְּעַל פֶּה. וַיֵּט שִׁכְמוֹ לִסְבּוֹל, לְמִסְבַּל עוּלָא דְאוֹרַיְיתָא, וּלְדָבְקָא בָּהּ יוֹמֵי וְלֵילֵי. וַיְהִי לְמַס עוֹבֵד, לְמֶהוֵי פָּלַח לְקוּדְשָׁא בְּרִיךְ הוּא, וּלְאִתְדַּבְּקָא בֵּיהּ, וּלְאַתָּשָׁא גַרְמֵיהּ בָּהּ.</p>\n<p>רִבִּי שִׁמְעוֹן וְרִבִּי יוֹסֵי וְרִבִּי חִיָּיא הֲווּ קָא אָזְלֵי מִגָּלִילָא עִלָּאָה לִטְבֶרְיָה, אָמַר רַבִּי שִׁמְעוֹן, נֵיהַךְ וְנִשְׁתַּדַּל בְּאוֹרַיְיתָא, דְּכָל מַאן דְּיָדַע לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא, וְלָא אִשְׁתַּדַּל, אִתְחַיֵּיב בְּנַפְשֵׁיהּ. וְלָא עוֹד אֶלָּא דְּיַהֲבִין לֵיהּ עוּלָא דְאַרְעָא, וְשִׁעְבּוּדָא בִּישָׁא, דִּכְתִיב בְּיִשָּׂשכָר, וַיֵּט שִׁכְמוֹ לִסְבּוֹל, מַהוּ וַיֵּט, סָטָא. כְּמָא דְאַתְּ אָמֵר, (שמואל א ח׳:ג׳) וַיַּטּוּ אַחֲרֵי הַבָּצַע. מַאן דְּסָטָא אָרְחֵיהּ וְגַרְמֵיהּ, דְּלָא לְמִסְבַּל עוּלָא דְאוֹרַיְיתָא, מִיָּד וַיְהִי לְמַס עוֹבֵד.</p>\n<p>פָּתַח רִבִּי שִׁמְעוֹן וְאָמַר, (משלי ח׳:כ״א) לְהַנְחִיל אוֹהֲבַי יֵשׁ וְאוֹצְרוֹתֵיהֶם אֲמַלֵּא. זַכָּאִין אִינוּן בְּנֵי עַלְמָא, אִינוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, דְּכָל מַאן דְּאִשְׁתָּדַּל בְּאוֹרַיְיתָא, אִתְרָחִים לְעֵילָא, וְאִתְרָחִים לְתַתָּא, וְאַחְסִין בְּכָל יוֹמָא, יְרוּתָא דְעַלְמָא דְאָתֵי. הֲדָא הוּא דִכְתִיב, לְהַנְחִיל אוֹהֲבַי יֵשׁ. מַאי יֵשׁ. דָּא עַלְמָא דְאָתֵי דְלָא פָּסַק מֵימוֹי לְעָלְמִין, וְנָטַל אֲגַר טַב עִלָּאָה, דְּלָא זָכֵי בֵּיהּ בַּר נָשׁ אָחֳרָא, וּמַאי אִיהוּ. יֵ\"שׁ. וּבְגִינֵי כָּךְ, רָמִיז לָן שְׁמָא דְיִשָּׂשכָר דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא, יֵשׁ שָׂכָר. דָּא הוּא אַגְרָא דְּאִינוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, י\"ש.</p>\n<p>כְּתִיב, (דניאל ז׳:ט׳) חָזֵה הֲוֵית עַד דִּי כָרְסָוָון רְמִיו וְעַתִּיק יוֹמִין יְתִיב וְגו'. חָזֵה הֲוֵית עַד דִּי כָרְסָוָון רְמִיו, כַּד אִתְחָרַב בֵּי מַקְדְּשָׁא, תְּרֵי כָּרְסָוָון נָפְלוּ, תְּרֵי לְעֵילָא, תְּרֵי לְתַתָּא. תְּרֵי לְעֵילָא, בְּגִין דְּאִתְרְחִיקַת תַּתָּאָה מֵעִלָּאָה, כֻּרְסְיָיא דְיַעֲקֹב אִתְרְחִיקַת מִכֻּרְסְיָיא דְּדָוִד. וְכֻּרְסְיָיא דְּדָוִד נָפְלַת. הֲדָא הוּא דִכְתִיב, (איכה ב׳:א׳) הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ. תְּרִי כָּרְסָוָון לְתַתָּא, יְרוּשָׁלַ ם, וְאִינוּן מָארֵי דְאוֹרַיְיתָא. וְכָרְסָוָון דִּלְתַתָּא כְּגַוְונָא דְּכָרְסָוָון דִּלְעֵילָא, מָרֵיהוֹן דְּאוֹרַיְיתָא הַיְינוּ כֻּרְסְיָיא דְיַעֲקֹב. יְרוּשָׁלַ ם הַיְינוּ כֻּרְסְיָיא דְדָוִד, וְעַל דָא כְּתִיב, עַד דִּי כָּרְסָוָון, וְלָא כָּרְסְיָא. כָּרְסָוָון סַגִּיאִין נָפְלוּ, וְכֻלְּהוּ לָא נָפְלוּ, אֶלָּא מֵעֶלְבּוֹנָהּ דְּאוֹרַיְיתָא.</p>\n<p>תָּא חֲזֵי, כַּד אִינוּן זַכָּאֵי קְשׁוֹט מִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, כָּל אִינוּן תּוּקְפִין דִּשְׁאָר עַמִּין, דִּשְׁאָר חֵילִין, וְכָל חֵילִין דִּלְהוֹן, אִתְכַּפְיָין וְלָא שָׁלְטֵי בְּעַלְמָא, וְיִשְׂרָאֵל (נ\"א וי\"ש) אִזְדַּמַּן עֲלַיְיהוּ לְסַלְקָא לוֹן עַל כֹּלָּא. וְאִי לָא, חֲמוֹר גָּרְמָא לוֹן לְיִשְׂרָאֵל לְמֵיהַךְ בְּגָלוּתָא, וּלְמִנְפַּל בֵּינֵי עַמְּמַיָא, וּלְמִשְׁלַט עֲלַיְיהוּ. וְכָל דָּא אַמַּאי, בְּגִין, וַיַּרְא מְנוּחָה כִּי טוֹב, וּמִתַּקְנָא קַמֵּיהּ, וְיָכִיל לְמִרְוַוח בְּגִינָהּ כַּמָּה טָבִין וְכַמָּה כִּסּוּפִין, וְסָטָא אוֹרְחֵיהּ דְּלָא לְמִסְבַּל עוּלָא דְאוֹרַיְיתָא. בְגִין כָּךְ וַיְהִי לְמַס עוֹבֵד.</p>\n<p>כְּתִיב, (שיר השירים ו) הַדּוּדָאִים נָתְנוּ רֵיחַ וְעַל פְּתָחֵינוּ כָּל מְגָדִים חֲדָשִׁים גַּם יְשָׁנִים וְגו'. הַדּוּדָאִים נָתְנוּ רֵיחַ, (הדודאים) אִלֵּין אִינוּן דְּאַשְׁכַּח רְאוּבֵן. כְּמָא דְאַתְּ אָמֵר, (בראשית ל׳:י״ד) וַיִּמְצָא <Nonei></i>דּוּדָאִים בַּשָּׂדֶה, וְלָא אִתְחַדְּשָׁן מִלֵּי דְאוֹרַיְיתָא, אֶלָּא עַל יְדוֹי בְּיִשְׂרָאֵל, כְּמָא דְאַתְּ אָמֵר, (דברי הימים א י״ב:ל״ג) וּמִבְּנֵי יִשָּׂשכָר יוֹדְעֵי בִּינָה לְעִתִּים וְגו'.</p>\n<p>וְעַל פְּתָחֵינוּ כָּל מְגָדִים, אִינוּן גָּרְמוּ לְמֶהֱוֵי עַל פְּתָחֵינוּ, עַל פִּתְחֵי בָּתֵּי כְנִסִיּוֹת וּבָתֵּי מִדְרָשׁוֹת, כָּל מְגָדִים. חֲדָשִׁים גַּם יְשָׁנִים, כַּמָּה מִלֵּי חַדְּתָאן וְעַתִּיקִין דְּאוֹרַיְיתָא, דְּאִתְגַּלְּיָין עַל יָדַיְיהוּ, לְקָרְבָא לְיִשְׂרָאֵל לַאֲבוּהוֹן דִּלְעֵילָא. הֲדָא הוּא דִכְתִיב, (דברי הימים א י״ב:ל״ג) לָדַעַת מַה יַּעֲשֶׂה יִשְׂרָאֵל.</p>\n<p>(שיר השירים ז׳:י״ד) דּוֹדִי צָפַנְתִּי לָךְ. מֵהָכָא אוֹלִיפְנָא, כָּל מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא כְּדְקָא יְאוּת, וְיָדַע לְמֶחֱדֵי מִלִּין, וּלְחַדְּתוּתֵי מִלִּין כְּדְקָא יְאוּת, אִינוּן מִלִּין סָלְקִין עַד כֻּרְסְיָיא דְמַלְכָּא, וּכְנֶסֶת יִשְׂרָאֵל פָּתַח לוֹן תַּרְעִין, וְגָנִיז לוֹן. וּבְשַׁעְתָּא דְּעָאל קוּדְשָׁא בְּרִיךְ הוּא לְאִשְׁתַּעְשְׁעָא עִם צַדִּיקַיָּיא בְּגִנְתָא דְעֵדֶן, אֲפִיקַת לוֹן קַמֵּיהּ, וְקוּדְשָׁא בְּרִיךְ הוּא מִסְתַּכֵּל בְּהוּ וְחָדֵי, כְּדֵין קוּדְשָׁא בְּרִיךְ הוּא מִתְעַטַּר בְּעִטְּרִין עִלָּאִין, וְחָדֵי בְּמַטְרוֹנִיתָא, הֲדָא הוּא דִכְתִיב, חֲדָשִׁים גַּם יְשָׁנִים דּוֹדִי צָפַנְתִּי לָךְ. וּמֵהַהִיא שַׁעְתָּא, מִלּוֹי כְּתִיבִין בְּסִפְרָא, הֲדָא הוּא דִכְתִיב, (מלאכי ג׳:ט״ז) וַיִּכָּתֵב סֵפֶר זִכָּרוּן לְפָנָיו.</p>\n<p>זַכָּאָה חוּלָקֵיהּ, מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא כְּדְקָא יְאוּת, זַכָּאָה הוּא בְּהַאי עַלְמָא, וְזַכָּאָה הוּא בְּעַלְמָא דְאָתֵי. עַד הָכָא שׁוּלְטָנוּתָא דִיהוּדָה, דְּרוֹעָא דְּאִתְכְּלִיל בְּכֹלָא, בְּחֵילָא דְכָל סִטְרִין, תְּלַת קִשְׁרִין דִּדְרוֹעָא, לְאִתְגַּבְּרָא עַל כֹּלָּא:</p>"],[9520011491,"<p>דָּן יָדִין עַמּוֹ כְּאַחַד שִׁבְטֵי יִשְׂרָאֵל. רִבִּי חִיָּיא אָמַר, הַאי קְרָא הָכִי אִית לֵיה לְמֵימַר, דָּן יָדִין לְשִׁבְטֵי יִשְׂרָאֵל, אוֹ דָּן יָדִין לְשִׁבְטֵי יִשְׂרָאֵל כְּאֶחָד, מַהוּ דָּן יָדִין עַמּוֹ, וּלְבָתַר כְּאַחַד שִׁבְטֵי יִשְׂרָאֵל. אֶלָּא דָּן, הוּא דִּכְתִיב בֵּיהּ, (במדבר י׳:כ״ה) מְאַסֵּף לְכָל הַמַּחֲנוֹת, דְּהוּא יַרְכָא שְׂמָאלָא, וְאָזִיל לְבַתְרַיְיתָא.</p>\n<p>תָּא חֲזֵי, כֵּיוָן דִּיהוּדָה וּרְאוּבֵן נָטְלִין, לֵיוָאֵי וַאֲרוֹנָא פָּרְשִׂין דִּגְלִין, וְנָטִיל דִּגְלָא דְאֶפְרַיִם דְּאִיהוּ לְמַעֲרָב, יַרְכָא יְמִינָא נָטִיל, בְּקַפְסִירֵי קִסְטָא. וְאִי תֵימָא זְבוּלֻן דְּאִיהוּ עָאל, וְנָפִיק, דִּכְתִיב בֵּיהּ, (דברים ל״ג:י״ח) שְׂמַח זְבוּלֻן בְּצֵאתֶךָ, וּכְתִיב וְיַרְכָתוֹ וְגו'. אֶלָּא וַדַּאי, יְהוּדָה אִתְכְּלִיל מִכֹּלָּא.</p>\n<p>תָּא חֲזֵי, מַלְכוּ דִּלְעֵילָא אִתְכְּלִיל מִכֹּלָּא, וִיהוּדָה אִיהוּ מַלְכוּ תַּתָּאָה. כְּמָה דְמַלְכוּ עִלָּאָה אִתְכְּלִיל מִכֹּלָּא, הָכִי נָמֵי מַלְכוּ תַּתָּאָה, אִתְכְּלִיל מִכֹּלָּא מִגּוּפָא מִיַּרְכָא, בְּגִין לְאִתְגַּבְּרָא בְּתוּקְפֵיהּ.</p>\n<p>כְּתִיב, (דברים לג) מִימִינ\"וֹ אֵ\"שׁ דָּ\"ת לָמוֹ, (ע\"ד ע\"א) אוֹרַיְיתָא מִסִּטְרָא דִגְבוּרָה אִתְיְיהִיב (אתייהיבת), וּגְבוּרָה אִתְכְּלִיל בִּימִינָא, וּבְגוּפָא, וְיַרְכָא, וּבְכֹלָּא. הָכִי נָמֵי סִדְרָא קַדְמָאָה, יְהוּדָה אִיהוּ, מַלְכוּ דְּאָתֵי מִסְּטַר גְּבוּרָה, וְאִתְכְּלִיל בִּימִינָא בְּגוּפָא וּבְיַרְכָא, בְּכֹלָּא אִתְכְּלִיל. כְּמָה דְמַלְכוּ דִלְעֵילָא, אִתְכְּלִיל מִכֹּלָּא.</p>\n<p>סִדְּרָא תִּנְיָינָא רְאוּבֵן, דְּאִיהוּ לִסְטַר דָּרוֹם, וְדָרוֹם אִיהוּ יְמִינָא, וְכָל חֵילָא דִּימִינָא, יְהוּדָה נָטִיל לֵיהּ, בְּגִין דִּרְאוּבֵן (ס\"א אתעביד) אִתְעֲבִיר מִנֵּיהּ מַלְכוּ, כְּמָא דְאַתְּ אָמֵר פַּחַז כַּמַּיִם אַל תּוֹתַר, וְנָטִיל לֵיהּ יְהוּדָה, וְאִתְגַּבַּר בְּתוּקְפָא דִּימִינָא, דְּהֲוָה מֵרְאוּבֵן, וְכֵן כְּתִיב בְּדָוִד, (תהילים ק״י:א׳) נְאֻם יְיָ לַאדֹנִי שֵׁב לִימִינִי. בְּגִין דִּשְּׂמָאלָא אִתְכְּלִיל בִּימִינָא, וְאִתְתַּקַּף בְּחֵילֵיהּ, הֲדָא הוּא דִכְתִיב, (תהילים קי״ח:ט״ו) יְמִין יְיָ עוֹשָׂה חָיִל וְגו'. יְהוּדָה וּרְאוּבֵן תְּרֵין דְּרוֹעִין הֲווּ.</p>\n<p>סִדְּרָא תְּלִיתָאָה, אֶפְרַיִם, דְּאִיהוּ יַרְכָא יְמִינָא, וְנָטְלָא קַמֵּי שְׂמָאלָא תָּדִיר, וְדָן (דא) דְּאִיהוּ יַרְכָא שְׂמָאלָא, נָטִיל לְבַתְרַיְיתָא, וְעַל דָּא הוּא הַמְאַסֵּף לְכָל הַמַּחֲנוֹת לְצִבְאוֹתָם, וְאָזִיל לְבַתְרַיְיתָא.</p>\n<p>יְהוּדָה נָטִיל חֵילָא בִּתְרֵין דְּרוֹעִין, בְּגִין דִּרְאוּבֵן דְּאִיהוּ יְמִינָא, (ס\"א אתעביר) אִתְאֲבִיד מִנֵּיהּ בְּכֵירוּתָא כְּהוּנָּתָא וּמַלְכוּתָא, וְעַל דָּא כְּתִיב בִּיהוּדָה, (דברים ל״ג:ז׳) יָדָיו רָב לוֹ וְעֵזֶר מִצָּרָיו תִּהְיֶה.</p>\n<p>תָּא חֲזֵי, כְּתִיב, (מלכים א י׳:ט״ז) וַיַּעַשׂ הַמֶּלֶךְ שְׁלמֹה כִּסֵּא שֵׁן גָּדוֹל. כֻּרְסְיָיא דִשְׁלֹמֹה, עֲבַד לֵיהּ כְּגַוְונָא דִלְעֵילָא, וְכָל דִּיוּקְנִין (דהכא) דִּלְעֵילָא עֲבַד הָכָא. וְעַל דָּא כְּתִיב, (דברי הימים א כ״ט:כ״ג) וַיֵּשֶׁב שְׁלֹמֹה עַל כִּסֵּא ה' לְמֶלֶךְ, מֶלֶךְ מִלָּה סְתִימָא הוּא. וְכֵן (מלכים א ב׳:י״ב) וּשְׁלֹמֹה יָשַׁב עַל כִּסֵּא דָּוִד אָבִיו וַתִּכּוֹן מַלְכוּתוֹ מְאֹד, דְּקָיְימָא סִיהֲרָא בְּאַשְׁלָמוּתָא.</p>\n<p>דָּן יָדִין עַמּוֹ בְּקַדְמִיתָא, וּלְבָתַר שִׁבְטֵי יִשְׂרָאֵל כְּאַחַד, כְּיִחוּדוֹ שֶׁל עוֹלָם <Nonei></i>כְּמָה דְּהֲוָה בְּשִׁמְשׁוֹן, דְּאִיהוּ יְחִידָאי עָבִיד דִּינָא בְּעַלְמָא, וְדָאִין וְקָטִיל כְּחֲדָא, וְלָא אִצְטְרִיךְ סֶמֶךְ.</p>\n<p>דָּן יָדִין עַמּוֹ. רִבִּי יִצְחָק אָמַר, דָּן, הַיְינוּ חִוְיָא, כָּמִין עַל אוֹרְחִין וּשְׁבִילִין. וְאִי תֵימָא דְּעַל שִׁמְשׁוֹן בִּלְחוֹדוֹי הוּא. אוּף הָכִי נָמֵי לְעֵילָא, דָּא הוּא נֶפֶשׁ אָחֳרָא (ס\"א נחש זוטא) מְאַסֵּף לְכָל הַמַּחֲנוֹת, וְכָמִין לְאוֹרְחִין וּשְׁבִילִין. לְבָתַר, חֵילִין וּמַשִּׁירְיָין מֵהָכָא נָפְקֵי, אִינוּן דְּכָמָאן לִבְנֵי נָשָׁא, עַל חוֹבִין, דְרָאמִין לְהוּ לַאֲחוֹרָא בָּתַר כִּתְפַיְּיהוּ. אָמַר רִבִּי חִיָּיא, נָחָשׁ הַקַּדְמוֹנִי לְעֵילָא, עַד דְּלָא יִתְבַּסַּם בְּחַמְרָא דְחֵידוּ.</p>\n<p>נָחָשׁ עֲלֵי דֶרֶךְ. תָּא חֲזֵי, כְּמָה דְאִית דֶּרֶךְ לְעֵילָא, הָכִי נָמֵי אִית דֶּרֶךְ לְתַתָּא, וּמִתְפָּרְשָׁא יַמָּא, לְכַמָּה אוֹרְחִין בְּכָל סְטַר. וְאִית אוֹרְחָא חַד, דְּאָתֵי וְאַסְגֵּי יַמָּא, וְרַבֵּי נוּנִין בִּישִׁין לִזְנַיְיהוּ, כְּמָה דַאֲפִיקוּ מַיִין לְתַתָּא נוּנִין טָבִין, (שמות ל) נוּנִין בִּישִׁין, נוּנֵי עוּרְדְּעָנַיָא, כְּגַוְונָא דָא, נוּנִין בִּישִׁין לִזְנַיְיהוּ.</p>\n<p>וְכַד מִשְׁתַּמְּשֵׁי מֵאָרְחָא דְיַמָּא, אִתְחֲזוּן רָכְבִין עַל סוּסַיְיהוּ. וְאִלְמָלֵא דְּהַאי חִוְיָא, דְּאִיהוּ כָּנִישׁ לְכָל מַשִּׁירְיָין, כָּמִין לְסוֹף אָרְחִין, וּבַדַּר לוֹן לַאֲחוֹרָא, הֲווּ מְטַשְׁטְשֵׁי עַלְמָא. מִסִּטְרָא דְּהַנֵּי נָפְקִין חֳרָשִׁין לְעָלְמָא. תָּא חֲזֵי, בְּבִלְעָם כְּתִיב, (במדבר כ״ד:א׳) וְלא הָלַךְ כְּפַעַם בְּפַעַם לִקְרַאת נְחָשִׁים, בְּגִין דְּאִינוּן קָיְימִין לְלַחֲשָׁא בַּחֲרָשֵׁי עַלְמָא.</p>\n<p>חָמֵי מַה כְּתִיב, יְהִי דָן נָחָשׁ עֲלֵי דֶרֶךְ. מַאי עֲלֵי דֶרֶךְ. אֶלָּא נָחָשׁ, מַאן דְּאִשְׁתָּדַּל אֲבַתְרֵיהּ, אַכְּחִישׁ פַמַּלְיָא דִלְעֵילָא, וּמַאי אִיהוּ, הַהוּא דֶרֶךְ עִלָּאָה דְּנָפַק מִלְּעֵילָא. כְּמָא דְאַתְּ אָמֵר, (ישעיהו מ״ג:ט״ז) הַנּוֹתֵן בַּיָּם דֶּרֶךְ וְגו'. נָחָשׁ, מַאן דְּאִשְׁתָּדַּל אֲבַתְרֵיהּ, כְּאִילוּ אָזִיל עַל הַהוּא דֶרֶךְ עִלָּאָה לְאַכְּחָשָׁא לֵיהּ, בְּגִין דִּמְהַהוּא דֶרֶךְ, אִתְזָנוּ עַלְמִין עִלָּאֵי.</p>\n<p>וְאִי תֵימָא, דָּן, אַמַּאי אִיהוּ בְּדַרְגָּא דָא, אֶלָּא כְּדִכְתִיב, (בראשית ג׳:כ״ד) וְאֶת לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת לִשְׁמוֹר אֶת דֶּרֶךְ עֵץ הַחַיִּים. הָכִי נָמֵי הַנּוֹשֵׁךְ עִקְבֵי סוּס וְגו', בְּגִין לְנַטְרָא לֵיהּ לְכָל מַשִּׁירְיָין. אָמַר רִבִּי אֶלְעָזָר, תִּקּוּנָא דְּכוּרְסְיָיא אִיהוּ. תָּא חֲזֵי, כֻּרְסְיָיא דִשְׁלֹמֹה מַלְכָּא, חַד חִוְיָא מְרַפְרֵף בְּקִטּוּרֵי שַׁרְבִיטָא לְעֵילָא מֵאַרְיְוָתָא.</p>\n<p>כְּתִיב, (שופטים י״ג:כ״ה) וַתָּחֶל רוּחַ ה' לְפַעֲמוֹ בְּמַחֲנֵה דָן וְגו'. תָּא חֲזֵי, שִׁמְשׁוֹן נְזִיר עוֹלָם הֲוָה, וּפָרֵישׁ עַלְמָא אִיהוּ, וְאִתְגַּבַּר בֵּיהּ חֵילָא תַּקִּיפָא, וְהוּא הֲוָה חִוְיָא בְּהַאי עַלְמָא, לָקֳבֵל עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, דְּהָא אַחְסָנַת חוּלָקָא דְבִרְכָתָא דְּדָן אֲבוּהִי יָרִית, דִּכְתִיב, יְהִי דָן נָחָשׁ עֲלֵי דֶרֶךְ וְגו'.</p>\n<p>אָמַר רִבִּי חִיָּיא, נָחָשׁ יְדִיעָא, שְׁפִיפוֹן מַאי נִיהוּ. אָמַר לֵיהּ, רָזָא דְתִקּוּנָא דַּחֳרָשִׁין, דְּנָחָשׁ אִיהוּ שְׁפִיפוֹן, הָכִי נָמֵי הַהוּא רָשָׁע דְּבִלְעָם, בְּכֹלָּא הֲוָה יָדַע. תָּא חֲזֵי כְּתִיב, (במדבר כ״ג:ג׳) וַיֵּלֶךְ שֶׁפִי, לְזִמְנִין בְּהַאי, וּלְזִמְנִין בְּהַאי.</p>\n<p>וְאִי תֵימָא דָן, לָאו דַּרְגֵּיהּ בְּהַאי. הָכִי הוּא וַדַּאי. אֶלָּא אִתְמַנָּא עַל דַּרְגָּא דָא (לההוא), לְמֶהֱוֵי סִטְרָא בַּתְרַיְיתָא, וּשְׁבָחָא אִיהוּ דִילֵיהּ, מְמַנָּן דְּמַלְכָּא בְּהַאי, וּמְמַנָּא עַל הַאי, וִיקָרָא אִיהוּ לְכָל אִינוּן מְמֻנִּין. וְכֻּרְסְיָיא דְמַלְכָּא, בְּכָל אִינוּן מְמַנָּן אִתְתַּקָּן, בְּכָל הַנֵּי מְמַנָּן תְּחוֹתַיְיהוּ מִתְפָּרְשָׁן אוֹרְחִין וְדַרְגִּין, הֵן לְטַב, הֵן לְבִישׁ, וְכֻלְּהוּ אִתְאַחֲדָן בְּהַנֵּי תִּקּוּנֵי דְּכֻּרְסְיָיא. וּבְגִינִי כָּךְ דָּן לִסְטַר צָפוֹן, בְּנוּקְבָא דִּתְהוֹמָא רַבָּא. דִּסְטַר צָפוֹן כַּמָּה חֲבִילֵי טְרִיקִין אִזְדַּמְּנָן תַּמָּן, וְכֻלְּהוּ טַפְסִירָא דְּקִסְטְרָא לְאַבְאָשָׁא עַלְמָא.</p>\n<p>בְּגִינֵי כָּךְ צַלֵּי יַעֲקֹב וְאָמַר, לִישׁוּעָתְךָ קִוִּיתִי ה'. בְּכָל שְׁבָטִים לָא קָאֲמַר לִישׁוּעָתְךָ אֶלָּא בְּהַאי. בְּגִין דְּחָמָא לֵיהּ תּוּקְפָא תַּקִּיפָא דְּחִוְיָא, מְרַחֲשָׁא דִינָא לְאִתְגַּבְּרָא.</p>\n<p>רִבִּי יוֹסֵי וְרִבִּי חִזְקִיָּה הֲווּ אָזְלֵי לְמֶחֱמֵי לְרִבִּי שִׁמְעוֹן בְּקַפּוּטְקִיָּא, אָמַר רִבִּי חִזְקִיָּה, הַאי דְאַמְרִינָן לְעוֹלָם יְסַדֵּר בַּר נָשׁ שְׁבָחָא דְמָרֵיהּ, וּלְבָתַר יְצַלֵּי צְלוֹתֵיהּ, הַאי מַאן דְּלִבֵּיהּ טָרִיד, וּבָעֵי לְצַלָּאָה צְלוֹתֵיהּ, וְאִיהוּ בְּעָקוּ, וְלָא יָכִיל לְסַדְּרָא שְׁבָחָא דְמָרֵיהּ כְּדְקָא יְאוּת, מַאי הוּא.</p>\n<p>אָמַר לֵיהּ, אַף עַל גַּב דְלָא יָכִיל לְכַוְּונָא לִבָּא וּרְעוּתָא, סִדּוּרָא וְשִׁבְחָא דְמָרֵיהּ אַמַּאי גָרַע, אֶלָּא יְסַדֵּר שִׁבְחֵיהּ דְּמָארֵיהּ, אַף עַל גַּב <Nonei></i>דְּלָא יָכִיל לְכַוְּונָא, וִיצַלֵּי צְלוֹתֵיהּ. הֲדָא הוּא דִכְתִיב, (תהילים י״ז:א׳) תְּפִלָּה לְדָוִד שִׁמְעָה ה' צֶדֶק הַקְשִׁיבָה רִנָּתִי, שִׁמְעָה ה' צֶדֶק בְּקַדְמִיתָא, בְּגִין דְּאִיהוּ סִדּוּרָא דְּשִׁבְחָא דְמָרֵיהּ. וּלְבָתַר הַקְשִׁיבָה רִנָּתִי הַאֲזִינָה תְּפִלָּתִי. מַאן דְּיָכִיל לְסַדְּרָא שְׁבָחָא דְמָרִיהּ, וְלָא עָבִיד, עֲלֵיהּ כְּתִיב, (ישעיה ס) גַּם כִּי תַרְבּוּ תְּפִלָּה אֵינֶנִּי שׁוֹמֵעַ יְדֵיכֶם וְגו'.</p>\n<p>כְּתִיב, (שמות כ״ט:ל״ט) אֶת הַכֶּבֶשׂ הָאֶחָד תַּעֲשֶׂה בַּבֹּקֶר וְאֵת הַכֶּבֶשׂ הַשֵּׁנִי תַּעֲשֶׂה בֵּין הָעַרְבָּיִם. תְּפִלּוֹת כְּנֶגֶד תְּמִידִין תִּקְּנוּם. תָּא חֲזֵי, בְּאִתְעֲרוּתָא דִלְתַתָּא, אִתְעַר הָכִי נָמֵי לְעֵילָא. וּבְאִתְעֲרוּתָא דִלְעֵילָא, הָכִי נָמֵי לְעֵילָא מִנֵּיהּ, עַד דְּמָטֵי אִתְעֲרוּתָא לְאֲתַר דְּבָעְיָא בּוּצִינָא לְאַדְלָקָא וְאַדְלִיק. וּבְאִתְעֲרוּתָא דִתְנָנָא דִלְתַתָּא, אַדְלִיק בּוּצִינָא לְעֵילָא, וְכַד הַאי אַדְלִיק (בוצינין), כֻּלְּהוּ בּוּצִינִין אָחֳרָנִין דָּלְקִין, וּמִתְבָּרְכָאן מִנֵּיהּ כֻּלְּהוּ עָלְמִין. אִשְׁתַּכַּח, דְּאִתְעֲרוּתָא דְקָרְבָּנָא תִּקּוּנָא דְעַלְמָא, וּבִרְכָאן דְּעַלְמִין כֻּלְּהוּ.</p>\n<p>הָא כֵיצַד, שָׁארֵי תְּנָנָא לְסָלְקָא, אִינוּן דִּיוּקְנִין קַדִּישִׁין דִּמְמַנָּן עַל עַלְמָא אִתְהַנּוּן (ס\"א אתתקנן) לְאַתְעָרָא, וּמִתְעָרִין לְדַרְגִּין בְּכִסּוּפָא דִלְעֵילָא, כְּמָא דְאַתְּ אָמֵר, (תהילים ק״ד:כ״א) הַכְּפִירִים שׁוֹאֲגִים לַטָּרֶף וְגו'. אִלֵּין אִתְעָרִין לְדַרְגִּין עִלָּאִין דְּעֲלַיְיהוּ, עַד דְּמָטֵי אִתְעֲרוּתָא, עַד דְּבָעֵי מַלְכָּא לְאִתְחַבְּרָא בְּמַטְרוֹנִיתָא.</p>\n<p>וּבְכִסּוּפָא דִלְתַתָּא, נָבְעִין מַיִין תַּתָּאִין, לְקִבְלָא מַיִין עִלָּאִין, דְּהָא לָא נָבְעִין מַיִין עִלָּאִין, אֶלָּא בְּאִתְעֲרוּתָא דְכִסוּפָא דִלְתַתָּא, וּכְדֵין תִּיאוּבְתָּא אִתְדָּבַּק, וְנָבְעִין מַיִין תַּתָּאִין לָקֳבֵל מַיִין עִלָּאִין, וְעָלְמִין מִתְבָּרְכָאן, וּבוּצִינִין כֻּלְּהוּ דְלִיקָן, וְעִלָּאִין וְתַתָּאִין מִשְׁתַּכְּחֵי בְּבִרְכָאן.</p>\n<p>תָּא חֲזֵי, כֹּהֲנֵי וְלֵיוָאֵי. מִתְעָרֵי לְאִתְחַבְּרָא שְׂמָאלָא בִּימִינָא. אָמַר רִבִּי חִזְקִיָּה, כֹּלָּא הָכִי הוּא וַדַּאי, אֲבָל הָכִי שְׁמַעְנָא, כֹּהֲנֵי וְלֵיוָאֵי, דָּא אִתְעַר שְׂמָאלָא, וְדָא אִתְעַר יְמִינָא, בְּגִין דְּאִתְחַבְּרוּתָא דִּדְכוּרָא לְגַבֵּי נוּקְבָא, לָאו אִיהוּ אֶלָּא בִּשְׂמָאלָא וִימִינָא. כְּמָא דְאַתְּ אָמֵר, (שיר השירים ב׳:ו׳) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. וּכְדֵין אִתְחַבַּר דְּכַר בְּנוּקְבָא, וְתִיאוּבְתָּא אִשְׁתַּכַּח, וְעַלְמִין מִתְבָּרְכִין, וְעִלָּאֵי וְתַתָּאֵי בְּחֵידוּ.</p>\n<p>וְעַל דָּא, כֹּהֲנֵי וְלֵיוָאֵי, מִתְעָרֵי מִלָּה לְתַתָּא, לְאִתְעָרָא כִּסּוּפָא וַחֲבִיבוּתָא לְעֵילָא, דְּכֹלָּא תַּלְיָא בִּימִינָא וּשְׂמָאלָא. אִשְׁתַּכַּח דְּקָרְבָּנָא יְסוֹדָא דְעָלְמָא, תִּקּוּנָא דְעַלְמָא, חֵידוּ דְעִלָּאִין וְתַתָּאִין. אָמַר רִבִּי יוֹסֵי וַדַּאי שַׁפִּיר קָא אֲמַרְתְּ, וְהָכִי הוּא, וְהָכִי שְׁמַעְנָא מִלָּה, וְאַנְשֵׁינָא לָהּ, וְאֲנָא שְׁמַעְנָא הָא, וְכֹלָּא בְּחַד סַלְקָא.</p>\n<p>הַשְׁתָּא צְלוֹתָא בְּאֲתַר דְּקָרְבָּנָא, וּבְעֵי בַּר נָשׁ לְסַדְּרָא שְׁבָחָא דְמָרֵיהּ כְּדְקָא יְאוּת, וְאִי לָא יְסַדַּר, לָאו צְלוֹתֵיהּ צְלוֹתָא. תָּא חֲזֵי, סִדּוּרָא שְׁלִים דְּשִׁבְחָא דְּקוּדְשָׁא בְּרִיךְ הוּא, מַאן דְּיָדַע לְיַחֲדָא שְׁמָא קַדִּישָׁא כְּדְקָא יְאוּת, דִּבְהַאי מִתְעָרִין עִלָּאִין וְתַתָּאִין, וְנַגְדֵי בִּרְכָאן לְכֻלְּהוּ עָלְמִין.</p>\n<p>אָמַר רִבִּי חִזְקִיָּה, לָא אַשְׁרֵי קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל בְּגָלוּתָא בֵּינֵי עַמְמַיָא, אֶלָּא בְּגִין דְּיִתְבָּרְכוּן שְׁאָר עַמִין בְּגִינֵיהוֹן, דְּהָא אִינוּן נָגְדִין בִּרְכָאן מִלְּעֵילָא לְתַתָּא כָּל יוֹמָא.</p>\n<p>אֲזְלוּ, עַד דְּהֲווּ אָזְלֵי, חָמוּ חַד חִוְיָא דְּהֲוָה קָמַסְחַר (ואסטר) בְּאָרְחָא. סָטוּ מֵאָרְחָא. אֲתָא בַּר נָשׁ אָחֳרָא לְגַבַּיְיהוּ, קָטִיל לֵיהּ חִוְיָא. אַהֲדָרוּ רֵישַׁיְיהוּ, וְחָמוּ לֵיהּ, לְהַהוּא בַּר נָשׁ דְּמִית. אָמְרוּ, וַדַּאי הַהוּא נָחָשׁ, שְׁלִיחוּתָא דְמָרֵיהּ קָא עָבִיד. בְּרִיךְ רַחֲמָנָא דְּשֵׁזְבִינָנָא.</p>\n<p>פָּתַח רִבִּי יוֹסֵי וְאָמַר, יְהִי דָן נָחָשׁ עֲלֵי דֶרֶךְ. אֵימָתַי הֲוָה דָן נָחָשׁ, בְּיוֹמוֹי דִירָבְעָם, דִּכְתִיב, (מלכים א י״ב:כ״ט) וְאֶת הָאֶחָד נָתַן בְּדָן אַמַּאי אִתְיְיהִיב תַּמָּן עֲלֵי דֶרֶךְ. עַל הַהוּא אֹרַח, דְּיִתְמְנַע (ההוא דרך דסלקין) דְלָא יִסְלְקוּן לִירוּשָׁלַם (ולא יסלקון תמן). וְדָא דָן, הֲוָה לוֹן נָחָשׁ לְיִשְׂרָאֵל עֲלֵי דֶרֶךְ, עֲלֵי דֶרֶךְ וַדַּאי, כְּמָא דְאַתְּ אָמֵר, (מלכים א י״ב:ו׳) וַיִּוָּעַץ הַמֶּלֶךְ וְגו'. שְׁפִיפוֹן עֲלֵי אֹרַח. דְּעָקִיץ לוֹן לְיִשְׂרָאֵל. וְכֹלָּא לָא הֲוָה אֶלָּא עֲלֵי דֶרֶךְ, וַעֲלֵי אוֹרְחָא, לְאִתְמְנָעָא מִיִּשְׂרָאֵל דְּלָא יִסְלְקוּן לִירוּשָׁלַם, לְמֵיחַג חֲגַיְיהוּ, וּלְקָרָבָא קָרְבָּנִין וְעִלַּוָּון, לְמִפְלַח תַּמָּן.</p>\n<p><Nonei></i>תָּא חֲזֵי, בְּשַׁעְתָּא דְּמָטוּ בִּרְכָאן לִידָא דְמשֶׁה, לְבָרְכָא לְכֻלְּהוּ שְׁבָטִים, חָמָא לְדָן דְּהֲוָה קָטִיר בְּחִוְיָא, אַהֲדַר קָטַר לֵיהּ בְּאַרְיָא. הֲדָא הוּא דִכְתִיב, (דברים ל״ג:כ״ב) וּלְדָן אָמַר דָּן גּוּר אַרְיֵה יְזַנֵּק מִן הַבָּשָׁן. מַאי טַעְמָא, בְּגִין (דאיהו) דִּיהֵא שֵׁירוּתָא וְסוֹפָא דְּד' דִּגְלִין קָטִיר בִּיהוּדָה דְּאִיהוּ מַלְכָּא, כְּמָא דְאַתְּ אָמֵר, גּוּר אַרְיֵה יְהוּדָה, וְהוּא שֵׁירוּתָא דְּדִגְלִין. וְסוֹפָא דְּדִגְלִין דָּן, דִּכְתִיב דָּן גּוּר אַרְיֵה וְגו', לְמֶהֱוִי שֵׁירוּתָא וְסוֹפָא קָטִיר בְּחַד אֲתַר:</p>\n<p>לִישׁוּעָתְךָ קִוִּיתִי ה', רִבִּי חִיָּיא אָמַר, (כדכתיב) כְּמָא דְאַתְּ אָמֵר, (שופטים י״ג:ה׳) וְהוּא יָחֵל לְהוֹשִׁיעַ אֶת יִשְׂרָאֵל מִיַּד פְּלִשְׁתִּים. אָמַר (ס\"א רבי אחא), וְכִי אַמַּאי קִוִּיתִי וְהָא סָלִיק הֲוָה יַעֲקֹב מֵעַלְמָא בְּהַהוּא זִמְנָא מִכַּמָּה שְׁנִין. אַמַּאי אָמַר דְּאִיהוּ מְחַכֶּה לְהַהוּא יְשׁוּעָה. (ס\"א אלא ודאי) אָמַר לֵיהּ וַדַּאי רָזָא דְמִלָּה, כְּדִכְתִיב, (שמות י״ז:י״א) וְהָיָה כַּאֲשֶׁר יָרִים משֶׁה יָדוֹ וְגָבַר יִשְׂרָאֵל, יִשְׂרָאֵל סְתָם. אוּף הָכָא וְהוּא יָחֵל לְהוֹשִׁיעַ אֶת יִשְׂרָאֵל, יִשְׂרָאֵל סְתָם. בְּגִינֵי כָּךְ אָמַר, לִישׁוּעָתְךָ קִוִּיתִי ה'. אָמַר רִבִּי חִיָּיא. וַדַּאי הָכִי הוּא, וְשַׁפִּיר. זַכָּאָה חוּלְקֵהוֹן דְּצַדִּיקַיָיא, דְּיָדְעֵי לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא, לְמִזְכֵּי בָּהּ לְחַיִּין דִּלְעֵילָא. כְּמָא דְאַתְּ אָמֵר, (דברים ל׳:כ׳) כִּי הוּא חַיֶּיךָ וְאֹרֶךְ יָמֶיךָ לָשֶׁבֶת עַל הָאֲדָמָה וְגו'.</p>"],[9520011492,"<p>גָּד גְּדוּד יְגוּדֶנוּ וְהוּא יָגוּד עָקֵב. רִבִּי יֵיסָא אָמַר, מִגָּד אִשְׁתְּמַע, דְּהָא חֵילִין יִפְקוּן לַאֲגָחָא קְרָבָא, מַשְׁמַע דִּכְתִיב גָּד, בְּכָל אֲתַר גִימֶ\"ל (רל\"ד ע\"ב) דָלֶ\"ת, חֵילִין וּמַשִּׁרְיָין נָפְקֵי מִנַּיְיהוּ. דְּהָא גִימֶ\"ל יָהִיב, וְדָלֶ\"ת לָקִיט. וּמֵהָכָא (נ\"א משכא) כַּמָּה חֵילִין וְכַמָּה מַשִּׁירְיָין תַּלְיָין בְּהוּ.</p>\n<p>תָּא חֲזֵי, הַהוּא נָהָר דְּנָגִיד וְנָפִיק מֵעֵדֶן, לָא פָּסְקִין מֵימוֹי לְעָלְמִין, וְהוּא אַשְׁלִים לְמִסְכְּנֵי, וְעַל דָּא קָיְימֵי כַּמָּה חֵילִין וְכַמָּה מַשִּׁירְיָין, וְאִתְּזָנוּ מֵהָכָא. וְעַל דָּא גָּד, דָּא אַפִּיק וְיָהִיב, וְדָא לָקִיט וְנָקִיט, וְאִתְּזָן בֵּיתָא וְכָל אַנְשֵׁי בֵּיתָא.</p>\n<p>אָמַר רִבִּי יִצְחָק, אִלְּמָלֵא דְּהֲוֵי גָד מִבְּנֵי שְׁפָחוֹת, שַׁעְתָּא קַיְימָא לֵיהּ לְאַשְׁלָמָא יַתִּיר מִכֹּלָא. הֲדָא הוּא דִכְתִיב, (בראשית ל) בָּא גָד קְרִי, וּכְתִיב בָּגָד חָסֵר אָלֶ\"ף, דְּהָא שַׁעְתָא קָיְימָא בִּשְׁלִימוּ, וְאִסְתַּלַּק מִנֵּיהּ. הֲדָא הוּא דִכְתִיב, (איוב ו׳:ט״ו) אַחַי בָּגְדוּ כְמוֹ נָחַל, בְּגִין דְּהַהוּא נָהָר דְּנָגִיד, אִסְתַּלַּק בְּהַהִיא שַׁעְתָא, וּכְתִיב בָּגָד חָסֵר אָלֶ\"ף, וְעַל דָּא, לָא זָכָה בְּאַרְעָא קַדִּישָׁא וְאִסְתַּלַּק מִינָהּ.</p>\n<p>רִבִּי יְהוּדָה אָמַר, מִנַּיִן לִרְאוּבֵן דְּהֲוָה כְּהַאי גַוְונָא, כְּדִכְתִיב, פַּחַז כַּמַּיִם אַל תּוֹתַר דְּאִסְתַּלְּקוּ מַיִין וְלָא נְגִידוּ, וְהָא אִתְּמָר בְּמָּה אַפְגִים. וְתַרְוַויְיהוּ לָא זָכוּ בְּאַרְעָא קַדִּישָׁא, וְחֵילִין וּמַשִּׁירְיָין אֲפִיקוּ לְאַחְסָנָא לְהוּ לְיִשְׂרָאֵל אַרְעָא. תָּא חֲזֵי, מַה דְאִתְּפַגִים בְּגָד, אִשְׁתְּלִים בְּאָשֵׁר, הֲדָא הוּא דִכְתִיב, מֵאָשֵׁר שְׁמֵנָה לַחְמוֹ וְהוּא יִתֵּן מַעֲדַנֵּי מֶלֶךְ. הַשְׁתָּא אַשְׁלִים גִימֶ\"ל לְדָלֶ\"ת.</p>"],[9520011493,"<p>רִבִּי אֶלְעָזָר וְרִבִּי אַבָּא אִשְׁתְּמִיטוּ בִּמְעַרְתָּא דְלוּד, דְּעָאלוּ קַמֵּי תּוּקְפָא דְשִׁמְשָׁא, דְּהֲווּ אָזְלֵי בְּאָרְחָא. אָמַר רִבִּי אַבָּא נַסְחַר הַאי מְעַרְתָּא בְּמִלֵּי דְאוֹרַיְיתָא. פָּתַח רִבִּי אֶלְעָזָר וְאָמַר, (שמות קי\"ד ע\"א) (שיר השירים ח׳:ו׳) שִׂימֵנִי כַּחוֹתָם עַל לִבֶּךָ כַּחוֹתָם עַל זְרוֹעֶךָ וְגו', רְשָׁפֶיהָ רִשְׁפֵּי אֵשׁ שַׁלְּהֶבֶת יָהּ, הַאי קְרָא אִתְעָרְנָא בֵּיהּ. אֲבָל לֵילְיָא חַד הֲוָה כַּד הֲוֵינָא קָאִים קַמֵּי אַבָּא, וְשָׁמַעְנָא מִנֵּיהּ מִלָּה, דְּלֵית שְׁלִימוּ וּרְעוּתָא וְכִסּוּפָא דִּכְנֶסֶת יִשְׂרָאֵל בְּקוּדְשָׁא בְּרִיךְ הוּא, אֶלָּא (ס\"ח ע\"ב) בְּנִשְׁמַתְהוֹן דְּצַדִּיקַיָיא. דְּאִינוּן מִתְעָרֵי נְבִיעוּ דְמַיָא תַּתָּאֵי, לְקִבְלֵי עִלָּאֵי. וּבְהַהִיא שַׁעְתָא שְׁלִימוּ דִּרְעוּתָא וְכִסּוּפָא בִּדְבִיקוּ חָדָא לְמֶעְבַּד פֵּירִין.</p>\n<p>תָּא חֲזֵי, בָּתַר דְּאִתְדַּבְּקוּ דָּא בְּדָא, וְהִיא קַבִּילַת רְעוּתָא, הִיא אֲמָרַת שִׂימֵנִי כַחוֹתָם עַל לִבֶּךָ, אַמַּאי כַחוֹתָם. אֶלָּא אָרְחֵיהּ דְּחוֹתָם, כֵּיוָן דְּאִתְדָּבַּק בְּאֲתַר חַד, אַף עַל גַּב דְּאִתְעֲדֵי מִינֵיהּ, הָא אִשְׁתָּאַר רְשִׁימוּ בְּהַהוּא אֲתַר, וְלָא אַעֲדֵי מִנֵּיהּ. דְּכָל רְשִׁימוּ, וְכָל דִּיוּקְנָא דִילֵיהּ, בֵּיהּ אִשְׁתָּאַר. כָּךְ אָמְרָה כְּנֶסֶת יִשְׂרָאֵל, הָא אִתְדָּבַּקְנָא בָּךְ, אַף עַל גַּב דְּאִתְעֲדֵי מִינָךְ וְאָזִיל <Nonei></i>בְּגָלוּתָא. שִׂימֵנִי כַחוֹתָם עַל לִבֶּךָ, בְּגִין דְּיִשְׁתָּאַר כָּל דְּיוּקְנִי בָּךְ, כְּהַאי חוֹתָם דְּיִשְׁתָּאַר כָּל דִּיוּקְנֵיהּ, בְּהַהוּא אֲתַר דְּאִתְדָּבַּק בֵּיהּ.</p>\n<p>כִּי עַזָּה כַמָּוְת אַהֲבָה, תַּקִּיפָא הִיא, כִּפְרִישׁוּ דְרוּחָא מִן גּוּפָא. דְּתָנִינָן, בְּשַׁעְתָּא דְּבַּר נָשׁ מָטֵי לְאִסְתַּלָּקָא מִן עַלְמָא וְחָמֵי מַה דְּחָמֵי, רוּחָא אָזְלָא בְּכָל (ויקרא קכ\"ו ע\"ב) שַׁיְיפֵי דְגוּפָא וְסָלִיק גַּלְגַּלּוֹי, כְּמַאן דְאָזִיל בְּיַמָּא בְּלָא שַׁיָּיטִין, סָלִיק וְנָחִית וְלָא מְהַנְיָיא לֵיהּ, אֲתָא וְאִישְׁתָּאִיל מִכָּל שַׁיְיפֵי גוּפָא, וְלֵית (לון) תַּקִּיפוּ כְּיוֹמָא דְּפָּרִישׁ רוּחָא מִן גּוּפָא. כָּךְ תַּקִּיפוּ דִּרְחִימוּ דְּכְנֶסֶת יִשְׂרָאֵל לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, כְּתַקִּיפוּ דְמוֹתָא, בְּשַׁעְתָּא דְבָעֵי רוּחָא לְאִתְפְּרָשָׁא מִן גּוּפָא.</p>\n<p>קָשָׁה כִּשְׁאוֹל קִנְאָה, כָּל מַאן דְּרָחִים, וְלָא קָשִׁיר עִמֵּיהּ קִנְאָה, לָאו רְחִימוּתֵיהּ רְחִימוּתָא. כֵּיוָן דְּקַנֵּי, הָא רְחִימוּתָא אִשְׁתְּלִים. מִכָּאן אוֹלִיפְנָא דְּבָעֵי בַּר נָשׁ לְקַנָּאָה לְאִנְתְּתֵיהּ, בְּגִין דְּיִתְקַשַּׁר עִמָּהּ רְחִימוּתָא שְׁלִים, דְּהָא מִגּוֹ כָּךְ לָא יָהִיב עֵינוֹי בְּאִינְתּוּ אָחֳרָא. מַהוּ קָשָׁה כִּשְׁאוֹל. אֶלָּא, מַה שְּׁאוֹל קַשְׁיָא בְּעֵינַיְיהוּ דְּחַיָּיבִין לְמֵיחַת בֵּיהּ, כָּךְ קִנְאָה קַשְׁיָא בְּעֵינַיְיהוּ דְּמַאן דְּרָחִים וְקַנֵּי, לְאִתְפְּרָשָׁא מֵרְחִימוּתָא.</p>\n<p>דָּבָר אַחֵר, קָשָׁה כִּשְׁאוֹל קִנְאָה, מַה שְּׁאוֹל, בְּשַׁעְתָּא דְּנָחֲתִין לוֹן לְחַיָּיבַיָא בֵּיהּ, מוֹדִיעִין לוֹן חוֹבַיְיהוּ עַל מָה נָחֲתִין לֵיהּ, וְקַשְׁיָא לְהוּ. כָּךְ, מַאן דְּקַנֵּי, הוּא תָּבַע עַל חוֹבֵיהּ, וְחָשִׁיב (נ\"א וחשיד) כַּמָּה עוֹבָדִין, וּכְדֵין קִשּׁוּרָא דִּרְחִימוּתָא אִתְקַשַּׁר בֵּיהּ.</p>\n<p>רְשָׁפֶיהָ רִשְׁפֵּי אֵשׁ שַׁלְהֶבֶת יָהּ. מַאן שַׁלְהֶבֶת יָהּ, דָּא שַׁלְהוֹבָא דְּאִתּוֹקְדָא וְנַפְקָא מִגּוֹ שׁוֹפָר, דְּאִיהוּ אִתְעַר וְאוֹקִיד, וּמַאן אִיהוּ, שְׂמָאלָא. הֲדָא הוּא דִכְתִיב, (שיר השירים ב׳:ו׳) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי. דָּא אוֹקִיד שַׁלְּהוֹבָא דִּרְחִימוּ דִּכְנֶסֶת יִשְׂרָאֵל לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>וּבְגִינֵי כָּךְ, (שיר השירים ח׳:ז׳) מַיִם רַבִּים לא יוּכְלוּ לְכַבּוֹת אֶת הָאַהֲבָה. דְּהָא כַּד אָתֵי יְמִינָא דְּאִיהוּ מַיִם, אוֹסִיף יְקִידוּ דִּרְחִימוּתָא, וְלָא כָּבֵי שַׁלְהוֹבָא דִשְׂמָאלָא, כְּמָא דְאַתְּ אָמֵר וִימִינוֹ תְּחַבְּקֵנִי, הַאי אִיהוּ מַיִם רַבִּים לֹא יוּכְלוּ לְכַבּוֹת אֶת הָאַהֲבָה, וְכֵן כֹּלָּא כְּהַאי גַוְונָא.</p>\n<p>עַד דְּהֲווּ יַתְבֵי, שָׁמְעוּ קָלֵיהּ דְּרִבִּי שִׁמְעוֹן, דְּהֲוָה אָתֵי בְּאוֹרְחָא, הוּא וְרִבִּי יְהוּדָה וְרִבִּי יִצְחָק. קָרִיב לִמְעַרְתָּא, נָפְקוּ רִבִּי אֶלְעָזָר וְרִבִּי אַבָּא. אָמַר רִבִּי שִׁמְעוֹן, מִכּוֹתְלֵי דִמְעַרְתָּא חָמִינָא דִּשְׁכִינְתָּא הָכָא. יָתְבוּ. אָמַר רִבִּי שִׁמְעוֹן בְּמַאי עַסְקִיתוּ. אָמַר רִבִּי אַבָּא, בִּרְחִימוּתָא דִכְנֶסֶת יִשְׂרָאֵל לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְרִבִּי אֶלְעָזָר פָּרִישׁ הַאי קְרָא בִּכְנֶסֶת יִשְׂרָאֵל, שִׂימֵנִי כַחוֹתָם עַל לִבֶּךָ וְגו'. אָמַר לֵיהּ, אֶלְעָזָר בִּרְחִימוּ עִלָּאָה וּקְשִׁירוּ דַּחֲבִיבוּתָא אִסְתַּכַּלְתְּ.</p>\n<p>אִשְׁתִּיק רִבִּי שִׁמְעוֹן שַׁעְתָּא. אָמַר, בְּכָל אֲתַר בָּעְיָיא שְׁתִיקוּ, בַּר שְׁתִיקוּ דְאוֹרַיְיתָא. גִּינְזָא חָדָא אִית לִי גְנִיזָא, וְלָא בָּעֵינָא דְּיִתְאֲבִיד מִנַּיְיכוּ, וְהִיא מִלָּה עִלָּאָה, וְאַשְׁכַּחְנָא לָהּ בְּסִפְרָא דְרַב הַמְנוּנָא סָבָא.</p>\n<p>תָּא חֲזֵי, בְּכָל אֲתַר דְּכוּרָא רָדִיף בָּתַר נוּקְבָא, וְאִתְעַר לְגַבָּהּ רְחִימוּתָא, וְהָכָא אַשְׁכַּחְנָא, דְּהִיא אִתְעָרַת רְחִימוּתָא וְרָדְפָה אֲבַתְרֵיהּ, וְאוֹרְחֵיהּ דְּעַלְמָא, דְּלֵית שְׁבָחָא דְנוּקְבָא, לְמִרְדַּף בַּתְרֵיהּ דִּדְכוּרָא. אֶלָּא, מִלָּה סְתִימָא הִיא, וּמִלָּה עִלָּאָה דְבֵי גִנְזַיָיא דְמַלְכָּא.</p>"],[9520011494,"<p>תָּא חֲזֵי, תְּלַת נִשְׁמָתִין אִינוּן, וְאִינוּן סָלְקִין בְּדַרְגִּין עִלָאִין יְדִיעָן, וְעַל דְּאִינוּן תְּלָתָא אַרְבַּע אִינוּן. חַד נִשְׁמָתָא עִלָּאָה דְּלָא אִתְּפַס, וְלָא אִתְעַר בֵּיהּ גִּזְבְּרָא (ס\"א גזעא) דְּקַרְטִיטָאָה עִלָּאָה, כָּל שֶׁכֵּן תַּתָּאָה. וְהַאי נִשְׁמָתָא לְכָל נִשְׁמָתִין. וְהוּא סָתִים, וְלָא אִתְגַּלְּיָא לְעָלְמִין, וְלָא אִתְיְידַע, וְכֻלְּהוּ בֵּיהּ תַּלְיָין.</p>\n<p>וְהַאי אִתְעַטַּף בְּעִטּוּפָא דְזָהֲרָא דְּכַרְמְלָא, (נ\"א דבדולחא) בְּגוֹ זְהִירוּתָא וְנָטִיף טִפִּין טִפִּין מַרְגְּלָאן וְאִתְקַשְּׁרוּ כֻּלְּהוּ כְּחַד, כְּקִשְׁרִין דְּשַׁיְיפֵי דְגוּפָא חַד. וְהוּא אָעִיל בְּגַוַּוְיְיהוּ, וְאַחֲזֵי בְּהוּ עֲבִידְתֵּיהּ. הוּא וְאִינוּן חַד הוּא, וְלֵית בְּהוּ פְּרִישׁוּ. הַאי נִשְׁמָתָא עִלָּאָה טְמִירוּ דְּכֹלָּא.</p>\n<p>נִשְׁמָתָא אָחֳרָא, נוּקְבָא דְמִטַּמְּרָא בְּגוֹ חֵילָהָא, וְהִיא נִשְׁמָתָא לְהוּ, וּמִנַּיְיהוּ אֲחִידָא <Nonei></i>גוּפָא, לְאַחֲזָאָה בְּהוּ עֲבִידְתָּא לְכָל עַלְמָא. כְּגוּפָא דְּאִיהוּ מָאנָא לְנִשְׁמָתָא, לְמֶעְבַּד בֵּיהּ עֲבִידְתָּא. וְאִלֵּין כְּגַוְונָא דְּאִינוּן קְשִׁירִין טְמִירִין דִּלְעֵילָא.</p>\n<p>נִשְׁמָתָא אָחֳרָא, הִיא נִשְׁמַתְהוֹן דְּצַדִּיקַיָיא לְתַתָּא. נִשְׁמַתְהוֹן דְּצַדִּיקַיָיא אַתְיָין מֵאִינוּן נִשְׁמָתִין עִלָּאִין, מִנִּשְׁמָתָא דְנוּקְבָא, וּמִנִּשְׁמָתָא דִּדְכוּרָא. וּבְגִין כָּךְ, נִשְׁמָתִין דְּצַדִּיקַיָיא עִלָּאִין, עַל כָּל אִינוּן חֵילִין וּמַשִּׁרְיָין דִּלְעֵילָא.</p>\n<p>וְאִי תֵימָא, הָא עִלָּאִין אִינוּן מִתְּרֵין סִטְרִין, אַמַּאי נַחֲתִין לְהַאי עַלְמָא, וְאַמַּאי אִסְתַּלְּקוּ מִנִּיהּ. לְמַלְכָּא דְּאִתְיְילִיד לֵיהּ בַּר, שַׁדַּר לֵיהּ לְחַד כְּפַר, לְמַרְבָּה לֵיהּ וּלְגַדְּלָא לֵיהּ עַד דְּיִתְרַבֵּי (ליה), וְיוֹלְפוּן לֵיהּ אָרְחֵי דְהֵיכָלָא דְמַלְכָּא. שָׁמַע מַלְכָּא דְּהָא בְּרֵיהּ רַב וְאִתְרַבֵּי. מַה עָבַד בִּרְחִימוּ דִבְרֵיהּ, מְשַׁדֵּר לָהּ לְמַטְרוֹנִיתָא אִמֵּיהּ בְּגִינֵיהּ, וְאָעִיל לְהֵיכְלֵיהּ, וְחָדֵי עִמֵּיהּ כָּל יוֹמָא.</p>\n<p>כַּךָ קוּדְשָׁא בְּרִיךְ הוּא, אוֹלִיד בַּר בְמַטְרוֹנִיתָא, וּמַאי אִיהוּ, נִשְׁמָתָא עִלָּאָה קַדִּישָׁא, שַׁדַּר לֵיהּ לִכְפַר, לְהַאי עַלְמָא, דְּיִתְרַבֵּי בֵּיהּ, וְיוֹלְפוּן לֵיהּ אוֹרְחֵי דְהֵיכָלָא דְמַלְכָּא. כֵּיוָן דְּיָדַע מַלְכָּא דְּהָא בְּרֵיהּ אִתְרַבֵּי בְּהַאי כְּפַר, וְעִידָן הוּא לְמַיְיתֵי לֵיהּ לְהֵיכָלֵיהּ. מַה עֲבַד בִּרְחִימוּ דִּבְרֵיהּ, מְשַׁדֵּר לְמַטְרוֹנִיתָא בְּגִינֵיהּ וְאָעִיל לֵיהּ לְהֵיכָלֵיהּ. נִשְׁמָתָא לָא סַלְקָא מֵהַאי עַלְמָא, עַד דְּאָתַת מַטְרוֹנִיתָא בְּגִינָהּ, וְאָעִילַת לָהּ בְּהֵיכָלָא דְמַלְכָּא, וְיָתִיבַת תַּמָּן לְעָלְמִין.</p>\n<p>וְעִם כָּל דָּא, אוֹרְחָא דְעַלְמָא, דְּאִינוּן בְּנִי כְּפַר בָּכָאן עַל פְּרִישׁוּ דִּבְרֵיהּ דְּמַלְכָּא מִנַּיְיהוּ. חַד פִּקֵּחַ הֲוָה תַּמָּן, אָמַר לוֹן, עַל מָה אַתּוּן בָּכָאן, וְכִי לָאו בְּרֵיהּ דְּמַלְכָּא אִיהוּ, וְלָא אִתְחֲזֵי לְמֵידַר יַתִּיר בֵּינַיְיכוּ, אֶלָּא בְּהֵיכָלָא דְּאֲבוֹי. כָּךְ משֶׁה, דְּהֲוָה פִּקֵּחַ, חָמָא בְּנֵי כְפַר דְּהֲוָה בָּכָאן. עַל דָּא אָמַר, (דברים י״ד:א׳) בָּנִים אַתֶּם לַיְיָ אֱלֹהֵיכֶם לא תִתְגּוֹדְדוּ.</p>\n<p>תָּא חֲזֵי, אִילּוּ הֲווּ יָדְעִין כֻּלְּהוּ צַדִּיקַיָּיא הַאי, הֲווּ חָדָאן הַהוּא יוֹמָא דְּמָטֵי לוֹן לְאִסְתַּלְּקָא מֵהַאי עַלְמָא. וְכִי לָאו יְקָרָא עִלָּאָה הוּא, דְּמַטְרוֹנִיתָא אָתַת בְּגִינַיְיהוּ, וּלְאוֹבָלָא לוֹן לְהֵיכָלָא לְמַלְכָּא, לְמֶחֱדֵי בְּהוּ מַלְכָּא כָּל יוֹמָא, דְּהָא קוּדְשָׁא בְּרִיךְ הוּא לָא אִשְׁתַּעְשַׁע אֶלָּא בְּנִשְׁמַתְהוֹן דְּצַדִּיקַיָא.</p>\n<p>תָּא חֲזֵי, אִתְעֲרוּתָא דִּרְחִימוּ דְּכְנֶסֶת יִשְׂרָאֵל, לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, נִשְׁמַתְהוֹן דְּצַדִּיקַיָא לְתַתָּא מִתְעָרִין לָהּ. בְּגִין דְּאִינוּן אַתְיָין מִסִּטְרָא דְמַלְכָּא, מִסִּטְרָא דִּדְכוּרָא, וְאִתְעֲרוּתָא דָא מָטֵי לְנוּקְבָא מִסִּטְרָא דִּדְכוּרָא, וְאִתְעַר רְחִימוּתָא. אִשְׁתַּכַּח דִּדְכוּרָא אִתְעַר חֲבִיבוּ וּרְחִימוּתָא לְנוּקְבָא, וּכְדֵין נוּקְבָא אִתְקַשְּׁרַת בִּרְחִימוּתָא, לְגַבֵּי דְכוּרָא.</p>\n<p>כְּהַאי גַוְונָא, תִּיאוּבְתָּא דְנוּקְבָא לְמִשְׁדֵי מַיִין תַּתָּאִין לָקֳבֵל מַיִין עִלָּאִין, לָאו אִיהוּ אֶלָּא בְּנִשְׁמַתְהוֹן דְּצַדִּיקַיָא. זַכָּאִין אִינוּן צַדִּיקַיָא בְּהַאי עַלְמָא, וּבְעַלְמָא דְאָתֵי, דְּעֲלַיְיהוּ קָיְימִין עִלָּאִין וְתַתָּאִין. וְעַל דָּא (משלי י׳:כ״ה) וְצַדִּיק יְסוֹד עוֹלָם כְּתִיב, סְתָם.</p>\n<p>וְרָזָא דְּכֹלָּא, צַדִּיק, אִיהוּ יְסוֹדָא דִלְעֵילָא, וְאִיהוּ יְסוֹדָא לְתַתָּא, וּכְנְסֶת יִשְׂרָאֵל אִתְכְּלִילַת מִצַּדִּיק, מִלְּעֵילָא וּמִתַּתָּא. (קנ\"ג ע\"ב) צַדִּיק מֵהַאי סִטְרָא, וְצַדִּיק מֵהַאי סִטְרָא, יַרְתִין לָהּ. הֲדָא הוּא דִכְתִיב, (תהילים ל״ז:כ״ט) צַדִּיקִים יִרְשׁוּ אָרֶץ. יִרְשׁוּ אָרֶץ וַדַּאי. תָּא חֲזֵי, צַדִּיק אַחְסִין לָהּ לְהַאי אֶרֶץ, וְאָרִיק עֲלָהּ בִּרְכָאן בְּכָל יוֹמָא, וְיָהִיב לָהּ תַּפְנוּקִין וְעִדּוּנִין, בִּנְגִידוּ עִלָּאָה דְּנָגִיד עֲלָהּ, וְהָא (רל\"ה ע\"ב) אוֹקִימְנָא מִלָּה.</p>\n<p>וְרָזָא דִּכְתִיב (בראשית מ״ט:כ׳) מֵאָשֵׁר שְׁמֵנָה לַחְמוֹ וְהוּא יִתֵּן מַעֲדַנֵי מֶלֶךְ. וְעִם כָּל דָּא, מִלָּה אָחֳרָא, כְּמָה דִכְתִיב, (שיר השירים ו׳:ט׳) רָאוּהָ בָּנוֹת וַיְאַשְׁרוּהָ, וְעַל דָּא אָמְרָה לֵאָה, (בראשית ל׳:י״ג) בְּאָשְׁרִי כִּי אִשְּׁרוּנִי בָנוֹת וְכֹלָּא שַׁפִּיר. וְתָא חֲזֵי מֵעַלְמָא דְאָתֵי, אִתְמְשִׁיךְ וְנָגִיד לְהַאי צַדִּיק, לְמֵיהַב תַּפְנוּקִין וְעִדּוּנִין לְהַאי אֶרֶץ, דְּאִיהוּ לֶחֶם עוֹנִי, וְאִתְעֲבִיד לֶחֶם פַּנַּג, הֲדָא הוּא דִכְתִיב, מֵאָשֵׁר שְׁמֵנָה לַחְמוֹ וְהוּא יִתֵּן מַעֲדַנֵּי מֶלֶךְ ודַּאי, וְהָא (ע\"ז ע\"ב) אוֹקִימְנָא.</p>\n<p><Nonei></i>תָּא חֲזֵי, מֵאָשֵׁר שְׁמֵנָה לַחְמוֹ. דָּא הוּא אֲתַר דְּכֹלָּא מְאַשְׁרִין לֵיהּ. וּמַאי אִיהוּ, עַלְמָא דְאָתֵי. דְּעִלָּאֵי וְתַתָּאֵי מְאַשְׁרִין לֵיהּ, וּמִכַּסְּפִין לֵיהּ. שְׁמֵנָה לַחְמוֹ, מַאן, עַד כָּאן לָא פָּרִישׁ מַאן הוּא אֲתַר. אֶלָּא, אִית לֶחֶם, וְאִית לֶחֶם, כְּמָה דְאִית אִילָנָא, וְאִית אִילָנָא. אִית אִילָנָא דְחַיֵּי, וְאִית אִילָנָא דְתַלְיָיא בֵּיהּ מוֹתָא. אִית לֶחֶם דְּאִקְרֵי לֶחֶם עוֹנִי, וְאִית לֶחֶם דְּאִקְרֵי לֶחֶם פַּנַּג. וּמַאן אִיהוּ (לחם). דָּא ו', וְדָא הוּא לַחְמ\"וֹ, לֶחֶ\"ם ו'. וְעַל דָּא כְּתִיב, (שמות ט״ז:ד׳) הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמַיִם, מִן הַשָּׁמַיִם וַדַּאי.</p>\n<p>וְעַל דָּא, מֵאָשֵׁר שְׁמֵנָה לַחְמוֹ, לֶחֶם ו', דְּהָא מִינֵיהּ אִתְּזָן הַאי אִילָנָא, וְהוּא מְעַטְּרָא לֵיהּ, כְּדִכְתִיב, (שיר השירים ג׳:י״א) בָּעֲטָרָה שֶׁעִטְּרָה לוֹ אִמּוֹ. וְכַד אִיהוּ נָקִיט, וַדַּאי הוּא יִתֵּן מַעֲדַנֵּי מֶלֶךְ. וּמַאן מֶלֶךְ. דָּא כְּנֶסֶת יִשְׂרָאֵל, דְּהָא מִנֵּיהּ אִתְּזָנַת, וְהוּא יָהִיב לָהּ עַל יְדָא דְּצַדִּיק, דַּרְגָּא קַדִּישָׁא אָת קַיָּימָא. וּמֵהָכָא לִשְׁאָר דַּרְגִּין דִּלְתַתָּא, וְכֻלְּהוּ כְּגַוְונָא דִלְעֵילָא.</p>\n<p>בְּסִפְרָא דְּרַב הַמְנוּנָא סָבָא, אָמַר הָכִי, מֵאָשֵׁר שְׁמֵנָה לַחְמוֹ, (לעיל מז ע\"ב) דָּא לֶחֶם שַׁבָּת, דְּאִיהוּ פַּנַג, עַל חַד תְּרֵין. כְּדִכְתִיב, (שמות ט״ז:כ״ב) לָקְטוּ לֶחֶם מִשְׁנְה. מַאי לֶחֶם מִשְׁנְה. אֶלָּא, תְּרֵי לֶחֶם, לֶחֶם מִן הַשָּׁמַיִם, וְלֶחֶם מִן הָאָרֶץ. דָּא הוּא לֶחֶם פַּנַּג, וְדָא הוּא לֶחֶם דְּמִסְכֵּנָא, וּבְשַׁבָּת אִתְכְּלִיל לֶחֶם תַּתָּאָה בְּלֶחֶם עִלָּאָה, וְאִתְבָּרֵךְ הַאי בְּגִינִי הַאי, וְאִיהוּ לֶחֶם מִשְׁנְה.</p>\n<p>וְתוּ הֲוָה אָמַר, לֶחֶם מִשְׁנְה דְּשַׁבָּת, נָקִיט מִשַּׁבָּת עִלָּאָה, דְּאִיהוּ נָגִיד וְאַנְהִיר לְכֹלָּא, וְאִתְחַבַּר לֶחֶם בְּלֶחֶם, וְאִיהוּ מִשְׁנֶה. וּבְכָל אֲתַר, רָזָא דְלֶחֶם, נוּקְבָא הִיא. בְּגִין כָּךְ שְׁמֵנָה כְּתִיב וְלא שָׁמֵן. וּכְתִיב, (בראשית מט) כִּי אִם הַלֶּחֶם אֲשֶׁר הוּא אוֹכֵל, דָּא אִנְתְּתֵיהּ.</p>\n<p>וְאִי תֵימָא (שמואל א ט׳:ז׳) וְהַלֶּחֶם אָזַל מִכֵּלֵינוּ, וְלָא כְּתִיב אָזְלַת. שְׁאָר מְזוֹנָא לֶחֶם קָרִינָן לֵיהּ, וְאִשְׁתְּמוֹדְעָן מִלִּין, מַאן הוּא שְׁאָר מְזוֹנָא, וּמַאן הוּא לֶחֶם מַמָּשׁ. לֶחֶם דִּלְעֵילָא, בְּכָל אֲתַר דְּכַר, לֶחֶם תַּתָּאָה, בְּכָל אֲתַר נוּקְבָא וְאֲנַן אַשְׁכְּחִינָא דְּזִמְנִין כְּתִיב דְּכַר, וּלְזִמְנִין נוּקְבָא, וְכֹלָּא חַד מִלָּה, הַאי כְּהַאי, וְשַׁפִּיר כֹּלָּא.</p>\n<p>תָּא חֲזֵי, אָשֵׁר, רָשִׁים לְעֵילָא וְרָשִׁים לְתַתָּא, בְּתִקּוּנִי כַּלָּה. וְכֻלְּהוּ תְּרֵיסַר שִׁבְטִין יַמָּא קָאִים עֲלַיְיהוּ, וְאִתְתַּקַּן בְּהוּ. הֲדָא הוּא דִכְתִיב, (מלכים א ז׳:כ״ה) וְהַיָּם עֲלֵיהֶם מִלְּמָעְלָה. וְרָזָא דְמִלָּה, אִתְתַּקַּן לְעֵילָא וְאִתְתַּקַּן לְתַתָּא בְּאַרְעָא. אִתְתַּקַּן לְעֵילָא בְּתִקּוּנִין יְדִיעָן, כְּגַוְונָא דְעַלְמָא עִלָּאָה. וְאִתְתַּקַּן לְתַתָּא בְהַנֵי תְּרֵיסַר שִׁבְטִין כּגַוְונָא דִלְעֵילָא. וְעַל דָּא שְׁכִינְתָּא לְעֵילָא וּשְׁכִינְתָּא לְתַתָּא בְּגִינַיְיהוּ (בגווייהו) דְיִשְׂרָאֵל, וּבִתְרֵיסַר שִׁבְטִין (נ\"א ובתרין שבטין) (נ\"א ובתרין סטרין) אִתְכְּלִילַת וְאִתְתַּקָּנַת. אָשֵׁר בְּתִקּוּנָהָא קָיְימָא, כִּשְׁאָר שִׁבְטִין.</p>\n<p>וְאִי לָאו דְּגָלֵי משֶׁה, לָא אִתְיְידַע. דִּכְתִיב, (דברים ל״ג:כ״ד) וְטוֹבֵל בַּשֶּׁמֶן רַגְלוֹ. לְאַחֲזָאָה אָן הוּא קִשְׁרָא דִּילֵיהּ בְּאַתְרִיהּ, דְּאִיהוּ נָגִיד הַהוּא מְשַׁח רְבוּת מִלְּעֵילָא. בְּגִינִי כָּךְ כְּתִיב, בָּרוּךְ מִבָּנִים אָשֵׁר וְגו'.</p>"],[9520011495,"<p>רִבִּי שִׁמְעוֹן פָּתַח וְאָמַר נַפְתָּלִי אַיָּלָה שְׁלוּחָה הַנּוֹתֵן אִמְרֵי שָׁפֶר. הָא אִתְּמָר, דְּעַלְמָא עִלָּאָה עַלְמָא דִּדְכוּרָא אִיהוּ, כֵּיוָן דְּסָלְקָא מִלָּה מִכְּנְסֶת יִשְׂרָאֵל וּלְעֵילָא, כֹּלָּא הוּא דְּכַר. מְנָלָן, מֵעוֹלָה, אַמַּאי אִתְקְרֵי עוֹלָה, בְּגִין דְּסָלְקָא לְעֵילָא מִן נוּקְבָא. וּבְגִינֵי כָּךְ, (ויקרא א׳:ג׳) עוֹלָה זָכָר תָּמִים יַקְרִיבֶנּוּ וְגו'.</p>\n<p>אַמַּאי תָּמִים, וְכִי פִּיסְקֵי פִּיסְקֵי בְּעִינָן לֵיהּ, דְּאָמַר תָּמִים, מַהוּ תָּמִים. אֶלָּא, כְּדִכְתִיב, (בראשית י״ז:א׳) הִתְהַלֵּךְ לְפָנַי וֶהְיֶה תָמִים. אֵימָתַי תָּמִים, בְּשַׁעְתָּא (ס\"א באתר) דְאִתְגְּזַר, דְּהָא דְכוּרָא לָא הֲוֵי, וְלָא אִשְׁתְּמוֹדַע, אֶלָּא בְּהַהוּא אֲתַר דְּאִקְרֵי תָמִים. וּמַאן אִיהוּ, דָּא אָת קַיָּימָא, דְּבֵיהּ אִשְׁתְּמוֹדַע דְּכוּרָא מִן נוּקְבָא. כְּדִכְתִיב, (בראשית ו׳:ט׳) אִישׁ צַדִּיק תָּמִים הָיָה. בְּגִינֵי כָּךְ זָכָר תָּמִים, דְּאִשְׁתְּמוֹדַע בֵּיהּ הַאי שַׁיְיפָא, וְלָא יְסָרְסוּן לֵיהּ.</p>\n<p>וְאִי תֵימָא, הָא כְּתִיב, (ויקרא ד׳:ל״ב) נְקֵבָה תְמִימָה. הָכִי הוּא וַדַּאי, כְּמָה דְאִקְרֵי צַדִּיק תָּמִים, כָּךְ אִקְרֵי צֶדֶק תְּמִימָה. בְּגִין דְּכֹלָּא, נָטְלָא מִנֵּיהּ, בְּגִינֵי כָּךְ, עוֹלָה דְּסָלְקָא מִן נוּקְבָא לִדְכוּרָא, וּמֵהַאי אֲתַר וּלְעֵילָא, כֹּלָּא הוּא דְּכוּרָא. וּמִן נוּקְבָא <Nonei></i>וּלְתַתָּא, כֹּלָּא הוּא נוּקְבָא, וְהָא אוֹקִימְנָא.</p>\n<p>וְאִי תֵימָא, הָכִי נָמֵי נוּקְבָא דִּלְעֵילָא. אֶלָא, סִיּוּמָא דְגוּפָא אַחֲזֵי עַל כָּל גּוּפָא דְּאִיהוּ דְכַר, רֵישָׁא דְגוּפָא נוּקְבָא, עַד דְּנָחִית לְסִיּוּמָא, וְכַד סִיּוּמָא אִתְחֲזֵי, הָא עָבִיד כֹּלָּא דְכַר. אֲבָל הָכָא, רֵישָׁא וְסוֹפָא נוּקְבָא, דְּהָא כָּל תִּקּוּן גּוּפָא נוּקְבָא.</p>\n<p>תָּא חֲזֵי, חַד רָזָא עִלָּאָה אִית בְּמִלָּה דָא, דְּהָא חָמִינָן דְּיַעֲקֹב בָּרִיךְ לְיוֹסֵף בְּגוֹ אֲחוֹהִי, כֵּיוָן דְּמַנֵּי קוּדְשָׁא בְּרִיךְ הוּא אַרְבַּע דְּגָלִים בִּשְׁכִינְתָּא, בִּתְרֵיסַר שִׁבְטִין לְאִתְתַּקְּנָא בְּהוּ, גָּרַע מִנַּיְיהוּ לְיוֹסֵף, וְשַׁוֵּי לְאֶפְרַיִם בְּאַתְרֵיהּ. מַאי טַעְמָא אִסְתַּלַּק יוֹסֵף מִנַּיְיהוּ. אִי תֵימָא בְּגִין חוֹבוֹי, לָאו הָכִי, דְּהָא זַכָּאָה אִיהוּ.</p>\n<p>אֶלָּא, רָזָא דְמִלָּה, יוֹסֵף רְשִׁימָא דִּדְכוּרָא הֲוָה, דִּכְתִיב בֵּן פּוֹרָת יוֹסֵף בֵּן פּוֹרָת עֲלֵי עָיִן. וּכְתִיב מִשָּׁם רוֹעֶה אֶבֶן יִשְׂרָאֵל, מִתַּמָּן אִתְּזָן הַאי אֶבֶן יִשְׂרָאֵל. אֶבֶן, דָּא כְּנֶסֶת יִשְׂרָאֵל, וְעֲלָה אָמַר דָוִד (תהילים קי״ח:כ״ב) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה. וּבְגִין דְּיוֹסֵף אִיהוּ רְשִׁימוּ דִּדְכוּרָא, אִקְרֵי יוֹסֵף הַצַּדִּיק, דְּהָא אִיהוּ צַדִּיק וַדַּאי, מִשָּׁם רוֹעֶה אֶבֶן יִשְׂרָאֵל.</p>\n<p>וּבְגִין דְּכָל תִּקּוּנֵי שְׁכִינְתָּא אִינוּן נוּקְבָן, אִסְתַּלַּק יוֹסֵף מִתַּמָּן, וְאִתְמַנֵּי תְּחוֹתֵיהּ אֶפְרַיִם, וְאִיהוּ נוּקְבָא לְתִקּוּנָהָא. וּבְגִין דְּאִיהוּ הָכִי, אִתְמַנֵּי לִסְטַר מַעֲרָב, אֲתַר דְּנוּקְבָא שַׁרְיָא, וְהַהוּא רְשִׁימוּ דְּאִיהוּ דְכוּרָא, אִסְתַּלַּק מִתִּקּוּנָהָא, בְּגִין דְּאִיהוּ עַלְמָא דְנוּקְבָא, וְלָא עַלְמָא דִּדְכוּרָא, וְכָל תִּקּוּנָהָא בָּעְיָין נוּקְבֵי.</p>\n<p>וּבְגִין כָּךְ, יוֹסֵף דְּאִיהוּ צַדִּיק, אִסְתַּלַֹק מִתִּקּוּנָהָא, וְאִתְמַנֵּי אֶפְרַיִם תְּחוֹתֵיהּ. וְעַל דָּא, כֻּלְּהוּ תְּרֵיסַר שִׁבְטִין, תִּקּוּנִי שְׁכִינְתָּא אִינוּן, וְכֻלְּהוּ בָּעְיָין כְּגַוְונָא דִלְעֵילָא, בַּר דַּרְגָּא דְּצַדִּיק, דְּאִיהוּ עָבִיד כָּל שַׁיְיפִין דְּכַר, וְלָא בָּעֵי לְאַכְּחָשָׁא (נ\"א ליה).</p>\n<p>נַפְתָּלִי אַיָּלָה שְׁלוּחָה הַנּוֹתֵן אִמְרֵי שָׁפֶר, הַיְינוּ דִכְתִיב, (שיר השירים ד׳:ג׳) וּמִדְבָּרֵךְ נָאוְה, בְּגִין דְּקוֹל מַדְבַּר לֵיהּ לְדִבּוּר, וְלֵית קוֹל בְּלָא דִבּוּר. וְהַהוּא קוֹל אִשְׁתַּלַּח מֵאֲתַר עֲמִיקָא דִּלְעֵילָא, וּשְׁלִיחַ מִקַּמֵּיהּ, לְאַנְהָגָא לְדִבּוּר, דְּהָא לֵית קוֹל בְּלָא דִבּוּר, וְלָא דִבּוּר בְּלֹא קוֹל. וְדָא כְּלַל דְּצָרִיךְ לִפְרַט, וּפְרַט דְּצָרִיךְ לִכְלַל. וְדָא קוֹל נַפְקָא מִדָּרוֹם, וּמַדְבַּר לְמַעֲרָב, יָרִית לִתְרֵין סִטְרִין. וְדָא הוּא דִכְתִיב, (דברים ל״ג:כ״ג) וּלְנַפְתָּלִי אָמַר וְגו', יָם וְדָרוֹם יְרָשָׁה, לְעֵילָא דְכַר, לְתַתָּא נוּקְבָא, בְּגִין כָּךְ נַפְתָּלִי אַיָּלָה שְׁלוּחָה נוּקְבָא לְתַתָּא. כְּגַוְונָא דָּא דְּכַר לְעֵילָא, דִּכְתִיב הַנּוֹתֵן אִמְרֵי שָׁפֶר, הַנּוֹתֵן כְּתִיב, וְלא הַנּוֹתֶנֶת.</p>"],[9520011496,"<p>תָּא חֲזֵי, מַחְשָׁבָה רֵאשִׁיתָא דְכֹלָּא, וּבְגִין דְּאִיהִי מַחְשָׁבָה, אִיהִי לְגוֹ סְתִימָא וְלָא אִתְיְידַע. כָּךְ אִתְפַּשַּׁט הַאי מַחְשָׁבָה יַתִּיר, אַתְיָא לְאֲתַר דְּרוּחָא שַׁרְיָא, וְכַד מָטֵי לְהַהוּא אֲתַר אִקְרֵי בִּינָ\"ה, וְהָא לָאו סָתִים כִּדְקַדְמִיתָא, וְאַף עַל גַּב דְּאִיהוּ סָתִים, הַאי רוּחָא אִתְפַּשַּׁט, וְאַפִּיק קָלָא, כָּלִיל מֵאֶשָּׁא וּמַיָא וְרוּחָא, דְּאִינוּן צָפוֹן וְדָרוֹם וּמִזְרָח. וְהַאי קָלָא, כְּלָלָא דְּכָל שְׁאָר חֵילִין, וְקָלָא דָּא מַדְבַּר לְדִבּוּר, וְדָא יָהִיב מִלָּה בְּתִקּוּנָא, בְּגִין דְּקוֹל אִשְׁתַּלַּח מֵאֲתַר דְּרוּחָא, וְאָתֵי לְדַבְּרָא מִלָּה, לְאֲפָקָא מִלִּין תְּרִיצִין.</p>\n<p>וְכַד תִּסְתַּכֵּל בְּדַרְגִּין, הוּא מַחְשָׁבָה, הוּא בִּינָה, הוּא קוֹל, הוּא דִבּוּר, וְכֹלָּא חַד, וְהִיא הִיא מַחְשָׁבָה, רֵאשִׁיתָא דְכֹלָּא, וְלָא הֲוֵי פֵּרוּד, אֶלָּא כֹּלָּא חַד, וְקִשּׁוּרָא חַד, דְּאִיהוּ מַחְשָׁבָה מַמָּשׁ אִתְקַשַּׁר בְּאַיִן, וְלָא אִתְפָּרַשׁ לְעָלְמִין, וְדָא הוּא (זכריה י״ד:ט׳) ה' אֶחָד וּשְׁמוֹ אֶחָד. וְעַל דָּא, הַנּוֹתֵן אִמְרֵי שָׁפֶר כְּתִיב, דָּא גוּפָא.</p>"]]});
